#[derive(Default)]
struct MysqlFamilyScriptCatalog {
    tables: Vec<String>,
    views: Vec<String>,
    materialized_views: Vec<String>,
    types: Vec<String>,
    procedures: Vec<String>,
    functions: Vec<String>,
    packages: Vec<String>,
    sequences: Vec<String>,
    synonyms: Vec<String>,
    public_synonyms: Vec<String>,
    directories: Vec<String>,
    triggers: Vec<String>,
    events: Vec<String>,
    indexes: Vec<String>,
    constraints: Vec<String>,
    partitions: Vec<String>,
    schemas: Vec<String>,
    users: Vec<String>,
    columns: HashMap<String, Vec<String>>,
    type_members: HashMap<String, Vec<String>>,
    collection_element_types: HashMap<String, String>,
    synonym_targets: HashMap<String, String>,
    signatures: HashMap<String, crate::ui::intellisense::SignatureLabel>,
    signature_kinds: HashMap<String, QualifiedMemberKind>,
    routine_return_types: HashMap<String, String>,
    relation_object_types: HashMap<String, String>,
    /// `TABLE.COLUMN` -> declared type word, for columns typed with a
    /// user-defined object type. Filtered against `type_members` when the
    /// catalog is materialised, so scalar columns never leak in.
    column_object_types: HashMap<String, String>,
}

/// `PARTITION <name>` in a `PARTITION BY ... (...)` definition or in an
/// `ALTER TABLE ... REORGANIZE ... INTO (...)` list names a partition of the table.
fn collect_partition_names(tokens: &[SqlToken], partitions: &mut Vec<String>) {
    for (idx, token) in tokens.iter().enumerate() {
        let is_partition_keyword = matches!(token, SqlToken::Word(word)
            if word.eq_ignore_ascii_case("PARTITION")
                || word.eq_ignore_ascii_case("SUBPARTITION"));
        if !is_partition_keyword {
            continue;
        }
        let Some(SqlToken::Word(name)) = tokens.get(idx + 1) else {
            continue;
        };
        if crate::sql_text::is_mysql_sql_keyword(name)
            || crate::sql_text::is_oracle_sql_keyword(&name.to_ascii_uppercase())
        {
            continue;
        }
        push_unique_case_insensitive(partitions, name);
    }
}

/// `ALTER TABLE t ADD [UNIQUE|FULLTEXT|SPATIAL] INDEX|KEY <name> (...)` creates a
/// named index just like `CREATE INDEX`.
fn collect_added_index_names(tokens: &[SqlToken], indexes: &mut Vec<String>) {
    for (idx, token) in tokens.iter().enumerate() {
        if !token_word_eq(Some(token), "ADD") {
            continue;
        }
        let mut cursor = idx + 1;
        while matches!(tokens.get(cursor), Some(SqlToken::Word(word))
        if matches!(
            word.to_ascii_uppercase().as_str(),
            "UNIQUE" | "FULLTEXT" | "SPATIAL" | "CONSTRAINT"
        )) {
            cursor += 1;
        }
        if !(token_word_eq(tokens.get(cursor), "INDEX") || token_word_eq(tokens.get(cursor), "KEY"))
        {
            continue;
        }
        if let Some(SqlToken::Word(name)) = tokens.get(cursor + 1) {
            if !crate::sql_text::is_mysql_sql_keyword(name) {
                push_unique_case_insensitive(indexes, name);
            }
        }
    }
}

fn token_word_eq(token: Option<&SqlToken>, expected: &str) -> bool {
    matches!(token, Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case(expected))
}

fn token_word_text(token: Option<&SqlToken>) -> Option<&str> {
    match token {
        Some(SqlToken::Word(word)) => Some(word),
        Some(SqlToken::String(value)) if crate::sql_text::is_quoted_identifier(value) => {
            Some(value)
        }
        _ => None,
    }
}

fn push_unique_case_insensitive(values: &mut Vec<String>, value: &str) {
    let display = value.trim();
    let normalized = crate::sql_text::strip_identifier_quotes(display);
    let lookup = normalized.trim();
    if lookup.is_empty()
        || values
            .iter()
            .any(|item| crate::sql_text::strip_identifier_quotes(item).eq_ignore_ascii_case(lookup))
    {
        return;
    }
    values.push(display.to_string());
}

fn matching_paren_index(tokens: &[SqlToken], open_idx: usize) -> Option<usize> {
    let mut depth = 0usize;
    for (idx, token) in tokens.iter().enumerate().skip(open_idx) {
        match token {
            SqlToken::Symbol(symbol) if symbol == "(" => depth = depth.saturating_add(1),
            SqlToken::Symbol(symbol) if symbol == ")" => {
                depth = depth.saturating_sub(1);
                if depth == 0 {
                    return Some(idx);
                }
            }
            _ => {}
        }
    }
    None
}

fn collect_create_table_columns(tokens: &[SqlToken], open_idx: usize) -> Vec<String> {
    let Some(close_idx) = matching_paren_index(tokens, open_idx) else {
        return Vec::new();
    };
    let mut columns = Vec::new();
    let mut depth = 0usize;
    let mut at_item_start = true;
    for (offset, token) in tokens.iter().take(close_idx).skip(open_idx + 1).enumerate() {
        let token_idx = open_idx + 1 + offset;
        match token {
            SqlToken::Symbol(symbol) if symbol == "(" => depth = depth.saturating_add(1),
            SqlToken::Symbol(symbol) if symbol == ")" => depth = depth.saturating_sub(1),
            SqlToken::Symbol(symbol) if symbol == "," && depth == 0 => at_item_start = true,
            SqlToken::Comment(comment) if depth == 0 && at_item_start => {
                let mut words = comment.split_whitespace();
                let column = words.next();
                let data_type = words
                    .next()
                    .and_then(|word| word.split('(').next())
                    .map(str::to_ascii_uppercase);
                if column.is_some_and(|word| word.eq_ignore_ascii_case("REMARK"))
                    && data_type.as_deref().is_some_and(|word| {
                        matches!(
                            word,
                            "BINARY_DOUBLE"
                                | "BINARY_FLOAT"
                                | "BLOB"
                                | "CHAR"
                                | "CLOB"
                                | "DATE"
                                | "DECIMAL"
                                | "FLOAT"
                                | "INTEGER"
                                | "NCHAR"
                                | "NCLOB"
                                | "NUMBER"
                                | "NVARCHAR2"
                                | "RAW"
                                | "TIMESTAMP"
                                | "VARCHAR"
                                | "VARCHAR2"
                        )
                    })
                {
                    push_unique_case_insensitive(&mut columns, column.unwrap_or("REMARK"));
                    at_item_start = false;
                }
            }
            SqlToken::Word(word) if depth == 0 && at_item_start => {
                let structural_keyword = matches!(
                    word.to_ascii_uppercase().as_str(),
                    "PRIMARY"
                        | "UNIQUE"
                        | "KEY"
                        | "INDEX"
                        | "CONSTRAINT"
                        | "FOREIGN"
                        | "CHECK"
                        | "FULLTEXT"
                        | "SPATIAL"
                );
                let followed_by_data_type = tokens
                    .get(token_idx + 1..close_idx)
                    .unwrap_or(&[])
                    .iter()
                    .find(|token| !matches!(token, SqlToken::Comment(_)))
                    .is_some_and(|token| {
                        let SqlToken::Word(data_type) = token else {
                            return false;
                        };
                        [
                            crate::db::DatabaseType::Oracle,
                            crate::db::DatabaseType::MySQL,
                            crate::db::DatabaseType::MariaDB,
                        ]
                        .into_iter()
                        .any(|db_type| {
                            data_type_keywords_for(Some(db_type), DataTypePosition::ColumnDef)
                                .iter()
                                .any(|candidate| candidate.eq_ignore_ascii_case(data_type))
                        })
                    });
                if !structural_keyword || followed_by_data_type {
                    push_unique_case_insensitive(&mut columns, word);
                }
                at_item_start = false;
            }
            SqlToken::String(value)
                if depth == 0 && at_item_start && crate::sql_text::is_quoted_identifier(value) =>
            {
                push_unique_case_insensitive(&mut columns, value);
                at_item_start = false;
            }
            _ => {}
        }
    }
    columns
}

/// `(column type, …)` pairs of a `CREATE TABLE` element list. The object-type
/// filter applied at the call site discards scalar and constraint elements.
fn collect_create_table_column_types(
    tokens: &[SqlToken],
    open_idx: usize,
) -> Vec<(String, String)> {
    let Some(close_idx) = matching_paren_index(tokens, open_idx) else {
        return Vec::new();
    };
    let mut pairs = Vec::new();
    let mut depth = 0usize;
    let mut item: Vec<&str> = Vec::new();
    let mut flush = |item: &mut Vec<&str>| {
        if let [column, type_word, rest @ ..] = item.as_slice() {
            let type_word = if type_word.eq_ignore_ascii_case("REF") {
                rest.first().copied().unwrap_or(type_word)
            } else {
                type_word
            };
            pairs.push(((*column).to_string(), type_word.to_string()));
        }
        item.clear();
    };
    for token in tokens.iter().take(close_idx).skip(open_idx + 1) {
        match token {
            SqlToken::Symbol(symbol) if symbol == "(" => depth = depth.saturating_add(1),
            SqlToken::Symbol(symbol) if symbol == ")" => depth = depth.saturating_sub(1),
            SqlToken::Symbol(symbol) if symbol == "," && depth == 0 => flush(&mut item),
            SqlToken::Word(word) if depth == 0 => {
                if item.len() < 3 {
                    item.push(word.as_str());
                }
            }
            SqlToken::Comment(_) => {}
            _ if depth == 0 => item.push(""),
            _ => {}
        }
    }
    flush(&mut item);
    pairs
}

fn collect_mysql_inline_index_names(tokens: &[SqlToken], open_idx: usize) -> Vec<String> {
    let Some(close_idx) = matching_paren_index(tokens, open_idx) else {
        return Vec::new();
    };
    let mut indexes = Vec::new();
    let mut item_start = open_idx + 1;
    let mut depth = 0usize;
    for idx in open_idx + 1..=close_idx {
        match tokens.get(idx) {
            Some(SqlToken::Symbol(symbol)) if symbol == "(" => depth = depth.saturating_add(1),
            Some(SqlToken::Symbol(symbol)) if symbol == ")" && depth > 0 => {
                depth = depth.saturating_sub(1)
            }
            Some(SqlToken::Symbol(symbol)) if (symbol == "," && depth == 0) || idx == close_idx => {
                let words = tokens[item_start..idx]
                    .iter()
                    .filter_map(|token| token_word_text(Some(token)))
                    .collect::<Vec<_>>();
                let name = match words.as_slice() {
                    [primary, key, ..]
                        if primary.eq_ignore_ascii_case("PRIMARY")
                            && key.eq_ignore_ascii_case("KEY") =>
                    {
                        Some("PRIMARY")
                    }
                    [kind, name, ..]
                        if matches!(kind.to_ascii_uppercase().as_str(), "INDEX" | "KEY") =>
                    {
                        Some(*name)
                    }
                    [modifier, kind, name, ..]
                        if matches!(
                            modifier.to_ascii_uppercase().as_str(),
                            "FULLTEXT" | "SPATIAL" | "UNIQUE"
                        ) && matches!(kind.to_ascii_uppercase().as_str(), "INDEX" | "KEY") =>
                    {
                        Some(*name)
                    }
                    _ => None,
                };
                if let Some(name) = name {
                    push_unique_case_insensitive(&mut indexes, name);
                }
                item_start = idx + 1;
            }
            _ => {}
        }
    }
    indexes
}

fn collect_oracle_object_type_members(tokens: &[SqlToken], open_idx: usize) -> Vec<String> {
    let Some(close_idx) = matching_paren_index(tokens, open_idx) else {
        return Vec::new();
    };
    let mut members = Vec::new();
    let mut item_start = open_idx + 1;
    let mut depth = 0usize;
    for idx in open_idx + 1..=close_idx {
        match tokens.get(idx) {
            Some(SqlToken::Symbol(symbol)) if symbol == "(" => depth = depth.saturating_add(1),
            Some(SqlToken::Symbol(symbol)) if symbol == ")" && depth > 0 => {
                depth = depth.saturating_sub(1)
            }
            Some(SqlToken::Symbol(symbol)) if (symbol == "," && depth == 0) || idx == close_idx => {
                let item = &tokens[item_start..idx];
                let words = item
                    .iter()
                    .filter_map(|token| token_word_text(Some(token)))
                    .collect::<Vec<_>>();
                let member = if words.first().is_some_and(|word| {
                    matches!(
                        word.to_ascii_uppercase().as_str(),
                        "CONSTRUCTOR" | "MAP" | "MEMBER" | "ORDER" | "STATIC"
                    )
                }) {
                    words
                        .iter()
                        .position(|word| {
                            matches!(word.to_ascii_uppercase().as_str(), "FUNCTION" | "PROCEDURE")
                        })
                        .and_then(|routine_idx| words.get(routine_idx + 1).copied())
                } else {
                    words.first().copied()
                };
                if let Some(member) = member {
                    push_unique_case_insensitive(&mut members, member);
                }
                item_start = idx.saturating_add(1);
            }
            _ => {}
        }
    }
    members
}

fn collect_oracle_property_graph_properties(
    tokens: &[SqlToken],
    start_idx: usize,
    end_idx: usize,
) -> Vec<String> {
    let mut properties = Vec::new();
    let mut idx = start_idx;
    while idx < end_idx {
        if !token_word_eq(tokens.get(idx), "PROPERTIES")
            || !matches!(
                tokens.get(idx + 1),
                Some(SqlToken::Symbol(symbol)) if symbol == "("
            )
        {
            idx += 1;
            continue;
        }
        let open_idx = idx + 1;
        let Some(close_idx) = matching_paren_index(tokens, open_idx) else {
            break;
        };
        let mut item_start = open_idx + 1;
        let mut depth = 0usize;
        for item_end in open_idx + 1..=close_idx {
            match tokens.get(item_end) {
                Some(SqlToken::Symbol(symbol)) if symbol == "(" => depth = depth.saturating_add(1),
                Some(SqlToken::Symbol(symbol)) if symbol == ")" && depth > 0 => {
                    depth = depth.saturating_sub(1)
                }
                Some(SqlToken::Symbol(symbol))
                    if (symbol == "," && depth == 0) || item_end == close_idx =>
                {
                    if let Some(property) = tokens[item_start..item_end]
                        .iter()
                        .rev()
                        .find_map(|token| token_word_text(Some(token)))
                        .filter(|word| {
                            !crate::sql_text::is_sql_keyword_for_db(
                                &word.to_ascii_uppercase(),
                                crate::db::DatabaseType::Oracle,
                            )
                        })
                    {
                        push_unique_case_insensitive(&mut properties, property);
                    }
                    item_start = item_end.saturating_add(1);
                }
                _ => {}
            }
        }
        idx = close_idx.saturating_add(1);
    }
    properties
}

fn oracle_q_quote_body(literal: &str) -> Option<&str> {
    let quote_idx = literal.find('\'')?;
    let delimiter_start = quote_idx.saturating_add(1);
    let delimiter = literal.get(delimiter_start..)?.chars().next()?;
    let body_start = delimiter_start.saturating_add(delimiter.len_utf8());
    let closing = crate::sql_text::q_quote_closing(delimiter);
    let suffix = format!("{closing}'");
    let body_end = literal.rfind(&suffix)?;
    (body_end >= body_start)
        .then(|| literal.get(body_start..body_end))
        .flatten()
}

fn oracle_sql_macro_projection_columns(
    tokens: &[SqlToken],
    start_idx: usize,
    end_idx: usize,
) -> Vec<String> {
    tokens
        .get(start_idx..end_idx)
        .unwrap_or(&[])
        .iter()
        .find_map(|token| match token {
            SqlToken::String(literal) => oracle_q_quote_body(literal),
            _ => None,
        })
        .map(super::query_text::tokenize_sql)
        .map(|body_tokens| oracle_view_projection_columns(&body_tokens))
        .unwrap_or_default()
}

fn collect_mysql_create_routine_names_from_text(script: &str, keyword: &str) -> Vec<String> {
    let upper = script.to_ascii_uppercase();
    let marker = format!("CREATE {keyword}");
    let mut names = Vec::new();
    let mut search_start = 0usize;
    while let Some(relative_idx) = upper
        .get(search_start..)
        .and_then(|tail| tail.find(&marker))
    {
        let mut idx = search_start + relative_idx + marker.len();
        while script
            .as_bytes()
            .get(idx)
            .is_some_and(|byte| byte.is_ascii_whitespace())
        {
            idx += 1;
        }
        if upper
            .get(idx..)
            .is_some_and(|tail| tail.starts_with("IF NOT EXISTS"))
        {
            idx += "IF NOT EXISTS".len();
            while script
                .as_bytes()
                .get(idx)
                .is_some_and(|byte| byte.is_ascii_whitespace())
            {
                idx += 1;
            }
        }
        let name_start = idx;
        if script.as_bytes().get(idx) == Some(&b'`') {
            idx += 1;
            while script.as_bytes().get(idx).is_some_and(|byte| *byte != b'`') {
                idx += 1;
            }
            let name = script.get(name_start..idx.saturating_add(1)).unwrap_or("");
            push_unique_case_insensitive(&mut names, name);
        } else {
            while script.as_bytes().get(idx).is_some_and(|byte| {
                byte.is_ascii_alphanumeric() || matches!(*byte, b'_' | b'$' | b'.')
            }) {
                idx += 1;
            }
            let name = script.get(name_start..idx).unwrap_or("");
            push_unique_case_insensitive(&mut names, name);
        }
        search_start = idx.saturating_add(1);
    }
    names
}

fn mysql_identifier_from_text(text: &str, mut idx: usize) -> Option<(String, usize)> {
    while text
        .as_bytes()
        .get(idx)
        .is_some_and(|byte| byte.is_ascii_whitespace())
    {
        idx += 1;
    }
    let start = idx;
    if text.as_bytes().get(idx) == Some(&b'`') {
        idx += 1;
        while text.as_bytes().get(idx).is_some_and(|byte| *byte != b'`') {
            idx += 1;
        }
        return Some((text.get(start + 1..idx)?.to_string(), idx.saturating_add(1)));
    }
    while text
        .as_bytes()
        .get(idx)
        .is_some_and(|byte| byte.is_ascii_alphanumeric() || matches!(*byte, b'_' | b'$' | b'.'))
    {
        idx += 1;
    }
    (idx > start).then(|| (text.get(start..idx).unwrap_or("").to_string(), idx))
}

fn mysql_select_columns_from_text(select_sql: &str) -> Vec<String> {
    let upper = select_sql.to_ascii_uppercase();
    let Some(select_idx) = upper.find("SELECT") else {
        return Vec::new();
    };
    let Some(from_rel_idx) = upper.get(select_idx..).and_then(|tail| tail.find("FROM")) else {
        return Vec::new();
    };
    let list = select_sql
        .get(select_idx + "SELECT".len()..select_idx + from_rel_idx)
        .unwrap_or("");
    let mut columns = Vec::new();
    for item in list.split(',') {
        let item = item.trim();
        if item.is_empty() {
            continue;
        }
        let item_upper = item.to_ascii_uppercase();
        let name = item_upper
            .rsplit_once(" AS ")
            .and_then(|(_, alias)| mysql_identifier_from_text(alias, 0).map(|(name, _)| name))
            .or_else(|| {
                item.rsplit_once('.').and_then(|(_, tail)| {
                    mysql_identifier_from_text(tail.trim(), 0).map(|(name, _)| name)
                })
            })
            .or_else(|| mysql_identifier_from_text(item, 0).map(|(name, _)| name));
        if let Some(name) = name {
            push_unique_case_insensitive(&mut columns, &name);
        }
    }
    columns
}

fn collect_mysql_temporary_tables_from_text(script: &str) -> Vec<(String, Vec<String>)> {
    let upper = script.to_ascii_uppercase();
    let marker = "CREATE TEMPORARY TABLE";
    let mut tables = Vec::new();
    let mut search_start = 0usize;
    while let Some(relative_idx) = upper.get(search_start..).and_then(|tail| tail.find(marker)) {
        let idx = search_start + relative_idx + marker.len();
        let Some((name, after_name)) = mysql_identifier_from_text(script, idx) else {
            search_start = idx.saturating_add(1);
            continue;
        };
        let tail = script.get(after_name..).unwrap_or("");
        let tail_upper = upper.get(after_name..).unwrap_or("");
        // Only this statement may contribute columns. Without the bound, a
        // `CREATE TEMPORARY TABLE t (col …)` picked up the next ` AS` alias
        // anywhere later in the script and overwrote the real DDL columns.
        let statement_len = tail.find(';').unwrap_or(tail.len());
        let statement = tail.get(..statement_len).unwrap_or("");
        let statement_upper = tail_upper.get(..statement_len).unwrap_or("");
        let columns = if statement.trim_start().starts_with('(') {
            // Explicit column list — the token-based pass already registered it.
            Vec::new()
        } else if let Some(as_idx) = statement_upper.find(" AS") {
            let select_sql = statement.get(as_idx + " AS".len()..).unwrap_or("");
            mysql_select_columns_from_text(select_sql)
        } else {
            Vec::new()
        };
        tables.push((name, columns));
        search_start = after_name.saturating_add(1);
    }
    tables
}

fn collect_mssql_bracket_tables_from_text(script: &str) -> Vec<(String, Vec<String>)> {
    fn bracket_identifier(text: &str, mut idx: usize) -> Option<(String, usize)> {
        while text
            .as_bytes()
            .get(idx)
            .is_some_and(|byte| byte.is_ascii_whitespace())
        {
            idx += 1;
        }
        let start = idx;
        if text.as_bytes().get(idx) != Some(&b'[') {
            return None;
        }
        idx += 1;
        while idx < text.len() {
            if text.as_bytes().get(idx) != Some(&b']') {
                idx += 1;
                continue;
            }
            if text.as_bytes().get(idx + 1) == Some(&b']') {
                idx += 2;
                continue;
            }
            idx += 1;
            return Some((text.get(start..idx)?.to_string(), idx));
        }
        None
    }

    let upper = script.to_ascii_uppercase();
    let marker = "CREATE TABLE";
    let mut tables = Vec::new();
    let mut search_start = 0usize;
    while let Some(relative_idx) = upper.get(search_start..).and_then(|tail| tail.find(marker)) {
        let name_idx = search_start + relative_idx + marker.len();
        let Some((display_name, after_name)) = bracket_identifier(script, name_idx) else {
            search_start = name_idx.saturating_add(1);
            continue;
        };
        let tail = script.get(after_name..).unwrap_or("");
        let Some(open_rel) = tail.find('(') else {
            search_start = after_name.saturating_add(1);
            continue;
        };
        let body_start = after_name + open_rel + 1;
        let body_tail = script.get(body_start..).unwrap_or("");
        let body_len = body_tail.find("\n)").unwrap_or(body_tail.len());
        let body = body_tail.get(..body_len).unwrap_or("");
        let columns = body
            .lines()
            .filter_map(|line| bracket_identifier(line, 0).map(|(column, _)| column))
            .collect::<Vec<_>>();
        tables.push((
            SqlEditorWidget::strip_identifier_quotes(&display_name),
            columns,
        ));
        search_start = body_start.saturating_add(body_len);
    }
    tables
}

fn mysql_family_collect_package_signatures(
    tokens: &[SqlToken],
    catalog: &mut MysqlFamilyScriptCatalog,
) {
    let mut current_package = None::<String>;
    let mut idx = 0usize;
    while idx < tokens.len() {
        if token_word_eq(tokens.get(idx), "CREATE") {
            let statement_end = tokens
                .iter()
                .enumerate()
                .skip(idx + 1)
                .find_map(|(token_idx, token)| {
                    matches!(token, SqlToken::Symbol(symbol) if symbol == ";").then_some(token_idx)
                })
                .unwrap_or(tokens.len());
            let package_idx = tokens
                .iter()
                .enumerate()
                .take(statement_end)
                .skip(idx + 1)
                .find_map(|(token_idx, token)| {
                    token_word_eq(Some(token), "PACKAGE").then_some(token_idx)
                });
            current_package = package_idx.and_then(|package_idx| {
                let name_idx = package_idx
                    + usize::from(token_word_eq(tokens.get(package_idx + 1), "BODY"))
                    + 1;
                script_object_name_at(tokens, name_idx).map(|(name, _)| name)
            });
        }

        let Some(routine_kind) = token_word_text(tokens.get(idx))
            .map(str::to_ascii_uppercase)
            .filter(|word| matches!(word.as_str(), "PROCEDURE" | "FUNCTION"))
        else {
            idx += 1;
            continue;
        };
        let Some(package) = current_package.as_deref() else {
            idx += 1;
            continue;
        };
        let Some((name, after_name_idx)) = script_object_name_at(tokens, idx + 1) else {
            idx += 1;
            continue;
        };
        let params = if matches!(
            tokens.get(after_name_idx),
            Some(SqlToken::Symbol(symbol)) if symbol == "("
        ) {
            script_parameter_names_from_open_paren(tokens, after_name_idx)
        } else {
            Vec::new()
        };
        let member_kind = if routine_kind == "FUNCTION" {
            QualifiedMemberKind::Function
        } else {
            QualifiedMemberKind::Procedure
        };
        let return_type = oracle_script_routine_return_type(tokens, after_name_idx);
        oracle_insert_signature(
            catalog,
            format!("{package}.{name}"),
            &name,
            &params,
            member_kind,
            return_type.as_deref(),
        );
        idx += 1;
    }
}

fn mysql_family_catalog_from_script(script: &str) -> MysqlFamilyScriptCatalog {
    let tokens = super::query_text::tokenize_sql_with_mysql_compat(script, true);
    let mut catalog = MysqlFamilyScriptCatalog::default();
    mysql_family_collect_package_signatures(&tokens, &mut catalog);
    let mut idx = 0usize;
    while idx < tokens.len() {
        if token_word_eq(tokens.get(idx), "CREATE") {
            let statement_end = tokens
                .iter()
                .enumerate()
                .skip(idx + 1)
                .find_map(|(token_idx, token)| {
                    matches!(token, SqlToken::Symbol(symbol) if symbol == ";").then_some(token_idx)
                })
                .unwrap_or(tokens.len());
            let view_idx = tokens
                .iter()
                .enumerate()
                .take(statement_end)
                .skip(idx + 1)
                .find_map(|(token_idx, token)| {
                    token_word_eq(Some(token), "VIEW").then_some(token_idx)
                })
                .filter(|view_idx| {
                    tokens[idx + 1..*view_idx].iter().any(|token| {
                        token_word_text(Some(token)).is_some_and(|word| {
                            matches!(
                                word.to_ascii_uppercase().as_str(),
                                "ALGORITHM" | "DEFINER" | "SECURITY"
                            )
                        })
                    })
                });
            let Some(kind_idx) = view_idx.or_else(|| {
                tokens
                    .iter()
                    .enumerate()
                    .take(statement_end)
                    .skip(idx + 1)
                    .find_map(|(token_idx, token)| {
                        token_word_text(Some(token))
                            .is_some_and(|word| {
                                matches!(
                                    word.to_ascii_uppercase().as_str(),
                                    "DATABASE"
                                        | "EVENT"
                                        | "FUNCTION"
                                        | "INDEX"
                                        | "PACKAGE"
                                        | "PROCEDURE"
                                        | "ROLE"
                                        | "SCHEMA"
                                        | "SEQUENCE"
                                        | "TABLE"
                                        | "TRIGGER"
                                        | "USER"
                                        | "VIEW"
                                )
                            })
                            .then_some(token_idx)
                    })
            }) else {
                idx += 1;
                continue;
            };
            let Some(kind) = token_word_text(tokens.get(kind_idx)) else {
                idx += 1;
                continue;
            };
            let mut name_idx = kind_idx + 1;
            if kind.eq_ignore_ascii_case("PACKAGE") && token_word_eq(tokens.get(name_idx), "BODY") {
                name_idx += 1;
            }
            match kind.to_ascii_uppercase().as_str() {
                "TABLE" => {
                    if let Some((name, qualified_name, after_name_idx)) =
                        script_qualified_object_name_at(&tokens, name_idx)
                    {
                        push_unique_case_insensitive(&mut catalog.tables, &name);
                        if matches!(
                            tokens.get(after_name_idx),
                            Some(SqlToken::Symbol(symbol)) if symbol == "("
                        ) {
                            insert_script_relation_columns(
                                &mut catalog,
                                &name,
                                &qualified_name,
                                collect_create_table_columns(&tokens, after_name_idx),
                            );
                            for index in collect_mysql_inline_index_names(&tokens, after_name_idx) {
                                push_unique_case_insensitive(&mut catalog.indexes, &index);
                            }
                        } else {
                            let statement_end = tokens
                                .iter()
                                .enumerate()
                                .skip(after_name_idx)
                                .find_map(|(idx, token)| {
                                    matches!(token, SqlToken::Symbol(symbol) if symbol == ";")
                                        .then_some(idx)
                                })
                                .unwrap_or(tokens.len());
                            if token_word_eq(tokens.get(after_name_idx), "LIKE") {
                                if let Some((source, _, _)) =
                                    script_qualified_object_name_at(&tokens, after_name_idx + 1)
                                {
                                    if let Some(columns) =
                                        catalog.columns.get(&source.to_ascii_uppercase()).cloned()
                                    {
                                        insert_script_relation_columns(
                                            &mut catalog,
                                            &name,
                                            &qualified_name,
                                            columns,
                                        );
                                    }
                                }
                            } else if let Some(as_idx) = tokens
                                .iter()
                                .enumerate()
                                .take(statement_end)
                                .skip(after_name_idx)
                                .find_map(|(idx, token)| {
                                    token_word_eq(Some(token), "AS").then_some(idx)
                                })
                            {
                                let columns = mysql_family_query_projection_columns(
                                    &tokens[as_idx + 1..statement_end],
                                    &catalog,
                                );
                                insert_script_relation_columns(
                                    &mut catalog,
                                    &name,
                                    &qualified_name,
                                    columns,
                                );
                            }
                        }
                    }
                }
                "VIEW" => {
                    if let Some((name, qualified_name, after_name_idx)) =
                        script_qualified_object_name_at(&tokens, name_idx)
                    {
                        push_unique_case_insensitive(&mut catalog.views, &name);
                        let statement_end = tokens
                            .iter()
                            .enumerate()
                            .skip(after_name_idx)
                            .find_map(|(idx, token)| {
                                matches!(token, SqlToken::Symbol(symbol) if symbol == ";")
                                    .then_some(idx)
                            })
                            .unwrap_or(tokens.len());
                        let explicit_columns = tokens
                            .iter()
                            .enumerate()
                            .take(statement_end)
                            .skip(after_name_idx)
                            .find(|(_, token)| !matches!(token, SqlToken::Comment(_)))
                            .filter(
                                |(_, token)| {
                                    matches!(token, SqlToken::Symbol(symbol) if symbol == "(")
                                },
                            )
                            .map(|(open_idx, _)| {
                                script_parameter_names_from_open_paren(&tokens, open_idx)
                                    .into_iter()
                                    .map(|column| {
                                        crate::sql_text::strip_identifier_quotes(&column)
                                    })
                                    .collect::<Vec<_>>()
                            })
                            .unwrap_or_default();
                        if let Some(as_idx) = tokens
                            .iter()
                            .enumerate()
                            .take(statement_end)
                            .skip(after_name_idx)
                            .find_map(|(idx, token)| {
                                token_word_eq(Some(token), "AS").then_some(idx)
                            })
                        {
                            let columns = if explicit_columns.is_empty() {
                                mysql_family_query_projection_columns(
                                    &tokens[as_idx + 1..statement_end],
                                    &catalog,
                                )
                            } else {
                                explicit_columns
                            };
                            insert_script_relation_columns(
                                &mut catalog,
                                &name,
                                &qualified_name,
                                columns,
                            );
                        }
                    }
                }
                "PROCEDURE" => {
                    if let Some(name) = token_word_text(tokens.get(name_idx)) {
                        push_unique_case_insensitive(&mut catalog.procedures, name);
                    }
                }
                "FUNCTION" => {
                    if let Some(name) = token_word_text(tokens.get(name_idx)) {
                        push_unique_case_insensitive(&mut catalog.functions, name);
                    }
                }
                "TRIGGER" => {
                    if token_word_eq(tokens.get(name_idx), "IF")
                        && token_word_eq(tokens.get(name_idx + 1), "NOT")
                        && token_word_eq(tokens.get(name_idx + 2), "EXISTS")
                    {
                        name_idx += 3;
                    }
                    if let Some((name, _)) = script_object_name_at(&tokens, name_idx) {
                        push_unique_case_insensitive(&mut catalog.triggers, &name);
                    }
                }
                "EVENT" => {
                    if let Some((name, _)) = script_object_name_at(&tokens, name_idx) {
                        push_unique_case_insensitive(&mut catalog.events, &name);
                    }
                }
                "SEQUENCE" => {
                    if let Some((name, _)) = script_object_name_at(&tokens, name_idx) {
                        push_unique_case_insensitive(&mut catalog.sequences, &name);
                    }
                }
                "INDEX" => {
                    if let Some((name, _)) = script_object_name_at(&tokens, name_idx) {
                        push_unique_case_insensitive(&mut catalog.indexes, &name);
                    }
                }
                "DATABASE" | "SCHEMA" => {
                    let mut schema_name_idx = name_idx;
                    if token_word_eq(tokens.get(schema_name_idx), "IF")
                        && token_word_eq(tokens.get(schema_name_idx + 1), "NOT")
                        && token_word_eq(tokens.get(schema_name_idx + 2), "EXISTS")
                    {
                        schema_name_idx += 3;
                    }
                    if let Some(name) = token_word_text(tokens.get(schema_name_idx)) {
                        push_unique_case_insensitive(&mut catalog.schemas, name);
                        push_unique_case_insensitive(&mut catalog.users, name);
                    }
                }
                "ROLE" | "USER" => {
                    if let Some(name) = token_word_text(tokens.get(name_idx)) {
                        push_unique_case_insensitive(&mut catalog.users, name);
                    }
                }
                "PACKAGE" => {
                    if let Some((name, _)) = script_object_name_at(&tokens, name_idx) {
                        push_unique_case_insensitive(&mut catalog.packages, &name);
                    }
                }
                _ => {}
            }
        }
        idx += 1;
    }
    let mut idx = 0usize;
    while idx < tokens.len() {
        if !token_word_eq(tokens.get(idx), "ALTER") {
            idx += 1;
            continue;
        }
        let statement_end = tokens
            .iter()
            .enumerate()
            .skip(idx + 1)
            .find_map(|(token_idx, token)| {
                matches!(token, SqlToken::Symbol(symbol) if symbol == ";").then_some(token_idx)
            })
            .unwrap_or(tokens.len());
        let Some(view_idx) = tokens
            .iter()
            .enumerate()
            .take(statement_end)
            .skip(idx + 1)
            .find_map(|(token_idx, token)| {
                token_word_eq(Some(token), "VIEW").then_some(token_idx)
            })
        else {
            idx = statement_end.saturating_add(1);
            continue;
        };
        let Some((name, qualified_name, after_name_idx)) =
            script_qualified_object_name_at(&tokens, view_idx + 1)
        else {
            idx = statement_end.saturating_add(1);
            continue;
        };
        push_unique_case_insensitive(&mut catalog.views, &name);
        let explicit_columns = tokens
            .iter()
            .enumerate()
            .take(statement_end)
            .skip(after_name_idx)
            .find(|(_, token)| !matches!(token, SqlToken::Comment(_)))
            .filter(
                |(_, token)| matches!(token, SqlToken::Symbol(symbol) if symbol == "("),
            )
            .map(|(open_idx, _)| {
                script_parameter_names_from_open_paren(&tokens, open_idx)
                    .into_iter()
                    .map(|column| crate::sql_text::strip_identifier_quotes(&column))
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        let inferred_columns = tokens
            .iter()
            .enumerate()
            .take(statement_end)
            .skip(after_name_idx)
            .find_map(|(token_idx, token)| {
                token_word_eq(Some(token), "AS").then_some(token_idx)
            })
            .map(|as_idx| {
                mysql_family_query_projection_columns(
                    &tokens[as_idx + 1..statement_end],
                    &catalog,
                )
            })
            .unwrap_or_default();
        insert_script_relation_columns(
            &mut catalog,
            &name,
            &qualified_name,
            if explicit_columns.is_empty() {
                inferred_columns
            } else {
                explicit_columns
            },
        );
        idx = statement_end.saturating_add(1);
    }
    let mut idx = 0usize;
    while idx + 4 < tokens.len() {
        if token_word_eq(tokens.get(idx), "ALTER") && token_word_eq(tokens.get(idx + 1), "TABLE") {
            if let Some(table_name) = token_word_text(tokens.get(idx + 2)) {
                let statement_end = tokens
                    .iter()
                    .enumerate()
                    .skip(idx + 3)
                    .find_map(|(token_idx, token)| {
                        matches!(token, SqlToken::Symbol(symbol) if symbol == ";")
                            .then_some(token_idx)
                    })
                    .unwrap_or(tokens.len());
                let columns = catalog
                    .columns
                    .entry(table_name.to_ascii_uppercase())
                    .or_default();
                let mut action_idx = idx + 3;
                while action_idx + 2 < statement_end {
                    if token_word_eq(tokens.get(action_idx), "ADD")
                        && token_word_eq(tokens.get(action_idx + 1), "COLUMN")
                    {
                        let mut column_idx = action_idx + 2;
                        if token_word_eq(tokens.get(column_idx), "IF")
                            && token_word_eq(tokens.get(column_idx + 1), "NOT")
                            && token_word_eq(tokens.get(column_idx + 2), "EXISTS")
                        {
                            column_idx += 3;
                        }
                        if let Some(column) = token_word_text(tokens.get(column_idx)) {
                            push_unique_case_insensitive(columns, column);
                        }
                    }
                    if token_word_eq(tokens.get(action_idx), "CHANGE") {
                        let old_name_idx = if token_word_eq(tokens.get(action_idx + 1), "COLUMN") {
                            action_idx + 2
                        } else {
                            action_idx + 1
                        };
                        if let Some(column) = token_word_text(tokens.get(old_name_idx + 1)) {
                            push_unique_case_insensitive(columns, column);
                        }
                    }
                    if token_word_eq(tokens.get(action_idx), "RENAME")
                        && token_word_eq(tokens.get(action_idx + 1), "COLUMN")
                    {
                        if let Some(column) = token_word_text(tokens.get(action_idx + 2)) {
                            push_unique_case_insensitive(columns, column);
                        }
                        if token_word_eq(tokens.get(action_idx + 3), "TO") {
                            if let Some(column) = token_word_text(tokens.get(action_idx + 4)) {
                                push_unique_case_insensitive(columns, column);
                            }
                        }
                    }
                    action_idx += 1;
                }
            }
        }
        if token_word_eq(tokens.get(idx), "RENAME")
            && token_word_eq(tokens.get(idx + 1), "TABLE")
        {
            let statement_end = tokens
                .iter()
                .enumerate()
                .skip(idx + 2)
                .find_map(|(token_idx, token)| {
                    matches!(token, SqlToken::Symbol(symbol) if symbol == ";")
                        .then_some(token_idx)
                })
                .unwrap_or(tokens.len());
            let mut pair_idx = idx + 2;
            while pair_idx < statement_end {
                let Some((old_name, old_qualified_name, after_old_idx)) =
                    script_qualified_object_name_at(&tokens, pair_idx)
                else {
                    break;
                };
                if !token_word_eq(tokens.get(after_old_idx), "TO") {
                    break;
                }
                let Some((new_name, new_qualified_name, after_new_idx)) =
                    script_qualified_object_name_at(&tokens, after_old_idx + 1)
                else {
                    break;
                };
                push_unique_case_insensitive(&mut catalog.tables, &new_name);
                let columns = catalog
                    .columns
                    .get(&old_qualified_name.to_ascii_uppercase())
                    .or_else(|| catalog.columns.get(&old_name.to_ascii_uppercase()))
                    .cloned()
                    .unwrap_or_default();
                insert_script_relation_columns(
                    &mut catalog,
                    &new_name,
                    &new_qualified_name,
                    columns,
                );
                pair_idx = after_new_idx;
                if matches!(
                    tokens.get(pair_idx),
                    Some(SqlToken::Symbol(symbol)) if symbol == ","
                ) {
                    pair_idx += 1;
                } else {
                    break;
                }
            }
        } else if token_word_eq(tokens.get(idx), "RENAME")
            && token_word_eq(tokens.get(idx + 2), "TO")
        {
            if let (Some(old_name), Some(new_name)) = (
                token_word_text(tokens.get(idx + 1)),
                token_word_text(tokens.get(idx + 3)),
            ) {
                push_unique_case_insensitive(&mut catalog.tables, new_name);
                if let Some(columns) =
                    catalog.columns.get(&old_name.to_ascii_uppercase()).cloned()
                {
                    insert_script_relation_columns(
                        &mut catalog,
                        new_name,
                        new_name,
                        columns,
                    );
                }
            }
        }
        idx += 1;
    }
    for name in collect_mysql_create_routine_names_from_text(script, "PROCEDURE") {
        push_unique_case_insensitive(&mut catalog.procedures, &name);
    }
    for name in collect_mysql_create_routine_names_from_text(script, "FUNCTION") {
        push_unique_case_insensitive(&mut catalog.functions, &name);
    }
    for name in collect_mysql_create_routine_names_from_text(script, "TRIGGER") {
        push_unique_case_insensitive(&mut catalog.triggers, &name);
    }
    for name in collect_mysql_create_routine_names_from_text(script, "EVENT") {
        push_unique_case_insensitive(&mut catalog.events, &name);
    }
    for name in collect_mysql_create_routine_names_from_text(script, "SEQUENCE") {
        push_unique_case_insensitive(&mut catalog.sequences, &name);
    }
    for idx in 0..tokens.len() {
        if token_word_eq(tokens.get(idx), "CONSTRAINT") {
            if let Some((name, _)) = script_object_name_at(&tokens, idx + 1) {
                push_unique_case_insensitive(&mut catalog.constraints, &name);
            }
        }
    }
    for (table, columns) in collect_mysql_temporary_tables_from_text(script) {
        push_unique_case_insensitive(&mut catalog.tables, &table);
        if !columns.is_empty() {
            catalog.columns.insert(table.to_ascii_uppercase(), columns);
        }
    }
    for (table, columns) in collect_mssql_bracket_tables_from_text(script) {
        push_unique_case_insensitive(&mut catalog.tables, &table);
        if !columns.is_empty() {
            catalog.columns.insert(table.to_ascii_uppercase(), columns);
        }
    }
    let script_tokens = super::query_text::tokenize_sql(script);
    collect_partition_names(&script_tokens, &mut catalog.partitions);
    collect_added_index_names(&script_tokens, &mut catalog.indexes);
    catalog
}

fn intellisense_data_from_mysql_family_catalog(
    catalog: &MysqlFamilyScriptCatalog,
) -> IntellisenseData {
    let mut data = IntellisenseData::new();
    data.tables = catalog.tables.clone();
    data.views = catalog.views.clone();
    data.materialized_views = catalog.materialized_views.clone();
    data.types = catalog.types.clone();
    data.procedures = catalog.procedures.clone();
    data.functions = catalog.functions.clone();
    data.packages = catalog.packages.clone();
    data.sequences = catalog.sequences.clone();
    data.synonyms = catalog.synonyms.clone();
    data.public_synonyms = catalog.public_synonyms.clone();
    data.directories = catalog.directories.clone();
    data.triggers = catalog.triggers.clone();
    data.events = catalog.events.clone();
    data.indexes = catalog.indexes.clone();
    data.constraints = catalog.constraints.clone();
    data.partitions = catalog.partitions.clone();
    data.schemas = catalog.schemas.clone();
    data.users = catalog.users.clone();
    // The fixtures use a single database, so every collected schema object is
    // reachable through the schema qualifier (`sq_hard_mysql.sq_hard_w6_series`).
    for schema in &catalog.schemas {
        let members = catalog
            .tables
            .iter()
            .map(|name| (name.clone(), Some(QualifiedMemberKind::Table)))
            .chain(
                catalog
                    .views
                    .iter()
                    .map(|name| (name.clone(), Some(QualifiedMemberKind::View))),
            )
            .chain(
                catalog
                    .materialized_views
                    .iter()
                    .map(|name| (name.clone(), Some(QualifiedMemberKind::MaterializedView))),
            )
            .chain(
                catalog
                    .procedures
                    .iter()
                    .map(|name| (name.clone(), Some(QualifiedMemberKind::Procedure))),
            )
            .chain(
                catalog
                    .functions
                    .iter()
                    .map(|name| (name.clone(), Some(QualifiedMemberKind::Function))),
            )
            .chain(
                catalog
                    .packages
                    .iter()
                    .map(|name| (name.clone(), Some(QualifiedMemberKind::Package))),
            )
            .collect();
        data.set_members_for_qualifier_with_kinds(schema, members);
    }
    for relation in catalog
        .tables
        .iter()
        .chain(catalog.views.iter())
        .chain(catalog.materialized_views.iter())
        .chain(catalog.functions.iter())
    {
        if let Some(columns) = catalog.columns.get(&relation.to_ascii_uppercase()) {
            data.set_columns_for_table(relation, columns.clone());
        }
    }
    for (relation, columns) in &catalog.columns {
        data.set_columns_for_table(relation, columns.clone());
    }
    for schema in &catalog.schemas {
        for relation in catalog
            .tables
            .iter()
            .chain(catalog.views.iter())
            .chain(catalog.materialized_views.iter())
            .chain(catalog.functions.iter())
        {
            if let Some(columns) = catalog.columns.get(&relation.to_ascii_uppercase()) {
                data.set_columns_for_table(&format!("{schema}.{relation}"), columns.clone());
            }
        }
    }
    for routine in catalog.routine_return_types.keys() {
        if let Some(columns) = catalog.columns.get(routine) {
            data.set_columns_for_table(routine, columns.clone());
        }
    }
    for (key, label) in &catalog.signatures {
        data.set_signature(key.clone(), Some(label.clone()));
    }
    for (type_name, members) in &catalog.type_members {
        data.set_members_for_qualifier(type_name, members.clone());
    }
    for (table_column, type_name) in &catalog.column_object_types {
        // Only object types the script actually declared can own members.
        if !catalog
            .type_members
            .keys()
            .any(|declared| declared.eq_ignore_ascii_case(type_name))
        {
            continue;
        }
        if let Some((table, column)) = table_column.rsplit_once('.') {
            data.set_object_type_for_column(table, column, type_name);
        }
    }
    for (collection_type, element_type) in &catalog.collection_element_types {
        data.set_collection_element_type_for_type(collection_type, element_type);
    }
    for (relation, type_name) in &catalog.relation_object_types {
        data.set_object_type_for_relation(relation, type_name);
    }
    for (synonym, target) in &catalog.synonym_targets {
        data.set_synonym_target(synonym, target);
    }
    let mut members_by_qualifier =
        HashMap::<String, Vec<(String, Option<QualifiedMemberKind>)>>::new();
    for key in catalog.signatures.keys() {
        let Some((qualifier, member)) = key.rsplit_once('.') else {
            continue;
        };
        let members = members_by_qualifier
            .entry(qualifier.to_string())
            .or_default();
        if members
            .iter()
            .all(|(name, _)| !name.eq_ignore_ascii_case(member))
        {
            members.push((
                member.to_string(),
                catalog.signature_kinds.get(key).copied(),
            ));
        }
    }
    for (qualifier, members) in members_by_qualifier {
        data.set_members_for_qualifier_with_kinds(&qualifier, members);
    }
    data.rebuild_indices();
    data
}

