/// A completed `BETWEEN lo AND hi` is a complete predicate, so the conjunction
/// (`AND`/`OR`) and the downstream clause openers must follow it - identical to
/// any other complete `WHERE`/`HAVING` predicate. Regression guard for the bug
/// where the predicate-completeness scan mistook the `BETWEEN` separator `AND`
/// for a boolean conjunction and split off a bare `hi` operand with no operator,
/// leaving the popup silent. The intermediate `BETWEEN lo |` slot (still awaiting
/// `AND`) and the open `BETWEEN lo AND |` slot must NOT offer the openers.
#[test]
fn completed_between_predicate_offers_conjunction_and_clause_openers() {
    let has = |v: &[String], s: &str| v.iter().any(|x| x == s);
    let kw = |sql: &str, db: crate::db::DatabaseType| {
        let cursor = sql.find('|').expect("cursor marker");
        let s = sql.replace('|', "");
        let prefix = crate::ui::intellisense::get_word_at_cursor(&s, cursor).0;
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    // Completed BETWEEN -> conjunction + downstream openers, both dialects, in
    // both standalone and second-conjunct positions, and when negated.
    for sql in [
        "SELECT a FROM t WHERE x BETWEEN 1 AND 2 |",
        "SELECT a FROM t WHERE x NOT BETWEEN 1 AND 2 |",
        "SELECT a FROM t WHERE a = 1 AND x BETWEEN 1 AND 2 |",
        "SELECT a FROM t HAVING count(*) BETWEEN 1 AND 2 |",
    ] {
        for db in [Oracle, MySQL, MariaDB] {
            let got = kw(sql, db);
            assert!(
                has(&got, "AND") && has(&got, "OR"),
                "conjunction for `{sql}` {db:?}: {got:?}"
            );
            assert!(has(&got, "ORDER BY"), "openers for `{sql}` {db:?}: {got:?}");
        }
    }

    // A *conjunction* after a completed BETWEEN starts a fresh conjunct, which is
    // incomplete -> no openers (but the column position is live).
    for sql in [
        "SELECT a FROM t WHERE x BETWEEN 1 AND 2 AND |", // fresh conjunct
        "SELECT a FROM t WHERE x BETWEEN 1 AND |",       // awaiting hi operand
        "SELECT a FROM t WHERE x BETWEEN 1 |",           // awaiting AND (offers AND only)
    ] {
        assert!(
            !has(&kw(sql, Oracle), "ORDER BY") && !has(&kw(sql, Oracle), "GROUP BY"),
            "opener leaked at incomplete BETWEEN `{sql}`: {:?}",
            kw(sql, Oracle)
        );
    }
    // Mid-BETWEEN still offers exactly `AND`.
    assert_eq!(
        kw("SELECT a FROM t WHERE x BETWEEN 1 |", Oracle),
        vec!["AND".to_string()]
    );
}

/// The empty `GROUP BY |` slot is a column position, not a complete grouping
/// item: the downstream clause openers (`HAVING`/`ORDER BY`/`LIMIT`/…) must not
/// leak there. Regression guard for the MySQL path where the clause keyword `BY`
/// was mistaken for a complete operand. (Oracle intercepts this slot with its
/// `ROLLUP`/`CUBE`/`GROUPING SETS` openers, which is correct and preserved.)
#[test]
fn empty_group_by_slot_does_not_leak_downstream_openers() {
    let kw = |sql: &str, db: crate::db::DatabaseType| {
        let cursor = sql.find('|').expect("cursor marker");
        let s = sql.replace('|', "");
        let prefix = crate::ui::intellisense::get_word_at_cursor(&s, cursor).0;
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    for db in [MySQL, MariaDB] {
        let got = kw("SELECT a, count(*) FROM t GROUP BY |", db);
        for leaked in ["HAVING", "ORDER BY", "LIMIT", "UNION", "FOR UPDATE"] {
            assert!(
                !got.iter().any(|k| k == leaked),
                "`{leaked}` leaked at empty GROUP BY for {db:?}: {got:?}"
            );
        }
    }

    // A *complete* grouping item still offers the downstream openers.
    assert!(kw("SELECT a, count(*) FROM t GROUP BY a |", MySQL)
        .iter()
        .any(|k| k == "HAVING"));

    // Oracle keeps its grouping-set openers at the empty slot.
    let oracle = kw("SELECT a, count(*) FROM t GROUP BY |", Oracle);
    assert!(oracle.iter().any(|k| k == "ROLLUP"), "{oracle:?}");
}

#[test]
fn mysql_family_boolean_literal_join_condition_completes_join() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);
    let final_suggestions = |sql: &str, db| audit_final_suggestions_for(sql, db).2;

    for db in [MySQL, MariaDB] {
        let join = final_suggestions("SELECT * FROM t1 JOIN t ON TRUE JOI|", db);
        assert!(
            contains(&join, "JOIN"),
            "JOIN missing after a complete TRUE join condition for {db:?}: {join:?}"
        );

        let where_clause = final_suggestions("SELECT * FROM t1 JOIN t ON FALSE WHER|", db);
        assert!(
            contains(&where_clause, "WHERE"),
            "WHERE missing after a complete FALSE join condition for {db:?}: {where_clause:?}"
        );

        let set_branch_join =
            final_suggestions("SELECT 1 UNION ALL SELECT * FROM t1 JOIN t ON TRUE JOI|", db);
        assert!(
            contains(&set_branch_join, "JOIN"),
            "JOIN missing in the second UNION ALL branch for {db:?}: {set_branch_join:?}"
        );

        let recursive_sql = "WITH RECURSIVE graph_walk AS (
                SELECT 1 AS node_id
                UNION ALL
                SELECT edge.child_id
                FROM graph_walk AS w
                JOIN t AS parent ON parent.id = w.node_id
                JOIN JSON_TABLE(
                    parent.payload,
                    '$.edges[*]' COLUMNS (child_id INT PATH '$')
                ) AS edge ON TRUE
                JOI|
            )
            SELECT * FROM graph_walk";
        let recursive_context = analyze_inline_cursor_sql(recursive_sql);
        let recursive_join = final_suggestions(recursive_sql, db);
        assert!(
            contains(&recursive_join, "JOIN"),
            "JOIN missing after JSON_TABLE ... ON TRUE in a recursive CTE for {db:?}: \
             phase={:?}, cursor_token_len={}, current_query_end={}, current_query={:?}, \
             tokens={:?}, suggestions={recursive_join:?}",
            recursive_context.phase,
            recursive_context.cursor_token_len,
            SqlEditorWidget::cursor_token_len_in_current_query(&recursive_context),
            SqlEditorWidget::current_query_tokens(&recursive_context),
            recursive_context.statement_tokens,
        );

        for sql in [
            "SELECT * FROM t1 JOIN t ON |",
            "SELECT * FROM t1 JOIN t ON t.id |",
        ] {
            let incomplete = final_suggestions(sql, db);
            for leaked in ["JOIN", "WHERE", "GROUP BY", "ORDER BY", "LIMIT"] {
                assert!(
                    !contains(&incomplete, leaked),
                    "{leaked} leaked after incomplete join condition `{sql}` for {db:?}: {incomplete:?}"
                );
            }
        }
    }
}

/// After the *complete* content of a query clause, the downstream clause openers
/// (`GROUP BY`/`ORDER BY`/…) are offered - additively and in canonical order -
/// so the popup is no longer silent there. The completeness gating must keep them
/// out of every lookalike: a dangling/incomplete predicate, a mid-construct
/// operand, a partial clause opener, a non-SELECT statement, and a sub-expression.
#[test]
fn query_clause_continuation_offers_downstream_clause_openers() {
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));
    let kw = |sql: &str, db: crate::db::DatabaseType| {
        let cursor = sql.find('|').expect("cursor marker");
        let s = sql.replace('|', "");
        let prefix = crate::ui::intellisense::get_word_at_cursor(&s, cursor).0;
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    // Complete clauses -> downstream openers (Oracle).
    assert!(has(&kw("SELECT a FROM t |", Oracle), "ORDER BY"));
    assert!(has(&kw("SELECT a FROM t alias |", Oracle), "WHERE"));
    assert!(has(
        &kw("SELECT a FROM t WHERE a = 1 |", Oracle),
        "ORDER BY"
    ));
    assert!(has(
        &kw("SELECT a FROM t WHERE a = 1 |", Oracle),
        "GROUP BY"
    ));
    assert!(has(&kw("SELECT a FROM t GROUP BY a |", Oracle), "HAVING"));
    assert!(has(
        &kw(
            "SELECT a, count(*) FROM t GROUP BY a HAVING count(*) > 1 |",
            Oracle
        ),
        "ORDER BY"
    ));
    assert!(has(
        &kw("SELECT a FROM t WHERE upper(a) = upper(b) |", Oracle),
        "ORDER BY"
    ));
    // MySQL-family uses LIMIT, never CONNECT BY / OFFSET-FETCH.
    for db in [MySQL, MariaDB] {
        let got = kw("SELECT a FROM t WHERE a = 1 |", db);
        assert!(has(&got, "LIMIT"), "{db:?} uses LIMIT: {got:?}");
        assert!(!has(&got, "CONNECT BY"), "{db:?} no CONNECT BY: {got:?}");

        let boolean_call = kw(
            "SELECT a FROM t1 JOIN t2 ON MBRContains(t2.shape, t1.point) AND ST_Contains(t2.shape, t1.point) |",
            db,
        );
        assert!(
            has(&boolean_call, "JOIN") && has(&boolean_call, "WHERE"),
            "{db:?} complete boolean function condition should admit another join or clause: {boolean_call:?}"
        );
    }

    // Incomplete / lookalike positions -> no openers.
    for sql in [
        "SELECT a FROM t WHERE a |",           // dangling operand (no comparison)
        "SELECT a FROM t WHERE a = |",         // open operator
        "SELECT a FROM t WHERE a = 1 AND |",   // open conjunction
        "SELECT a FROM t WHERE a + 1 |",       // arithmetic, no comparison
        "SELECT a FROM t WHERE x BETWEEN 1 |", // mid-construct (awaits AND)
        "SELECT a FROM t WHERE obj IS A |",    // mid IS predicate (awaits SET)
        "SELECT a FROM t WHERE obj IS OF TYPE |",
        "SELECT a FROM t1, |",           // fresh table position
        "SELECT a FROM t GROUP BY a, |", // fresh group item
        "SELECT a FROM t CONNECT BY PRIOR a = b ORDER SIBLINGS |", // partial opener
    ] {
        assert!(
            !has(&kw(sql, Oracle), "ORDER BY") && !has(&kw(sql, Oracle), "GROUP BY"),
            "clause opener leaked at incomplete position `{sql}`: {:?}",
            kw(sql, Oracle)
        );
    }

    // `IS NULL` *is* a complete predicate, so openers return there.
    assert!(has(
        &kw("SELECT a FROM t WHERE a IS NULL |", Oracle),
        "ORDER BY"
    ));

    // DELETE/UPDATE are not SELECTs: Oracle offers DML RETURNING, not query
    // clauses; MySQL-family allows only ORDER BY + LIMIT after the WHERE.
    assert_eq!(
        kw("DELETE FROM emp WHERE a = 1 |", Oracle),
        vec!["RETURNING".to_string()]
    );
    assert_eq!(
        kw("UPDATE emp SET a = 1 WHERE b = 2 |", Oracle),
        vec!["RETURNING".to_string()]
    );
    for db in [MySQL, MariaDB] {
        assert_eq!(
            kw("DELETE FROM emp WHERE a = 1 |", db),
            vec!["ORDER BY".to_string(), "LIMIT".to_string()],
            "{db:?} DELETE tail"
        );
        assert!(
            !has(&kw("UPDATE emp SET a = 1 WHERE b = 2 |", db), "GROUP BY"),
            "{db:?} UPDATE tail must not offer GROUP BY"
        );
    }
}

/// `INSERT/REPLACE INTO t (cols) |` offers the value source (`VALUES`/`SELECT`;
/// MySQL also admits a CTE `WITH`) and suppresses relations, mirroring the
/// bare-target `INSERT INTO t |` slot. The hint must not re-appear once the source
/// is supplied (`VALUES (…) |`).
#[test]
fn insert_after_column_list_offers_value_source() {
    let kw = |sql: &str, db: crate::db::DatabaseType| {
        let cursor = sql.find('|').expect("cursor marker");
        let s = sql.replace('|', "");
        let prefix = crate::ui::intellisense::get_word_at_cursor(&s, cursor).0;
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};
    let values_select = vec!["VALUES".to_string(), "SELECT".to_string()];
    assert_eq!(
        kw("INSERT INTO emp (a, b) |", Oracle),
        values_select.clone()
    );
    assert_eq!(
        kw("INSERT INTO emp |", Oracle),
        vec!["SET", "BY NAME", "VALUES", "SELECT"]
    );
    assert_eq!(
        kw("INSERT INTO emp (a, b) |", MySQL),
        vec!["VALUES", "SELECT", "WITH"]
    );
    assert_eq!(
        kw("INSERT INTO emp (a, b) |", MariaDB),
        vec!["VALUES", "SELECT", "WITH"]
    );
    assert_eq!(
        kw("REPLACE INTO emp (a) |", MySQL),
        vec!["VALUES", "SELECT", "WITH"]
    );
    assert_eq!(
        kw("REPLACE INTO emp (a) |", MariaDB),
        vec!["VALUES", "SELECT", "WITH"]
    );
    // Already-supplied source: no value-source re-emission.
    for sql in [
        "INSERT INTO emp VALUES (1, 2) |",
        "INSERT INTO emp (a, b) VALUES (1, 2) |",
    ] {
        let got = kw(sql, Oracle);
        assert!(
            !got.iter().any(|item| item == "VALUES"),
            "VALUES leaked for `{sql}`: {got:?}"
        );
        assert!(
            !got.iter().any(|item| item == "SELECT"),
            "SELECT leaked for `{sql}`: {got:?}"
        );
    }
}

#[test]
fn window_order_by_sort_modifier_slots_are_scoped_to_sort_tails() {
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));
    let kw = |sql: &str, prefix: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let suppresses = |sql: &str| {
        let cursor = sql.find('|').expect("cursor marker");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(
            &analyze_inline_cursor_sql(sql),
            !prefix.is_empty(),
        )
    };

    // Window ORDER BY null-ordering keywords are not valid anywhere in the
    // window specification; they only belong after a sort expression.
    let partition =
        typed_emp_suggestions("SELECT sum(empno) OVER (PARTITION BY empno nul|) FROM emp");
    assert!(
        !has(&partition, "NULLS"),
        "NULLS leaked in a PARTITION BY expression: {partition:?}"
    );
    let order_expr =
        typed_emp_suggestions("SELECT sum(empno) OVER (ORDER BY hiredate fir|) FROM emp");
    assert!(
        !has(&order_expr, "FIRST"),
        "FIRST leaked before NULLS in a window ORDER BY: {order_expr:?}"
    );
    let last_expr =
        typed_emp_suggestions("SELECT sum(empno) OVER (ORDER BY hiredate las|) FROM emp");
    assert!(
        !has(&last_expr, "LAST"),
        "LAST leaked before NULLS in a window ORDER BY: {last_expr:?}"
    );
    for (sql, keyword) in [
        (
            "SELECT sum(empno) OVER (PARTITION BY empno row|) FROM emp",
            "ROWS",
        ),
        (
            "SELECT sum(empno) OVER (PARTITION BY empno ran|) FROM emp",
            "RANGE",
        ),
        (
            "SELECT sum(empno) OVER (PARTITION BY empno gro|) FROM emp",
            "GROUPS",
        ),
    ] {
        let suggestions = typed_emp_suggestions(sql);
        assert!(
            !has(&suggestions, keyword),
            "{keyword} leaked after a window PARTITION BY expression: {suggestions:?}"
        );
    }

    assert_eq!(
        kw(
            "SELECT sum(empno) OVER (ORDER BY hiredate nul|) FROM emp",
            "nul"
        ),
        vec!["NULLS".to_string()]
    );
    assert_eq!(
        kw(
            "SELECT sum(empno) OVER (ORDER BY hiredate d|) FROM emp",
            "d"
        ),
        vec!["DESC".to_string()]
    );
    assert_eq!(
        kw(
            "SELECT sum(empno) OVER (ORDER BY hiredate DESC NULLS f|) FROM emp",
            "f"
        ),
        vec!["FIRST".to_string()]
    );
    assert_eq!(
        kw(
            "SELECT sum(empno) OVER (ORDER BY hiredate NULLS |) FROM emp",
            ""
        ),
        vec!["FIRST".to_string(), "LAST".to_string()]
    );
    assert_eq!(
        kw(
            "SELECT sum(empno) OVER (ORDER BY hiredate NULLS FIRST row|) FROM emp",
            "row"
        ),
        vec!["ROWS".to_string()]
    );

    for sql in [
        "SELECT sum(empno) OVER (ORDER BY hiredate DESC |) FROM emp",
        "SELECT sum(empno) OVER (ORDER BY hiredate NULLS |) FROM emp",
        "SELECT sum(empno) OVER (ORDER BY hiredate NULLS FIRST |) FROM emp",
    ] {
        assert!(
            suppresses(sql),
            "window sort modifier tail must suppress `{sql}`"
        );
    }
}

/// The definition-list classifier keys off the `TABLE` keyword, so it must not
/// engage for statements that merely contain `TABLE` without being a
/// `CREATE TABLE` / `ALTER TABLE` definition (`CREATE TYPE … AS TABLE OF …`),
/// nor for `ALTER` of a non-table object, nor leak across a statement boundary.
#[test]
fn ddl_definition_list_detector_does_not_misfire_on_lookalikes() {
    // `TABLE` keyword present but not a table-definition list.
    for sql in [
        "CREATE TYPE my_type AS TABLE OF |",
        "CREATE OR REPLACE TYPE t AS TABLE OF | NUMBER",
        "ALTER INDEX idx REBUILD |",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(!ctx.ddl_new_name_position, "{sql}");
        assert_eq!(
            ctx.phase,
            intellisense_context::SqlPhase::Initial,
            "phase for `{sql}`"
        );
    }

    // A prior statement must not bleed into the cursor's statement.
    let after_semicolon =
        analyze_inline_cursor_sql("SELECT * FROM dept; ALTER TABLE emp ADD PRIMARY KEY (|)");
    assert_eq!(
        after_semicolon.phase,
        intellisense_context::SqlPhase::DdlColumnList
    );
    assert_eq!(after_semicolon.focused_tables, vec!["emp".to_string()]);

    let ddl_then_select =
        analyze_inline_cursor_sql("ALTER TABLE emp ADD (a NUMBER); SELECT | FROM dept");
    assert!(!ddl_then_select.ddl_new_name_position);
    assert_eq!(
        ddl_then_select.phase,
        intellisense_context::SqlPhase::SelectList
    );
}

fn mysql_context_and_suggestions_for_inline_sql(
    sql_with_cursor: &str,
    db: crate::db::DatabaseType,
) -> (SqlContext, Vec<String>) {
    let cursor = sql_with_cursor
        .find('|')
        .expect("cursor marker should exist");
    let sql = sql_with_cursor.replace('|', "");
    let token_spans = super::query_text::tokenize_sql_spanned(&sql);
    let split_idx = token_spans.partition_point(|span| span.end <= cursor);
    let full_tokens: Vec<SqlToken> = token_spans.into_iter().map(|span| span.token).collect();
    let deep_ctx = intellisense_context::analyze_cursor_context_owned(full_tokens, split_idx);
    let context = SqlEditorWidget::classify_intellisense_context(
        &deep_ctx,
        deep_ctx.statement_tokens.as_ref(),
    );
    let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
    let mut data = IntellisenseData::new();
    let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
        &deep_ctx,
        &data,
        &[],
        !prefix.is_empty(),
        Some(db),
    );
    let suggestions = SqlEditorWidget::base_suggestions_for_context(
        &mut data,
        &prefix,
        None,
        None,
        matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
        context,
        false,
        Some(db),
        expr_keyword_ctx,
    );

    (context, suggestions)
}

// Production view: the shared context-resolved merge pipeline. There is no
// catalog-wide widening layer after this result.
#[test]
fn production_sources_have_no_contextless_catalog_widening_hooks() {
    let completion = include_str!("completion.rs");
    let data = include_str!("../../intellisense.rs");

    for removed in [
        "append_full_catalog_tail",
        "collect_full_catalog_tail_for_context",
        "cursor_offers_full_catalog_safety_net",
        "collect_all_completion_fallback_suggestions_for_db",
        "expected_object_kind_allows_all_completion_fallback",
        "expected_object_kind_allows_unknown_member_fallback",
        "suggestion_matches_expected_object_kind_for_db",
        "oracle_bounded_text_structural_keyword_prefix_fallback",
        "oracle_forward_visible_relation_tables_for_qualifier",
        "oracle_visible_relation_tables_from_statement_text",
        "oracle_visible_relation_tables_from_bounded_text",
        "oracle_statement_relation_alias_suggestions",
        "exact_catalog_keyword_for_prefix",
        "should_append_expected_catalog_keyword_after_context_filters",
        "append_catalog_keyword_suggestion",
        "should_append_exact_catalog_keyword_in_base_context",
        "append_exact_catalog_keyword_suggestion",
        "has_early_oracle_builtin_package_members",
    ] {
        assert!(
            !completion.contains(removed),
            "removed completion widening hook reappeared: {removed}"
        );
    }
    assert!(
        !completion.contains("get_column_suggestions(prefix, None)"),
        "production completion requested columns without a relation scope"
    );

    for removed in [
        "all_columns_entries",
        "ensure_all_columns_entries",
        "relation_lookup_short_key",
    ] {
        assert!(
            !data.contains(removed),
            "removed global/short-key cache hook reappeared: {removed}"
        );
    }
}

fn audit_final_suggestions_for(
    sql: &str,
    db: crate::db::DatabaseType,
) -> (
    Option<ExpectedObjectSuggestionKind>,
    Vec<String>,
    Vec<String>,
) {
    audit_final_suggestions_impl(sql, db)
}

