        let (default_context, default_suggestions) = mysql_context_and_suggestions_for_inline_sql(
            "CREATE TABLE demo (id INT) DEF| CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci",
            db,
        );
