        let (collate_context, collate_suggestions) = mysql_context_and_suggestions_for_inline_sql(
            "CREATE TABLE demo (id INT) DEFAULT CHARACTER SET utf8mb4 COL| utf8mb4_unicode_ci",
            db,
        );
