#[test]
fn collect_context_name_suggestions_in_table_context_keep_only_ctes() {
    let script = "WITH recent_emp AS (SELECT empno FROM emp)\nSELECT *\nFROM emp e\nCROSS APPLY (SELECT deptno FROM dept) sub\nJOIN __CODEX_CURSOR__";
    let (_statement, _cursor, deep_ctx) = analyze_full_script_marker(script);

    let suggestions =
        SqlEditorWidget::collect_context_name_suggestions("", &deep_ctx, SqlContext::TableName);
    let upper: Vec<String> = suggestions.into_iter().map(|s| s.to_uppercase()).collect();

    assert!(
        upper.contains(&"RECENT_EMP".to_string()),
        "suggestions: {:?}",
        upper
    );
    assert!(
        !upper.contains(&"E".to_string()),
        "suggestions: {:?}",
        upper
    );
    assert!(
        !upper.contains(&"SUB".to_string()),
        "suggestions: {:?}",
        upper
    );
}

#[test]
fn context_name_suggestions_are_suppressed_after_complete_operand() {
    let sql = "WITH recent_emp AS (SELECT empno FROM emp) \
               SELECT * FROM emp e WHERE empno e|";
    let cursor = sql.find('|').expect("cursor marker");
    let plain = sql.replace('|', "");
    let deep_ctx = analyze_inline_cursor_sql(sql);
    let context = SqlEditorWidget::classify_intellisense_context(
        &deep_ctx,
        deep_ctx.statement_tokens.as_ref(),
    );
    let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
    let data = IntellisenseData::new();
    let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
        &deep_ctx,
        &data,
        &[],
        !prefix.is_empty(),
        Some(crate::db::DatabaseType::Oracle),
    );

    assert_eq!(
        expr_keyword_ctx.follows_operand,
        Some(true),
        "test must exercise a post-operand expression slot"
    );
    let policy = CompletionSourcePolicy::new(false, false, false, false, false, expr_keyword_ctx);
    assert!(
        policy.suppresses_context_names(context, expr_keyword_ctx),
        "aliases/CTEs are identifier operands and must not be merged after a complete operand"
    );
}

#[test]
fn local_identifier_sources_are_suppressed_after_complete_operand() {
    let mut expr_keyword_ctx = ExpressionKeywordContext::ambiguous();
    let operand_start =
        CompletionSourcePolicy::new(false, false, false, false, false, expr_keyword_ctx).allowance(
            SqlContext::ColumnName,
            None,
            expr_keyword_ctx,
        );
    assert!(
        operand_start.session_bind_names
            && operand_start.local_suggestions
            && operand_start.prepend_local_symbol_suggestions,
        "local/session identifiers should stay available at an operand start"
    );

    expr_keyword_ctx.follows_operand = Some(true);
    let after_operand =
        CompletionSourcePolicy::new(false, false, false, false, false, expr_keyword_ctx).allowance(
            SqlContext::ColumnName,
            None,
            expr_keyword_ctx,
        );
    assert!(
        !after_operand.session_bind_names
            && !after_operand.local_suggestions
            && !after_operand.prepend_local_symbol_suggestions,
        "local/session identifiers are operand material and must not be merged after a complete operand"
    );
}

#[test]
fn collect_clause_wildcard_suggestions_for_select_list_include_star_and_scoped_rowsources() {
    let deep_ctx = analyze_inline_cursor_sql(
        "WITH recent_emp AS (SELECT empno FROM emp) \
         SELECT | \
         FROM emp e \
         JOIN recent_emp ON recent_emp.empno = e.empno \
         CROSS JOIN (SELECT deptno FROM dept) sub",
    );

    assert_eq!(deep_ctx.phase, intellisense_context::SqlPhase::SelectList);

    let suggestions = SqlEditorWidget::collect_clause_wildcard_suggestions("", None, &deep_ctx);

    assert_eq!(suggestions.first().map(String::as_str), Some("*"));
    assert_has_case_insensitive(&suggestions, "e.*");
    assert_has_case_insensitive(&suggestions, "recent_emp.*");
    assert_has_case_insensitive(&suggestions, "sub.*");
}

