/// `ALTER TABLE t ADD (…)` is a column-definition list, not a table target.
/// Each entry start is a brand-new column name (suppress identifiers) and a
/// position after the name is a data-type slot; neither should offer existing
/// relations or columns. Previously the parenthesised form fell through to the
/// DML machine's `IntoClause`/`DerivedAliasColumnList`, leaking table names and
/// the wrong table's columns.
#[test]
fn alter_table_add_column_definition_slots_are_new_name_positions() {
    for sql in [
        "ALTER TABLE emp ADD (|)",
        "ALTER TABLE emp ADD (col1 NUMBER, |)",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            ctx.ddl_new_name_position,
            "`{sql}` should be a DDL new-name position"
        );
    }

    // The slot after the new column name stays a data-type position (not a
    // name position), so dialect type keywords still appear there.
    let type_slot = analyze_inline_cursor_sql("ALTER TABLE emp ADD (col1 |)");
    assert!(!type_slot.ddl_new_name_position);
    assert!(SqlEditorWidget::data_type_position_for_context(&type_slot, false).is_some());
}

/// Constraint and `REFERENCES` column lists inside `ALTER TABLE … ADD …`
/// reference existing columns of a single table — the altered table for
/// `PRIMARY KEY`/`UNIQUE`/`FOREIGN KEY`, and the referenced table for
/// `REFERENCES x (…)`. They must classify as a column context focused on that
/// table, never offer relations.
#[test]
fn alter_table_add_constraint_column_lists_target_existing_columns() {
    for sql in [
        "ALTER TABLE emp ADD PRIMARY KEY (|)",
        "ALTER TABLE emp ADD UNIQUE (|)",
        "ALTER TABLE emp ADD CONSTRAINT pk PRIMARY KEY (|)",
        "ALTER TABLE emp ADD FOREIGN KEY (|) REFERENCES dept(id)",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert_eq!(
            ctx.phase,
            intellisense_context::SqlPhase::DdlColumnList,
            "phase for `{sql}`"
        );
        assert_eq!(ctx.focused_tables, vec!["emp".to_string()], "{sql}");
    }

    // The `REFERENCES <table> (…)` list targets the referenced table's columns.
    let references =
        analyze_inline_cursor_sql("ALTER TABLE emp ADD FOREIGN KEY (deptno) REFERENCES dept(|)");
    assert_eq!(
        references.phase,
        intellisense_context::SqlPhase::DdlColumnList
    );
    assert_eq!(references.focused_tables, vec!["dept".to_string()]);

    let qualified_references = analyze_inline_cursor_sql(
        "ALTER TABLE emp ADD FOREIGN KEY (deptno) REFERENCES scott.dept(|)",
    );
    assert_eq!(
        qualified_references.phase,
        intellisense_context::SqlPhase::DdlColumnList
    );
    assert_eq!(
        qualified_references.focused_tables,
        vec!["scott.dept".to_string()]
    );

    // A schema-qualified target keeps the qualifier so the right table's
    // columns are loaded.
    let qualified = analyze_inline_cursor_sql("ALTER TABLE scott.emp ADD PRIMARY KEY (|)");
    assert_eq!(
        qualified.phase,
        intellisense_context::SqlPhase::DdlColumnList
    );
    assert_eq!(qualified.focused_tables, vec!["scott.emp".to_string()]);
}

/// A `CHECK (…)` constraint is an expression over the altered table's columns,
/// so it must offer those columns — never relations. A type precision/size
/// argument (`NUMBER(…)`) is a numeric-literal slot and must stay suppressed
/// rather than leak columns. Both previously fell through to the DML machine.
#[test]
fn alter_table_add_check_and_type_precision_are_classified_precisely() {
    for sql in [
        "ALTER TABLE emp ADD CHECK (| > 0)",
        "ALTER TABLE emp ADD CONSTRAINT c CHECK (|)",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert_eq!(
            ctx.phase,
            intellisense_context::SqlPhase::DdlColumnList,
            "phase for `{sql}`"
        );
        assert_eq!(ctx.focused_tables, vec!["emp".to_string()], "{sql}");
    }

    // A type precision/size argument inside the definition list is a literal
    // position: suppressed, never the catalog or the altered table's columns.
    let precision = analyze_inline_cursor_sql("ALTER TABLE emp ADD (col1 NUMBER(|))");
    assert!(precision.ddl_new_name_position);
}

/// MySQL/MariaDB allow an index or constraint name between the `KEY`/`INDEX`
/// keyword and its column list (`ADD KEY idx (col)`, `ADD INDEX idx (col)`,
/// `ADD UNIQUE KEY uk (col)`, `ADD … FOREIGN KEY fk (col)`). The intervening
/// name must not break the column-list classification into a table target.
#[test]
fn alter_table_add_named_index_column_lists_target_existing_columns() {
    for sql in [
        "ALTER TABLE emp ADD INDEX idx (|)",
        "ALTER TABLE emp ADD KEY idx (|)",
        "ALTER TABLE emp ADD UNIQUE KEY uk (|)",
        "ALTER TABLE emp ADD CONSTRAINT fk FOREIGN KEY fk_name (|) REFERENCES dept(id)",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert_eq!(
            ctx.phase,
            intellisense_context::SqlPhase::DdlColumnList,
            "phase for `{sql}`"
        );
        assert_eq!(ctx.focused_tables, vec!["emp".to_string()], "{sql}");
    }
}

/// MySQL `CHANGE [COLUMN] old new …` names a brand-new column after the source
/// name; that slot (and the data type after it) must suppress identifiers
/// rather than offer existing relations. The source-name slot itself stays an
/// existing-column position.
#[test]
fn alter_table_change_new_name_slot_is_suppressed() {
    for sql in [
        "ALTER TABLE emp CHANGE old_col |",
        "ALTER TABLE emp CHANGE COLUMN old_col |",
        "ALTER TABLE emp CHANGE old_col new_col |",
        "ALTER TABLE emp CHANGE old_col scott.|",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(ctx.ddl_new_name_position, "`{sql}` should suppress");
    }

    // The source-column slot is still an existing-column position, not a new
    // name — including after the optional `COLUMN` keyword.
    for sql in [
        "ALTER TABLE emp CHANGE |",
        "ALTER TABLE emp CHANGE COLUMN |",
    ] {
        let source = analyze_inline_cursor_sql(sql);
        assert!(!source.ddl_new_name_position, "{sql}");
        assert_eq!(
            source.phase,
            intellisense_context::SqlPhase::DdlColumnList,
            "{sql}"
        );
        assert_eq!(source.focused_tables, vec!["emp".to_string()], "{sql}");
    }
}

#[test]
fn alter_table_qualified_new_name_slots_do_not_use_schema_members() {
    let mut data = IntellisenseData::new();
    data.set_members_for_qualifier_with_kinds(
        "SCOTT",
        vec![("EMP".to_string(), Some(QualifiedMemberKind::Table))],
    );
    data.set_relation_members_for_qualifier("SCOTT", vec!["EMP".to_string()]);

    for sql in [
        "ALTER TABLE emp ADD CONSTRAINT scott.|",
        "ALTER TABLE emp RENAME TO scott.|",
        "ALTER TABLE emp RENAME COLUMN old_col TO scott.|",
        "ALTER TABLE emp CHANGE old_col scott.|",
        "ALTER TABLE emp CHANGE COLUMN old_col scott.|",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            ctx.ddl_new_name_position,
            "`{sql}` should be a DDL new-name slot"
        );
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let mode =
            SqlEditorWidget::resolve_qualified_completion_mode("scott", context, &ctx, &data);
        assert_eq!(
            mode, None,
            "qualified DDL new-name slot must not switch to existing schema members for `{sql}`"
        );
    }
}

#[test]
fn alter_table_index_subcommand_object_slots_filter_to_indexes() {
    let mut data = IntellisenseData::new();
    data.tables = vec!["EMP".to_string()];
    data.indexes = vec!["EMP_PK".to_string()];
    data.rebuild_indices();

    for sql in [
        "ALTER TABLE emp DROP INDEX |",
        "ALTER TABLE emp DROP KEY |",
        "ALTER TABLE emp RENAME INDEX | TO emp_pk2",
        "ALTER TABLE emp RENAME KEY | TO emp_pk2",
        "ALTER TABLE emp ADD INDEX idx_emp (empno) COMMENT 'doc', DROP INDEX |",
        "ALTER TABLE emp ADD UNIQUE idx_emp (empno) COMMENT 'doc', RENAME INDEX | TO emp_pk2",
    ] {
        let suggestions = SqlEditorWidget::collect_expected_object_suggestions(
            &mut data,
            "",
            &analyze_inline_cursor_sql(sql),
        );
        assert_eq!(
            suggestions,
            vec!["EMP_PK".to_string()],
            "`{sql}` should suggest only existing indexes"
        );
    }

    let prefixed = analyze_inline_cursor_sql("ALTER TABLE emp DROP INDEX emp|");
    let prefixed_suggestions =
        SqlEditorWidget::collect_expected_object_suggestions(&mut data, "emp", &prefixed);
    assert_eq!(prefixed_suggestions, vec!["EMP_PK".to_string()]);

    let prefixed_after_index_option = analyze_inline_cursor_sql(
        "ALTER TABLE emp ADD INDEX idx_emp (empno) COMMENT 'doc', DROP INDEX emp|",
    );
    let prefixed_after_index_option_suggestions =
        SqlEditorWidget::collect_expected_object_suggestions(
            &mut data,
            "emp",
            &prefixed_after_index_option,
        );
    assert_eq!(
        prefixed_after_index_option_suggestions,
        vec!["EMP_PK".to_string()]
    );

    data.set_members_for_qualifier_with_kinds(
        "SCOTT",
        vec![
            ("EMP".to_string(), Some(QualifiedMemberKind::Table)),
            ("EMP_PK".to_string(), Some(QualifiedMemberKind::Index)),
        ],
    );
    let qualified = analyze_inline_cursor_sql("ALTER TABLE emp DROP INDEX scott.|");
    let qualified_suggestions = SqlEditorWidget::expected_member_suggestions_for_qualifier(
        &mut data, "scott", "", &qualified,
    );
    assert_eq!(
        qualified_suggestions,
        vec!["EMP_PK".to_string()],
        "qualified ALTER TABLE index slot must not leak schema tables"
    );

    let qualified_after_index_option = analyze_inline_cursor_sql(
        "ALTER TABLE emp ADD INDEX idx_emp (empno) COMMENT 'doc', DROP INDEX scott.|",
    );
    let qualified_after_index_option_suggestions =
        SqlEditorWidget::expected_member_suggestions_for_qualifier(
            &mut data,
            "scott",
            "",
            &qualified_after_index_option,
        );
    assert_eq!(
        qualified_after_index_option_suggestions,
        vec!["EMP_PK".to_string()],
        "qualified ALTER TABLE index slot after an index option must not leak schema tables"
    );
}

#[test]
fn alter_table_constraint_and_completed_object_slots_suppress_unrelated_identifiers() {
    let exclude_flag = |sql_with_cursor: &str| {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        !prefix.is_empty()
    };

    for sql in [
        "ALTER TABLE emp DROP FOREIGN KEY |",
        "ALTER TABLE emp DROP PRIMARY KEY |",
        "ALTER TABLE emp ENABLE PRIMARY KEY |",
        "ALTER TABLE emp DISABLE PRIMARY KEY |",
        "ALTER TABLE emp DROP PARTITION |",
        "ALTER TABLE emp DROP SUBPARTITION p1|",
        "ALTER TABLE emp TRUNCATE PARTITION |",
        "ALTER TABLE emp MOVE PARTITION p1|",
        "ALTER TABLE emp EXCHANGE PARTITION p1 |",
        "ALTER TABLE emp SPLIT PARTITION |",
        "ALTER TABLE emp MERGE PARTITIONS |",
        "ALTER TABLE emp COALESCE PARTITION |",
        "ALTER TABLE emp RENAME PARTITION | TO p2",
        "ALTER TABLE emp RENAME CONSTRAINT fk_emp |",
        "ALTER TABLE emp DROP INDEX EMP_PK |",
        "ALTER TABLE emp RENAME INDEX EMP_PK |",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            SqlEditorWidget::cursor_is_at_ddl_identifier_suppression_slot_for_context(
                &ctx,
                exclude_flag(sql),
            ),
            "`{sql}` should suppress unrelated identifier suggestions"
        );
    }

    for sql in [
        "ALTER TABLE emp DROP CONSTRAINT |",
        "ALTER TABLE emp DROP CONSTRAINT fk_emp|",
        "ALTER TABLE emp DROP CHECK |",
        "ALTER TABLE emp ENABLE CONSTRAINT |",
        "ALTER TABLE emp ENABLE NOVALIDATE CONSTRAINT |",
        "ALTER TABLE emp DISABLE CONSTRAINT fk_emp|",
        "ALTER TABLE emp VALIDATE CONSTRAINT |",
        "ALTER TABLE emp NOVALIDATE CONSTRAINT |",
        "ALTER TABLE emp MODIFY CONSTRAINT |",
        "ALTER TABLE emp RENAME CONSTRAINT | TO fk_emp2",
        "ALTER TABLE emp DROP INDEX |",
        "ALTER TABLE emp RENAME INDEX | TO emp_pk2",
        "ALTER TABLE emp RENAME INDEX EMP_PK TO |",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            !SqlEditorWidget::cursor_is_at_ddl_identifier_suppression_slot_for_context(
                &ctx,
                exclude_flag(sql),
            ),
            "`{sql}` is handled by exact object suggestions or new-name suppression"
        );
    }
}

#[test]
fn rename_statement_target_new_name_slots_are_suppressed() {
    let exclude_flag = |sql_with_cursor: &str| {
        sql_with_cursor
            .strip_suffix('|')
            .and_then(|sql| sql.chars().last())
            .is_some_and(|ch| ch.is_alphanumeric() || ch == '_' || ch == '.')
    };

    for sql in [
        "RENAME emp TO |",
        "RENAME emp TO new_emp|",
        "RENAME TABLE emp TO |",
        "RENAME TABLE emp TO new_emp|",
        "RENAME USER alice TO |",
        "RENAME USER alice TO bob|",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            ctx.ddl_new_name_position,
            "`{sql}` should suppress existing identifiers at the rename target"
        );
    }

    let mut data = IntellisenseData::new();
    data.set_members_for_qualifier_with_kinds(
        "SCOTT",
        vec![("EMP".to_string(), Some(QualifiedMemberKind::Table))],
    );
    data.set_relation_members_for_qualifier("SCOTT", vec!["EMP".to_string()]);
    for sql in [
        "RENAME emp TO scott.|",
        "RENAME TABLE emp TO scott.|",
        "RENAME USER alice TO scott.|",
    ] {
        let qualified_ctx = analyze_inline_cursor_sql(sql);
        assert!(
            qualified_ctx.ddl_new_name_position,
            "qualified rename target should still be a new-name slot for `{sql}`"
        );
        let context = SqlEditorWidget::classify_intellisense_context(
            &qualified_ctx,
            qualified_ctx.statement_tokens.as_ref(),
        );
        let mode = SqlEditorWidget::resolve_qualified_completion_mode(
            "scott",
            context,
            &qualified_ctx,
            &data,
        );
        assert_eq!(
            mode, None,
            "qualified rename target must not switch to existing schema members for `{sql}`"
        );
    }

    let source = analyze_inline_cursor_sql("RENAME | TO new_emp");
    assert!(
        !source.ddl_new_name_position,
        "rename source should still reference an existing object"
    );

    let next_source = analyze_inline_cursor_sql("RENAME TABLE emp TO emp2, |");
    assert!(
        !next_source.ddl_new_name_position,
        "next rename source should still reference an existing object"
    );

    for sql in [
        "RENAME TABLE emp TO emp2, dept TO |",
        "RENAME TABLE emp TO emp2, dept TO new_dept|",
        "RENAME USER alice TO bob, carol TO |",
        "RENAME USER alice TO bob, carol TO dave|",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            SqlEditorWidget::cursor_is_at_rename_target_new_name_slot_for_context(
                &ctx,
                exclude_flag(sql),
            ),
            "`{sql}` should suppress existing identifiers at a later rename target"
        );
    }
}

/// `CREATE TABLE … PARTITION BY {RANGE|HASH|LIST|RANGE COLUMNS} (…)` lists the
/// partitioning columns/expressions over the table's own columns — not a table
/// target. For `CREATE TABLE` the columns are defined in the same statement, so
/// the slot is suppressed rather than leaking the catalog. The partition-value
/// parens that follow must keep their ordinary classification.
#[test]
fn create_table_partition_column_list_never_offers_relations() {
    for sql in [
        "CREATE TABLE t (id NUMBER) PARTITION BY RANGE (|)",
        "CREATE TABLE t (id INT) PARTITION BY HASH (|)",
        "CREATE TABLE t (id INT) PARTITION BY LIST (|)",
        "CREATE TABLE t (a INT, b INT) PARTITION BY RANGE COLUMNS (|)",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            ctx.ddl_new_name_position,
            "`{sql}` partition column list should suppress relations"
        );
    }

    // The partition-value paren after the column list is not a column list.
    let bound = analyze_inline_cursor_sql(
        "CREATE TABLE t (id INT) PARTITION BY RANGE (id) (PARTITION p VALUES LESS THAN (|))",
    );
    assert!(!bound.ddl_new_name_position);
}

#[test]
fn partition_column_expression_slots_offer_only_target_columns_in_final_suggestions() {
    use crate::db::DatabaseType::{MySQL, Oracle};

    let contains_ci = |values: &[String], needle: &str| {
        values
            .iter()
            .any(|value| value.eq_ignore_ascii_case(needle))
    };
    let assert_no_catalog_noise = |sql: &str, suggestions: &[String]| {
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "APP_USER",
            "SCOTT",
            "RUN_JOB",
            "CALC_TOTAL",
            "ENAME",
            "DNAME",
        ] {
            assert!(
                !suggestions.iter().any(|value| value == leaked),
                "{leaked} leaked into partition column slot at `{sql}`: {suggestions:?}"
            );
        }
    };

    for (db, sql, expected) in [
        (
            Oracle,
            "CREATE TABLE new_emp (empno INT, deptno INT) PARTITION BY HASH (d|)",
            "deptno",
        ),
        (
            MySQL,
            "CREATE TABLE new_emp (empno INT, deptno INT) PARTITION BY HASH (d|)",
            "deptno",
        ),
        (
            MySQL,
            "CREATE TABLE new_emp (empno INT, deptno INT) PARTITION BY HASH (LOWER(d|))",
            "deptno",
        ),
        (
            Oracle,
            "CREATE TABLE new_emp (empno INT, deptno INT) PARTITION BY RANGE COLUMNS (|)",
            "empno",
        ),
        (Oracle, "ALTER TABLE emp PARTITION BY HASH (s|)", "SAL"),
        (
            MySQL,
            "ALTER TABLE emp PARTITION BY HASH (LOWER(s|))",
            "SAL",
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert_eq!(
            kind, None,
            "partition column slot should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            keywords.is_empty(),
            "partition column slot should not offer keywords at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            contains_ci(&final_suggestions, expected),
            "{expected} missing from partition column slot at `{sql}`: final={final_suggestions:?}"
        );
        assert_no_catalog_noise(sql, &final_suggestions);
    }

    let (_kind, _keywords, bound_suggestions) = audit_final_suggestions_for(
        "CREATE TABLE new_emp (empno INT) PARTITION BY RANGE (empno) (PARTITION p VALUES LESS THAN (e|))",
        Oracle,
    );
    assert!(
        !contains_ci(&bound_suggestions, "empno"),
        "partition value bound must not be treated as a partition column list: {bound_suggestions:?}"
    );
}

/// `CREATE TABLE … AS SELECT …` (CTAS) has no column-definition list: its
/// subquery and expression parens are ordinary query positions and must keep
/// their query classification, not be mistaken for a definition list. Guards
/// the "first paren after the table name" definition-list heuristic.
#[test]
fn create_table_as_select_parens_are_not_definition_lists() {
    let expr = analyze_inline_cursor_sql("CREATE TABLE t AS SELECT (| ) FROM dept");
    assert!(!expr.ddl_new_name_position);
    assert_eq!(expr.phase, intellisense_context::SqlPhase::SelectList);

    let subquery = analyze_inline_cursor_sql(
        "CREATE TABLE t AS SELECT * FROM dept WHERE deptno IN (SELECT | FROM emp)",
    );
    assert!(!subquery.ddl_new_name_position);
    assert_eq!(subquery.phase, intellisense_context::SqlPhase::SelectList);

    // A real definition list followed by `AS SELECT` still classifies its body
    // as a query.
    let mixed = analyze_inline_cursor_sql("CREATE TABLE t (id NUMBER) AS SELECT | FROM dept");
    assert!(!mixed.ddl_new_name_position);
    assert_eq!(mixed.phase, intellisense_context::SqlPhase::SelectList);
}

/// `CREATE TABLE (…)` column definitions name brand-new columns; the position
/// is a new-name slot, not a table target. Constraint sub-lists reference
/// columns defined in the same (not-yet-existing) statement, so they are left a
/// name position rather than leaking the catalog. The data-type slot is
/// unaffected.
#[test]
fn create_table_definition_slots_never_offer_relations() {
    for sql in [
        "CREATE TABLE t (|)",
        "CREATE TABLE t (id NUMBER, |)",
        "CREATE TABLE t (id NUMBER, PRIMARY KEY (|))",
        "CREATE TABLE t (id NUMBER, CONSTRAINT pk PRIMARY KEY (|))",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            ctx.ddl_new_name_position,
            "`{sql}` should be a DDL new-name position"
        );
    }

    let type_slot = analyze_inline_cursor_sql("CREATE TABLE t (id NUMBER, name |)");
    assert!(!type_slot.ddl_new_name_position);
    assert!(SqlEditorWidget::data_type_position_for_context(&type_slot, false).is_some());
}

/// `ALTER TABLE … MODIFY/DROP/RENAME …` (existing-column operations) and a
/// plain `CREATE TABLE … AS SELECT` must keep their established classification —
/// the new definition-list detector only governs `ADD`/`CREATE TABLE (…)` lists.
#[test]
fn ddl_definition_list_detector_leaves_other_alter_operations_intact() {
    for (sql, expected) in [
        (
            "ALTER TABLE emp MODIFY (|)",
            intellisense_context::SqlPhase::DdlColumnList,
        ),
        (
            "ALTER TABLE emp MODIFY |",
            intellisense_context::SqlPhase::DdlColumnList,
        ),
        (
            "ALTER TABLE emp DROP COLUMN |",
            intellisense_context::SqlPhase::DdlColumnList,
        ),
        (
            "ALTER TABLE emp RENAME COLUMN | TO x",
            intellisense_context::SqlPhase::DdlColumnList,
        ),
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert_eq!(ctx.phase, expected, "phase for `{sql}`");
        assert!(!ctx.ddl_new_name_position, "{sql}");
        assert_eq!(ctx.focused_tables, vec!["emp".to_string()], "{sql}");
        assert!(
            ctx.tables_in_scope
                .iter()
                .all(|table| table.alias.as_deref() != Some("MODIFY")),
            "`MODIFY` must not be parsed as a table alias for `{sql}`: {:?}",
            ctx.tables_in_scope
        );
    }

    // CTAS body is an ordinary SELECT list, untouched by the detector.
    let ctas = analyze_inline_cursor_sql("CREATE TABLE t AS SELECT | FROM emp");
    assert_eq!(ctas.phase, intellisense_context::SqlPhase::SelectList);
    assert!(!ctas.ddl_new_name_position);
}

#[test]
fn alter_table_existing_column_operations_suggest_target_columns() {
    let suggestions_for = |sql: &str| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        let ctx = analyze_inline_cursor_sql(sql);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        assert_eq!(context, SqlContext::ColumnName, "{sql}");

        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string(), "DEPT".to_string()];
        data.set_columns_for_table(
            "EMP",
            vec!["EMPNO".to_string(), "ENAME".to_string(), "SAL".to_string()],
        );
        data.set_columns_for_table("DEPT", vec!["DEPTNO".to_string(), "DNAME".to_string()]);
        data.rebuild_indices();

        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        assert_eq!(column_tables, vec!["emp".to_string()], "{sql}");
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(crate::db::DatabaseType::Oracle),
        );

        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            ClauseCompletionPolicy::for_phase(ctx.phase, true).restrict_to_relation_columns,
            Some(crate::db::DatabaseType::Oracle),
            expr_keyword_ctx,
        )
    };

    for sql in [
        "ALTER TABLE emp MODIFY |",
        "ALTER TABLE emp MODIFY (|)",
        "ALTER TABLE emp DROP COLUMN |",
        "ALTER TABLE emp RENAME COLUMN | TO new_name",
    ] {
        let suggestions = suggestions_for(sql);
        assert!(
            suggestions.iter().any(|value| value == "ENAME")
                && suggestions.iter().any(|value| value == "EMPNO"),
            "`{sql}` should suggest EMP columns: {suggestions:?}"
        );
        assert!(
            !suggestions
                .iter()
                .any(|value| value == "DNAME" || value == "DEPT"),
            "`{sql}` leaked unrelated relation data: {suggestions:?}"
        );
    }

    let (_kind, keywords, final_suggestions) =
        audit_final_suggestions_for("ALTER TABLE emp MODIFY |", crate::db::DatabaseType::Oracle);
    assert!(
        final_suggestions.iter().any(|value| value == "ENAME")
            && final_suggestions.iter().any(|value| value == "EMPNO"),
        "final suggestions lost EMP columns at ALTER MODIFY column slot: keywords={keywords:?} final={final_suggestions:?}"
    );
    assert!(
        !final_suggestions.iter().any(|value| value == "MODIFY"),
        "`MODIFY` leaked as a final column suggestion: keywords={keywords:?} final={final_suggestions:?}"
    );
}

