#[test]
fn oracle_returning_row_image_modifiers_keep_the_dml_target_column_scope() {
    use crate::db::DatabaseType::Oracle;

    for sql in [
        "UPDATE emp SET sal = sal + 1 RETURNING OLD sa| INTO :old_sal",
        "UPDATE emp SET sal = sal + 1 RETURNING sal, NEW sa| INTO :sal, :new_sal",
        "DELETE FROM emp WHERE empno = 1 RETURNING OLD emp| INTO :old_empno",
        "INSERT INTO emp (empno) VALUES (1) RETURNING NEW emp| INTO :new_empno",
    ] {
        let context = analyze_inline_cursor_sql(sql);
        let scope = SqlEditorWidget::oracle_dml_returning_row_image_column_scope_for_context(
            &context,
            true,
            Some(Oracle),
        );
        assert_eq!(scope, Some(vec!["emp".to_string()]), "scope for `{sql}`");
        let tokens = SqlEditorWidget::current_query_tokens(&context);
        let end = SqlEditorWidget::expected_suggestion_context_end(
            tokens,
            SqlEditorWidget::cursor_token_len_in_current_query(&context),
            true,
        );
        let row_image_keywords =
            SqlEditorWidget::expected_oracle_dml_returning_row_image_candidates(
                tokens,
                end,
                Some(Oracle),
            );
        assert_eq!(
            row_image_keywords, None,
            "row-image keyword state at a target column for `{sql}`: end={end} tokens={tokens:?}",
        );
        assert!(
            !SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
                &context,
                true,
                Some(Oracle),
            ),
            "row-image target column must not be treated as a keyword-only slot for `{sql}`",
        );
    }
}

#[test]
fn oracle_returning_item_start_offers_columns_alongside_row_image_modifiers() {
    use crate::db::DatabaseType::Oracle;

    let (_, keywords, suggestions) =
        audit_final_suggestions_for("UPDATE emp SET sal = sal + 1 RETURNING | INTO :sal", Oracle);
    for expected in ["EMPNO", "ENAME", "SAL"] {
        assert!(
            suggestions.iter().any(|suggestion| suggestion == expected),
            "{expected} missing from RETURNING item start: keywords={keywords:?} final={suggestions:?}"
        );
    }

    for (sql, expected) in [
        (
            "UPDATE emp SET sal = sal + 1 RETURNING sa| INTO :sal",
            "SAL",
        ),
        (
            "INSERT INTO emp (empno) VALUES (1) RETURNING emp| INTO :empno",
            "EMPNO",
        ),
    ] {
        let (_, keywords, suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert!(
            suggestions.iter().any(|suggestion| suggestion == expected),
            "{expected} missing at `{sql}`: keywords={keywords:?} final={suggestions:?}"
        );
    }
}

#[test]
fn oracle_json_transform_set_operations_complete_their_presence_handlers() {
    use crate::db::DatabaseType::Oracle;

    for sql in [
        "SELECT JSON_TRANSFORM(payload, ADD_SET '$.tags' = 'x' IGNORE I| PRESENT) FROM t",
        "SELECT JSON_TRANSFORM(payload, REMOVE_SET '$.tags' = 'x' IGNORE I| ABSENT) FROM t",
    ] {
        let context = analyze_inline_cursor_sql(sql);
        let inferred =
            SqlEditorWidget::oracle_structural_keyword_inference("I", &context, Some(Oracle));
        assert_eq!(
            inferred,
            Some("IF".to_string()),
            "structural inference at `{sql}`: statement={:?}",
            context.statement_tokens,
        );
        let suggestions = query_keyword_completion_suggestions(sql, Oracle);
        assert!(
            suggestions
                .iter()
                .any(|suggestion| suggestion.eq_ignore_ascii_case("IF")),
            "IGNORE IF handler lost IF at `{sql}`: {suggestions:?}",
        );
    }
}

#[test]
fn oracle_json_type_modifiers_and_plsql_json_type_use_production_completion() {
    use crate::db::DatabaseType::Oracle;

    for (sql, expected) in [
        ("CREATE TABLE t (payload JSON (OBJE|) NOT NULL)", "OBJECT"),
        ("CREATE TABLE t (payload JSON (ARR|) NOT NULL)", "ARRAY"),
        ("CREATE TABLE t (payload JSON (SCAL|) NOT NULL)", "SCALAR"),
        (
            "DECLARE alternate_document JSO|; BEGIN NULL; END;",
            "JSON",
        ),
    ] {
        let suggestions = query_keyword_completion_suggestions(sql, Oracle);
        assert!(
            suggestions
                .iter()
                .any(|suggestion| suggestion.eq_ignore_ascii_case(expected)),
            "`{expected}` missing at `{sql}`: {suggestions:?}"
        );
    }
}

#[test]
fn oracle_json_transform_sort_and_all_operation_heads_use_production_completion() {
    use crate::db::DatabaseType::Oracle;

    let operation_suggestions = query_keyword_completion_suggestions(
        "SELECT JSON_TRANSFORM(payload, |) FROM t",
        Oracle,
    );
    for expected in ORACLE_JSON_TRANSFORM_OPERATION_KEYWORDS {
        assert!(
            operation_suggestions
                .iter()
                .any(|suggestion| suggestion.eq_ignore_ascii_case(expected)),
            "`{expected}` missing from JSON_TRANSFORM operation heads: {operation_suggestions:?}"
        );
    }

    for (sql, expected) in [
        (
            "SELECT JSON_TRANSFORM(payload, SO| '$.tags' ASC UNIQUE) FROM t",
            "SORT",
        ),
        (
            "SELECT JSON_TRANSFORM(payload, SORT '$.tags' AS| UNIQUE) FROM t",
            "ASC",
        ),
        (
            "SELECT JSON_TRANSFORM(payload, SORT '$.tags' ASC UNIQ|) FROM t",
            "UNIQUE",
        ),
        (
            "SELECT JSON_TRANSFORM(payload, SORT '$.tags' DE| UNIQUE) FROM t",
            "DESC",
        ),
        (
            "SELECT JSON_TRANSFORM(payload, SORT '$.tags' REV|) FROM t",
            "REVERSE",
        ),
    ] {
        let suggestions = query_keyword_completion_suggestions(sql, Oracle);
        assert!(
            suggestions
                .iter()
                .any(|suggestion| suggestion.eq_ignore_ascii_case(expected)),
            "`{expected}` missing at `{sql}`: {suggestions:?}"
        );
    }
}

#[test]
fn oracle_json_transform_nested_path_and_empty_string_on_null_use_production_completion() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let nested_path = query_keyword_completion_suggestions(
        "SELECT JSON_TRANSFORM(payload, NESTED PA| '$.items[*]' (SET '$.x' = 1)) FROM t",
        Oracle,
    );
    assert!(
        nested_path
            .iter()
            .any(|suggestion| suggestion.eq_ignore_ascii_case("PATH")),
        "JSON_TRANSFORM NESTED PATH lost PATH: {nested_path:?}"
    );

    for sql in [
        "SELECT JSON_ARRAY(CAST(NULL AS VARCHAR2(1)) EMPTY STRING ON NULL) FROM dual",
        "SELECT JSON_ARRAYAGG(CAST(NULL AS VARCHAR2(1)) EMPTY STRING ON NULL) FROM dual",
        "SELECT JSON_OBJECT('x': CAST(NULL AS VARCHAR2(1)) EMPTY STRING ON NULL) FROM dual",
        "SELECT JSON_OBJECTAGG(KEY 'x' VALUE CAST(NULL AS VARCHAR2(1)) EMPTY STRING ON NULL) FROM dual",
        "SELECT JSON_SCALAR(CAST(NULL AS VARCHAR2(1)) EMPTY STRING ON NULL) FROM dual",
    ] {
        for (needle, replacement, expected) in [
            ("EMPTY", "EMPT|", "EMPTY"),
            ("STRING", "STRI|", "STRING"),
            ("ON NULL", "O| NULL", "ON"),
        ] {
            let marked = sql.replacen(needle, replacement, 1);
            let suggestions = query_keyword_completion_suggestions(&marked, Oracle);
            assert!(
                suggestions
                    .iter()
                    .any(|suggestion| suggestion.eq_ignore_ascii_case(expected)),
                "`{expected}` missing at `{marked}`: {suggestions:?}"
            );
        }
    }

    for db_type in [MySQL, MariaDB] {
        let suggestions = query_keyword_completion_suggestions(
            "SELECT JSON_OBJECT('x', NULL EMPT| STRING ON NULL)",
            db_type,
        );
        assert!(
            suggestions
                .iter()
                .all(|suggestion| !suggestion.eq_ignore_ascii_case("EMPTY")),
            "Oracle EMPTY STRING ON NULL leaked into {db_type:?}: {suggestions:?}"
        );
    }
}

#[test]
fn resolve_column_tables_for_merge_insert_column_list_prefers_merge_target() {
    let sql_with_cursor =
            "MERGE INTO target_table t USING source_table s ON (t.id = s.id) WHEN NOT MATCHED THEN INSERT (|) VALUES (s.id)";
    let cursor = sql_with_cursor
        .find('|')
        .expect("cursor marker should exist");
    let sql = sql_with_cursor.replace('|', "");

    let token_spans = super::query_text::tokenize_sql_spanned(&sql);
    let split_idx = token_spans.partition_point(|span| span.end <= cursor);
    let full_tokens: Vec<SqlToken> = token_spans.into_iter().map(|span| span.token).collect();
    let deep_ctx = intellisense_context::analyze_cursor_context(&full_tokens, split_idx);

    let tables = SqlEditorWidget::resolve_column_tables_for_context(None, &deep_ctx);
    assert_eq!(tables, vec!["target_table".to_string()]);
}

