#[test]
fn qualified_value_and_keyword_only_slots_do_not_use_schema_members() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let mut data = IntellisenseData::new();
    data.set_members_for_qualifier_with_kinds(
        "SCOTT",
        vec![
            ("EMP".to_string(), Some(QualifiedMemberKind::Table)),
            ("RUN_JOB".to_string(), Some(QualifiedMemberKind::Procedure)),
            ("ADDRESS_T".to_string(), Some(QualifiedMemberKind::Type)),
        ],
    );
    data.set_relation_members_for_qualifier("SCOTT", vec!["EMP".to_string()]);

    for (db, sql) in [
        (Oracle, "COMMENT ON TABLE emp IS scott.|"),
        (Oracle, "COMMENT ON COLUMN emp.sal IS scott.|"),
        (Oracle, "CREATE SEQUENCE s START WITH scott.|"),
        (Oracle, "CREATE TABLE t (a NUMBER) TABLESPACE scott.|"),
        (Oracle, "DROP TABLE emp PURGE scott.|"),
        (Oracle, "LOCK TABLE emp IN SHARE scott.|"),
        (Oracle, "SELECT * FROM emp e ORDER e.|"),
        (Oracle, "SELECT * FROM emp e GROUP e.|"),
        (Oracle, "SELECT * FROM emp e ORDER BY empno ASC e.|"),
        (Oracle, "SELECT * FROM emp e JOIN dept d e.|"),
        (Oracle, "SELECT empno FROM emp UNION e.|"),
        (Oracle, "SELECT INTERVAL '1' scott.| FROM emp"),
        (Oracle, "SELECT INTERVAL '1' DAY TO scott.| FROM emp"),
        (Oracle, "SELECT TIMESTAMP WITH TIME ZONE scott.| FROM emp"),
        (Oracle, "SELECT POSITION('a' scott.|"),
        (Oracle, "SELECT TRIM(LEADING 'x' scott.|"),
        (
            Oracle,
            "SELECT JSON_VALUE(payload, '$.amount' NULL ON scott.|) FROM emp",
        ),
        (
            Oracle,
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON scott.|) FROM emp",
        ),
        (
            Oracle,
            "SELECT XMLQUERY('/root' RETURNING CONTENT NULL ON scott.|) FROM emp",
        ),
        (Oracle, "SELECT * FROM emp WHERE hiredate AT scott.|"),
        (Oracle, "SELECT * FROM emp WHERE hiredate AT TIME scott.|"),
        (Oracle, "SELECT * FROM emp WHERE elem MEMBER scott.|"),
        (
            Oracle,
            "SELECT * FROM emp WHERE child_nt SUBMULTISET scott.|",
        ),
        (Oracle, "SELECT * FROM emp WHERE child_nt IS A scott.|"),
        (Oracle, "UPDATE emp SET sal = 1 LOG scott.|"),
        (Oracle, "UPDATE emp SET sal = 1 LOG ERRORS scott.|"),
        (
            Oracle,
            "UPDATE emp SET sal = 1 LOG ERRORS INTO err$_emp scott.|",
        ),
        (Oracle, "UPDATE emp SET sal = 1 LOG ERRORS REJECT scott.|"),
        (
            Oracle,
            "UPDATE emp SET sal = 1 LOG ERRORS REJECT LIMIT scott.|",
        ),
        (Oracle, "UPDATE emp SET sal = 1 RETURNING empno scott.|"),
        (
            Oracle,
            "UPDATE emp SET sal = 1 RETURNING empno INTO scott.|",
        ),
        (
            Oracle,
            "BEGIN SELECT empno INTO scott.| FROM emp WHERE rownum = 1; END;",
        ),
        (Oracle, "BEGIN FETCH cur_emp INTO scott.|; END;"),
        (
            Oracle,
            "BEGIN EXECUTE IMMEDIATE 'select count(*) from emp' INTO scott.|; END;",
        ),
        (
            Oracle,
            "BEGIN EXECUTE IMMEDIATE 'select * from emp where deptno = :1' USING scott.|; END;",
        ),
        (
            Oracle,
            "BEGIN OPEN c FOR SELECT empno FROM emp WHERE deptno = :1 USING scott.|; END;",
        ),
        (Oracle, "UPDATE emp e.|"),
        (Oracle, "DELETE FROM emp e.|"),
        (Oracle, "ALTER TABLE emp e.|"),
        (Oracle, "GRANT SELECT ON emp TO scott e.|"),
        (Oracle, "REVOKE SELECT ON emp FROM scott e.|"),
        (MySQL, "CREATE DATABASE db CHARACTER SET scott.|"),
        (MySQL, "CREATE USER alice IDENTIFIED BY scott.|"),
        (MySQL, "CREATE TABLESPACE ts ADD DATAFILE scott.|"),
        (MySQL, "ALTER TABLESPACE ts ADD DATAFILE scott.|"),
        (MySQL, "SET NAMES utf8mb4 COLLATE scott.|"),
        (MySQL, "SELECT SUBSTRING(name scott.| FROM emp"),
        (MySQL, "SELECT match(ename) AGAINST scott.| FROM emp"),
        (MySQL, "SELECT * FROM emp WHERE ename SOUNDS scott.|"),
        (MySQL, "INSERT INTO emp VALUES (1) ON scott.|"),
        (MySQL, "INSERT INTO emp VALUES (1) ON DUPLICATE scott.|"),
        (MySQL, "INSERT INTO emp VALUES (1) ON DUPLICATE KEY scott.|"),
        (
            MySQL,
            "INSERT INTO emp VALUES (1) ON DUPLICATE KEY UPDATE sal = 1 scott.|",
        ),
        (MySQL, "CREATE INDEX ix ON emp (empno) e.|"),
        (MySQL, "ALTER TABLE emp ADD COLUMN id INT e.|"),
        (MySQL, "CREATE TRIGGER trg BEFORE e.|"),
        (MySQL, "SELECT * FROM emp e ORDER e.|"),
        (MySQL, "SELECT * FROM emp e GROUP e.|"),
        (Oracle, "SELECT * FROM emp e WHERE empno IS e.|"),
        (Oracle, "SELECT * FROM emp e FETCH FIRST 1 ROWS ONLY e.|"),
        (MySQL, "SELECT * FROM emp e WHERE ename COLLATE e.|"),
        (MariaDB, "CREATE DATABASE db CHARACTER SET scott.|"),
        (MariaDB, "CREATE USER alice IDENTIFIED BY scott.|"),
        (MariaDB, "SET NAMES utf8mb4 COLLATE scott.|"),
        (MariaDB, "SELECT SUBSTRING(name scott.| FROM emp"),
        (MariaDB, "SELECT match(ename) AGAINST scott.| FROM emp"),
        (MariaDB, "SELECT * FROM emp WHERE ename SOUNDS scott.|"),
        (MariaDB, "INSERT INTO emp VALUES (1) ON scott.|"),
        (MariaDB, "INSERT INTO emp VALUES (1) ON DUPLICATE scott.|"),
        (
            MariaDB,
            "INSERT INTO emp VALUES (1) ON DUPLICATE KEY scott.|",
        ),
        (
            MariaDB,
            "INSERT INTO emp VALUES (1) ON DUPLICATE KEY UPDATE sal = 1 scott.|",
        ),
        (MariaDB, "CREATE INDEX ix ON emp (empno) e.|"),
        (MariaDB, "ALTER TABLE emp ADD COLUMN id INT e.|"),
        (MariaDB, "CREATE TRIGGER trg BEFORE e.|"),
        (MariaDB, "SELECT * FROM emp e ORDER e.|"),
        (MariaDB, "SELECT * FROM emp e GROUP e.|"),
        (MariaDB, "SELECT * FROM emp e WHERE ename COLLATE e.|"),
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        assert!(
            SqlEditorWidget::cursor_is_at_qualified_identifier_suppression_slot_for_context(
                &ctx,
                Some(db),
            ),
            "`{sql}` should be a qualified value/keyword-only suppression slot"
        );
        assert_eq!(
            SqlEditorWidget::resolve_qualified_completion_mode_for_db(
                "scott",
                context,
                &ctx,
                &data,
                Some(db),
            ),
            None,
            "qualified value/keyword-only slot must not switch to schema members for `{sql}`"
        );
        assert!(
            audit_final_suggestions_for(sql, db).2.is_empty(),
            "qualified value/keyword-only slot leaked final suggestions for `{sql}`"
        );
    }

    for (db, sql) in [
        (Oracle, "DROP TABLE scott.|"),
        (Oracle, "GRANT SELECT ON scott.|"),
        (Oracle, "SELECT CAST(empno AS scott.|) FROM emp"),
        (Oracle, "SELECT e.| FROM emp e"),
        (Oracle, "SELECT * FROM emp e WHERE e.|"),
        (MySQL, "DROP TABLE scott.|"),
        (MySQL, "SHOW CREATE TABLE scott.|"),
        (MySQL, "SELECT e.| FROM emp e"),
        (MariaDB, "DROP TABLE scott.|"),
        (MariaDB, "SHOW CREATE TABLE scott.|"),
        (MariaDB, "SELECT e.| FROM emp e"),
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            !SqlEditorWidget::cursor_is_at_qualified_identifier_suppression_slot_for_context(
                &ctx,
                Some(db),
            ),
            "`{sql}` is a real qualified identifier slot and must stay open"
        );
    }
}

#[test]
fn qualified_object_context_uses_the_narrowest_scoped_member_cache() {
    let grant_execute_ctx = analyze_inline_cursor_sql("GRANT EXECUTE ON scott.|");
    let grant_select_ctx = analyze_inline_cursor_sql("GRANT SELECT ON scott.|");
    let mut data = IntellisenseData::new();
    data.set_members_for_qualifier_with_kinds(
        "SCOTT",
        vec![
            ("EMP".to_string(), Some(QualifiedMemberKind::Table)),
            ("EMP_VIEW".to_string(), Some(QualifiedMemberKind::View)),
            ("EMP_SEQ".to_string(), Some(QualifiedMemberKind::Sequence)),
            ("RUN_JOB".to_string(), Some(QualifiedMemberKind::Procedure)),
            ("UTIL_PKG".to_string(), Some(QualifiedMemberKind::Package)),
            ("ADDRESS_T".to_string(), Some(QualifiedMemberKind::Type)),
        ],
    );
    data.set_relation_members_for_qualifier(
        "SCOTT",
        vec!["EMP".to_string(), "EMP_VIEW".to_string()],
    );

    let execute_mode = SqlEditorWidget::resolve_qualified_completion_mode(
        "scott",
        SqlContext::TableName,
        &grant_execute_ctx,
        &data,
    );
    assert_eq!(execute_mode, Some(QualifiedCompletionMode::ObjectMembers));
    let execute_suggestions = SqlEditorWidget::expected_member_suggestions_for_qualifier(
        &mut data,
        "scott",
        "",
        &grant_execute_ctx,
    );
    assert_eq!(
        execute_suggestions,
        vec![
            "ADDRESS_T".to_string(),
            "RUN_JOB".to_string(),
            "UTIL_PKG".to_string(),
        ]
    );

    let select_mode = SqlEditorWidget::resolve_qualified_completion_mode(
        "scott",
        SqlContext::TableName,
        &grant_select_ctx,
        &data,
    );
    assert_eq!(select_mode, Some(QualifiedCompletionMode::RelationMembers));
    let select_suggestions = SqlEditorWidget::expected_member_suggestions_for_qualifier(
        &mut data,
        "scott",
        "",
        &grant_select_ctx,
    );
    assert_eq!(
        select_suggestions,
        vec![
            "EMP".to_string(),
            "EMP_SEQ".to_string(),
            "EMP_VIEW".to_string(),
        ]
    );
}

#[test]
fn collect_expected_keyword_suggestions_complete_common_clause_tails() {
    let cases: &[(&str, &[&str])] = &[
        ("SELECT * FROM emp ORDER |", &["BY"]),
        (
            "SELECT * FROM emp CONNECT BY PRIOR empno = mgr ORDER SIBLINGS |",
            &["BY"],
        ),
        (
            "SELECT * FROM emp ORDER BY empno FETCH FIRST |",
            &["ROW", "ROWS"],
        ),
        (
            "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 |",
            &["ROW", "ROWS", "PARTITIONS"],
        ),
        (
            "SELECT * FROM emp ORDER BY empno FETCH FIRST :limit |",
            &["ROW", "ROWS", "PARTITIONS"],
        ),
        (
            "SELECT * FROM emp ORDER BY empno FETCH NEXT page_size |",
            &["ROW", "ROWS", "PARTITIONS"],
        ),
        (
            "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 PERCENT |",
            &["ROW", "ROWS"],
        ),
        (
            "SELECT * FROM emp ORDER BY empno FETCH FIRST :percent PERCENT |",
            &["ROW", "ROWS"],
        ),
        (
            "SELECT * FROM emp ORDER BY empno FETCH FIRST ROWS |",
            &["ONLY", "WITH"],
        ),
        (
            "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS |",
            &["ONLY", "WITH"],
        ),
        (
            "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 PERCENT ROWS |",
            &["ONLY", "WITH"],
        ),
        (
            "SELECT * FROM emp ORDER BY empno FETCH FIRST :percent PERCENT ROWS |",
            &["ONLY", "WITH"],
        ),
        (
            "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS WITH |",
            &["TIES"],
        ),
        ("SELECT * FROM emp OFFSET 10 |", &["ROW", "ROWS"]),
        ("SELECT * FROM emp OFFSET :skip |", &["ROW", "ROWS"]),
        ("SELECT * FROM emp OFFSET 10 ROWS |", &["FETCH"]),
        ("SELECT * FROM emp OFFSET :skip ROWS |", &["FETCH"]),
    ];
    let when_ctx =
        analyze_inline_cursor_sql("MERGE INTO target t USING src s ON (t.id = s.id) WHEN |");

    for (sql, expected) in cases {
        let ctx = analyze_inline_cursor_sql(sql);
        let suggestions = SqlEditorWidget::collect_expected_keyword_suggestions("", &ctx, None);
        let expected: Vec<String> = expected.iter().map(|value| (*value).to_string()).collect();
        assert_eq!(suggestions, expected, "sql: {sql}");
    }

    let when_suggestions =
        SqlEditorWidget::collect_expected_keyword_suggestions("", &when_ctx, None);

    assert!(when_suggestions.iter().any(|value| value == "MATCHED"));
    assert!(when_suggestions.iter().any(|value| value == "NOT"));
}

#[test]
fn oracle_package_body_insert_statement_offers_dml_keywords() {
    let package_body = r#"
CREATE OR REPLACE NONEDITIONABLE PACKAGE BODY "SYSTEM"."OQT_DEEP_PKG" AS
  PROCEDURE log_msg(p_tag IN VARCHAR2, p_msg IN VARCHAR2, p_depth IN NUMBER) IS
  BEGIN
    INSERT __CURSOR__ into oqt_t_log(log_id, tag, msg, depth)
    values (oqt_seq_log.NEXTVAL, SUBSTR(p_tag,1,30), SUBSTR(p_msg,1,4000), p_depth);
  END;
END;
"#;
    let sql = package_body.replace("__CURSOR__", "|");
    let (_kind, _keywords, final_suggestions) =
        audit_final_suggestions_for(&sql, crate::db::DatabaseType::Oracle);
    assert!(
        final_suggestions.iter().any(|value| value == "INTO"),
        "INSERT inside package body should offer INTO, got: {final_suggestions:?}"
    );

    let package_body = r#"
CREATE OR REPLACE NONEDITIONABLE PACKAGE BODY "SYSTEM"."OQT_DEEP_PKG" AS
  PROCEDURE log_msg(p_tag IN VARCHAR2, p_msg IN VARCHAR2, p_depth IN NUMBER) IS
  BEGIN
    INSERT into oqt_t_log(log_id, tag, msg, depth) __CURSOR__
    values (oqt_seq_log.NEXTVAL, SUBSTR(p_tag,1,30), SUBSTR(p_msg,1,4000), p_depth);
  END;
END;
"#;
    let sql = package_body.replace("__CURSOR__", "|");
    let (_kind, _keywords, final_suggestions) =
        audit_final_suggestions_for(&sql, crate::db::DatabaseType::Oracle);
    assert!(
        final_suggestions.iter().any(|value| value == "VALUES"),
        "INSERT column list inside package body should offer VALUES, got: {final_suggestions:?}"
    );

    let package_body = r#"
CREATE OR REPLACE NONEDITIONABLE PACKAGE BODY "SYSTEM"."OQT_DEEP_PKG" AS
  PROCEDURE log_msg(p_tag IN VARCHAR2, p_msg IN VARCHAR2, p_depth IN NUMBER) IS
  BEGIN
    INSERT into oqt_t_log(log_id, tag, msg, depth)
    values (oqt_seq_log.NEXTVAL, SUBSTR(p_tag,1,30), SUBSTR(p_msg,1,4000), p_depth);
    DBMS_OUT__CURSOR__
  END;
END;
"#;
    let sql = package_body.replace("__CURSOR__", "|");
    let (_kind, _keywords, final_suggestions) =
        audit_final_suggestions_for(&sql, crate::db::DatabaseType::Oracle);
    assert!(
        final_suggestions.iter().any(|value| value == "DBMS_OUTPUT"),
        "package body should offer DBMS_OUTPUT at a PL/SQL call statement, got: {final_suggestions:?}"
    );
}

#[test]
fn oracle_package_body_plsql_keywords_are_offered_inside_nested_blocks() {
    let package_body = r#"
CREATE OR REPLACE NONEDITIONABLE PACKAGE BODY "SYSTEM"."OQT_DEEP_PKG" AS

  FUNCTION f_calc(p_n IN NUMBER) RETURN NUMBER IS
    v NUMBER := 0;
  BEGIN
    IF p_n IS NULL THEN
      v := -1;
    ELSE
      CASE
        WHEN p_n < 0 THEN
          v := p_n * p_n;
        WHEN p_n BETWEEN 0 AND 10 THEN
          DECLARE
            x NUMBER := p_n + 100;
          BEGIN
            v := x - 50;
          END;
        ELSE
          v := p_n + 999;
      END CASE;
    END IF;

    RETURN v;
  EXCEPTION
    WHEN OTHERS THEN
      log_msg('F_CALC', SQLERRM, 999);
      RETURN NULL;
  END;
END;
"#;

    let cases = [
        ("IS NULL THEN", "IS NUL__CURSOR__ THEN", "NULL"),
        ("IS NULL THEN", "IS NULL TH__CURSOR__", "THEN"),
        (
            "END IF;\n\n    RETURN",
            "END IF;\n\n    RET__CURSOR__",
            "RETURN",
        ),
        ("EXCEPTION\n    WHEN", "EXCEPTION\n    WH__CURSOR__", "WHEN"),
        ("WHEN OTHERS", "WHEN OTH__CURSOR__", "OTHERS"),
        ("OTHERS THEN", "OTHERS TH__CURSOR__", "THEN"),
        ("RETURN NULL", "RETURN NUL__CURSOR__", "NULL"),
        ("CASE\n        WHEN", "CASE\n        WH__CURSOR__", "WHEN"),
        ("p_n BETWEEN", "p_n BET__CURSOR__", "BETWEEN"),
        ("END;\n        ELSE", "END;\n        EL__CURSOR__", "ELSE"),
    ];

    for (target, replacement, expected) in cases {
        let sql = package_body
            .replace(target, replacement)
            .replace("__CURSOR__", "|");
        let (_kind, keywords, final_suggestions) =
            audit_final_suggestions_for(&sql, crate::db::DatabaseType::Oracle);
        assert!(
            final_suggestions.iter().any(|value| value == expected),
            "{expected} should be offered for target `{target}`, keywords={keywords:?}, final={final_suggestions:?}"
        );
    }
}

#[test]
fn extract_field_slot_suppresses_columns_and_offers_field_keywords() {
    let at_field = |sql: &str| {
        SqlEditorWidget::extract_field_position_for_context(&analyze_inline_cursor_sql(sql), false)
            .is_some()
    };
    // Field slot (`EXTRACT(|`) and the awaiting-FROM slot (`EXTRACT(YEAR |`) both
    // suppress columns — a column is never valid before the FROM.
    assert!(at_field("SELECT EXTRACT(| FROM hire_date) FROM emp"));
    assert!(at_field("SELECT EXTRACT(YEAR | FROM hire_date) FROM emp"));
    // The source expression after FROM is a real column position.
    assert!(!at_field("SELECT EXTRACT(YEAR FROM |) FROM emp"));
    assert!(!at_field(
        "SELECT EXTRACT(YEAR FROM hire_date) , | FROM emp"
    ));
    // An ordinary column position / a non-EXTRACT function call is unaffected.
    assert!(!at_field("SELECT | FROM emp"));
    assert!(!at_field("SELECT TRUNC(| ) FROM emp"));

    // Oracle field keywords are offered at the field slot; MySQL has its own set.
    let oracle_fields = SqlEditorWidget::collect_expected_keyword_suggestions(
        "",
        &analyze_inline_cursor_sql("SELECT EXTRACT(| FROM hire_date) FROM emp"),
        Some(crate::db::DatabaseType::Oracle),
    );
    assert!(oracle_fields.iter().any(|value| value == "YEAR"));
    assert!(oracle_fields.iter().any(|value| value == "TIMEZONE_HOUR"));
    for db_type in [
        crate::db::DatabaseType::MySQL,
        crate::db::DatabaseType::MariaDB,
    ] {
        let mysql_fields = SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql("SELECT EXTRACT(| FROM hire_date) FROM emp"),
            Some(db_type),
        );
        assert!(
            mysql_fields.iter().any(|value| value == "QUARTER"),
            "MySQL-family EXTRACT field set should include QUARTER for {db_type:?}"
        );
        assert!(
            mysql_fields.iter().any(|value| value == "YEAR_MONTH"),
            "MySQL-family EXTRACT field set should include YEAR_MONTH for {db_type:?}"
        );
    }
    // After the field name, `FROM` is offered.
    let awaiting_from = SqlEditorWidget::collect_expected_keyword_suggestions(
        "",
        &analyze_inline_cursor_sql("SELECT EXTRACT(YEAR | FROM hire_date) FROM emp"),
        Some(crate::db::DatabaseType::Oracle),
    );
    assert_eq!(awaiting_from, vec!["FROM".to_string()]);
}

#[test]
fn json_returning_type_slot_offers_types_and_suppresses_columns() {
    // The JSON `RETURNING` type slot routes through the shared keyword-only
    // chokepoint, so columns are suppressed there.
    let at_slot = |sql: &str| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(
            &analyze_inline_cursor_sql(sql),
            false,
        )
    };
    assert!(at_slot("SELECT JSON_VALUE(doc, '$.a' RETURNING |) FROM t"));
    assert!(at_slot("SELECT JSON_QUERY(doc, '$.a' RETURNING |) FROM t"));
    assert!(at_slot("SELECT JSON_ARRAY(v RETURNING |) FROM t"));
    assert!(at_slot(
        "SELECT JSON_OBJECT(KEY k VALUE v RETURNING |) FROM t"
    ));
    assert!(at_slot("SELECT JSON_ARRAYAGG(v RETURNING |) FROM t"));
    assert!(at_slot(
        "SELECT JSON_OBJECTAGG(KEY k VALUE v RETURNING |) FROM t"
    ));
    // A statement-level DML RETURNING lists columns, not types — not a type slot.
    assert!(!at_slot("UPDATE t SET x = 1 RETURNING | INTO :v"));
    assert!(!at_slot("DELETE FROM t WHERE id = 1 RETURNING |"));

    // Dialect-correct type keywords are offered at the JSON RETURNING slot.
    let oracle = SqlEditorWidget::collect_expected_keyword_suggestions(
        "",
        &analyze_inline_cursor_sql("SELECT JSON_VALUE(doc, '$.a' RETURNING |) FROM t"),
        Some(crate::db::DatabaseType::Oracle),
    );
    assert!(oracle.iter().any(|value| value == "VARCHAR2"));
    assert!(oracle.iter().any(|value| value == "NUMBER"));
    for db_type in [
        crate::db::DatabaseType::MySQL,
        crate::db::DatabaseType::MariaDB,
    ] {
        let mysql = SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql("SELECT JSON_VALUE(doc, '$.a' RETURNING |) FROM t"),
            Some(db_type),
        );
        assert!(
            mysql.iter().any(|value| value == "UNSIGNED"),
            "MySQL-family JSON_RETURNING slot should offer UNSIGNED for {db_type:?}"
        );
    }
}

#[test]
fn clause_continuation_keyword_is_suppressed_after_qualified_member() {
    let suggests = |sql: &str, kw: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            None,
        )
        .iter()
        .any(|value| value == kw)
    };
    // A standalone clause keyword still offers its continuation.
    assert!(suggests("SELECT * FROM emp ORDER |", "BY"));
    assert!(suggests("SELECT * FROM emp GROUP |", "BY"));
    assert!(suggests("SELECT * FROM emp CONNECT |", "BY"));
    assert!(suggests("SELECT * FROM emp START |", "WITH"));
    // A qualified member named order/group/start is a column — no continuation.
    assert!(!suggests("SELECT * FROM emp e WHERE e.order |", "BY"));
    assert!(!suggests("SELECT * FROM emp e WHERE e.group |", "BY"));
    assert!(!suggests("SELECT * FROM emp e WHERE e.start |", "WITH"));
    // Before the query's FROM clause these words are select-list expressions, not
    // clause openers.
    for (sql, keyword) in [
        ("SELECT order | FROM emp", "BY"),
        ("SELECT group | FROM emp", "BY"),
        ("SELECT connect | FROM emp", "BY"),
        ("SELECT start | FROM emp", "WITH"),
        ("CREATE TABLE x AS SELECT order | FROM emp", "BY"),
        ("CREATE VIEW v AS SELECT group | FROM emp", "BY"),
        (
            "CREATE TRIGGER trg BEFORE INSERT ON emp BEGIN SELECT start | FROM emp; END;",
            "WITH",
        ),
    ] {
        assert!(
            !suggests(sql, keyword),
            "{keyword} leaked into a select-list expression for `{sql}`"
        );
        assert!(
            !SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(
                &analyze_inline_cursor_sql(sql),
                false,
            ),
            "select-list expression should not be keyword-only for `{sql}`"
        );
    }
}

#[test]
fn join_continuation_keyword_is_scoped_to_table_context() {
    let suggests_join = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            None,
        )
        .iter()
        .any(|value| value == "JOIN")
    };
    // In a table position the join continuation is still offered.
    assert!(suggests_join("SELECT * FROM a LEFT |"));
    assert!(suggests_join("SELECT * FROM a INNER |"));
    assert!(suggests_join("SELECT * FROM a NATURAL |"));
    assert!(suggests_join("SELECT * FROM a CROSS |"));
    // A column/function named left/right in an expression position must not.
    assert!(!suggests_join("SELECT left | FROM a"));
    assert!(!suggests_join("SELECT * FROM a WHERE right | "));
}

#[test]
fn column_suppressing_keyword_slot_covers_every_family() {
    let at = |sql: &str| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(
            &analyze_inline_cursor_sql(sql),
            false,
        )
    };
    // One representative of each keyword/value-only family routes through the
    // single chokepoint, so suppression can never drift from keyword emission.
    assert!(at("SELECT CAST(x AS |) FROM t")); // data type
    assert!(at("SELECT * FROM t ORDER BY id FETCH FIRST |")); // row limiting
    assert!(at(
        "SELECT sum(x) OVER (ORDER BY d ROWS BETWEEN UNBOUNDED |) FROM t"
    )); // window frame
    assert!(at(
        "SELECT sum(x) OVER (ORDER BY d ROWS BETWEEN UNBOUNDED PRECEDING |) FROM t"
    )); // completed first frame bound
    assert!(at(
        "SELECT sum(x) OVER (ORDER BY d ROWS CURRENT ROW |) FROM t"
    )); // completed frame bound
    assert!(at(
        "SELECT sum(x) OVER (ORDER BY d ROWS CURRENT ROW EXCLUDE NO |) FROM t"
    )); // EXCLUDE tail
    assert!(at("SELECT max(empno) KEEP (DENSE_RANK |) FROM emp")); // KEEP dense-rank slot
    assert!(at("SELECT listagg(ename) WITHIN | FROM emp")); // WITHIN GROUP slot
    assert!(at("SELECT last_value(empno) IGNORE | FROM emp")); // analytic null treatment
    assert!(at("SELECT EXTRACT(| FROM hire_date) FROM emp")); // EXTRACT field
    assert!(at("SELECT hire_date - INTERVAL '5' | FROM emp")); // INTERVAL unit
    assert!(at("SELECT CAST | FROM emp")); // expression construct opening paren
    assert!(at("SELECT * FROM emp WHERE EXISTS |")); // expression construct opening paren
    assert!(at("SELECT * FROM emp WHERE empno IN |")); // predicate list opening paren
    assert!(at("SELECT * FROM emp WHERE empno NOT IN |"));
    assert!(at("SELECT * FROM emp WHERE empno = ANY |")); // quantified comparison opening paren
    assert!(at("SELECT * FROM emp WHERE EXISTS (|)")); // subquery-only body
    assert!(at("SELECT * FROM emp WHERE empno = ANY (|)")); // quantified subquery body
    assert!(at("SELECT XMLCAST | FROM emp")); // function-like construct opening paren
    assert!(at("SELECT * FROM emp WHERE JSON_EXISTS |")); // function-like construct opening paren
    assert!(at("SELECT * FROM JSON_TABLE |")); // table-source construct opening paren
    assert!(at(
        "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER PATH |))"
    )); // table-function path literal
    assert!(at("SELECT JSON_VALUE(doc, '$.a' NULL ON |) FROM t")); // JSON ON target
    assert!(at("SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON |) FROM t")); // JSON ON NULL target
    assert!(at("SELECT * FROM emp ORDER BY id ASC |")); // ORDER BY sort modifier
    assert!(at("SELECT * FROM emp ORDER BY id NULLS FIRST |")); // completed sort modifier
    assert!(at("SELECT sum(x) OVER (ORDER BY d NULLS |) FROM t")); // window sort modifier
    assert!(at("SELECT * FROM emp ORDER |")); // pure clause-keyword continuation
    assert!(at("SELECT * FROM a LEFT |")); // pure join-type continuation
    assert!(at("SELECT sum(x) OVER (PARTITION |) FROM t")); // window PARTITION BY
    assert!(at("SELECT * FROM emp WHERE a IS |")); // IS predicate operator
    assert!(at("SELECT * FROM emp WHERE a IS NOT |"));
    assert!(at("SELECT * FROM emp WHERE a IS DISTINCT |"));
    assert!(at("SELECT * FROM emp WHERE payload IS JSON OBJECT WITH |"));
    assert!(at("CREATE ROLLBACK |")); // statement structural keyword tail
    assert!(at("CREATE JAVA |")); // statement structural keyword tail
    assert!(at("CREATE SYNONYM emp_syn |")); // statement structural keyword tail
                                             // Ordinary column positions remain column positions.
    assert!(!at("SELECT | FROM emp"));
    assert!(!at("SELECT * FROM emp WHERE | "));
    assert!(!at("SELECT * FROM emp WHERE empno IN (|)"));
    assert!(!at("SELECT CASE | FROM emp"));
    assert!(!at("CREATE TABLE IF NOT EXISTS |"));
    // Value-bound window-frame slots accept an expression, so they are NOT here.
    assert!(!at(
        "SELECT sum(x) OVER (ORDER BY d ROWS BETWEEN | ) FROM t"
    ));

    for sql in [
        "SELECT CAST | FROM emp",
        "SELECT XMLCAST | FROM emp",
        "SELECT * FROM emp WHERE EXISTS |",
        "SELECT * FROM emp WHERE JSON_EXISTS |",
    ] {
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "value-only expression opener should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.is_empty(),
            "value-only expression opener should not offer catalog or keywords at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
    }
}

#[test]
fn pure_clause_keyword_continuation_covers_every_family() {
    let at = |sql: &str| {
        SqlEditorWidget::cursor_is_at_pure_clause_keyword_continuation_for_context(
            &analyze_inline_cursor_sql(sql),
            false,
        )
    };
    // Multi-word clause openers whose trailing keyword has not been typed: only
    // that keyword is grammatical, so every identifier source is suppressed.
    assert!(at("SELECT * FROM t ORDER |")); // -> BY
    assert!(at("SELECT * FROM t GROUP |")); // -> BY
    assert!(at("SELECT * FROM t CONNECT |")); // -> BY
    assert!(at("SELECT * FROM t ORDER SIBLINGS |")); // -> BY
    assert!(at("SELECT * FROM t START |")); // -> WITH
    assert!(at("SELECT * FROM a LEFT |")); // -> JOIN
    assert!(at("SELECT * FROM a INNER |"));
    assert!(at("SELECT * FROM a CROSS |"));
    assert!(at("SELECT * FROM a NATURAL |"));
    assert!(at("SELECT * FROM a LEFT OUTER |")); // -> JOIN
    assert!(at("SELECT * FROM a FULL OUTER |"));
    // The clause openers suppress in a column context too (a complete predicate
    // precedes the bare ORDER), not only in the FROM table context.
    assert!(at("SELECT a FROM t WHERE a = 1 ORDER |"));
    assert!(at("SELECT a FROM t GROUP BY a ORDER |"));

    // `PARTITION |` continues to `BY` only inside an analytic window spec, so it
    // is a continuation there (`OVER (...)` and `WINDOW name AS (...)`) …
    assert!(at("SELECT sum(x) OVER (PARTITION |) FROM t"));
    assert!(at("SELECT count(*) FROM t WINDOW w AS (PARTITION |)"));
    // … but not where `PARTITION` introduces a partition name: a partition-
    // extended table reference, a partitioned outer join, or a DDL maintenance op.
    assert!(!at("SELECT * FROM sales PARTITION |"));
    assert!(!at("SELECT * FROM sales s PARTITION |"));
    assert!(!at("ALTER TABLE t DROP PARTITION |"));

    // Not a continuation: the trailing keyword is already present, an ordinary
    // clause body, a typed prefix, a qualified member column, a join-type word in
    // an expression, or a completed join target.
    assert!(!at("SELECT * FROM t ORDER BY |"));
    assert!(!at("SELECT * FROM t ORDER BY id ASC |"));
    assert!(!at("SELECT * FROM t ORDER BY id NULLS |"));
    assert!(!at("SELECT * FROM t ORDER BY id NULLS FIRST |"));
    assert!(!at("SELECT | FROM t"));
    assert!(!at("SELECT * FROM t WHERE |"));
    assert!(!at("SELECT * FROM t |"));
    assert!(!at("SELECT * FROM t ORD|"));
    assert!(!at("SELECT left | FROM t"));
    assert!(!at("SELECT * FROM t e WHERE e.order |"));
    assert!(!at("SELECT * FROM a LEFT OUTER JOIN b |"));
}

#[test]
fn outer_join_continuation_offers_join_keyword() {
    let suggests_join = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            None,
        )
        .iter()
        .any(|value| value == "JOIN")
    };
    // `<side> OUTER` is a join continuation just like the bare join types, so it
    // must offer `JOIN` (and, via the shared continuation predicate, suppress the
    // relation list that would otherwise leak there).
    assert!(suggests_join("SELECT * FROM a LEFT OUTER |"));
    assert!(suggests_join("SELECT * FROM a RIGHT OUTER |"));
    assert!(suggests_join("SELECT * FROM a FULL OUTER |"));
    // Still scoped to a table context.
    assert!(!suggests_join("SELECT outer | FROM a"));

    // `LEFT`/`RIGHT`/`FULL` additionally offer the optional `OUTER` before
    // `JOIN`, so typing it mid-keyword (`LEFT O|`) stays useful; `INNER`/`CROSS`/
    // `NATURAL` do not take `OUTER`.
    let candidates = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            None,
        )
    };
    assert!(candidates("SELECT * FROM a LEFT |")
        .iter()
        .any(|v| v == "OUTER"));
    assert!(candidates("SELECT * FROM a FULL |")
        .iter()
        .any(|v| v == "OUTER"));
    assert!(!candidates("SELECT * FROM a INNER |")
        .iter()
        .any(|v| v == "OUTER"));

    for db_type in [
        crate::db::DatabaseType::MySQL,
        crate::db::DatabaseType::MariaDB,
    ] {
        let mysql_candidates = |sql: &str| {
            SqlEditorWidget::collect_expected_keyword_suggestions(
                "",
                &analyze_inline_cursor_sql(sql),
                Some(db_type),
            )
        };
        for (sql, leaked) in [
            ("SELECT * FROM a FULL |", "OUTER"),
            ("SELECT * FROM a FULL |", "JOIN"),
            ("SELECT * FROM a FULL OUTER |", "JOIN"),
        ] {
            let got = mysql_candidates(sql);
            assert!(
                !got.iter().any(|value| value == leaked),
                "{leaked} leaked from unsupported {db_type:?} FULL join continuation at `{sql}`: {got:?}"
            );
        }
        assert!(mysql_candidates("SELECT * FROM a LEFT |")
            .iter()
            .any(|v| v == "OUTER"));
        assert!(mysql_candidates("SELECT * FROM a RIGHT OUTER |")
            .iter()
            .any(|v| v == "JOIN"));
    }
}

#[test]
fn window_partition_continuation_offers_by_and_suppresses_columns() {
    let suggests_by = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
        .iter()
        .any(|value| value == "BY")
    };
    // Inside an analytic spec, `PARTITION |` offers `BY`.
    assert!(suggests_by("SELECT sum(x) OVER (PARTITION |) FROM t"));
    assert!(suggests_by(
        "SELECT count(*) FROM t WINDOW w AS (PARTITION |)"
    ));
    // A non-window `PARTITION` expects a partition name, never `BY`.
    assert!(!suggests_by("SELECT * FROM sales PARTITION |"));
    assert!(!suggests_by("ALTER TABLE t DROP PARTITION |"));
}

#[test]
fn is_predicate_continuations_offer_keywords_and_suppress_columns() {
    let words = |values: &[&str]| {
        values
            .iter()
            .map(|value| (*value).to_string())
            .collect::<Vec<_>>()
    };
    let prefix_for = |sql_with_cursor: &str| {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        crate::ui::intellisense::get_word_at_cursor(&sql, cursor)
            .0
            .to_string()
    };
    let at_for = |sql: &str, db_type| {
        SqlEditorWidget::cursor_is_at_is_predicate_keyword_position_for_context(
            &analyze_inline_cursor_sql(sql),
            !prefix_for(sql).is_empty(),
            db_type,
        )
    };
    let kw_for = |sql: &str, db_type| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix_for(sql),
            &analyze_inline_cursor_sql(sql),
            db_type,
        )
    };
    let at = |sql: &str| at_for(sql, None);
    let kw = |sql: &str| kw_for(sql, None);

    let is_tail = words(&[
        "NOT", "NULL", "TRUE", "FALSE", "UNKNOWN", "DISTINCT", "JSON", "OF", "EMPTY", "A", "NAN",
        "INFINITE",
    ]);
    let is_not_tail = words(&[
        "NULL", "TRUE", "FALSE", "UNKNOWN", "DISTINCT", "JSON", "OF", "EMPTY", "A", "NAN",
        "INFINITE",
    ]);
    let json_tail = words(&[
        "VALUE", "ARRAY", "OBJECT", "SCALAR", "STRICT", "LAX", "WITH", "WITHOUT",
    ]);

    // `IS |` / `IS NOT |` open every dialect-valid predicate continuation.
    // Identifiers are never valid immediately after `IS`, so these positions
    // route through the column-suppression chokepoint.
    assert!(at("SELECT * FROM t WHERE a IS |"));
    assert_eq!(kw("SELECT * FROM t WHERE a IS |"), is_tail);
    assert_eq!(kw("SELECT * FROM t WHERE a IS NO|"), words(&["NOT"]));
    assert!(at("SELECT * FROM t WHERE a IS NOT |"));
    assert_eq!(kw("SELECT * FROM t WHERE a IS NOT |"), is_not_tail);

    // Multi-token predicate tails stay exact at each cursor position.
    assert_eq!(kw("SELECT * FROM t WHERE a IS DI|"), words(&["DISTINCT"]));
    assert_eq!(
        kw("SELECT * FROM t WHERE a IS NOT DI|"),
        words(&["DISTINCT"])
    );
    assert_eq!(
        kw("SELECT * FROM t WHERE a IS DISTINCT |"),
        words(&["FROM"])
    );
    assert_eq!(
        kw("SELECT * FROM t WHERE a IS NOT DISTINCT |"),
        words(&["FROM"])
    );
    assert_eq!(kw("SELECT * FROM t WHERE a IS OF |"), words(&["TYPE"]));
    assert_eq!(kw("SELECT * FROM t WHERE a IS A |"), words(&["SET"]));
    assert_eq!(kw("SELECT * FROM t WHERE payload IS JSON |"), json_tail);
    assert_eq!(kw("SELECT * FROM t WHERE payload IS NOT JSON |"), json_tail);
    assert_eq!(
        kw("SELECT * FROM t WHERE payload IS JSON OBJECT |"),
        words(&["STRICT", "LAX", "WITH", "WITHOUT"])
    );
    assert_eq!(
        kw("SELECT * FROM t WHERE payload IS JSON OBJECT STRICT |"),
        words(&["WITH", "WITHOUT"])
    );
    assert_eq!(
        kw("SELECT * FROM t WHERE payload IS JSON OBJECT WITH |"),
        words(&["UNIQUE"])
    );
    assert_eq!(
        kw("SELECT * FROM t WHERE payload IS JSON OBJECT WITHOUT UNIQUE |"),
        words(&["KEYS"])
    );

    let mysql_tail = words(&["NOT", "NULL", "TRUE", "FALSE", "UNKNOWN"]);
    for db_type in [
        crate::db::DatabaseType::MySQL,
        crate::db::DatabaseType::MariaDB,
    ] {
        assert_eq!(
            kw_for("SELECT * FROM t WHERE a IS |", Some(db_type)),
            mysql_tail
        );
        assert!(
            kw_for("SELECT * FROM t WHERE a IS DI|", Some(db_type)).is_empty(),
            "{db_type:?}-compatible IS predicate must not offer DISTINCT"
        );
        assert!(
            !at_for("SELECT * FROM t WHERE payload IS JSON |", Some(db_type)),
            "{db_type:?}-compatible IS predicate must not enter Oracle JSON options"
        );
    }

    // Works for any operand and in any clause, including a chained predicate and a
    // boolean expression in the select list.
    assert!(at("SELECT * FROM t WHERE f(x) IS |"));
    assert!(at("SELECT * FROM t WHERE a IS NULL AND b IS |"));
    assert!(at("SELECT a IS | FROM t"));

    // Not the operator: a completed predicate, an ordinary operand position, the
    // `<col> NOT` predicate tail, a qualified member column named `is`, and the
    // continuation after a finished predicate.
    assert!(!at("SELECT * FROM t WHERE a IS NULL |"));
    assert!(!at(
        "SELECT * FROM t WHERE payload IS JSON WITH UNIQUE KEYS |"
    ));
    assert!(!at("SELECT * FROM t WHERE a |"));
    assert!(!at("SELECT * FROM t WHERE a NOT |"));
    assert!(!at("SELECT * FROM t e WHERE e.is |"));
    assert!(!at("SELECT is | FROM t"));
    assert!(
        !kw("SELECT is | FROM t")
            .iter()
            .any(|value| ["NOT", "NULL", "DISTINCT", "JSON"].contains(&value.as_str())),
        "IS keyword continuation leaked without a left operand"
    );
    assert!(!at("SELECT * FROM t WHERE a IS NULL AND b |"));

    for (sql, should_have_boolean_tail) in [
        ("SELECT * FROM t WHERE a IS NULL |", true),
        ("SELECT * FROM t WHERE a IS NOT NULL |", true),
        ("SELECT * FROM t WHERE a IS DISTINCT FROM b |", true),
        ("SELECT * FROM t WHERE a IS NOT DISTINCT FROM b |", true),
        ("SELECT * FROM t WHERE payload IS JSON |", false),
        (
            "SELECT * FROM t WHERE payload IS JSON OBJECT WITH UNIQUE KEYS |",
            true,
        ),
        (
            "SELECT * FROM t WHERE payload IS NOT JSON ARRAY STRICT WITHOUT UNIQUE KEYS |",
            true,
        ),
    ] {
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "completed IS predicate should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        if should_have_boolean_tail {
            assert!(
                final_suggestions.iter().any(|value| value == "AND")
                    || final_suggestions.iter().any(|value| value == "OR"),
                "completed IS predicate lost boolean continuation at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        } else {
            assert!(
                final_suggestions.iter().any(|value| value == "OBJECT"),
                "open IS JSON option tail lost JSON options at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "EMPNO",
            "ENAME",
            "DEPTNO",
            "DNAME",
            "RUN_JOB",
            "CALC_TOTAL",
        ] {
            assert!(
                !final_suggestions.iter().any(|value| value == leaked),
                "{leaked} leaked after completed IS predicate at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
}

#[test]
fn is_type_specific_predicate_tails_require_matching_left_operand() {
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));
    let kw = |sql_with_cursor: &str, db_type: crate::db::DatabaseType| -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let (prefix, word_start, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let qualifier = SqlEditorWidget::qualifier_before_word_in_text(&sql, word_start);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context_for_db(
            qualifier.as_deref(),
            &ctx,
            Some(db_type),
        );
        let mut data = IntellisenseData::new();
        data.tables = vec!["T".to_string()];
        data.set_columns_for_table(
            "T",
            vec![
                "NESTED_COL".to_string(),
                "FLOAT_COL".to_string(),
                "NUM_COL".to_string(),
                "CHAR_COL".to_string(),
            ],
        );
        data.set_column_meta_for_table(
            "T",
            HashMap::from([
                (
                    "NESTED_COL".to_string(),
                    ColumnMeta {
                        type_display: "NESTED TABLE OF NUMBER".to_string(),
                        nullable: true,
                        is_primary_key: false,
                    },
                ),
                (
                    "FLOAT_COL".to_string(),
                    ColumnMeta {
                        type_display: "BINARY_DOUBLE".to_string(),
                        nullable: true,
                        is_primary_key: false,
                    },
                ),
                (
                    "NUM_COL".to_string(),
                    ColumnMeta {
                        type_display: "NUMBER".to_string(),
                        nullable: true,
                        is_primary_key: false,
                    },
                ),
                (
                    "CHAR_COL".to_string(),
                    ColumnMeta {
                        type_display: "VARCHAR2(20)".to_string(),
                        nullable: true,
                        is_primary_key: false,
                    },
                ),
            ]),
        );
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(db_type),
        );
        SqlEditorWidget::collect_expected_keyword_suggestions_with_expression_context(
            &prefix,
            &ctx,
            Some(db_type),
            Some(expr_keyword_ctx),
        )
    };
    let oracle = |sql: &str| kw(sql, crate::db::DatabaseType::Oracle);

    for sql in [
        "SELECT * FROM t WHERE num_col IS |",
        "SELECT * FROM t WHERE char_col IS |",
        "SELECT * FROM t WHERE num_col IS NOT |",
        "SELECT * FROM t WHERE char_col IS NOT |",
    ] {
        let suggestions = oracle(sql);
        assert!(
            !has(&suggestions, "EMPTY") && !has(&suggestions, "A"),
            "collection-only IS predicate tails leaked for scalar operand `{sql}`: {suggestions:?}"
        );
        assert!(
            !has(&suggestions, "NAN") && !has(&suggestions, "INFINITE"),
            "floating-only IS predicate tails leaked for scalar operand `{sql}`: {suggestions:?}"
        );
        assert!(
            has(&suggestions, "NULL") && has(&suggestions, "JSON"),
            "general IS predicate tails were lost for scalar operand `{sql}`: {suggestions:?}"
        );
    }

    for sql in [
        "SELECT * FROM t WHERE float_col IS |",
        "SELECT * FROM t WHERE float_col IS NOT |",
    ] {
        let suggestions = oracle(sql);
        assert!(
            has(&suggestions, "NAN") && has(&suggestions, "INFINITE"),
            "floating IS predicate tails were suppressed for `{sql}`: {suggestions:?}"
        );
        assert!(
            !has(&suggestions, "EMPTY") && !has(&suggestions, "A"),
            "collection-only tails leaked after floating operand `{sql}`: {suggestions:?}"
        );
    }

    for sql in [
        "SELECT * FROM t WHERE nested_col IS |",
        "SELECT * FROM t WHERE nested_col IS NOT |",
    ] {
        let suggestions = oracle(sql);
        assert!(
            has(&suggestions, "EMPTY") && has(&suggestions, "A"),
            "collection IS predicate tails were suppressed for `{sql}`: {suggestions:?}"
        );
    }

    assert_eq!(
        oracle("SELECT * FROM t WHERE nested_col IS em|"),
        vec!["EMPTY".to_string()]
    );
    assert_eq!(
        oracle("SELECT * FROM t WHERE nested_col IS a|"),
        vec!["A".to_string()]
    );
    assert_eq!(
        oracle("SELECT * FROM t WHERE nested_col IS A |"),
        vec!["SET".to_string()]
    );
    let scalar_is_a = oracle("SELECT * FROM t WHERE num_col IS A |");
    assert!(
        !has(&scalar_is_a, "SET"),
        "SET tail must not appear after scalar IS A: {scalar_is_a:?}"
    );
    assert_eq!(
        oracle("SELECT * FROM t WHERE float_col IS na|"),
        vec!["NAN".to_string()]
    );
    assert_eq!(
        oracle("SELECT * FROM t WHERE float_col IS inf|"),
        vec!["INFINITE".to_string()]
    );
    assert!(
        oracle("SELECT * FROM t WHERE num_col IS na|").is_empty(),
        "NAN must not appear after ordinary NUMBER operands"
    );

    let mysql = kw(
        "SELECT * FROM t WHERE nested_col IS |",
        crate::db::DatabaseType::MySQL,
    );
    assert!(
        !has(&mysql, "EMPTY") && !has(&mysql, "A"),
        "Oracle collection IS tails leaked in MySQL mode: {mysql:?}"
    );
}

#[test]
fn is_of_type_slots_offer_type_objects_and_suppress_columns() {
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));
    let suggestions_for_db = |sql_with_cursor: &str,
                              db_type: crate::db::DatabaseType|
     -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, word_start, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let qualifier = SqlEditorWidget::qualifier_before_word_in_text(&sql, word_start);
        let column_tables =
            SqlEditorWidget::resolve_column_tables_for_context(qualifier.as_deref(), &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string()];
        data.types = vec!["ADDR_TYPE".to_string(), "EMPLOYEE_T".to_string()];
        data.set_columns_for_table("EMP", vec!["OBJ_COL".to_string(), "EMPNO".to_string()]);
        data.rebuild_indices();
        let at_data_type_position = SqlEditorWidget::data_type_position_for_context_for_db(
            &ctx,
            !prefix.is_empty(),
            Some(db_type),
        )
        .is_some();
        let at_keyword_only_slot =
            SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
                &ctx,
                !prefix.is_empty(),
                Some(db_type),
            );
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(db_type),
        );
        let mut values = if at_data_type_position {
            data.get_type_object_suggestions(&prefix)
        } else if at_keyword_only_slot {
            Vec::new()
        } else {
            SqlEditorWidget::base_suggestions_for_context(
                &mut data,
                &prefix,
                None,
                column_scope.as_deref(),
                matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
                context,
                false,
                Some(db_type),
                expr_keyword_ctx,
            )
        };
        for keyword in SqlEditorWidget::collect_expected_keyword_suggestions_with_expression_context(
            &prefix,
            &ctx,
            Some(db_type),
            Some(expr_keyword_ctx),
        ) {
            if !values
                .iter()
                .any(|value| value.eq_ignore_ascii_case(&keyword))
            {
                values.push(keyword);
            }
        }
        values
    };
    let suggestions = |sql_with_cursor: &str| {
        suggestions_for_db(sql_with_cursor, crate::db::DatabaseType::Oracle)
    };
    let suppresses_for_db = |sql: &str, db_type: crate::db::DatabaseType| {
        let cursor = sql.find('|').expect("cursor marker");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
            &analyze_inline_cursor_sql(sql),
            !prefix.is_empty(),
            Some(db_type),
        ) || SqlEditorWidget::data_type_position_for_context_for_db(
            &analyze_inline_cursor_sql(sql),
            !prefix.is_empty(),
            Some(db_type),
        )
        .is_some()
    };
    let suppresses = |sql: &str| suppresses_for_db(sql, crate::db::DatabaseType::Oracle);

    for sql in [
        "SELECT * FROM emp WHERE obj_col IS OF TYPE |",
        "SELECT * FROM emp WHERE obj_col IS NOT OF TYPE |",
    ] {
        assert!(
            suppresses(sql),
            "IS OF TYPE opener leaked columns for `{sql}`"
        );
        assert!(
            suggestions(sql).is_empty(),
            "punctuation-only IS OF TYPE opener should not offer identifiers for `{sql}`"
        );
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "IS OF TYPE opener should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.is_empty(),
            "IS OF TYPE opener should not offer catalog or keywords at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
    }

    for sql in [
        "SELECT * FROM emp WHERE obj_col IS OF TYPE (|)",
        "SELECT * FROM emp WHERE obj_col IS OF TYPE (ONLY |)",
        "SELECT * FROM emp WHERE obj_col IS OF TYPE (addr_type, |)",
        "SELECT * FROM emp WHERE obj_col IS NOT OF TYPE (|)",
        "SELECT * FROM emp WHERE obj_col IS NOT OF TYPE (ONLY |)",
        "SELECT * FROM emp WHERE obj_col IS NOT OF TYPE (addr_type, |)",
    ] {
        let values = suggestions(sql);
        assert!(
            has(&values, "ADDR_TYPE") && has(&values, "EMPLOYEE_T"),
            "IS OF TYPE list lost type objects for `{sql}`: {values:?}"
        );
        assert!(
            !has(&values, "OBJ_COL") && !has(&values, "EMPNO"),
            "columns leaked into IS OF TYPE list for `{sql}`: {values:?}"
        );
    }
    assert!(
        has(
            &suggestions("SELECT * FROM emp WHERE obj_col IS OF TYPE (|)"),
            "ONLY"
        ),
        "IS OF TYPE list should offer ONLY before a type name"
    );
    assert_eq!(
        suggestions("SELECT * FROM emp WHERE obj_col IS OF TYPE (ON|)"),
        vec!["ONLY".to_string()]
    );
    assert_eq!(
        suggestions("SELECT * FROM emp WHERE obj_col IS NOT OF TYPE (ON|)"),
        vec!["ONLY".to_string()]
    );
    for sql in [
        "SELECT * FROM emp WHERE obj_col IS OF TYPE (addr|)",
        "SELECT * FROM emp WHERE obj_col IS OF TYPE (ONLY addr|)",
        "SELECT * FROM emp WHERE obj_col IS NOT OF TYPE (addr|)",
        "SELECT * FROM emp WHERE obj_col IS NOT OF TYPE (ONLY addr|)",
    ] {
        assert_eq!(
            suggestions(sql),
            vec!["ADDR_TYPE".to_string()],
            "IS OF TYPE type-name prefix should filter to matching TYPE objects for `{sql}`"
        );
    }
    for sql in [
        "SELECT * FROM emp WHERE obj_col IS OF TYPE (addr_type |)",
        "SELECT * FROM emp WHERE obj_col IS OF TYPE (ONLY addr_type |)",
        "SELECT * FROM emp WHERE obj_col IS NOT OF TYPE (addr_type |)",
        "SELECT * FROM emp WHERE obj_col IS NOT OF TYPE (ONLY addr_type |)",
    ] {
        assert!(
            suppresses(sql),
            "completed IS OF TYPE name leaked columns for `{sql}`"
        );
        let got = suggestions(sql);
        assert!(
            !has(&got, "ADDR_TYPE") && !has(&got, "EMPLOYEE_T") && !has(&got, "ONLY"),
            "completed IS OF TYPE name should not offer identifiers for `{sql}`: {got:?}"
        );
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "completed IS OF TYPE name should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.is_empty(),
            "completed IS OF TYPE name should not offer catalog or keywords at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
    }

    for sql in [
        "SELECT * FROM emp WHERE obj_col IS OF TYPE (addr_type) |",
        "SELECT * FROM emp WHERE obj_col IS OF TYPE (ONLY addr_type) |",
        "SELECT * FROM emp WHERE obj_col IS NOT OF TYPE (addr_type) |",
        "SELECT * FROM emp WHERE obj_col IS NOT OF TYPE (ONLY addr_type) |",
    ] {
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "completed IS OF TYPE predicate should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            has(&final_suggestions, "AND") || has(&final_suggestions, "OR"),
            "completed IS OF TYPE predicate lost boolean continuation at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "OBJ_COL",
            "EMPNO",
            "ADDR_TYPE",
            "EMPLOYEE_T",
            "RUN_JOB",
            "CALC_TOTAL",
        ] {
            assert!(
                !has(&final_suggestions, leaked),
                "{leaked} leaked after completed IS OF TYPE predicate at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }

    for db_type in [
        crate::db::DatabaseType::MySQL,
        crate::db::DatabaseType::MariaDB,
    ] {
        for sql in [
            "SELECT * FROM emp WHERE obj_col IS OF TYPE |",
            "SELECT * FROM emp WHERE obj_col IS OF TYPE (|)",
            "SELECT * FROM emp WHERE obj_col IS OF TYPE (ONLY |)",
            "SELECT * FROM emp WHERE obj_col IS OF TYPE (addr|)",
            "SELECT * FROM emp WHERE obj_col IS OF TYPE (ONLY addr|)",
        ] {
            let values = suggestions_for_db(sql, db_type);
            assert!(
                !has(&values, "ADDR_TYPE") && !has(&values, "EMPLOYEE_T"),
                "Oracle IS OF TYPE object suggestions leaked for {db_type:?} `{sql}`: {values:?}"
            );
        }
        assert!(
            !suppresses_for_db("SELECT * FROM emp WHERE obj_col IS OF TYPE |", db_type),
            "Oracle-only IS OF TYPE opener should not become a {db_type:?} punctuation slot"
        );
    }
}

#[test]
fn oracle_sequence_value_slots_stay_sequence_scoped() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);
    let assert_no_non_sequence_catalog =
        |sql: &str, db: crate::db::DatabaseType, suggestions: &[String]| {
            for leaked in [
                "EMP",
                "DEPT",
                "EMP_V",
                "MVIEW_SALES",
                "ADDRESS_T",
                "APP_USER",
                "SCOTT",
                "RUN_JOB",
                "CALC_TOTAL",
                "HR_PKG",
                "IDX_EMP_NAME",
                "EMPNO",
                "ENAME",
                "WHERE",
                "SELECT",
            ] {
                assert!(
                    !contains(suggestions, leaked),
                    "{leaked} leaked into sequence slot at `{sql}` {db:?}: {suggestions:?}"
                );
            }
        };

    for sql in [
        "SELECT |.NEXTVAL FROM dual",
        "SELECT emp|.NEXTVAL FROM dual",
        "SELECT |.CURRVAL FROM dual",
        "INSERT INTO emp (empno) VALUES (|.NEXTVAL)",
        "UPDATE emp SET empno = |.NEXTVAL",
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind,
            Some(ExpectedObjectSuggestionKind::Sequence),
            "Oracle sequence value slot should resolve only sequences at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            contains(&final_suggestions, "EMP_SEQ"),
            "EMP_SEQ missing from Oracle sequence value slot at `{sql}`: {final_suggestions:?}"
        );
        assert_no_non_sequence_catalog(sql, Oracle, &final_suggestions);
    }

    for sql in [
        "SELECT app.|.NEXTVAL FROM dual",
        "SELECT app.emp|.NEXTVAL FROM dual",
        "INSERT INTO emp (empno) VALUES (app.|.NEXTVAL)",
        "UPDATE emp SET empno = app.emp|.NEXTVAL",
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind,
            Some(ExpectedObjectSuggestionKind::Sequence),
            "qualified Oracle sequence value slot should resolve only sequences at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            contains(&final_suggestions, "EMP_SEQ"),
            "schema EMP_SEQ missing from qualified Oracle sequence value slot at `{sql}`: {final_suggestions:?}"
        );
        for leaked in [
            "EMP", "EMP_VIEW", "EMP_FUNC", "EMP_PROC", "EMP_TYPE", "EMP_PKG",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into qualified Oracle sequence value slot at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }

    for sql in [
        "SELECT emp_seq.NEXTVAL | FROM dual",
        "SELECT emp_seq.CURRVAL | FROM dual",
        "INSERT INTO emp (empno) VALUES (emp_seq.NEXTVAL) |",
        "UPDATE emp SET empno = emp_seq.NEXTVAL |",
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "completed sequence pseudocolumn tail should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in ["EMP_SEQ", "NEXTVAL", "CURRVAL", "EMP", "DEPT", "CALC_TOTAL"] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked after completed sequence pseudocolumn at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }

    for db in [MySQL, MariaDB] {
        for sql in [
            "SELECT |.NEXTVAL FROM dual",
            "SELECT emp|.NEXTVAL FROM dual",
            "SELECT app.|.NEXTVAL FROM dual",
        ] {
            let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
            assert!(
                !matches!(kind, Some(ExpectedObjectSuggestionKind::Sequence)),
                "Oracle sequence object kind leaked into {db:?} at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
            assert!(
                !contains(&final_suggestions, "EMP_SEQ"),
                "Oracle sequence catalog leaked into {db:?} at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
}

#[test]
fn dml_target_continuation_offers_structural_keyword_and_suppresses_relations() {
    let det = |sql: &str| {
        SqlEditorWidget::cursor_is_after_complete_dml_target_for_context(
            &analyze_inline_cursor_sql(sql),
            false,
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let kw = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    // After a complete DML target table, only the following clause keyword is
    // grammatical — never another relation — so the position both offers that
    // keyword and routes through the identifier-suppression flag.
    assert!(det("UPDATE emp |"));
    assert_eq!(kw("UPDATE emp |"), vec!["SET"]);
    assert!(det("UPDATE emp e |")); // after the alias too
    assert!(det("UPDATE schema.emp |")); // schema-qualified target
    assert!(det("DELETE FROM emp |"));
    assert_eq!(kw("DELETE FROM emp |"), vec!["WHERE"]);
    assert!(det("DELETE FROM emp e |"));
    assert!(det("INSERT INTO emp |"));
    assert_eq!(
        kw("INSERT INTO emp |"),
        vec!["SET", "BY NAME", "VALUES", "SELECT"]
    );
    assert_eq!(kw("INSERT INTO emp BY |"), vec!["NAME"]);
    assert!(det("MERGE INTO emp |"));
    assert_eq!(kw("MERGE INTO emp |"), vec!["USING"]);
    assert!(det("MERGE INTO emp e |"));

    // The target is not yet complete (still the leading keyword), so the table
    // list must keep flowing.
    assert!(!det("UPDATE |"));
    assert!(!det("DELETE FROM |"));
    assert!(!det("INSERT INTO |"));
    assert!(!det("MERGE INTO |"));

    // A SELECT `FROM` shares the phase but is not a DML target — table completion
    // (including comma-separated cross joins) stays intact.
    assert!(!det("SELECT * FROM emp |"));
    assert!(!det("SELECT * FROM a, |"));
    assert!(!det("SELECT * FROM t WHERE x IN (SELECT a FROM u |)"));

    // MySQL multi-table / join forms still expect another relation, so the simple
    // single-target heuristics must not fire: a trailing comma, or a join target.
    assert!(!det("UPDATE t1, |"));
    assert!(!det("DELETE t1 FROM t1 JOIN t2 |"));
    assert!(!det("DELETE FROM emp e JOIN x |"));

    // Once the structural keyword is present the dedicated clause phase takes over.
    assert!(!det("UPDATE emp SET a = 1 |"));
    assert!(!det("DELETE FROM emp WHERE |"));
    assert!(!det("INSERT INTO emp VALUES |"));

    // `CREATE INDEX ... ON t` shares the phase but is not a DML target.
    assert!(!det("CREATE INDEX i ON t |"));
}

#[test]
fn join_target_continuation_offers_on_using_and_suppresses_relations() {
    let det = |sql: &str| {
        SqlEditorWidget::cursor_is_after_complete_join_target_for_context_for_db(
            &analyze_inline_cursor_sql(sql),
            false,
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let kw = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    // After a complete JOIN target table, the join condition keywords are
    // grammatical — never another relation — so the slot offers them and routes
    // through the identifier-suppression flag.
    assert!(det("SELECT * FROM a JOIN b |"));
    assert_eq!(kw("SELECT * FROM a JOIN b |"), vec!["ON", "USING"]);
    assert!(det("SELECT * FROM a JOIN b x |")); // after the alias too
    assert!(det("SELECT * FROM a LEFT JOIN b |"));
    assert!(det("SELECT * FROM a LEFT OUTER JOIN b |"));
    assert!(det("SELECT * FROM a INNER JOIN b |"));
    assert!(det("SELECT * FROM a JOIN sch.b |")); // schema-qualified target
    assert!(det("SELECT * FROM a JOIN b ON a.x = b.y JOIN c |")); // chained join
    assert!(det("SELECT * FROM (SELECT 1 x) z JOIN b |")); // subquery left side
    assert!(det("SELECT 1 FROM u JOIN v |")); // inside a subquery scope

    // `CROSS`/`NATURAL` joins take no condition keyword.
    assert!(!det("SELECT * FROM a CROSS JOIN b |"));
    assert!(!det("SELECT * FROM a NATURAL JOIN b |"));

    // The target is not yet present, the condition has already started, or the
    // cursor is in an ordinary FROM/comma position — table completion stays intact.
    assert!(!det("SELECT * FROM a JOIN |"));
    assert!(!det("SELECT * FROM a JOIN b ON |"));
    assert!(!det("SELECT * FROM a JOIN b ON a.x = b.y |"));
    assert!(!det("SELECT * FROM a JOIN b USING |"));
    assert!(!det("SELECT * FROM a JOIN b USING (c) |"));
    assert!(!det("SELECT * FROM a |"));
    assert!(!det("SELECT * FROM a, b |"));
    // A bare join-type word routes through the join-continuation family instead.
    assert!(!det("SELECT * FROM a LEFT |"));

    let kw_for = |sql: &str, db: crate::db::DatabaseType| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |values: &[String], needle: &str| values.iter().any(|value| value == needle);
    for db in [
        crate::db::DatabaseType::MySQL,
        crate::db::DatabaseType::MariaDB,
    ] {
        let mysql_straight = kw_for("SELECT * FROM a STRAIGHT_JOIN b |", db);
        assert!(
            has(&mysql_straight, "ON") && has(&mysql_straight, "USING"),
            "{db:?} STRAIGHT_JOIN target should offer ON/USING: {mysql_straight:?}"
        );
    }
    for (db, sql) in [
        (
            crate::db::DatabaseType::Oracle,
            "SELECT * FROM a STRAIGHT_JOIN b |",
        ),
        (
            crate::db::DatabaseType::MySQL,
            "SELECT * FROM a FULL JOIN b |",
        ),
        (
            crate::db::DatabaseType::MySQL,
            "SELECT * FROM a FULL OUTER JOIN b |",
        ),
        (
            crate::db::DatabaseType::MariaDB,
            "SELECT * FROM a FULL JOIN b |",
        ),
        (
            crate::db::DatabaseType::MariaDB,
            "SELECT * FROM a FULL OUTER JOIN b |",
        ),
    ] {
        let got = kw_for(sql, db);
        for leaked in ["ON", "USING"] {
            assert!(
                !has(&got, leaked),
                "{leaked} leaked into unsupported join target at `{sql}` {db:?}: {got:?}"
            );
        }
    }
}

#[test]
fn interval_unit_slot_suppresses_columns_and_offers_unit_keywords() {
    let at_unit = |sql: &str| {
        SqlEditorWidget::interval_unit_position_for_context(&analyze_inline_cursor_sql(sql), false)
            .is_some()
    };
    // Every qualifier slot of a quoted INTERVAL literal suppresses columns.
    assert!(at_unit("SELECT hire_date - INTERVAL '5' | FROM emp"));
    assert!(at_unit("SELECT hire_date - INTERVAL '5' DAY | FROM emp"));
    assert!(at_unit("SELECT hire_date - INTERVAL '5' DAY(2) | FROM emp"));
    assert!(at_unit("SELECT hire_date - INTERVAL '5' DAY TO | FROM emp"));
    assert!(at_unit(
        "SELECT hire_date - INTERVAL '5' DAY(2) TO | FROM emp"
    ));
    assert!(at_unit(
        "SELECT hire_date + INTERVAL '1-2' YEAR TO | FROM emp"
    ));
    assert!(at_unit(
        "SELECT hire_date - INTERVAL '1' SECOND(3) | FROM emp"
    ));
    // MySQL's unquoted `INTERVAL <expr> <unit>` keeps the expr a column position.
    assert!(!at_unit("SELECT hire_date - INTERVAL | DAY FROM emp"));
    // Ordinary expression positions are unaffected.
    assert!(!at_unit("SELECT | FROM emp"));
    assert!(!at_unit("SELECT hire_date - | FROM emp"));

    // Oracle leading units, then `TO`, then trailing units.
    let oracle = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let leading = oracle("SELECT hire_date - INTERVAL '5' | FROM emp");
    assert!(leading.iter().any(|value| value == "DAY"));
    assert!(leading.iter().any(|value| value == "SECOND"));
    assert_eq!(
        oracle("SELECT hire_date - INTERVAL '5' DAY | FROM emp"),
        vec!["TO".to_string()]
    );
    assert_eq!(
        oracle("SELECT hire_date - INTERVAL '5' DAY(2) | FROM emp"),
        vec!["TO".to_string()]
    );
    let trailing = oracle("SELECT hire_date - INTERVAL '5' DAY TO | FROM emp");
    assert!(trailing.iter().any(|value| value == "SECOND"));
    assert!(!trailing.iter().any(|value| value == "DAY"));
    assert!(!trailing.iter().any(|value| value == "MONTH"));
    assert_eq!(
        oracle("SELECT hire_date - INTERVAL '5' DAY(2) TO | FROM emp"),
        vec![
            "HOUR".to_string(),
            "MINUTE".to_string(),
            "SECOND".to_string()
        ]
    );
    assert_eq!(
        oracle("SELECT hire_date - INTERVAL '5' HOUR TO | FROM emp"),
        vec!["MINUTE".to_string(), "SECOND".to_string()]
    );
    assert_eq!(
        oracle("SELECT hire_date - INTERVAL '5' MINUTE TO | FROM emp"),
        vec!["SECOND".to_string()]
    );
    assert_eq!(
        oracle("SELECT hire_date - INTERVAL '1-2' YEAR TO | FROM emp"),
        vec!["MONTH".to_string()]
    );
    assert_eq!(
        oracle("SELECT hire_date - INTERVAL '1-2' YEAR(2) TO | FROM emp"),
        vec!["MONTH".to_string()]
    );
    assert!(
        oracle("SELECT hire_date - INTERVAL '1' MONTH | FROM emp").is_empty(),
        "MONTH is a complete leading unit and must not offer TO"
    );
    assert!(
        oracle("SELECT hire_date - INTERVAL '1' SECOND(3) | FROM emp").is_empty(),
        "SECOND precision is still a complete leading unit and must not offer TO"
    );
    assert!(
        oracle("SELECT hire_date - INTERVAL '1' SECOND | FROM emp").is_empty(),
        "SECOND is a complete leading unit and must not offer TO"
    );
    assert!(
        !at_unit("SELECT hire_date - INTERVAL '1' MONTH TO | FROM emp"),
        "invalid MONTH TO slot must not be treated as a keyword unit slot"
    );
    for db_type in [
        crate::db::DatabaseType::MySQL,
        crate::db::DatabaseType::MariaDB,
    ] {
        // MySQL-family offers its own interval units at the leading slot and no `TO`.
        let mysql_leading = SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql("SELECT hire_date - INTERVAL '5' | FROM emp"),
            Some(db_type),
        );
        assert!(mysql_leading.iter().any(|value| value == "QUARTER"));
        assert!(mysql_leading.iter().any(|value| value == "DAY_HOUR"));
        let mysql_prefixed = SqlEditorWidget::collect_expected_keyword_suggestions(
            "DAY_H",
            &analyze_inline_cursor_sql("SELECT hire_date - INTERVAL '5' DAY_H| FROM emp"),
            Some(db_type),
        );
        assert_eq!(mysql_prefixed, vec!["DAY_HOUR".to_string()]);
        assert!(
            at_unit("SELECT hire_date - INTERVAL '5' DAY_HOUR | FROM emp"),
            "completed MySQL-family compound interval unit should suppress columns"
        );
        assert!(
            SqlEditorWidget::collect_expected_keyword_suggestions(
                "",
                &analyze_inline_cursor_sql("SELECT hire_date - INTERVAL '5' DAY_HOUR | FROM emp"),
                Some(db_type),
            )
            .is_empty(),
            "completed MySQL-family compound interval unit should not offer TO"
        );
    }
}

#[test]
fn extract_and_interval_keyword_slots_suppress_catalog_in_final_suggestions() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for (sql, expected) in [
        ("SELECT EXTRACT(| FROM hiredate) FROM emp", "YEAR"),
        ("SELECT EXTRACT(Y| FROM hiredate) FROM emp", "YEAR"),
        (
            "SELECT EXTRACT(TIMEZONE_H| FROM hiredate) FROM emp",
            "TIMEZONE_HOUR",
        ),
        ("SELECT EXTRACT(YEAR |) FROM emp", "FROM"),
        ("SELECT EXTRACT(YEAR F|) FROM emp", "FROM"),
        ("SELECT INTERVAL '1' | FROM emp", "DAY"),
        ("SELECT INTERVAL '1' D| FROM emp", "DAY"),
        ("SELECT INTERVAL '1' DAY | FROM emp", "TO"),
        ("SELECT INTERVAL '1' DAY T| FROM emp", "TO"),
        ("SELECT INTERVAL '1' DAY TO | FROM emp", "SECOND"),
        ("SELECT INTERVAL '1' DAY TO S| FROM emp", "SECOND"),
        ("SELECT INTERVAL '1' DAY(2) TO | FROM emp", "SECOND"),
        ("SELECT INTERVAL '1-2' YEAR TO | FROM emp", "MONTH"),
        ("SELECT INTERVAL '1-2' YEAR TO M| FROM emp", "MONTH"),
        ("SELECT INTERVAL '1-2' YEAR(2) TO | FROM emp", "MONTH"),
        ("SELECT INTERVAL '1' HOUR TO | FROM emp", "MINUTE"),
        ("SELECT INTERVAL '1' HOUR TO M| FROM emp", "MINUTE"),
        ("SELECT INTERVAL '1' MINUTE TO | FROM emp", "SECOND"),
        ("SELECT INTERVAL '1' MINUTE TO S| FROM emp", "SECOND"),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "EXTRACT/INTERVAL keyword slot should not resolve object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            contains(&final_suggestions, expected),
            "{expected} missing from EXTRACT/INTERVAL keyword slot at `{sql}`: {final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "EMPNO",
            "ENAME",
            "RUN_JOB",
            "CALC_TOTAL",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into EXTRACT/INTERVAL keyword slot at `{sql}`: {final_suggestions:?}"
            );
        }
    }

    for (sql, unexpected) in [
        ("SELECT INTERVAL '1' DAY TO | FROM emp", "MONTH"),
        ("SELECT INTERVAL '1' DAY(2) TO | FROM emp", "MONTH"),
        ("SELECT INTERVAL '1' HOUR TO | FROM emp", "HOUR"),
        ("SELECT INTERVAL '1' HOUR TO | FROM emp", "MONTH"),
        ("SELECT INTERVAL '1' MINUTE TO | FROM emp", "MINUTE"),
        ("SELECT INTERVAL '1-2' YEAR TO | FROM emp", "SECOND"),
        ("SELECT INTERVAL '1-2' YEAR(2) TO | FROM emp", "SECOND"),
        ("SELECT INTERVAL '1' MONTH | FROM emp", "TO"),
        ("SELECT INTERVAL '1' SECOND | FROM emp", "TO"),
        ("SELECT INTERVAL '1' SECOND(3) | FROM emp", "TO"),
    ] {
        let (_, _, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert!(
            !contains(&final_suggestions, unexpected),
            "{unexpected} leaked into INTERVAL slot at `{sql}`: {final_suggestions:?}"
        );
    }

    for db in [MySQL, MariaDB] {
        let (kind, keywords, mysql_compound) =
            audit_final_suggestions_for("SELECT INTERVAL '1' DAY_HOUR | FROM emp", db);
        assert_eq!(
            kind, None,
            "completed {db:?} compound INTERVAL unit should not resolve object kind: keywords={keywords:?} final={mysql_compound:?}"
        );
        assert!(
            mysql_compound.is_empty(),
            "completed {db:?} compound INTERVAL unit should not offer catalog or TO: keywords={keywords:?} final={mysql_compound:?}"
        );
    }
}

#[test]
fn temporal_literal_body_slots_suppress_columns() {
    let exclude_flag = |sql_with_cursor: &str| {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        !prefix.is_empty()
    };
    let at = |sql: &str, db_type| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
            &analyze_inline_cursor_sql(sql),
            exclude_flag(sql),
            Some(db_type),
        )
    };

    for sql in [
        "SELECT DATE | FROM dual",
        "SELECT DATE val| FROM dual",
        "SELECT TIME | FROM dual",
        "SELECT TIMESTAMP | FROM dual",
        "SELECT TIMESTAMP val| FROM dual",
        "SELECT TIMESTAMP WITH TIME ZONE | FROM dual",
        "SELECT TIMESTAMP(6) WITH TIME ZONE val| FROM dual",
        "SELECT TIMESTAMP WITH LOCAL TIME ZONE | FROM dual",
        "SELECT TIME(3) WITH TIME ZONE | FROM dual",
        "SELECT INTERVAL | FROM dual",
    ] {
        assert!(
            at(sql, crate::db::DatabaseType::Oracle),
            "temporal literal body slot did not suppress columns for `{sql}`"
        );
    }

    for db_type in [
        crate::db::DatabaseType::MySQL,
        crate::db::DatabaseType::MariaDB,
    ] {
        assert!(
            at("SELECT DATE | FROM emp", db_type),
            "{db_type:?} DATE literal body slot did not suppress columns"
        );
        assert!(
            !at("SELECT CURRENT_DATE | FROM emp", db_type),
            "{db_type:?} complete niladic temporal value must not be treated as a literal-body slot"
        );
        assert!(
            !at("SELECT hiredate - INTERVAL | DAY FROM emp", db_type),
            "{db_type:?} unquoted INTERVAL expression slot must keep column completion"
        );
    }
    assert!(
        !at("SELECT t.DATE | FROM t", crate::db::DatabaseType::Oracle),
        "qualified column named DATE must not be treated as a literal introducer"
    );

    for sql in [
        "SELECT TIMESTAMP WITH TIME ZONE | FROM emp",
        "SELECT TIMESTAMP(6) WITH TIME ZONE val| FROM emp",
        "SELECT TIMESTAMP WITH LOCAL TIME ZONE | FROM emp",
        "SELECT TIME(3) WITH TIME ZONE | FROM emp",
    ] {
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "temporal literal body slot should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.is_empty(),
            "temporal literal body slot should not offer catalog or keywords at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
    }
}

#[test]
fn merge_when_matched_keyword_is_scoped_to_merge_action_slot() {
    let suggests_matched = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
        .iter()
        .any(|value| value == "MATCHED")
    };
    // Real MERGE merge-action slots still offer MATCHED.
    assert!(suggests_matched(
        "MERGE INTO target t USING src s ON (t.id = s.id) WHEN |"
    ));
    assert!(suggests_matched(
        "MERGE INTO target t USING src s ON (t.id = s.id) WHEN NOT |"
    ));
    // A `CASE WHEN` branch is never a merge-action slot: no MATCHED, even when
    // the CASE lives inside a MERGE's SET/INSERT expression.
    assert!(!suggests_matched("SELECT CASE WHEN | END FROM t"));
    assert!(!suggests_matched("SELECT CASE WHEN NOT | END FROM t"));
    assert!(!suggests_matched(
        "MERGE INTO target t USING src s ON (t.id = s.id) \
         WHEN MATCHED THEN UPDATE SET t.v = CASE WHEN |"
    ));
    // PL/SQL searched CASE statement is likewise not a merge slot.
    assert!(!suggests_matched(
        "BEGIN CASE WHEN | THEN NULL; END CASE; END;"
    ));
}

