    assert_eq!(create_public_database_suggestions, vec!["LINK".to_string()]);
    assert!(create_shared_suggestions
        .iter()
        .any(|value| value == "PUBLIC"));
    assert!(create_shared_suggestions
        .iter()
        .any(|value| value == "DATABASE"));
    assert!(create_or_replace_shared_suggestions.is_empty());
