#[test]
fn build_signature_label_formats_params_and_spans() {
    fn proc_arg(
        name: Option<&str>,
        position: i32,
        in_out: &str,
        data_type: Option<&str>,
        data_length: Option<i32>,
    ) -> crate::db::ProcedureArgument {
        crate::db::ProcedureArgument {
            name: name.map(str::to_string),
            position,
            sequence: position,
            data_type: data_type.map(str::to_string),
            in_out: Some(in_out.to_string()),
            data_length,
            data_precision: None,
            data_scale: None,
            type_owner: None,
            type_name: None,
            type_subname: None,
            pls_type: None,
            overload: None,
            default_value: None,
        }
    }

    let args = vec![
        proc_arg(None, 0, "OUT", Some("NUMBER"), None), // return type
        proc_arg(Some("P_ID"), 1, "IN", Some("NUMBER"), None),
        proc_arg(Some("P_NAME"), 2, "IN", Some("VARCHAR2"), Some(50)),
    ];

    let label = SqlEditorWidget::build_signature_label("myfunc", &args);

    assert_eq!(
        label.text,
        "MYFUNC(P_ID IN NUMBER, P_NAME IN VARCHAR2(50)) RETURN NUMBER"
    );
    assert_eq!(label.arg_spans.len(), 2);
    let (s0, e0) = label.arg_spans[0];
    let (s1, e1) = label.arg_spans[1];
    assert_eq!(&label.text[s0..e0], "P_ID IN NUMBER");
    assert_eq!(&label.text[s1..e1], "P_NAME IN VARCHAR2(50)");

    let mut overload_args = vec![
        proc_arg(Some("P_ID"), 1, "IN", Some("NUMBER"), None),
        proc_arg(Some("P_NAME"), 1, "IN", Some("VARCHAR2"), Some(50)),
        proc_arg(Some("P_FLAG"), 2, "IN", Some("NUMBER"), None),
    ];
    overload_args[0].overload = Some(1);
    overload_args[1].overload = Some(2);
    overload_args[2].overload = Some(2);

    let overloaded = SqlEditorWidget::build_signature_label("myproc", &overload_args);
    assert_eq!(
        overloaded.text,
        "MYPROC(P_ID IN NUMBER)\nMYPROC(P_NAME IN VARCHAR2(50), P_FLAG IN NUMBER)"
    );
    assert_eq!(overloaded.overloads.len(), 2);
    assert_eq!(overloaded.overloads[0].arg_spans.len(), 1);
    assert_eq!(overloaded.overloads[1].arg_spans.len(), 2);
    for overload in &overloaded.overloads {
        assert_eq!(
            &overloaded.text[overload.arg_spans[0].0..overload.arg_spans[0].1],
            if overload.arg_spans.len() == 1 {
                "P_ID IN NUMBER"
            } else {
                "P_NAME IN VARCHAR2(50)"
            }
        );
    }
}

/// Resolve window-frame keyword candidates at the `|` marker.
fn window_frame_candidates(sql_with_cursor: &str) -> Option<Vec<String>> {
    window_frame_candidates_for(sql_with_cursor, crate::db::DatabaseType::Oracle)
}

fn window_frame_candidates_for(
    sql_with_cursor: &str,
    db: crate::db::DatabaseType,
) -> Option<Vec<String>> {
    let cursor = sql_with_cursor
        .find('|')
        .expect("cursor marker should exist");
    let sql = sql_with_cursor.replace('|', "");
    let token_spans = super::query_text::tokenize_sql_spanned(&sql);
    let split_idx = token_spans.partition_point(|span| span.end <= cursor);
    let tokens: Vec<SqlToken> = token_spans.into_iter().map(|span| span.token).collect();
    SqlEditorWidget::expected_window_frame_keyword_candidates(&tokens, split_idx, Some(db))
        .map(|c| c.iter().map(|s| s.to_string()).collect())
}

#[test]
fn window_frame_after_unit_suggests_between_and_bounds() {
    assert_eq!(
        window_frame_candidates("SELECT sum(x) OVER (ORDER BY d ROWS |) FROM t"),
        Some(vec!["BETWEEN".into(), "UNBOUNDED".into(), "CURRENT".into()])
    );
}

