#[test]
fn cte_body_as_paren_is_not_a_window_spec() {
    // `WITH c AS (...)` shares the `name AS (` shape with a named window but must
    // never offer frame keywords for a column called `rows`.
    assert_eq!(
        window_frame_candidates("WITH c AS (SELECT x rows | FROM t) SELECT * FROM c"),
        None
    );
}

/// Data-type keyword suggestions at the `|` marker for a given dialect.
fn data_type_suggestions(
    sql_with_cursor: &str,
    prefix: &str,
    db: crate::db::DatabaseType,
) -> Vec<String> {
    let ctx = analyze_inline_cursor_sql(sql_with_cursor);
    SqlEditorWidget::collect_expected_keyword_suggestions(prefix, &ctx, Some(db))
}

fn has_data_type_keyword(values: &[String]) -> bool {
    values.iter().any(|value| {
        matches!(
            value.to_ascii_uppercase().as_str(),
            "NUMBER"
                | "VARCHAR"
                | "VARCHAR2"
                | "NVARCHAR2"
                | "CHAR"
                | "NCHAR"
                | "DATE"
                | "TIMESTAMP"
                | "INT"
                | "INTEGER"
                | "BLOB"
                | "CLOB"
                | "DECIMAL"
                | "FLOAT"
                | "PLS_INTEGER"
                | "SYS_REFCURSOR"
        )
    })
}

#[test]
fn suggested_data_types_have_keyword_popup_details_for_every_database() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let data = IntellisenseData::new();
    for db_type in [Oracle, MySQL, MariaDB] {
        for position in [
            DataTypePosition::Cast,
            DataTypePosition::ColumnDef,
            DataTypePosition::Plsql,
            DataTypePosition::ToolVariable,
        ] {
            let suggestions = data_type_keywords_for(Some(db_type), position)
                .iter()
                .map(|value| (*value).to_string())
                .collect::<Vec<_>>();
            let details = SqlEditorWidget::build_suggestion_details(
                &data,
                &suggestions,
                &[],
                None,
                Some(position),
                &HashMap::new(),
                Some(db_type),
            );
            for suggestion in &suggestions {
                assert_eq!(
                    details
                        .get(suggestion)
                        .map(|detail| detail.type_text.as_str()),
                    Some("KEYWORD"),
                    "{suggestion} should have a keyword popup detail at {position:?} for {db_type:?}"
                );
            }
        }
    }
}

