/// A real query embedded after a non-query head (`EXPLAIN PLAN FOR SELECT`,
/// `CREATE TABLE … AS SELECT`, `INSERT … SELECT`) must still reach its select
/// list — the privilege-statement guard only fires for the privilege verbs.
#[test]
fn embedded_query_select_lists_stay_column_contexts() {
    for sql in [
        "EXPLAIN PLAN FOR SELECT | FROM t",
        "CREATE TABLE x AS SELECT | FROM t",
        "INSERT INTO t SELECT | FROM s",
    ] {
        let deep_ctx = analyze_inline_cursor_sql(sql);
        assert_eq!(
            deep_ctx.phase,
            intellisense_context::SqlPhase::SelectList,
            "{sql}"
        );
    }
}

/// Resolves the column scope and base suggestions exactly as the apply path
/// does for a qualified position: `column_tables` empty ⇒ `column_scope` None.
fn qualified_base_suggestions_for(
    data: &mut IntellisenseData,
    sql_with_cursor: &str,
    qualifier: &str,
) -> Vec<String> {
    let ctx = analyze_inline_cursor_sql(sql_with_cursor);
    let column_tables = SqlEditorWidget::resolve_column_tables_for_context(Some(qualifier), &ctx);
    let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
    let context =
        SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
    SqlEditorWidget::base_suggestions_for_context(
        data,
        "",
        Some(qualifier),
        column_scope.as_deref(),
        true,
        context,
        ClauseCompletionPolicy::for_phase(ctx.phase, true).restrict_to_relation_columns,
        None,
        ExpressionKeywordContext::ambiguous(),
    )
}

/// A qualified reference must never fall back to the global all-columns list.
/// In a DML target column list (MERGE INSERT/UPDATE SET, INSERT column list) a
/// qualifier that resolves to an in-scope relation *outside* the focused target
/// used to yield an empty scope, which `get_column_suggestions` expands to every
/// column of every table — an unrelated-item dump. Such positions must suggest
/// nothing, while ordinary qualified references still resolve their columns.
#[test]
fn qualified_position_never_dumps_all_columns() {
    let mut data = IntellisenseData::new();
    data.tables = vec!["EMP".to_string(), "DEPT".to_string()];
    data.set_columns_for_table(
        "EMP",
        vec![
            "EMPNO".to_string(),
            "ENAME".to_string(),
            "DEPTNO".to_string(),
        ],
    );
    data.set_columns_for_table("DEPT", vec!["DEPTNO".to_string(), "DNAME".to_string()]);
    data.rebuild_indices();

    // Legitimate qualified references still resolve to their relation's columns.
    let e_cols = qualified_base_suggestions_for(&mut data, "SELECT e.| FROM emp e", "e");
    assert!(e_cols.iter().any(|c| c == "ENAME"));
    assert!(!e_cols.iter().any(|c| c == "DNAME"), "{:?}", e_cols);

    let d_cols = qualified_base_suggestions_for(
        &mut data,
        "SELECT d.| FROM emp e JOIN dept d ON e.deptno = d.deptno",
        "d",
    );
    assert!(d_cols.iter().any(|c| c == "DNAME"));
    assert!(!d_cols.iter().any(|c| c == "ENAME"), "{:?}", d_cols);

    // Unknown qualifier: nothing (not every column).
    assert!(qualified_base_suggestions_for(&mut data, "SELECT zzz.| FROM emp e", "zzz").is_empty());
    assert!(qualified_base_suggestions_for(&mut data, "SELECT ab.| FROM help", "ab").is_empty());

    // The regression: a cross-scope qualifier inside a focused DML target list
    // must not dump the whole catalog.
    for sql in [
        "MERGE INTO emp e USING dept d ON (e.deptno = d.deptno) WHEN NOT MATCHED THEN INSERT (d.|)",
        "MERGE INTO emp e USING dept d ON (e.deptno = d.deptno) WHEN MATCHED THEN UPDATE SET d.|",
        "INSERT INTO emp (d.|)",
    ] {
        let cols = qualified_base_suggestions_for(&mut data, sql, "d");
        assert!(
            cols.is_empty(),
            "qualified DML-target slot must not dump all columns: {sql}: {:?}",
            cols
        );
    }
}

#[test]
fn select_list_as_alias_slot_suppresses_completion() {
    // After `AS` in a SELECT list the slot names a brand-new column alias, so
    // identifier suggestions are suppressed — both at the empty slot and while
    // the alias is being typed.
    for sql in [
        "SELECT col AS | FROM t",
        "SELECT col AS my| FROM t",
        "SELECT a, b AS | FROM t",
        "SELECT (SELECT 1 FROM dual) AS | FROM t",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        let has_prefix = sql
            .split_once('|')
            .map(|(b, _)| b.ends_with(|ch: char| ch.is_alphanumeric()))
            .unwrap_or(false);
        assert!(
            SqlEditorWidget::cursor_is_at_select_list_alias_name_slot(&ctx, has_prefix),
            "alias slot should suppress: {sql}"
        );
    }

    // Positions where `AS` introduces a type, or where the slot is a real
    // column reference, keep completion.
    for sql in [
        "SELECT CAST(x AS |) FROM t",     // data-type slot
        "SELECT x | FROM t",              // implicit-alias slot (ambiguous)
        "SELECT a AS x, b | FROM t",      // new column reference after comma
        "SELECT * FROM t WHERE col AS |", // not a select-list context
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        let has_prefix = sql
            .split_once('|')
            .map(|(b, _)| b.ends_with(|ch: char| ch.is_alphanumeric()))
            .unwrap_or(false);
        assert!(
            !SqlEditorWidget::cursor_is_at_select_list_alias_name_slot(&ctx, has_prefix),
            "must not suppress: {sql}"
        );
    }
}

/// The table-clause alias-name slot after `AS` (`FROM t AS |`) names a
/// brand-new relation alias, so the identifier base must be suppressed there —
/// the empty-slot companion of the typed-alias suppression `LocalAliasContext`
/// already applies (`FROM t AS x|`). Previously only the select-list `AS` slot
/// was covered, so `FROM t AS |` leaked the whole relation catalog. Suppression
/// must hold in every table clause (FROM/UPDATE/DELETE/MERGE/JOIN target), and
/// the slot must NOT fire where `AS` introduces a type (`CAST(x AS |)`) or
/// after the flashback `OF` keyword (`FROM t AS OF |`).
#[test]
fn table_alias_slot_after_as_suppresses_identifier_base() {
    fn has_prefix(sql_with_cursor: &str) -> bool {
        sql_with_cursor
            .split_once('|')
            .map(|(b, _)| b.ends_with(|ch: char| ch.is_alphanumeric()))
            .unwrap_or(false)
    }

    // Empty table-alias slots across every table clause: suppress, and fold into
    // the shared keyword-only-identifier-slot family.
    for sql in [
        "SELECT * FROM emp AS |",
        "SELECT * FROM emp e1 JOIN dept AS |",
        "SELECT * FROM (SELECT 1 FROM dual) AS |",
        "UPDATE emp AS |",
        "DELETE FROM emp AS |",
        "MERGE INTO emp AS |",
        "INSERT INTO emp AS |",
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            SqlEditorWidget::cursor_is_at_table_alias_name_slot(&ctx, has_prefix(sql)),
            "table-alias slot should suppress: {sql}"
        );
    }

    // Positions where `AS` is not a table-alias slot: a type slot, the flashback
    // expression after `AS OF`, a select-list alias (handled by its own
    // predicate, not the table one), and a non-`AS` table position.
    for sql in [
        "SELECT * FROM emp AS OF |", // flashback timestamp expression
        "SELECT col AS | FROM t",    // select-list alias, not a table slot
        "SELECT * FROM emp |",       // no `AS`: ambiguous comma/join/clause slot
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            !SqlEditorWidget::cursor_is_at_table_alias_name_slot(&ctx, has_prefix(sql)),
            "must not be a table-alias slot: {sql}"
        );
    }
}

#[test]
fn alias_name_slots_do_not_offer_catalog_or_expression_noise() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);
    let assert_no_identifier_noise =
        |sql: &str, db: crate::db::DatabaseType, final_suggestions: &[String]| {
            for leaked in [
                "EMP",
                "DEPT",
                "EMP_V",
                "APP_USER",
                "SCOTT",
                "RUN_JOB",
                "CALC_TOTAL",
                "EMPNO",
                "ENAME",
                "SAL",
                "*",
                "SELECT",
                "WHERE",
            ] {
                assert!(
                    !contains(final_suggestions, leaked),
                    "{leaked} leaked into alias-name slot at `{sql}` {db:?}: {final_suggestions:?}"
                );
            }
        };

    for (db, sql) in [
        (Oracle, "SELECT col AS | FROM t"),
        (Oracle, "SELECT col AS my| FROM t"),
        (Oracle, "SELECT col AS n| FROM t"),
        (Oracle, "SELECT a, b AS | FROM t"),
        (MySQL, "SELECT col AS | FROM t"),
        (MySQL, "SELECT col AS my| FROM t"),
        (MySQL, "SELECT col AS n| FROM t"),
        (MySQL, "SELECT a, b AS | FROM t"),
        (MariaDB, "SELECT col AS | FROM t"),
        (MariaDB, "SELECT col AS my| FROM t"),
        (MariaDB, "SELECT col AS n| FROM t"),
        (MariaDB, "SELECT a, b AS | FROM t"),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert_eq!(
            kind, None,
            "select-list alias slot should not resolve an object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.is_empty(),
            "select-list alias slot should not offer completions at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
        );
    }

    for (db, sql, allowed_keywords) in [
        (Oracle, "SELECT * FROM emp AS |", &["OF"][..]),
        (Oracle, "SELECT * FROM emp AS n|", &[][..]),
        (Oracle, "SELECT * FROM emp e JOIN dept AS |", &["OF"][..]),
        (Oracle, "SELECT * FROM emp e JOIN dept AS n|", &[][..]),
        (Oracle, "SELECT * FROM (SELECT 1 FROM dual) AS |", &[][..]),
        (Oracle, "UPDATE emp AS |", &[][..]),
        (Oracle, "DELETE FROM emp AS |", &[][..]),
        (Oracle, "MERGE INTO emp AS |", &[][..]),
        (MySQL, "SELECT * FROM emp AS |", &[][..]),
        (MySQL, "SELECT * FROM emp AS n|", &[][..]),
        (MySQL, "SELECT * FROM emp e JOIN dept AS |", &[][..]),
        (MySQL, "SELECT * FROM emp e JOIN dept AS n|", &[][..]),
        (MySQL, "UPDATE emp AS |", &[][..]),
        (MySQL, "DELETE FROM emp AS |", &[][..]),
        (MariaDB, "SELECT * FROM emp AS |", &[][..]),
        (MariaDB, "SELECT * FROM emp AS n|", &[][..]),
        (MariaDB, "SELECT * FROM emp e JOIN dept AS |", &[][..]),
        (MariaDB, "SELECT * FROM emp e JOIN dept AS n|", &[][..]),
        (MariaDB, "UPDATE emp AS |", &[][..]),
        (MariaDB, "DELETE FROM emp AS |", &[][..]),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert_eq!(
            kind, None,
            "table alias slot should not resolve an object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        assert_no_identifier_noise(sql, db, &final_suggestions);
        for suggestion in &final_suggestions {
            assert!(
                allowed_keywords
                    .iter()
                    .any(|allowed| suggestion.eq_ignore_ascii_case(allowed)),
                "unexpected non-alias keyword `{suggestion}` at table alias slot `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
}

/// MERGE merge-action slot after `WHEN [NOT] MATCHED [AND <cond>] THEN |`:
/// only `UPDATE`/`DELETE` (matched) or `INSERT` (not matched) are grammatical
/// there — never a column. The `ON (...)` join phase used to bleed into this
/// slot and offer columns. Columns are suppressed and the action keywords are
/// emitted, while a `CASE … THEN` branch inside the statement is unaffected.
#[test]
fn merge_when_then_action_slot_offers_action_keywords_not_columns() {
    let matched = "MERGE INTO t USING s ON (t.id = s.id) WHEN MATCHED THEN |";
    let matched_cond = "MERGE INTO t USING s ON (t.id = s.id) WHEN MATCHED AND s.x > 0 THEN |";
    let not_matched = "MERGE INTO t USING s ON (t.id = s.id) WHEN NOT MATCHED THEN |";
    let case_branch =
        "MERGE INTO t USING s ON (t.id = s.id) WHEN MATCHED THEN UPDATE SET y = CASE WHEN s.z = 1 THEN |";

    for (sql, expected) in [
        (matched, vec!["UPDATE".to_string(), "DELETE".to_string()]),
        (
            matched_cond,
            vec!["UPDATE".to_string(), "DELETE".to_string()],
        ),
        (not_matched, vec!["INSERT".to_string()]),
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(&ctx, false),
            "columns must be suppressed: {sql}"
        );
        assert_eq!(
            SqlEditorWidget::collect_expected_keyword_suggestions("", &ctx, None),
            expected,
            "{sql}"
        );
    }

    // A `CASE … THEN` branch inside the MERGE action body is an expression slot,
    // not a merge-action slot: it must not be suppressed or offer action verbs.
    let case_ctx = analyze_inline_cursor_sql(case_branch);
    assert!(!SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(&case_ctx, false));
    assert!(SqlEditorWidget::collect_expected_keyword_suggestions("", &case_ctx, None).is_empty());
}

#[test]
fn merge_action_slots_final_suggestions_stay_keyword_only() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);
    let assert_no_catalog_noise = |sql: &str, suggestions: &[String]| {
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "APP_USER",
            "SCOTT",
            "RUN_JOB",
            "CALC_TOTAL",
            "A",
            "B",
            "X",
            "Y",
        ] {
            assert!(
                !contains(suggestions, leaked),
                "{leaked} leaked into MERGE keyword-only slot at `{sql}`: {suggestions:?}"
            );
        }
    };

    for (sql, expected) in [
        (
            "MERGE INTO t USING s ON (t.id = s.id) WHEN MATCHED THEN |",
            &["UPDATE", "DELETE"][..],
        ),
        (
            "MERGE INTO t USING s ON (t.id = s.id) WHEN MATCHED AND s.x > 0 THEN |",
            &["UPDATE", "DELETE"],
        ),
        (
            "MERGE INTO t USING s ON (t.id = s.id) WHEN NOT MATCHED THEN |",
            &["INSERT"],
        ),
        (
            "MERGE INTO t USING s ON (t.id = s.id) WHEN MATCHED |",
            &["THEN", "AND"],
        ),
        (
            "MERGE INTO t USING s ON (t.id = s.id) WHEN MATCHED AND s.x = 1 |",
            &["AND", "OR", "THEN"],
        ),
        (
            "MERGE INTO t USING s ON (t.id = s.id) WHEN |",
            &["MATCHED", "NOT"],
        ),
        (
            "MERGE INTO t USING s ON (t.id = s.id) WHEN NOT |",
            &["MATCHED"],
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "MERGE keyword-only slot should not resolve an object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        for keyword in expected {
            assert!(
                contains(&final_suggestions, keyword),
                "{keyword} missing from MERGE keyword-only slot at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        assert_no_catalog_noise(sql, &final_suggestions);
    }

    let (_kind, keywords, final_suggestions) = audit_final_suggestions_for(
        "MERGE INTO t USING s ON (t.id = s.id) WHEN MATCHED AND |",
        Oracle,
    );
    for leaked in ["MATCHED", "THEN", "UPDATE", "DELETE", "INSERT"] {
        assert!(
            !contains(&final_suggestions, leaked),
            "{leaked} leaked into open MERGE condition: keywords={keywords:?} final={final_suggestions:?}"
        );
    }
}

#[test]
fn merge_condition_slots_final_suggestions_stay_column_oriented() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| {
        values
            .iter()
            .any(|value| value.eq_ignore_ascii_case(needle))
    };
    let assert_columns = |sql: &str, expected: &[&str], leaked: &[&str]| {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "MERGE condition slot should not resolve an object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for column in expected {
            assert!(
                contains(&final_suggestions, column),
                "{column} missing from MERGE condition slot at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        for item in leaked {
            assert!(
                !contains(&final_suggestions, item),
                "{item} leaked into MERGE condition slot at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        for catalog_item in [
            "EMP",
            "DEPT",
            "EMP_V",
            "APP_USER",
            "SCOTT",
            "RUN_JOB",
            "CALC_TOTAL",
            "HR_PKG",
            "ADDRESS_T",
        ] {
            assert!(
                !contains(&final_suggestions, catalog_item),
                "{catalog_item} leaked into MERGE condition slot at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    };

    assert_columns(
        "MERGE INTO emp e USING dept d ON (|)",
        &["EMPNO", "ENAME", "SAL", "DEPTNO", "DNAME"],
        &["MATCHED", "UPDATE", "DELETE", "INSERT", "WHERE", "VALUES"],
    );
    assert_columns(
        "MERGE INTO emp e USING dept d ON (e.|)",
        &["EMPNO", "ENAME", "SAL"],
        &["DEPTNO", "DNAME", "MATCHED", "UPDATE", "DELETE", "INSERT"],
    );
    assert_columns(
        "MERGE INTO emp e USING dept d ON (e.deptno = d.deptno) WHEN MATCHED AND |",
        &["EMPNO", "ENAME", "SAL", "DEPTNO", "DNAME"],
        &["MATCHED", "UPDATE", "DELETE", "INSERT", "WHERE", "VALUES"],
    );
    assert_columns(
        "MERGE INTO emp e USING dept d ON (e.deptno = d.deptno) WHEN NOT MATCHED AND d.|",
        &["DEPTNO", "DNAME"],
        &[
            "EMPNO", "ENAME", "SAL", "MATCHED", "UPDATE", "DELETE", "INSERT",
        ],
    );
    assert_columns(
        "MERGE INTO emp e USING dept d ON (e.empno = d.deptno) WHEN MATCHED THEN UPDATE SET sal = 1 WHERE |",
        &["EMPNO", "ENAME", "SAL", "DEPTNO", "DNAME"],
        &["MATCHED", "UPDATE", "DELETE", "INSERT", "VALUES"],
    );
    assert_columns(
        "MERGE INTO emp e USING dept d ON (e.empno = d.deptno) WHEN MATCHED THEN UPDATE SET sal = 1 DELETE WHERE |",
        &["EMPNO", "ENAME", "SAL", "DEPTNO", "DNAME"],
        &["MATCHED", "UPDATE", "DELETE", "INSERT", "VALUES"],
    );
    assert_columns(
        "MERGE INTO emp e USING dept d ON (e.empno = d.deptno) WHEN MATCHED THEN UPDATE SET sal = 1 DELETE WHERE e.|",
        &["EMPNO", "ENAME", "SAL"],
        &["DEPTNO", "DNAME", "MATCHED", "UPDATE", "DELETE", "INSERT"],
    );
    assert_columns(
        "MERGE INTO emp e USING dept d ON (e.empno = d.deptno) WHEN MATCHED THEN UPDATE SET sal = 1 DELETE WHERE d.|",
        &["DEPTNO", "DNAME"],
        &["EMPNO", "ENAME", "SAL", "MATCHED", "UPDATE", "DELETE", "INSERT"],
    );
}

/// The MERGE match-condition region (`WHEN [NOT] MATCHED [AND <cond>] |`, before
/// `THEN`) is owned by a dedicated handler: right after `MATCHED` the only
/// grammatical continuations are `THEN` (proceed) or `AND` (open the optional
/// condition), and after a complete `AND <predicate>` the condition extends
/// (`AND`/`OR`) or closes with `THEN`. Guards against the generic
/// predicate-conjunction handler, which wrongly offered a bare `OR` right after
/// `MATCHED` and never offered the mandatory `THEN`.
#[test]
fn merge_match_condition_offers_then_and_not_bare_or() {
    use crate::db::DatabaseType::Oracle;
    let kw = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(Oracle),
        )
    };
    // Right after `MATCHED`/`NOT MATCHED`: `THEN` or `AND` — never a bare `OR`.
    for sql in [
        "MERGE INTO t USING s ON (t.id=s.id) WHEN MATCHED |",
        "MERGE INTO t USING s ON (t.id=s.id) WHEN NOT MATCHED |",
    ] {
        assert_eq!(
            kw(sql),
            vec!["THEN".to_string(), "AND".to_string()],
            "`{sql}`"
        );
    }
    // After a complete match condition: extend (`AND`/`OR`) or close (`THEN`).
    for sql in [
        "MERGE INTO t USING s ON (t.id=s.id) WHEN MATCHED AND t.x=1 |",
        "MERGE INTO t USING s ON (t.id=s.id) WHEN NOT MATCHED AND s.x=1 |",
    ] {
        assert_eq!(
            kw(sql),
            vec!["AND".to_string(), "OR".to_string(), "THEN".to_string()],
            "`{sql}`"
        );
    }
    // An open condition (`… AND |`) is an expression slot — no merge keywords —
    // and the action tail past `THEN` is unaffected.
    assert!(kw("MERGE INTO t USING s ON (t.id=s.id) WHEN MATCHED AND |").is_empty());
    assert_eq!(
        kw("MERGE INTO t USING s ON (t.id=s.id) WHEN MATCHED THEN UPDATE SET a=1 |"),
        vec![
            "WHERE".to_string(),
            "DELETE WHERE".to_string(),
            "WHEN".to_string()
        ]
    );

    // The keyword-only sub-slots (bare `MATCHED`, complete condition) suppress the
    // joined columns the `ON (...)` `JoinCondition` phase would otherwise leak; an
    // open condition (`… AND |`) keeps them, since the predicate needs an operand.
    let col_suppressed = |sql: &str| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(
            &analyze_inline_cursor_sql(sql),
            false,
        )
    };
    for sql in [
        "MERGE INTO t USING s ON (t.id=s.id) WHEN MATCHED |",
        "MERGE INTO t USING s ON (t.id=s.id) WHEN NOT MATCHED |",
        "MERGE INTO t USING s ON (t.id=s.id) WHEN MATCHED AND t.x=1 |",
    ] {
        assert!(col_suppressed(sql), "columns must be suppressed: `{sql}`");
    }
    assert!(
        !col_suppressed("MERGE INTO t USING s ON (t.id=s.id) WHEN MATCHED AND |"),
        "the open match condition must keep its column operand"
    );
}

/// The row-locking clause `… FOR |` (→ dialect-valid lock mode) and `… FOR UPDATE |`
/// (→ `OF`/`NOWAIT`/…) are keyword-only slots — a column is never valid. The
/// trailing-clause phase used to leave them in a column context. They are gated
/// to the statement top level so the SQL-standard `SUBSTRING(x FROM a FOR |)`
/// operand, the `MODEL`/`PIVOT` `FOR`, and PL/SQL `FOR` loops / `OPEN … FOR`
/// keep their normal completion.
#[test]
fn for_update_locking_clause_is_keyword_only_not_columns() {
    for (sql, expected) in [
        ("SELECT * FROM t FOR |", vec!["UPDATE".to_string()]),
        (
            "SELECT * FROM t WHERE x = 1 FOR |",
            vec!["UPDATE".to_string()],
        ),
        (
            "SELECT * FROM t ORDER BY x FOR |",
            vec!["UPDATE".to_string()],
        ),
        (
            "SELECT * FROM emp e WHERE e.sal > (SELECT avg(sal) FROM emp) FOR |",
            vec!["UPDATE".to_string()],
        ),
        (
            "SELECT * FROM t FOR UPDATE |",
            vec![
                "OF".to_string(),
                "NOWAIT".to_string(),
                "WAIT".to_string(),
                "SKIP".to_string(),
            ],
        ),
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(&ctx, false),
            "columns must be suppressed: {sql}"
        );
        assert_eq!(
            SqlEditorWidget::collect_expected_keyword_suggestions("", &ctx, None),
            expected,
            "{sql}"
        );
    }

    // `FOR UPDATE OF |` is a column list — columns must still be offered.
    let of_ctx = analyze_inline_cursor_sql("SELECT * FROM t FOR UPDATE OF |");
    assert!(!SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(&of_ctx, false));

    // Not the locking clause: keep normal completion.
    for sql in [
        "SELECT substr(x FROM 1 FOR |) FROM t", // SUBSTRING operand (in parens)
        "BEGIN FOR | IN (SELECT * FROM t) LOOP NULL; END LOOP; END;", // PL/SQL loop
        "DECLARE BEGIN OPEN c FOR | END;",      // ref-cursor OPEN FOR
    ] {
        let ctx = analyze_inline_cursor_sql(sql);
        assert!(
            !SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(&ctx, false),
            "must not suppress: {sql}"
        );
    }
}

#[test]
fn for_update_locking_clause_final_suggestions_stay_slot_specific() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);
    let assert_no_catalog_noise = |sql: &str,
                                   db: crate::db::DatabaseType,
                                   final_suggestions: &[String]| {
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "APP_USER",
            "SCOTT",
            "RUN_JOB",
            "CALC_TOTAL",
            "EMPNO",
            "ENAME",
            "DEPTNO",
            "DNAME",
        ] {
            assert!(
                    !contains(final_suggestions, leaked),
                    "{leaked} leaked into locking keyword slot at `{sql}` {db:?}: {final_suggestions:?}"
                );
        }
    };

    for (db, sql, expected_keywords, forbidden_keywords) in [
        (
            Oracle,
            "SELECT * FROM emp FOR |",
            &["UPDATE"][..],
            &["SHARE"][..],
        ),
        (
            Oracle,
            "SELECT * FROM emp WHERE empno = 1 FOR |",
            &["UPDATE"],
            &["SHARE"],
        ),
        (
            Oracle,
            "SELECT * FROM emp FOR UPDATE |",
            &["OF", "NOWAIT", "WAIT", "SKIP"],
            &[],
        ),
        (
            Oracle,
            "SELECT * FROM emp FOR UPDATE OF empno |",
            &["NOWAIT", "WAIT", "SKIP"],
            &["OF"],
        ),
        (
            MySQL,
            "SELECT * FROM emp FOR |",
            &["UPDATE", "SHARE"],
            &["WAIT"],
        ),
        (
            MySQL,
            "SELECT * FROM emp FOR UPDATE |",
            &["OF", "NOWAIT", "SKIP"],
            &["WAIT"],
        ),
        (
            MySQL,
            "SELECT * FROM emp FOR UPDATE OF empno |",
            &["NOWAIT", "SKIP"],
            &["OF", "WAIT"],
        ),
        (
            MariaDB,
            "SELECT * FROM emp FOR |",
            &["UPDATE", "SHARE"],
            &["WAIT"],
        ),
        (
            MariaDB,
            "SELECT * FROM emp FOR UPDATE |",
            &["OF", "NOWAIT", "SKIP"],
            &["WAIT"],
        ),
        (
            MariaDB,
            "SELECT * FROM emp FOR UPDATE OF empno |",
            &["NOWAIT", "SKIP"],
            &["OF", "WAIT"],
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert_eq!(
            kind, None,
            "locking keyword slot should not resolve an object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        for expected in expected_keywords {
            assert!(
                contains(&final_suggestions, expected),
                "{expected} missing from locking keyword slot at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        for forbidden in forbidden_keywords {
            assert!(
                !contains(&final_suggestions, forbidden),
                "{forbidden} leaked into locking keyword slot at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        assert_no_catalog_noise(sql, db, &final_suggestions);
    }

    let (kind, keywords, of_list) =
        audit_final_suggestions_for("SELECT * FROM emp FOR UPDATE OF |", Oracle);
    assert_eq!(
        kind, None,
        "FOR UPDATE OF column list should stay column-oriented; keywords={keywords:?} final={of_list:?}"
    );
    assert!(
        contains(&of_list, "EMPNO") && contains(&of_list, "ENAME"),
        "FOR UPDATE OF column list lost EMP columns: keywords={keywords:?} final={of_list:?}"
    );
    for leaked in ["NOWAIT", "WAIT", "SKIP", "OF"] {
        assert!(
            !contains(&of_list, leaked),
            "{leaked} leaked before any FOR UPDATE OF column was written: keywords={keywords:?} final={of_list:?}"
        );
    }

    for (db, sql) in [
        (Oracle, "SELECT * FROM emp FOR UPDATE WAIT |"),
        (Oracle, "SELECT * FROM emp FOR UPDATE WAIT n|"),
        (Oracle, "SELECT * FROM emp FOR UPDATE OF empno WAIT |"),
        (Oracle, "SELECT * FROM emp FOR UPDATE OF empno WAIT n|"),
        (Oracle, "SELECT * FROM emp FOR UPDATE NOWAIT |"),
        (Oracle, "SELECT * FROM emp FOR UPDATE NOWAIT n|"),
        (Oracle, "SELECT * FROM emp FOR UPDATE WAIT 5 |"),
        (Oracle, "SELECT * FROM emp FOR UPDATE WAIT 5 n|"),
        (Oracle, "SELECT * FROM emp FOR UPDATE SKIP LOCKED |"),
        (Oracle, "SELECT * FROM emp FOR UPDATE SKIP LOCKED n|"),
        (Oracle, "SELECT * FROM emp FOR UPDATE OF empno NOWAIT |"),
        (Oracle, "SELECT * FROM emp FOR UPDATE OF empno NOWAIT n|"),
        (Oracle, "SELECT * FROM emp FOR UPDATE OF empno WAIT 5 |"),
        (Oracle, "SELECT * FROM emp FOR UPDATE OF empno WAIT 5 n|"),
        (
            Oracle,
            "SELECT * FROM emp FOR UPDATE OF empno SKIP LOCKED |",
        ),
        (
            Oracle,
            "SELECT * FROM emp FOR UPDATE OF empno SKIP LOCKED n|",
        ),
        (MySQL, "SELECT * FROM emp FOR UPDATE NOWAIT |"),
        (MySQL, "SELECT * FROM emp FOR UPDATE NOWAIT n|"),
        (MySQL, "SELECT * FROM emp FOR UPDATE SKIP LOCKED |"),
        (MySQL, "SELECT * FROM emp FOR UPDATE SKIP LOCKED n|"),
        (MySQL, "SELECT * FROM emp FOR SHARE NOWAIT |"),
        (MySQL, "SELECT * FROM emp FOR SHARE NOWAIT n|"),
        (MySQL, "SELECT * FROM emp FOR SHARE SKIP LOCKED |"),
        (MySQL, "SELECT * FROM emp FOR SHARE SKIP LOCKED n|"),
        (MariaDB, "SELECT * FROM emp FOR UPDATE NOWAIT |"),
        (MariaDB, "SELECT * FROM emp FOR UPDATE NOWAIT n|"),
        (MariaDB, "SELECT * FROM emp FOR UPDATE SKIP LOCKED |"),
        (MariaDB, "SELECT * FROM emp FOR UPDATE SKIP LOCKED n|"),
        (MariaDB, "SELECT * FROM emp FOR SHARE NOWAIT |"),
        (MariaDB, "SELECT * FROM emp FOR SHARE NOWAIT n|"),
        (MariaDB, "SELECT * FROM emp FOR SHARE SKIP LOCKED |"),
        (MariaDB, "SELECT * FROM emp FOR SHARE SKIP LOCKED n|"),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert_eq!(
            kind, None,
            "completed locking tail should not resolve an object kind at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.is_empty(),
            "completed locking tail should not offer catalog or stale keywords at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
        );
    }
}

#[test]
