/// The Oracle trigger body options follow `ON [schema.]table` in grammatical
/// order — `[REFERENCING …] [FOR EACH ROW] [WHEN (cond)] {DECLARE|BEGIN|…}` —
/// and each is single-use: once `FOR EACH ROW` is present it must not be
/// re-offered, and once the `WHEN` condition is present neither it nor
/// `FOR EACH ROW` reappears. Guards against the spent-clause re-offer that dumped
/// `FOR EACH ROW` back into the suggestion list after it was already typed.
#[test]
fn oracle_trigger_body_options_are_single_use_and_ordered() {
    use crate::db::DatabaseType::Oracle;
    let kw = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(Oracle),
        )
    };
    assert_eq!(
        kw("CREATE TRIGGER trg BEFORE INSERT ON t |"),
        vec![
            "REFERENCING".to_string(),
            "FOR EACH ROW".to_string(),
            "WHEN".to_string(),
            "DECLARE".to_string(),
            "BEGIN".to_string(),
        ]
    );
    // `FOR EACH ROW` present → not re-offered; `WHEN`/body still available.
    assert_eq!(
        kw("CREATE TRIGGER trg AFTER UPDATE OF c ON t FOR EACH ROW |"),
        vec![
            "WHEN".to_string(),
            "DECLARE".to_string(),
            "BEGIN".to_string()
        ]
    );
    assert_eq!(
        kw("CREATE TRIGGER trg INSTEAD OF INSERT ON v FOR EACH ROW |"),
        vec![
            "WHEN".to_string(),
            "DECLARE".to_string(),
            "BEGIN".to_string()
        ]
    );
    // `WHEN` condition present → only the body block remains (no `FOR EACH ROW`,
    // no second `WHEN`), whether or not `FOR EACH ROW` preceded it.
    for sql in [
        "CREATE TRIGGER trg BEFORE INSERT ON t FOR EACH ROW WHEN (n.id>0) |",
        "CREATE TRIGGER trg BEFORE INSERT ON t WHEN (n.id>0) |",
    ] {
        assert_eq!(
            kw(sql),
            vec!["DECLARE".to_string(), "BEGIN".to_string()],
            "`{sql}`"
        );
    }
}

#[test]
fn oracle_trigger_referencing_slots_are_precise_without_catalog() {
    use crate::db::DatabaseType::Oracle;

    let kw = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(Oracle),
        )
    };
    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for (sql, expected) in [
        ("CREATE TRIGGER trg BEFORE INSERT ON t REFERENCING |", "NEW"),
        (
            "CREATE TRIGGER trg BEFORE INSERT ON t REFERENCING NEW |",
            "AS",
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON t REFERENCING OLD AS old |",
            "NEW",
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON t REFERENCING NEW AS old |",
            "OLD",
        ),
        (
            "CREATE TRIGGER trg BEFORE INSERT ON t REFERENCING NEW AS new |",
            "FOR EACH ROW",
        ),
        ("CREATE TRIGGER trg BEFORE DELETE ON t REFERENCING |", "OLD"),
        (
            "CREATE TRIGGER trg BEFORE DELETE ON t REFERENCING OLD AS old |",
            "FOR EACH ROW",
        ),
        (
            "CREATE TRIGGER trg BEFORE INSERT ON t REFERENCING OLD AS old |",
            "NEW",
        ),
        (
            "CREATE TRIGGER trg BEFORE DELETE ON t REFERENCING NEW AS new |",
            "OLD",
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON t REFERENCING PARENT AS parent_row |",
            "OLD",
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON t REFERENCING PARENT AS parent_row |",
            "NEW",
        ),
        (
            "CREATE TRIGGER trg INSTEAD OF INSERT ON NESTED TABLE nt OF v REFERENCING |",
            "PARENT",
        ),
        (
            "CREATE TRIGGER trg INSTEAD OF UPDATE ON NESTED TABLE nt OF v REFERENCING PARENT AS old |",
            "OLD",
        ),
    ] {
        assert!(
            contains(&kw(sql), expected),
            "{expected} missing from trigger REFERENCING slot at `{sql}`: {:?}",
            kw(sql)
        );
    }

    for (sql, leaked) in [
        ("CREATE TRIGGER trg BEFORE INSERT ON t REFERENCING |", "OLD"),
        (
            "CREATE TRIGGER trg BEFORE INSERT ON t REFERENCING NEW AS new |",
            "OLD",
        ),
        ("CREATE TRIGGER trg BEFORE DELETE ON t REFERENCING |", "NEW"),
        (
            "CREATE TRIGGER trg BEFORE DELETE ON t REFERENCING OLD AS old |",
            "NEW",
        ),
        (
            "CREATE TRIGGER trg BEFORE INSERT ON t REFERENCING |",
            "PARENT",
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON t REFERENCING |",
            "PARENT",
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON t REFERENCING OLD AS old NEW AS new |",
            "PARENT",
        ),
    ] {
        assert!(
            !contains(&kw(sql), leaked),
            "{leaked} leaked into event-scoped trigger REFERENCING slot at `{sql}`: {:?}",
            kw(sql)
        );
    }

    for sql in [
        "CREATE TRIGGER trg BEFORE INSERT ON t REFERENCING |",
        "CREATE TRIGGER trg BEFORE INSERT ON t REFERENCING NEW |",
        "CREATE TRIGGER trg BEFORE INSERT ON t REFERENCING NEW AS |",
        "CREATE TRIGGER trg BEFORE INSERT ON t REFERENCING NEW AS new |",
        "CREATE TRIGGER trg BEFORE INSERT ON t REFERENCING OLD AS |",
        "CREATE TRIGGER trg BEFORE DELETE ON t REFERENCING NEW AS |",
        "CREATE TRIGGER trg BEFORE UPDATE ON t REFERENCING PARENT AS |",
        "CREATE TRIGGER trg BEFORE UPDATE ON t REFERENCING OLD AS old NEW AS |",
        "CREATE TRIGGER trg BEFORE UPDATE ON t REFERENCING OLD AS old NEW AS new |",
        "CREATE TRIGGER trg BEFORE DELETE ON t REFERENCING OLD |",
        "CREATE TRIGGER trg BEFORE DELETE ON t REFERENCING OLD AS old |",
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "trigger REFERENCING slot should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "RUN_JOB",
            "CALC_TOTAL",
            "HR_PKG",
            "ADDRESS_T",
            "APP_USER",
            "SCOTT",
            "SELECT",
            "WHERE",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into trigger REFERENCING slot at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
}

#[test]
fn oracle_trigger_update_of_column_slots_offer_only_target_columns() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for (sql, expected_columns) in [
        (
            "CREATE TRIGGER trg BEFORE UPDATE OF | ON emp",
            &["EMPNO", "ENAME", "SAL"][..],
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE OF en| ON emp",
            &["ENAME"][..],
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE OF ename, | ON emp",
            &["EMPNO", "SAL"][..],
        ),
        (
            "CREATE TRIGGER trg INSTEAD OF UPDATE OF | ON NESTED TABLE nt OF emp",
            &["N_ID", "N_VALUE"][..],
        ),
        (
            "CREATE TRIGGER trg INSTEAD OF UPDATE OF n_id, | ON NESTED TABLE nt OF emp",
            &["N_VALUE"][..],
        ),
        (
            "CREATE TRIGGER trg INSTEAD OF UPDATE OF | ON NESTED TABLE scott.nt OF scott.dept",
            &["S_N_ID", "S_N_VALUE"][..],
        ),
        (
            "CREATE TRIGGER trg INSTEAD OF UPDATE OF s_n_id, | ON NESTED TABLE scott.nt OF scott.dept",
            &["S_N_VALUE"][..],
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "trigger UPDATE OF column slot should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for expected in expected_columns {
            assert!(
                contains(&final_suggestions, expected),
                "{expected} missing from trigger UPDATE OF column slot at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        if sql.contains("ename,") {
            assert!(
                !contains(&final_suggestions, "ENAME"),
                "already listed trigger UPDATE OF column leaked back at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        if sql.contains("n_id,") {
            assert!(
                !contains(&final_suggestions, "N_ID"),
                "already listed nested trigger UPDATE OF column leaked back at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        if sql.contains("s_n_id,") {
            assert!(
                !contains(&final_suggestions, "S_N_ID"),
                "already listed schema-qualified nested trigger UPDATE OF column leaked back at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        if sql.contains("NESTED TABLE") {
            for leaked in ["EMPNO", "ENAME", "SAL", "S_DEPTNO", "S_DNAME"] {
                assert!(
                    !contains(&final_suggestions, leaked),
                    "{leaked} parent-table column leaked into nested trigger UPDATE OF slot at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
                );
            }
        }
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "RUN_JOB",
            "CALC_TOTAL",
            "HR_PKG",
            "ADDRESS_T",
            "APP_USER",
            "SCOTT",
            "SELECT",
            "WHERE",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into trigger UPDATE OF column slot at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }

    let (kind, keywords, final_suggestions) =
        audit_final_suggestions_for("CREATE TRIGGER trg BEFORE UPDATE OF |", Oracle);
    assert_eq!(kind, None);
    assert!(
        keywords.is_empty() && final_suggestions.is_empty(),
        "trigger UPDATE OF column slot without target table should stay silent: keywords={keywords:?} final={final_suggestions:?}"
    );
}

#[test]
fn oracle_trigger_when_condition_offers_only_correlation_aliases_and_columns() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for (sql, expected_aliases) in [
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON emp FOR EACH ROW WHEN (|) BEGIN NULL; END;",
            &["OLD", "NEW"][..],
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON emp REFERENCING OLD AS old_row NEW AS new_row FOR EACH ROW WHEN (|) BEGIN NULL; END;",
            &["old_row", "new_row"][..],
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON emp REFERENCING OLD AS old_row NEW AS new_row FOR EACH ROW WHEN (new|) BEGIN NULL; END;",
            &["new_row"][..],
        ),
        (
            "CREATE TRIGGER trg INSTEAD OF UPDATE ON NESTED TABLE nt OF emp FOR EACH ROW WHEN (|) BEGIN NULL; END;",
            &["OLD", "NEW", "PARENT"][..],
        ),
        (
            "CREATE TRIGGER trg INSTEAD OF UPDATE ON NESTED TABLE nt OF emp REFERENCING PARENT AS parent_row FOR EACH ROW WHEN (|) BEGIN NULL; END;",
            &["OLD", "NEW", "parent_row"][..],
        ),
        (
            "CREATE TRIGGER trg INSTEAD OF UPDATE ON NESTED TABLE nt OF emp REFERENCING PARENT AS parent_row FOR EACH ROW WHEN (pa|) BEGIN NULL; END;",
            &["parent_row"][..],
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "trigger WHEN condition should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for expected in expected_aliases {
            assert!(
                contains(&final_suggestions, expected),
                "{expected} missing from trigger WHEN condition at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "RUN_JOB",
            "CALC_TOTAL",
            "HR_PKG",
            "ADDRESS_T",
            "APP_USER",
            "SCOTT",
            "SELECT",
            "WHERE",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into trigger WHEN condition at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }

    for sql in [
        "CREATE TRIGGER trg BEFORE UPDATE ON emp FOR EACH ROW WHEN (NEW.|) BEGIN NULL; END;",
        "CREATE TRIGGER trg BEFORE UPDATE ON emp REFERENCING OLD AS old_row NEW AS new_row FOR EACH ROW WHEN (old_row.|) BEGIN NULL; END;",
        "CREATE TRIGGER trg INSTEAD OF UPDATE ON NESTED TABLE nt OF emp FOR EACH ROW WHEN (PARENT.|) BEGIN NULL; END;",
        "CREATE TRIGGER trg INSTEAD OF UPDATE ON NESTED TABLE nt OF emp REFERENCING PARENT AS parent_row FOR EACH ROW WHEN (parent_row.|) BEGIN NULL; END;",
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "qualified trigger WHEN alias should resolve columns at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for expected in ["EMPNO", "ENAME", "SAL"] {
            assert!(
                contains(&final_suggestions, expected),
                "{expected} missing from qualified trigger WHEN alias at `{sql}`: {final_suggestions:?}"
            );
        }
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "RUN_JOB",
            "CALC_TOTAL",
            "HR_PKG",
            "ADDRESS_T",
            "APP_USER",
            "SCOTT",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into qualified trigger WHEN alias at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }

    let (kind, keywords, general_trigger_aliases) = audit_final_suggestions_for(
        "CREATE TRIGGER trg BEFORE UPDATE ON emp REFERENCING PARENT AS parent_row FOR EACH ROW WHEN (|) BEGIN NULL; END;",
        Oracle,
    );
    assert_eq!(
        kind, None,
        "invalid general-trigger PARENT alias should not resolve object kind in WHEN: keywords={keywords:?} final={general_trigger_aliases:?}"
    );
    assert!(
        contains(&general_trigger_aliases, "OLD") && contains(&general_trigger_aliases, "NEW"),
        "general trigger WHEN lost valid OLD/NEW aliases after invalid PARENT alias: keywords={keywords:?} final={general_trigger_aliases:?}"
    );
    assert!(
        !contains(&general_trigger_aliases, "parent_row"),
        "invalid general-trigger PARENT alias leaked into WHEN: keywords={keywords:?} final={general_trigger_aliases:?}"
    );
}

#[test]
fn oracle_trigger_body_correlation_aliases_offer_target_columns() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for sql in [
        "CREATE TRIGGER trg BEFORE UPDATE ON emp FOR EACH ROW BEGIN :NEW.| := :OLD.ename; END;",
        "CREATE TRIGGER trg BEFORE UPDATE ON emp FOR EACH ROW BEGIN :OLD.| := :NEW.ename; END;",
        "CREATE TRIGGER trg BEFORE UPDATE ON emp REFERENCING OLD AS old_row NEW AS new_row FOR EACH ROW BEGIN :new_row.| := :old_row.ename; END;",
        "CREATE TRIGGER trg BEFORE UPDATE ON emp REFERENCING OLD AS old_row NEW AS new_row FOR EACH ROW BEGIN :old_row.| := :new_row.ename; END;",
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "trigger body correlation alias should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for expected in ["EMPNO", "ENAME", "SAL"] {
            assert!(
                contains(&final_suggestions, expected),
                "{expected} missing from trigger body correlation alias at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "RUN_JOB",
            "CALC_TOTAL",
            "HR_PKG",
            "ADDRESS_T",
            "APP_USER",
            "SCOTT",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into trigger body correlation alias at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }

    let (_kind, _keywords, insert_old) = audit_final_suggestions_for(
        "CREATE TRIGGER trg BEFORE INSERT ON emp FOR EACH ROW BEGIN :OLD.| := :NEW.ename; END;",
        Oracle,
    );
    assert!(
        insert_old.is_empty(),
        "OLD alias should not be available in INSERT trigger body: {insert_old:?}"
    );

    let (_kind, _keywords, delete_new) = audit_final_suggestions_for(
        "CREATE TRIGGER trg BEFORE DELETE ON emp FOR EACH ROW BEGIN :NEW.| := :OLD.ename; END;",
        Oracle,
    );
    assert!(
        delete_new.is_empty(),
        "NEW alias should not be available in DELETE trigger body: {delete_new:?}"
    );

    for sql in [
        "CREATE TRIGGER trg BEFORE UPDATE ON emp FOR EACH ROW BEGIN NEW.| := :OLD.ename; END;",
        "CREATE TRIGGER trg BEFORE UPDATE ON emp FOR EACH ROW WHEN (:NEW.|) BEGIN NULL; END;",
        "CREATE TRIGGER trg BEFORE UPDATE ON emp REFERENCING :NEW.| FOR EACH ROW BEGIN NULL; END;",
        "CREATE TRIGGER trg BEFORE UPDATE ON emp FOR EACH ROW :NEW.| BEGIN NULL; END;",
    ] {
        let (_kind, _keywords, invalid_alias) = audit_final_suggestions_for(sql, Oracle);
        assert!(
            ["EMPNO", "ENAME", "SAL"]
                .iter()
                .all(|column| !contains(&invalid_alias, column)),
            "Oracle trigger correlation alias should only expose target columns in its valid WHEN/body positions at `{sql}`: {invalid_alias:?}"
        );
    }

    for (sql, expected_aliases) in [
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON emp FOR EACH ROW BEGIN :| := 1; END;",
            &["OLD", "NEW"][..],
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON emp FOR EACH ROW BEGIN :n| := 1; END;",
            &["NEW"][..],
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON emp REFERENCING OLD AS old_row NEW AS new_row FOR EACH ROW BEGIN :| := 1; END;",
            &["old_row", "new_row"][..],
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON emp REFERENCING OLD AS old_row NEW AS new_row FOR EACH ROW BEGIN :new| := 1; END;",
            &["new_row"][..],
        ),
        (
            "CREATE TRIGGER trg INSTEAD OF UPDATE ON NESTED TABLE nt OF emp REFERENCING PARENT AS parent_row FOR EACH ROW BEGIN :| := 1; END;",
            &["parent_row", "OLD", "NEW"][..],
        ),
        (
            "CREATE TRIGGER trg INSTEAD OF UPDATE ON NESTED TABLE nt OF emp REFERENCING PARENT AS parent_row FOR EACH ROW BEGIN :p| := 1; END;",
            &["parent_row"][..],
        ),
        (
            "CREATE TRIGGER trg INSTEAD OF UPDATE ON NESTED TABLE nt OF emp FOR EACH ROW BEGIN :p| := 1; END;",
            &["PARENT"][..],
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "trigger body correlation alias start should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for expected in expected_aliases {
            assert!(
                contains(&final_suggestions, expected),
                "{expected} missing from trigger body correlation alias start at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        for leaked in ["EMP", "EMP_V", "RUN_JOB", "CALC_TOTAL", "HR_PKG", "APP_USER"] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into trigger body correlation alias start at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }

    for (sql, leaked_alias, expected_alias) in [
        (
            "CREATE TRIGGER trg BEFORE INSERT ON emp REFERENCING OLD AS old_row FOR EACH ROW BEGIN :| := 1; END;",
            "old_row",
            "NEW",
        ),
        (
            "CREATE TRIGGER trg BEFORE DELETE ON emp REFERENCING NEW AS new_row FOR EACH ROW BEGIN :| := 1; END;",
            "new_row",
            "OLD",
        ),
        (
            "CREATE TRIGGER trg BEFORE UPDATE ON emp REFERENCING PARENT AS parent_row FOR EACH ROW BEGIN :| := 1; END;",
            "parent_row",
            "OLD",
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "invalid event correlation alias should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            contains(&final_suggestions, expected_alias),
            "{expected_alias} missing after invalid event correlation alias at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            !contains(&final_suggestions, leaked_alias),
            "{leaked_alias} leaked from invalid event correlation alias at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
    }

    let (kind, keywords, nested_parent_columns) = audit_final_suggestions_for(
        "CREATE TRIGGER trg INSTEAD OF UPDATE ON NESTED TABLE nt OF emp REFERENCING PARENT AS parent_row FOR EACH ROW BEGIN :parent_row.| := 1; END;",
        Oracle,
    );
    assert_eq!(
        kind, None,
        "nested-table trigger PARENT alias should not resolve object kind: keywords={keywords:?} final={nested_parent_columns:?}"
    );
    for expected in ["EMPNO", "ENAME", "SAL"] {
        assert!(
            contains(&nested_parent_columns, expected),
            "{expected} missing from nested-table trigger PARENT alias columns: keywords={keywords:?} final={nested_parent_columns:?}"
        );
    }
    for leaked in [
        "NESTED", "TABLE", "NT", "OF", "EMP", "DEPT", "EMP_V", "RUN_JOB",
    ] {
        assert!(
            !contains(&nested_parent_columns, leaked),
            "{leaked} leaked into nested-table trigger PARENT alias columns: keywords={keywords:?} final={nested_parent_columns:?}"
        );
    }

    let (kind, keywords, schema_parent_columns) = audit_final_suggestions_for(
        "CREATE TRIGGER trg INSTEAD OF UPDATE ON NESTED TABLE nt OF scott.dept REFERENCING PARENT AS parent_row FOR EACH ROW BEGIN :parent_row.| := 1; END;",
        Oracle,
    );
    assert_eq!(
        kind, None,
        "schema-qualified nested-table trigger PARENT alias should not resolve object kind: keywords={keywords:?} final={schema_parent_columns:?}"
    );
    for expected in ["S_DEPTNO", "S_DNAME"] {
        assert!(
            contains(&schema_parent_columns, expected),
            "{expected} missing from schema-qualified nested-table trigger PARENT alias columns: keywords={keywords:?} final={schema_parent_columns:?}"
        );
    }
    for leaked in ["DEPTNO", "DNAME", "EMP", "DEPT", "EMP_V", "RUN_JOB"] {
        assert!(
            !contains(&schema_parent_columns, leaked),
            "{leaked} leaked into schema-qualified nested-table trigger PARENT alias columns: keywords={keywords:?} final={schema_parent_columns:?}"
        );
    }
}

#[test]
fn data_type_trigger_declaration_offers_types_but_body_does_not() {
    use crate::db::DatabaseType::Oracle;
    assert!(has_plsql_type_suggestions(
        "CREATE TRIGGER trg BEFORE INSERT ON t FOR EACH ROW DECLARE v | BEGIN NULL; END;",
        Oracle
    ));
    assert!(!has_plsql_type_suggestions(
        "CREATE TRIGGER trg BEFORE INSERT ON t FOR EACH ROW BEGIN :NEW.col := | ; END;",
        Oracle
    ));
}

#[test]
fn data_type_declaration_after_rowtype_member_still_offers_types() {
    use crate::db::DatabaseType::Oracle;
    assert!(has_plsql_type_suggestions(
        "DECLARE v emp.sal%TYPE; w | BEGIN NULL; END;",
        Oracle
    ));
}

#[test]
fn data_type_json_table_columns_clause_offers_types() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};
    assert!(!data_type_suggestions(
        "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id | PATH '$.id'))",
        "",
        Oracle
    )
    .is_empty());
    assert!(!data_type_suggestions(
        "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER PATH '$.id', name | PATH '$.n'))",
        "",
        Oracle
    )
    .is_empty());
    assert!(!data_type_suggestions(
        "SELECT * FROM XMLTABLE('/r' PASSING x COLUMNS id | PATH 'id')",
        "",
        Oracle
    )
    .is_empty());
    for db in [MySQL, MariaDB] {
        assert!(!data_type_suggestions(
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id | PATH '$.id'))",
            "",
            db
        )
        .is_empty());
        assert!(
            data_type_suggestions(
                "SELECT * FROM XMLTABLE('/r' PASSING x COLUMNS id | PATH 'id')",
                "",
                db
            )
            .is_empty(),
            "Oracle-only XMLTABLE column type grammar leaked into {db:?}"
        );
    }
}

#[test]
fn json_table_column_name_tail_offers_ordinality_and_exists_path_keywords() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let kw = |sql: &str, db| {
        let cursor = sql.find('|').expect("cursor marker");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |values: &[String], keyword: &str| {
        values
            .iter()
            .any(|value| value.eq_ignore_ascii_case(keyword))
    };

    for db in [Oracle, MySQL, MariaDB] {
        let after_name = kw("SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id |))", db);
        assert!(
            has(&after_name, "FOR") && has(&after_name, "EXISTS"),
            "JSON_TABLE column-name tail lost FOR/EXISTS for {db:?}: {after_name:?}"
        );
        assert!(
            has(&after_name, if db == Oracle { "NUMBER" } else { "INT" }),
            "JSON_TABLE column-name tail lost data types for {db:?}: {after_name:?}"
        );

        let ordinality = kw("SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id FOR |))", db);
        assert_eq!(
            ordinality,
            vec!["ORDINALITY".to_string()],
            "JSON_TABLE FOR tail should be keyword-only for {db:?}"
        );

        let exists_path = kw("SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id EXISTS |))", db);
        assert_eq!(
            exists_path,
            vec!["PATH".to_string()],
            "JSON_TABLE EXISTS tail should be keyword-only for {db:?}"
        );

        let after_type = kw("SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER |))", db);
        assert!(
            has(&after_type, "PATH"),
            "JSON_TABLE column type tail lost PATH for {db:?}: {after_type:?}"
        );
        for invalid in ["FOR", "EXISTS"] {
            assert!(
                !has(&after_type, invalid),
                "{invalid} leaked after a JSON_TABLE column type for {db:?}: {after_type:?}"
            );
        }

        let nested = kw("SELECT * FROM JSON_TABLE(d, '$' COLUMNS (NESTED |))", db);
        assert_eq!(
            nested,
            vec!["PATH".to_string()],
            "JSON_TABLE NESTED tail should be keyword-only for {db:?}"
        );

        let nested_columns = kw(
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (NESTED PATH '$.items[*]' |))",
            db,
        );
        assert_eq!(
            nested_columns,
            vec!["COLUMNS".to_string()],
            "JSON_TABLE NESTED PATH tail should offer only COLUMNS for {db:?}"
        );

        let after_value_path = kw(
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER PATH '$.id' |))",
            db,
        );
        assert_eq!(
            after_value_path,
            vec![
                "NULL".to_string(),
                "ERROR".to_string(),
                "DEFAULT".to_string()
            ],
            "JSON_TABLE value PATH tail should offer only value handler heads for {db:?}"
        );

        let null_handler = kw(
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER PATH '$.id' NULL |))",
            db,
        );
        assert_eq!(
            null_handler,
            vec!["ON".to_string()],
            "JSON_TABLE NULL handler should continue with ON for {db:?}"
        );

        let after_exists_path = kw(
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id EXISTS PATH '$.id' |))",
            db,
        );
        assert_eq!(
            after_exists_path,
            vec!["TRUE".to_string(), "FALSE".to_string(), "ERROR".to_string()],
            "JSON_TABLE EXISTS PATH tail should offer only exists handler heads for {db:?}"
        );

        let true_handler = kw(
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id EXISTS PATH '$.id' TRUE |))",
            db,
        );
        assert_eq!(
            true_handler,
            vec!["ON".to_string()],
            "JSON_TABLE TRUE handler should continue with ON for {db:?}"
        );

        let after_on_empty = kw(
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER PATH '$.id' NULL ON EMPTY |))",
            db,
        );
        assert_eq!(
            after_on_empty,
            vec![
                "NULL".to_string(),
                "ERROR".to_string(),
                "DEFAULT".to_string()
            ],
            "JSON_TABLE completed ON EMPTY should offer ON ERROR handler heads for {db:?}"
        );

        let second_handler = kw(
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER PATH '$.id' NULL ON EMPTY ERROR |))",
            db,
        );
        assert_eq!(
            second_handler,
            vec!["ON".to_string()],
            "JSON_TABLE second handler head should continue with ON for {db:?}"
        );

        assert!(
            kw(
                "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER PATH '$.id' DEFAULT |))",
                db
            )
            .is_empty(),
            "JSON_TABLE DEFAULT handler value slot should not be keyword-only for {db:?}"
        );
        assert_eq!(
            kw(
                "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER PATH '$.id' DEFAULT 0 |))",
                db,
            ),
            vec!["ON".to_string()],
            "JSON_TABLE completed numeric DEFAULT handler should continue with ON for {db:?}"
        );
        assert_eq!(
            kw(
                "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER PATH '$.id' DEFAULT fallback_amt |))",
                db,
            ),
            vec!["ON".to_string()],
            "JSON_TABLE completed identifier DEFAULT handler should continue with ON for {db:?}"
        );
    }
}

#[test]
fn xmltable_column_tail_keeps_xmltable_grammar_separate_from_json_table() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let kw = |sql: &str, db_type| {
        let cursor = sql.find('|').expect("cursor marker");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db_type),
        )
    };
    let has = |values: &[String], keyword: &str| {
        values
            .iter()
            .any(|value| value.eq_ignore_ascii_case(keyword))
    };

    let after_name = kw("SELECT * FROM XMLTABLE('/r' COLUMNS id |) xt", Oracle);
    assert!(
        has(&after_name, "FOR") && has(&after_name, "NUMBER"),
        "XMLTABLE column tail lost FOR/data types: {after_name:?}"
    );
    for json_only in ["EXISTS", "NESTED", "TRUE", "FALSE"] {
        assert!(
            !has(&after_name, json_only),
            "{json_only} leaked into XMLTABLE column tail: {after_name:?}"
        );
    }

    assert_eq!(
        kw("SELECT * FROM XMLTABLE('/r' COLUMNS id FOR |) xt", Oracle),
        vec!["ORDINALITY".to_string()],
        "XMLTABLE FOR tail should be keyword-only"
    );
    assert_eq!(
        kw(
            "SELECT * FROM XMLTABLE('/r' COLUMNS id NUMBER |) xt",
            Oracle
        ),
        vec!["PATH".to_string()],
        "XMLTABLE typed column tail should offer PATH"
    );
    assert!(
        kw(
            "SELECT * FROM XMLTABLE('/r' COLUMNS id EXISTS |) xt",
            Oracle
        )
        .is_empty(),
        "JSON_TABLE EXISTS PATH leaked into XMLTABLE"
    );
    assert!(
        kw(
            "SELECT * FROM XMLTABLE('/r' COLUMNS id NUMBER PATH 'id' |) xt",
            Oracle,
        )
        .is_empty(),
        "JSON_TABLE handler heads leaked after XMLTABLE PATH"
    );
    for db in [MySQL, MariaDB] {
        for sql in [
            "SELECT * FROM XMLTABLE('/r' COLUMNS id FOR |) xt",
            "SELECT * FROM XMLTABLE('/r' COLUMNS id NUMBER |) xt",
            "SELECT * FROM XMLTABLE('/r' COLUMNS id NUMBER PATH 'id' |) xt",
        ] {
            let got = kw(sql, db);
            assert!(
                got.is_empty(),
                "Oracle-only XMLTABLE column-tail grammar leaked into {db:?} at `{sql}`: {got:?}"
            );
        }
    }

    let (kind, keywords, final_suggestions) = audit_final_suggestions_for(
        "SELECT * FROM XMLTABLE('/r' COLUMNS id NUMBER PATH 'id' |) xt",
        Oracle,
    );
    assert_eq!(
        kind, None,
        "completed XMLTABLE PATH tail should not resolve object kind; keywords={keywords:?} final={final_suggestions:?}"
    );
    for leaked in [
        "EMP",
        "DEPT",
        "EMP_V",
        "EMPNO",
        "ENAME",
        "RUN_JOB",
        "CALC_TOTAL",
    ] {
        assert!(
            !final_suggestions.iter().any(|value| value == leaked),
            "{leaked} leaked after completed XMLTABLE PATH: {final_suggestions:?}"
        );
    }
    let (_kind, keywords, final_suggestions) = audit_final_suggestions_for(
        "SELECT * FROM XMLTABLE('/r' COLUMNS id NUMBER PATH 'id' n|) xt",
        Oracle,
    );
    assert!(
        final_suggestions.is_empty(),
        "completed XMLTABLE PATH tail with prefix should not offer catalog or stale keywords: keywords={keywords:?} final={final_suggestions:?}"
    );
}

#[test]
fn table_function_path_literal_slots_suppress_identifier_base() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let exclude_flag = |sql_with_cursor: &str| {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        !prefix.is_empty()
    };
    let suppresses = |sql: &str, db_type| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
            &analyze_inline_cursor_sql(sql),
            exclude_flag(sql),
            Some(db_type),
        )
    };
    let apply_base = |sql_with_cursor: &str, db_type| {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        if SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
            &ctx,
            !prefix.is_empty(),
            Some(db_type),
        ) {
            return Vec::new();
        }
        let mut data = IntellisenseData::new();
        data.tables = vec!["PATH_STAGE".to_string(), "PAYLOADS".to_string()];
        data.rebuild_indices();
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            None,
            false,
            context,
            false,
            Some(db_type),
            ExpressionKeywordContext::ambiguous(),
        )
    };

    for (sql, db_type) in [
        (
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER PATH p|))",
            Oracle,
        ),
        (
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (NESTED PATH p| COLUMNS (id NUMBER PATH '$.id')))",
            Oracle,
        ),
        (
            "SELECT * FROM XMLTABLE('/r' PASSING x COLUMNS id NUMBER PATH p|)",
            Oracle,
        ),
        (
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id INT PATH p|))",
            MySQL,
        ),
        (
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id INT PATH p|))",
            MariaDB,
        ),
    ] {
        assert!(
            suppresses(sql, db_type),
            "PATH literal slot did not suppress identifiers for `{sql}`"
        );
        assert!(
            apply_base(sql, db_type).is_empty(),
            "identifier base survived in PATH literal slot for `{sql}`"
        );
    }
    for (sql, db_type) in [
        (
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER PATH |))",
            Oracle,
        ),
        (
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER PATH p|))",
            Oracle,
        ),
        (
            "SELECT * FROM XMLTABLE('/r' PASSING x COLUMNS id NUMBER PATH |)",
            Oracle,
        ),
        (
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id INT PATH |))",
            MySQL,
        ),
        (
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id INT PATH |))",
            MariaDB,
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db_type);
        assert_eq!(
            kind, None,
            "PATH literal slot should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.is_empty(),
            "PATH literal slot should not offer catalog or keywords at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
    }
    let (kind, keywords, final_suggestions) =
        audit_final_suggestions_for("SELECT * FROM JSON_TABLE |", Oracle);
    assert_eq!(
        kind, None,
        "table-function opener should not resolve object kind: keywords={keywords:?} final={final_suggestions:?}"
    );
    assert!(
        final_suggestions.is_empty(),
        "table-function opener should not offer catalog or keywords: keywords={keywords:?} final={final_suggestions:?}"
    );
    for db in [MySQL, MariaDB] {
        assert!(
            !suppresses(
                "SELECT * FROM XMLTABLE('/r' PASSING x COLUMNS id NUMBER PATH p|)",
                db,
            ),
            "Oracle-only XMLTABLE PATH literal slot should not suppress identifiers in {db:?}"
        );
    }

    assert!(
        !data_type_suggestions(
            "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (path |))",
            "",
            Oracle
        )
        .is_empty(),
        "column named PATH must remain a type slot"
    );
}

#[test]
fn json_on_target_keyword_slots_suppress_identifier_base() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let exclude_flag = |sql_with_cursor: &str| {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        !prefix.is_empty()
    };
    let suppresses_for = |sql: &str, db_type| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
            &analyze_inline_cursor_sql(sql),
            exclude_flag(sql),
            Some(db_type),
        )
    };
    let suppresses = |sql: &str| suppresses_for(sql, Oracle);
    let keywords_for = |sql_with_cursor: &str, db_type| {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql_with_cursor),
            Some(db_type),
        )
    };
    let keywords = |sql_with_cursor: &str| keywords_for(sql_with_cursor, Oracle);
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    for sql in [
        "SELECT JSON_VALUE(payload, '$.amount' NULL ON |) FROM emp",
        "SELECT JSON_VALUE(payload, '$.amount' DEFAULT fallback_amt ON |) FROM emp",
        "SELECT JSON_EXISTS(payload, '$' TRUE ON |) FROM emp",
        "SELECT JSON_QUERY(payload, '$' EMPTY ARRAY ON |) FROM emp",
        "SELECT JSON_QUERY(payload, '$' EMPTY OBJECT ON |) FROM emp",
        "SELECT * FROM JSON_TABLE(d, '$' COLUMNS (id NUMBER PATH '$.id' NULL ON |))",
    ] {
        assert!(
            suppresses(sql),
            "JSON ON target slot leaked identifiers for `{sql}`"
        );
        let kw = keywords(sql);
        assert!(
            has(&kw, "ERROR") && has(&kw, "EMPTY"),
            "JSON ON target keywords missing for `{sql}`: {kw:?}"
        );
    }

    for sql in [
        "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON |) FROM emp",
        "SELECT JSON_ARRAY(v NULL ON |) FROM emp",
    ] {
        assert!(
            suppresses(sql),
            "JSON ON NULL target slot leaked identifiers for `{sql}`"
        );
        assert_eq!(
            keywords(sql),
            vec!["NULL".to_string()],
            "JSON ON NULL target should only suggest NULL for `{sql}`"
        );
    }

    assert_eq!(
        keywords("SELECT JSON_VALUE(payload, '$.amount' NULL ON er|) FROM emp"),
        vec!["ERROR".to_string()]
    );
    assert_eq!(
        keywords("SELECT JSON_VALUE(payload, '$.amount' NULL ON em|) FROM emp"),
        vec!["EMPTY".to_string()]
    );
    assert_eq!(
        keywords("SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON nu|) FROM emp"),
        vec!["NULL".to_string()]
    );
    assert!(
        keywords("SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON er|) FROM emp").is_empty(),
        "JSON ON NULL target must not suggest ERROR"
    );
    for db in [MySQL, MariaDB] {
        assert!(
            !suppresses_for("SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON |) FROM emp", db),
            "Oracle JSON ON NULL target must not suppress identifiers in {db:?} mode"
        );
        assert!(
            keywords_for(
                "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON nu|) FROM emp",
                db
            )
            .is_empty(),
            "Oracle JSON ON NULL target must not emit keywords in {db:?} mode"
        );
    }

    assert!(
        !suppresses("SELECT * FROM emp e JOIN dept d ON |"),
        "ordinary JOIN ON must keep column completion"
    );
    let join_columns = typed_emp_suggestions("SELECT * FROM emp e JOIN dept d ON en|");
    assert!(
        has(&join_columns, "ENAME"),
        "ordinary JOIN ON lost column completion: {join_columns:?}"
    );
}

#[test]
fn json_function_option_tails_offer_handlers_and_wrapper_keywords() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let kw = |sql: &str, db| {
        let cursor = sql.find('|').expect("cursor marker");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };

    assert_eq!(
        kw(
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER |) FROM emp",
            Oracle
        ),
        vec![
            "NULL".to_string(),
            "ERROR".to_string(),
            "DEFAULT".to_string()
        ],
        "JSON_VALUE RETURNING type tail should offer handler heads"
    );
    assert_eq!(
        kw(
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER NULL |) FROM emp",
            Oracle
        ),
        vec!["ON".to_string()],
        "JSON_VALUE NULL handler should continue with ON"
    );
    assert_eq!(
        kw(
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER NULL ON EMPTY |) FROM emp",
            Oracle
        ),
        vec![
            "NULL".to_string(),
            "ERROR".to_string(),
            "DEFAULT".to_string()
        ],
        "JSON_VALUE completed ON EMPTY should offer ON ERROR handler heads"
    );
    assert!(
        kw("SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER NULL ON EMPTY DEFAULT |) FROM emp", Oracle)
            .is_empty(),
        "JSON_VALUE second DEFAULT handler value slot should not be keyword-only"
    );
    assert_eq!(
        kw(
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER NULL ON EMPTY DEFAULT 0 |) FROM emp",
            Oracle,
        ),
        vec!["ON".to_string()],
        "JSON_VALUE completed second numeric DEFAULT handler should continue with ON"
    );
    assert_eq!(
        kw(
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER NULL ON EMPTY DEFAULT fallback_amt |) FROM emp",
            Oracle,
        ),
        vec!["ON".to_string()],
        "JSON_VALUE completed second identifier DEFAULT handler should continue with ON"
    );
    assert!(
        kw(
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER DEFAULT |) FROM emp",
            Oracle
        )
        .is_empty(),
        "JSON_VALUE DEFAULT handler value slot should not be keyword-only"
    );
    assert_eq!(
        kw(
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER DEFAULT 0 |) FROM emp",
            Oracle,
        ),
        vec!["ON".to_string()],
        "JSON_VALUE completed numeric DEFAULT handler should continue with ON"
    );
    assert_eq!(
        kw(
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER DEFAULT fallback_amt |) FROM emp",
            Oracle,
        ),
        vec!["ON".to_string()],
        "JSON_VALUE completed identifier DEFAULT handler should continue with ON"
    );

    assert_eq!(
        kw(
            "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB |) FROM emp",
            Oracle
        ),
        vec![
            "FORMAT".to_string(),
            "WITH".to_string(),
            "WITHOUT".to_string(),
            "NULL".to_string(),
            "ERROR".to_string(),
            "EMPTY".to_string()
        ],
        "JSON_QUERY RETURNING type tail should offer format/wrapper/handler heads"
    );
    assert_eq!(
        kw(
            "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB FORMAT |) FROM emp",
            Oracle
        ),
        vec!["JSON".to_string()],
        "JSON_QUERY FORMAT should continue with JSON"
    );
    assert_eq!(
        kw(
            "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB FORMAT JSON WITH |) FROM emp",
            Oracle
        ),
        vec!["WRAPPER".to_string()],
        "JSON_QUERY WITH should continue with WRAPPER"
    );
    assert_eq!(
        kw("SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB FORMAT JSON WITH WRAPPER |) FROM emp", Oracle),
        vec!["PRETTY".to_string(), "ASCII".to_string()],
        "JSON_QUERY WRAPPER should offer formatting styles"
    );
    assert_eq!(
        kw(
            "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB FORMAT JSON |) FROM emp",
            Oracle
        ),
        vec![
            "WITH".to_string(),
            "WITHOUT".to_string(),
            "NULL".to_string(),
            "ERROR".to_string(),
            "EMPTY".to_string()
        ],
        "JSON_QUERY FORMAT JSON tail should not re-offer FORMAT"
    );
    assert_eq!(
        kw("SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB FORMAT JSON WITH WRAPPER PRETTY |) FROM emp", Oracle),
        vec!["NULL".to_string(), "ERROR".to_string(), "EMPTY".to_string()],
        "JSON_QUERY completed wrapper tail should offer only handler heads"
    );
    assert_eq!(
        kw(
            "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB EMPTY |) FROM emp",
            Oracle
        ),
        vec!["ON".to_string(), "ARRAY".to_string(), "OBJECT".to_string()],
        "JSON_QUERY EMPTY handler should offer ON/ARRAY/OBJECT"
    );
    assert_eq!(
        kw(
            "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB EMPTY ARRAY |) FROM emp",
            Oracle
        ),
        vec!["ON".to_string()],
        "JSON_QUERY EMPTY ARRAY should continue with ON"
    );
    assert_eq!(
        kw(
            "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB EMPTY OBJECT |) FROM emp",
            Oracle
        ),
        vec!["ON".to_string()],
        "JSON_QUERY EMPTY OBJECT should continue with ON"
    );
    for db in [MySQL, MariaDB] {
        assert!(
            !kw(
                "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB WITH |) FROM emp",
                db
            )
            .iter()
            .any(|value| value == "WRAPPER"),
            "Oracle JSON_QUERY wrapper tail leaked into {db:?}"
        );
    }

    assert_eq!(
        kw("SELECT JSON_EXISTS(payload, '$' |) FROM emp", Oracle),
        vec!["TRUE".to_string(), "FALSE".to_string(), "ERROR".to_string()],
        "JSON_EXISTS path tail should offer exists-handler heads"
    );
    assert_eq!(
        kw("SELECT JSON_EXISTS(payload, '$' TRUE |) FROM emp", Oracle),
        vec!["ON".to_string()],
        "JSON_EXISTS TRUE handler should continue with ON"
    );
    for db in [MySQL, MariaDB] {
        assert!(
            kw("SELECT JSON_EXISTS(payload, '$' |) FROM emp", db).is_empty(),
            "Oracle JSON_EXISTS option tail leaked into {db:?}"
        );
        assert!(
            kw("SELECT JSON_QUERY(payload, '$' NULL ON |) FROM emp", db).is_empty(),
            "Oracle JSON_QUERY ON target leaked into {db:?}"
        );
    }
}

#[test]
fn json_function_option_keyword_slots_suppress_catalog() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for (sql, expected) in [
        (
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER |) FROM emp",
            "NULL",
        ),
        (
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER NULL |) FROM emp",
            "ON",
        ),
        (
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER DEFAULT 0 |) FROM emp",
            "ON",
        ),
        (
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER DEFAULT fallback_amt |) FROM emp",
            "ON",
        ),
        (
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER NULL ON EMPTY DEFAULT 0 |) FROM emp",
            "ON",
        ),
        (
            "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER NULL ON EMPTY DEFAULT fallback_amt |) FROM emp",
            "ON",
        ),
        (
            "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB FORMAT |) FROM emp",
            "JSON",
        ),
        (
            "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB FORMAT JSON WITH |) FROM emp",
            "WRAPPER",
        ),
        (
            "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB FORMAT JSON WITH WRAPPER PRETTY |) FROM emp",
            "NULL",
        ),
        (
            "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB EMPTY |) FROM emp",
            "ARRAY",
        ),
        (
            "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB EMPTY ARRAY |) FROM emp",
            "ON",
        ),
        (
            "SELECT JSON_QUERY(payload, '$.items' RETURNING CLOB EMPTY OBJECT |) FROM emp",
            "ON",
        ),
        ("SELECT JSON_EXISTS(payload, '$' |) FROM emp", "TRUE"),
        ("SELECT JSON_EXISTS(payload, '$' TRUE |) FROM emp", "ON"),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "JSON function option keyword slot should not resolve object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            contains(&final_suggestions, expected),
            "{expected} missing from JSON function option slot at `{sql}`: {final_suggestions:?}"
        );
        for leaked in ["EMP", "DEPT", "EMP_V", "EMPNO", "ENAME", "RUN_JOB", "CALC_TOTAL"] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into JSON function option slot at `{sql}`: {final_suggestions:?}"
            );
        }
    }

    let completed =
        "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER NULL ON ERROR |) FROM emp";
    let (kind, keywords, final_suggestions) = audit_final_suggestions_for(completed, Oracle);
    assert_eq!(
        kind, None,
        "completed JSON function handler tail should not resolve object kind; keywords={keywords:?} final={final_suggestions:?}"
    );
    for leaked in [
        "EMP",
        "DEPT",
        "EMP_V",
        "EMPNO",
        "ENAME",
        "RUN_JOB",
        "CALC_TOTAL",
    ] {
        assert!(
            !contains(&final_suggestions, leaked),
            "{leaked} leaked after completed JSON function handler: {final_suggestions:?}"
        );
    }
    let completed_prefixed =
        "SELECT JSON_VALUE(payload, '$.amount' RETURNING NUMBER NULL ON ERROR n|) FROM emp";
    let (_kind, keywords, final_suggestions) =
        audit_final_suggestions_for(completed_prefixed, Oracle);
    assert!(
        final_suggestions.is_empty(),
        "completed JSON function handler tail with prefix should not offer catalog or stale keywords: keywords={keywords:?} final={final_suggestions:?}"
    );

    let completed_exists = "SELECT JSON_EXISTS(payload, '$' TRUE ON ERROR |) FROM emp";
    let (kind, keywords, final_suggestions) = audit_final_suggestions_for(completed_exists, Oracle);
    assert_eq!(
        kind, None,
        "completed JSON_EXISTS handler tail should not resolve object kind; keywords={keywords:?} final={final_suggestions:?}"
    );
    for leaked in [
        "EMP",
        "DEPT",
        "EMP_V",
        "EMPNO",
        "ENAME",
        "RUN_JOB",
        "CALC_TOTAL",
    ] {
        assert!(
            !contains(&final_suggestions, leaked),
            "{leaked} leaked after completed JSON_EXISTS handler: {final_suggestions:?}"
        );
    }
    let completed_exists_prefixed = "SELECT JSON_EXISTS(payload, '$' TRUE ON ERROR n|) FROM emp";
    let (_kind, keywords, final_suggestions) =
        audit_final_suggestions_for(completed_exists_prefixed, Oracle);
    assert!(
        final_suggestions.is_empty(),
        "completed JSON_EXISTS handler tail with prefix should not offer catalog or stale keywords: keywords={keywords:?} final={final_suggestions:?}"
    );
}

#[test]
fn xmlquery_option_keyword_slots_suppress_catalog_without_hiding_value_slots() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for (sql, expected) in [
        ("SELECT XMLQUERY('/root' |) FROM emp", "PASSING"),
        ("SELECT XMLQUERY('/root' P|) FROM emp", "PASSING"),
        ("SELECT XMLQUERY('/root' R|) FROM emp", "RETURNING"),
        (
            "SELECT XMLQUERY('/root' PASSING payload |) FROM emp",
            "RETURNING",
        ),
        ("SELECT XMLQUERY('/root' PASSING payload A|) FROM emp", "AS"),
        (
            "SELECT XMLQUERY('/root' PASSING payload R|) FROM emp",
            "RETURNING",
        ),
        ("SELECT XMLQUERY('/root' PASSING BY |) FROM emp", "VALUE"),
        ("SELECT XMLQUERY('/root' PASSING BY V|) FROM emp", "VALUE"),
        ("SELECT XMLQUERY('/root' RETURNING |) FROM emp", "CONTENT"),
        ("SELECT XMLQUERY('/root' RETURNING C|) FROM emp", "CONTENT"),
        (
            "SELECT XMLQUERY('/root' RETURNING CONTENT |) FROM emp",
            "NULL",
        ),
        (
            "SELECT XMLQUERY('/root' RETURNING CONTENT N|) FROM emp",
            "NULL",
        ),
        (
            "SELECT XMLQUERY('/root' RETURNING CONTENT NULL |) FROM emp",
            "ON",
        ),
        (
            "SELECT XMLQUERY('/root' RETURNING CONTENT NULL O|) FROM emp",
            "ON",
        ),
        (
            "SELECT XMLQUERY('/root' RETURNING CONTENT NULL ON |) FROM emp",
            "EMPTY",
        ),
        (
            "SELECT XMLQUERY('/root' RETURNING CONTENT NULL ON E|) FROM emp",
            "EMPTY",
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "XMLQUERY option keyword slot should not resolve object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            contains(&final_suggestions, expected),
            "{expected} missing from XMLQUERY option slot at `{sql}`: {final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "EMPNO",
            "ENAME",
            "RUN_JOB",
            "CALC_TOTAL",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into XMLQUERY option slot at `{sql}`: {final_suggestions:?}"
            );
        }
    }

    for sql in [
        "SELECT XMLQUERY('/root' PASSING |) FROM emp",
        "SELECT XMLQUERY('/root' PASSING BY VALUE |) FROM emp",
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "XMLQUERY value slot should stay expression-like at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            contains(&final_suggestions, "EMPNO") && contains(&final_suggestions, "ENAME"),
            "XMLQUERY value slot lost source columns at `{sql}`: {final_suggestions:?}"
        );
        for leaked in ["EMP", "DEPT", "EMP_V", "RUN_JOB", "CALC_TOTAL"] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into XMLQUERY value slot at `{sql}`: {final_suggestions:?}"
            );
        }
    }
}

#[test]
fn json_generation_option_tails_are_oracle_scoped_and_keyword_only() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let kw = |sql: &str, db| {
        let cursor = sql.find('|').expect("cursor marker");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };

    assert_eq!(
        kw(
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT |) FROM emp",
            Oracle
        ),
        vec!["ON".to_string()],
        "JSON_OBJECT ABSENT should continue with ON"
    );
    assert_eq!(
        kw("SELECT JSON_ARRAY(v NULL |) FROM emp", Oracle),
        vec!["ON".to_string()],
        "JSON_ARRAY NULL option should continue with ON"
    );
    assert_eq!(
        kw("SELECT JSON_ARRAYAGG(v ABSENT |) FROM emp", Oracle),
        vec!["ON".to_string()],
        "JSON_ARRAYAGG ABSENT should continue with ON"
    );
    assert_eq!(
        kw(
            "SELECT JSON_OBJECTAGG(KEY k VALUE v NULL |) FROM emp",
            Oracle
        ),
        vec!["ON".to_string()],
        "JSON_OBJECTAGG NULL option should continue with ON"
    );
    assert_eq!(
        kw(
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL |) FROM emp",
            Oracle
        ),
        vec![
            "WITH".to_string(),
            "WITHOUT".to_string(),
            "STRICT".to_string(),
            "RETURNING".to_string()
        ],
        "JSON generation ON NULL tail should offer generation options"
    );
    assert_eq!(
        kw(
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITH |) FROM emp",
            Oracle
        ),
        vec!["UNIQUE".to_string()],
        "JSON generation WITH should continue with UNIQUE"
    );
    assert_eq!(
        kw(
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITHOUT |) FROM emp",
            Oracle
        ),
        vec!["UNIQUE".to_string()],
        "JSON generation WITHOUT should continue with UNIQUE"
    );
    assert_eq!(
        kw(
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITH UNIQUE |) FROM emp",
            Oracle
        ),
        vec!["KEYS".to_string()],
        "JSON generation UNIQUE should continue with KEYS"
    );
    assert_eq!(
        kw(
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITHOUT UNIQUE |) FROM emp",
            Oracle
        ),
        vec!["KEYS".to_string()],
        "JSON generation WITHOUT UNIQUE should continue with KEYS"
    );
    assert_eq!(
        kw(
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITH UNIQUE KEYS |) FROM emp",
            Oracle
        ),
        vec!["STRICT".to_string(), "RETURNING".to_string()],
        "JSON generation UNIQUE KEYS tail should offer remaining options"
    );
    assert_eq!(
        kw(
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITHOUT UNIQUE KEYS |) FROM emp",
            Oracle
        ),
        vec!["STRICT".to_string(), "RETURNING".to_string()],
        "JSON generation WITHOUT UNIQUE KEYS tail should offer remaining options"
    );
    assert_eq!(
        kw(
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITH UNIQUE KEYS STRICT |) FROM emp",
            Oracle
        ),
        vec!["RETURNING".to_string()],
        "JSON generation STRICT should continue with RETURNING"
    );
    for db in [MySQL, MariaDB] {
        assert!(
            kw("SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON |) FROM emp", db).is_empty(),
            "Oracle JSON generation ON target leaked into {db:?}"
        );
    }
    assert!(
        kw("SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITH UNIQUE KEYS STRICT RETURNING CLOB |) FROM emp", Oracle)
            .is_empty(),
        "completed JSON generation RETURNING type tail should not emit keywords"
    );
    for db in [MySQL, MariaDB] {
        assert!(
            kw("SELECT JSON_OBJECT(KEY k VALUE v ABSENT |) FROM emp", db).is_empty(),
            "Oracle JSON generation ABSENT ON NULL option leaked into {db:?}"
        );
    }
}

#[test]
fn json_generation_option_keyword_slots_suppress_catalog() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for (sql, expected) in [
        ("SELECT JSON_OBJECT(KEY k VALUE v ABSENT |) FROM emp", "ON"),
        ("SELECT JSON_OBJECT(KEY k VALUE v ABSENT O|) FROM emp", "ON"),
        ("SELECT JSON_ARRAYAGG(v ABSENT |) FROM emp", "ON"),
        ("SELECT JSON_ARRAYAGG(v ABSENT O|) FROM emp", "ON"),
        ("SELECT JSON_OBJECTAGG(KEY k VALUE v NULL |) FROM emp", "ON"),
        (
            "SELECT JSON_OBJECTAGG(KEY k VALUE v NULL O|) FROM emp",
            "ON",
        ),
        (
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITH |) FROM emp",
            "UNIQUE",
        ),
        (
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITH U|) FROM emp",
            "UNIQUE",
        ),
        (
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITHOUT |) FROM emp",
            "UNIQUE",
        ),
        (
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITHOUT U|) FROM emp",
            "UNIQUE",
        ),
        (
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITH UNIQUE |) FROM emp",
            "KEYS",
        ),
        (
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITH UNIQUE K|) FROM emp",
            "KEYS",
        ),
        (
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITHOUT UNIQUE |) FROM emp",
            "KEYS",
        ),
        (
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITHOUT UNIQUE K|) FROM emp",
            "KEYS",
        ),
        (
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITHOUT UNIQUE KEYS |) FROM emp",
            "STRICT",
        ),
        (
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITHOUT UNIQUE KEYS S|) FROM emp",
            "STRICT",
        ),
        (
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITH UNIQUE KEYS STRICT |) FROM emp",
            "RETURNING",
        ),
        (
            "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITH UNIQUE KEYS STRICT R|) FROM emp",
            "RETURNING",
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "JSON generation option keyword slot should not resolve object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            contains(&final_suggestions, expected),
            "{expected} missing from JSON generation option slot at `{sql}`: {final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "EMPNO",
            "ENAME",
            "RUN_JOB",
            "CALC_TOTAL",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into JSON generation option slot at `{sql}`: {final_suggestions:?}"
            );
        }
    }

    for completed in [
        "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITH UNIQUE KEYS STRICT RETURNING CLOB |) FROM emp",
        "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITHOUT UNIQUE KEYS STRICT RETURNING CLOB |) FROM emp",
        "SELECT JSON_ARRAY(v RETURNING CLOB |) FROM emp",
        "SELECT JSON_ARRAYAGG(v ABSENT ON NULL RETURNING CLOB |) FROM emp",
        "SELECT JSON_OBJECTAGG(KEY k VALUE v NULL ON NULL RETURNING CLOB |) FROM emp",
        "SELECT JSON_OBJECT(KEY k VALUE v ABSENT ON NULL WITH UNIQUE KEYS STRICT RETURNING CLOB n|) FROM emp",
        "SELECT JSON_ARRAY(v RETURNING CLOB n|) FROM emp",
        "SELECT JSON_ARRAYAGG(v ABSENT ON NULL RETURNING CLOB n|) FROM emp",
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(completed, Oracle);
        assert_eq!(
            kind, None,
            "completed JSON generation RETURNING tail should not resolve object kind at `{completed}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in ["EMP", "DEPT", "EMP_V", "EMPNO", "ENAME", "RUN_JOB", "CALC_TOTAL"] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked after completed JSON generation RETURNING tail at `{completed}`: {final_suggestions:?}"
            );
        }
    }
}

