#[test]
fn data_type_table_named_columns_is_not_a_type_position() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};
    // A table literally named/aliased around "columns" must never offer types.
    // (The position *does* legitimately offer query-clause openers - `WHERE`,
    // `GROUP BY`, `ORDER BY`, … after a complete FROM relation - so assert the
    // absence of data-type keywords specifically rather than emptiness.)
    assert!(!has_data_type_keyword(&data_type_suggestions(
        "SELECT * FROM all_tab_columns c |",
        "",
        Oracle
    )));
    for db in [MySQL, MariaDB] {
        assert!(!has_data_type_keyword(&data_type_suggestions(
            "SELECT * FROM information_schema.columns x |",
            "",
            db
        )));
    }
    // Before the COLUMNS keyword (the JSON expression) is not a type slot either.
    assert!(!has_data_type_keyword(&data_type_suggestions(
        "SELECT * FROM JSON_TABLE(d| , '$' COLUMNS (id NUMBER PATH '$.id'))",
        "",
        Oracle
    )));
}

#[test]
fn data_type_prior_statement_does_not_leak_into_next() {
    // A PL/SQL or DDL statement before the cursor's statement must not push its
    // declaration/routine/column context into the next statement.
    for sql in [
        "DECLARE v NUMBER; BEGIN NULL; END;\nSELECT col | FROM t",
        "CREATE FUNCTION f RETURN NUMBER IS BEGIN RETURN 1; END;\nSELECT | FROM t",
        "CREATE TABLE a (x NUMBER);\nSELECT col | FROM t",
        "CREATE FUNCTION f(p IN NUMBER) RETURN NUMBER IS BEGIN RETURN 1; END;\nUPDATE t SET col = | WHERE id=1",
        "BEGIN proc(); END;\nSELECT a, | FROM t",
        "DECLARE CURSOR c IS SELECT 1 FROM dual; BEGIN NULL; END;\nINSERT INTO t (col, |) VALUES (1,2)",
    ] {
        assert!(
            SqlEditorWidget::data_type_position_for_context(&analyze_inline_cursor_sql(sql), false)
                .is_none(),
            "prior statement leaked a type position into: {sql}"
        );
    }
    // The current statement is still detected when it genuinely is a type slot.
    assert!(SqlEditorWidget::data_type_position_for_context(
        &analyze_inline_cursor_sql("SELECT col FROM t;\nDECLARE v | BEGIN NULL; END;"),
        false,
    )
    .is_some());
}

#[test]
fn row_count_positions_suppress_columns() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let at = |sql: &str| {
        SqlEditorWidget::cursor_is_in_row_limiting_clause_for_context(
            &analyze_inline_cursor_sql(sql),
            false,
        )
    };
    // Row-count / offset value slots accept only integers/binds.
    assert!(at("SELECT * FROM orders ORDER BY id LIMIT |"));
    assert!(at("SELECT * FROM orders LIMIT |"));
    assert!(at("SELECT * FROM orders LIMIT 10, |"));
    assert!(at("SELECT * FROM orders LIMIT 10 OFFSET |"));
    assert!(at("SELECT a FROM t OFFSET |"));
    assert!(at("SELECT * FROM orders LIMIT 10 |"));
    assert!(at("SELECT * FROM orders LIMIT 10 OFFSET 20 |"));
    assert!(at("SELECT * FROM orders LIMIT 10, 20 |"));
    // The whole Oracle/ANSI FETCH/OFFSET row-limiting tail is a no-column zone:
    // count slots, unit slots, PERCENT, and the ONLY/WITH/TIES keyword slots all
    // collapse to OrderByClause yet never accept a column.
    assert!(at("SELECT * FROM emp ORDER BY empno FETCH FIRST |"));
    assert!(at("SELECT * FROM emp ORDER BY empno FETCH NEXT |"));
    assert!(at("SELECT * FROM emp ORDER BY empno FETCH FIRST 5 |"));
    assert!(at("SELECT * FROM emp ORDER BY empno FETCH NEXT :n |"));
    assert!(at("SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS |"));
    assert!(at(
        "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 PERCENT |"
    ));
    assert!(at(
        "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS WITH |"
    ));
    assert!(at(
        "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS ONLY |"
    ));
    assert!(at(
        "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS WITH TIES |"
    ));
    assert!(at(
        "SELECT * FROM emp OFFSET 10 ROWS FETCH NEXT 5 ROWS ONLY |"
    ));
    assert!(at("SELECT * FROM emp OFFSET 10 |"));
    assert!(at("SELECT * FROM emp OFFSET 10 ROWS |"));

    for db in [MySQL, MariaDB] {
        let kw = |sql: &str| {
            SqlEditorWidget::collect_expected_keyword_suggestions(
                "",
                &analyze_inline_cursor_sql(sql),
                Some(db),
            )
        };
        assert_eq!(
            kw("SELECT * FROM orders LIMIT 10 |"),
            vec!["OFFSET".to_string()],
            "{db:?} LIMIT tail should suggest OFFSET: {:?}",
            kw("SELECT * FROM orders LIMIT 10 |")
        );
        assert!(
            kw("SELECT * FROM orders LIMIT 10 OFFSET 20 |").is_empty(),
            "{db:?} should not suggest anything after LIMIT/OFFSET tuple close: {:?}",
            kw("SELECT * FROM orders LIMIT 10 OFFSET 20 |")
        );
        assert_eq!(
            kw("SELECT limit 10 | FROM orders"),
            vec!["FROM".to_string()],
            "{db:?} should suggest FROM after LIMIT literal token: {:?}",
            kw("SELECT limit 10 | FROM orders")
        );
    }

    // Ordinary column positions are unaffected, including a `offset_*` column.
    assert!(!at("SELECT | FROM orders"));
    assert!(!at("SELECT a, | FROM orders"));
    assert!(!at("SELECT * FROM orders WHERE | "));
    assert!(!at("SELECT offset_days, | FROM t"));
    assert!(!at("SELECT limit | FROM orders"));
    assert!(!at("SELECT offset | FROM orders"));
    assert!(!at("SELECT * FROM orders ORDER BY |"));
}

#[test]
fn row_limiting_clause_final_suggestions_stay_keyword_or_empty() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);
    let assert_no_catalog_noise =
        |sql: &str, db: crate::db::DatabaseType, final_suggestions: &[String]| {
            for leaked in [
                "EMP",
                "DEPT",
                "EMP_V",
                "APP_USER",
                "SCOTT",
                "RUN_JOB",
                "CALC_TOTAL",
                "EMPNO",
                "ENAME",
                "DEPTNO",
                "DNAME",
                "*",
            ] {
                assert!(
                !contains(final_suggestions, leaked),
                "{leaked} leaked into row-limiting slot at `{sql}` {db:?}: {final_suggestions:?}"
            );
            }
        };

    for (db, sql, expected_keywords) in [
        (MySQL, "SELECT * FROM orders LIMIT |", &[][..]),
        (MySQL, "SELECT * FROM orders LIMIT 10, |", &[]),
        (MySQL, "SELECT * FROM orders LIMIT 10 OFFSET |", &[]),
        (MySQL, "SELECT * FROM orders LIMIT 10 |", &["OFFSET"]),
        (MySQL, "SELECT * FROM orders LIMIT 10 OFFSET 20 |", &[]),
        (MariaDB, "SELECT * FROM orders LIMIT |", &[][..]),
        (MariaDB, "SELECT * FROM orders LIMIT 10, |", &[]),
        (MariaDB, "SELECT * FROM orders LIMIT 10 OFFSET |", &[]),
        (MariaDB, "SELECT * FROM orders LIMIT 10 |", &["OFFSET"]),
        (MariaDB, "SELECT * FROM orders LIMIT 10 OFFSET 20 |", &[]),
        (
            Oracle,
            "SELECT * FROM emp ORDER BY empno FETCH |",
            &["FIRST", "NEXT"],
        ),
        (
            Oracle,
            "SELECT * FROM emp ORDER BY empno FETCH FIRST |",
            &["ROW", "ROWS"],
        ),
        (
            Oracle,
            "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 |",
            &["ROW", "ROWS"],
        ),
        (
            Oracle,
            "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS |",
            &["ONLY", "WITH"],
        ),
        (
            Oracle,
            "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS WITH |",
            &["TIES"],
        ),
        (
            Oracle,
            "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS ONLY |",
            &[],
        ),
        (
            Oracle,
            "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS ONLY n|",
            &[],
        ),
        (
            Oracle,
            "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS WITH TIES |",
            &[],
        ),
        (
            Oracle,
            "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS WITH TIES n|",
            &[],
        ),
        (Oracle, "SELECT * FROM emp OFFSET |", &[]),
        (Oracle, "SELECT * FROM emp OFFSET 10 |", &["ROW", "ROWS"]),
        (Oracle, "SELECT * FROM emp OFFSET 10 ROWS |", &["FETCH"]),
        (
            Oracle,
            "SELECT * FROM emp OFFSET 10 ROWS FETCH NEXT 5 ROWS ONLY |",
            &[],
        ),
        (
            Oracle,
            "SELECT * FROM emp OFFSET 10 ROWS FETCH NEXT 5 ROWS ONLY n|",
            &[],
        ),
        (MySQL, "SELECT * FROM orders LIMIT 10 OFFSET 20 n|", &[]),
        (MySQL, "SELECT * FROM orders LIMIT 10, 20 n|", &[]),
        (MariaDB, "SELECT * FROM orders LIMIT 10 OFFSET 20 n|", &[]),
        (MariaDB, "SELECT * FROM orders LIMIT 10, 20 n|", &[]),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert_eq!(
            kind, None,
            "row-limiting slot should not resolve an object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        for expected in expected_keywords {
            assert!(
                contains(&final_suggestions, expected),
                "{expected} missing from row-limiting slot at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        assert_no_catalog_noise(sql, db, &final_suggestions);
    }
}

#[test]
fn row_limiting_keyword_candidates_are_dialect_scoped() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let kw = |sql: &str, db: crate::db::DatabaseType| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor marker");
        let plain = sql.replace('|', "");
        let prefix = crate::ui::intellisense::get_word_at_cursor(&plain, cursor).0;
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for db in [MySQL, MariaDB] {
        let limit_tail = kw("SELECT * FROM orders LIMIT 10 |", db);
        assert!(
            has(&limit_tail, "OFFSET"),
            "{db:?} LIMIT tail lost OFFSET: {limit_tail:?}"
        );

        for (sql, leaked) in [
            (
                "SELECT * FROM emp ORDER BY empno FETCH |",
                &["FIRST", "NEXT"][..],
            ),
            (
                "SELECT * FROM emp ORDER BY empno FETCH FIRST |",
                &["ROW", "ROWS"],
            ),
            (
                "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS |",
                &["ONLY", "WITH"],
            ),
            ("SELECT * FROM emp OFFSET 10 |", &["ROW", "ROWS"]),
            ("SELECT * FROM emp OFFSET 10 ROWS |", &["FETCH"]),
        ] {
            let got = kw(sql, db);
            for keyword in leaked {
                assert!(
                    !has(&got, keyword),
                    "{keyword} leaked into {db:?} row-limiting slot at `{sql}`: {got:?}"
                );
            }
        }
    }

    let oracle_limit = kw("SELECT * FROM orders LIMIT 10 |", Oracle);
    assert!(
        !has(&oracle_limit, "OFFSET"),
        "MySQL LIMIT tail leaked into Oracle mode: {oracle_limit:?}"
    );

    let oracle_fetch = kw("SELECT * FROM emp ORDER BY empno FETCH |", Oracle);
    assert!(
        has(&oracle_fetch, "FIRST") && has(&oracle_fetch, "NEXT"),
        "{oracle_fetch:?}"
    );
}

#[test]
fn opposite_dialect_row_limiting_tails_do_not_offer_catalog_or_stale_keywords() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);
    let assert_clean = |db: crate::db::DatabaseType, sql: &str, leaked: &[&str]| {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert!(
            kind.is_none() || matches!(kind, Some(ExpectedObjectSuggestionKind::NoSuggestions)),
            "opposite-dialect row-limiting tail resolved object kind at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
        );
        for value in [
            "EMP",
            "DEPT",
            "EMP_V",
            "APP_USER",
            "SCOTT",
            "RUN_JOB",
            "CALC_TOTAL",
            "EMPNO",
            "ENAME",
            "DEPTNO",
            "DNAME",
            "*",
        ] {
            assert!(
                !contains(&final_suggestions, value),
                "{value} leaked into opposite-dialect row-limiting tail at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        for value in leaked {
            assert!(
                !contains(&keywords, value) && !contains(&final_suggestions, value),
                "{value} leaked into opposite-dialect row-limiting tail at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    };

    for db in [MySQL, MariaDB] {
        for sql in [
            "SELECT * FROM emp ORDER BY empno FETCH |",
            "SELECT * FROM emp ORDER BY empno FETCH FIRST |",
            "SELECT * FROM emp ORDER BY empno FETCH FIRST 5 ROWS |",
            "SELECT * FROM emp OFFSET 10 |",
            "SELECT * FROM emp OFFSET 10 ROWS |",
        ] {
            assert_clean(
                db,
                sql,
                &[
                    "FIRST", "NEXT", "ROW", "ROWS", "ONLY", "WITH", "TIES", "FETCH",
                ],
            );
        }
    }

    for sql in [
        "SELECT * FROM emp LIMIT |",
        "SELECT * FROM emp LIMIT 10 |",
        "SELECT * FROM emp LIMIT 10 OFFSET |",
        "SELECT * FROM emp LIMIT 10 OFFSET 20 |",
        "SELECT * FROM emp LIMIT 10, |",
    ] {
        assert_clean(Oracle, sql, &["OFFSET", "LIMIT"]);
    }
}

#[test]
fn local_record_member_scope_boundary_and_nested_loops() {
    let members = |sql: &str, q: &str| {
        SqlEditorWidget::collect_local_record_member_suggestions_for_test(sql, q, "")
    };
    // A loop record is not visible outside its own loop.
    assert!(members(
        "BEGIN FOR rec IN (SELECT a FROM t) LOOP NULL; END LOOP; rec.__CODEX_CURSOR__ END;",
        "rec",
    )
    .is_none());
    // Inner loop sees its own record and the enclosing loop's record.
    let inner = members(
        "BEGIN FOR a IN (SELECT x FROM t1) LOOP FOR b IN (SELECT y FROM t2) LOOP b.__CODEX_CURSOR__ END LOOP; END LOOP; END;",
        "b",
    )
    .expect("inner loop record visible");
    assert_has_case_insensitive(&inner, "y");
    let outer = members(
        "BEGIN FOR a IN (SELECT x FROM t1) LOOP FOR b IN (SELECT y FROM t2) LOOP a.__CODEX_CURSOR__ END LOOP; END LOOP; END;",
        "a",
    )
    .expect("enclosing loop record visible inside inner loop");
    assert_has_case_insensitive(&outer, "x");
}

/// The base catalog's flat, prefix-only keyword dump is filtered down to an
/// allowlist of keywords that are actually grammatical at the cursor's
/// expression position: clause/statement/DDL keywords never appear in a value
/// expression, construct-scoped keywords (CASE body, window-frame bounds, MERGE
/// `MATCHED`) appear only inside their construct, operators appear only after a
/// complete operand, and value/function keywords only where an operand is
/// expected. Columns, relations and objects stay scoped to operand positions
/// too, and a real column named like a keyword is never hidden.
#[test]
fn expression_keyword_completion_is_position_aware() {
    use crate::db::DatabaseType::Oracle;

    fn suggestions(sql_with_cursor: &str, extra_emp_columns: &[&str]) -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, word_start, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let qualifier = SqlEditorWidget::qualifier_before_word_in_text(&sql, word_start);
        let column_tables =
            SqlEditorWidget::resolve_column_tables_for_context(qualifier.as_deref(), &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string()];
        let mut emp_columns = vec!["ENAME".to_string(), "EMPNO".to_string()];
        emp_columns.extend(extra_emp_columns.iter().map(|c| c.to_string()));
        data.set_columns_for_table("EMP", emp_columns);
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(crate::db::DatabaseType::Oracle),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(Oracle),
            expr_keyword_ctx,
        )
    }
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    // Outside a CASE the body keywords are pure noise and must be dropped, while
    // the real columns of the position still come through.
    let s = suggestions("SELECT en| FROM emp", &[]);
    assert!(!has(&s, "END"), "END leaked outside CASE: {s:?}");
    assert!(has(&s, "ENAME"), "real column dropped: {s:?}");
    for (sql, kw) in [
        ("SELECT el| FROM emp", "ELSE"),
        ("SELECT el| FROM emp", "ELSIF"),
        ("SELECT * FROM emp WHERE th|", "THEN"),
        ("SELECT * FROM emp WHERE en| = 1", "END"),
        ("SELECT ename FROM emp GROUP BY th|", "THEN"),
    ] {
        let s = suggestions(sql, &[]);
        assert!(!has(&s, kw), "{kw} leaked outside CASE for `{sql}`: {s:?}");
    }

    // Inside an unclosed CASE the body keywords are grammatical only at the
    // matching CASE state, not merely because some CASE is open.
    let s = suggestions("SELECT CASE WHEN empno = 1 th| FROM emp", &[]);
    assert!(has(&s, "THEN"), "THEN suppressed inside CASE: {s:?}");
    let s = suggestions("SELECT CASE WHEN empno = 1 THEN 2 en| FROM emp", &[]);
    assert!(has(&s, "END"), "END suppressed inside CASE: {s:?}");
    let s = suggestions("SELECT CASE WHEN empno = 1 THEN 2 el| FROM emp", &[]);
    assert!(has(&s, "ELSE"), "ELSE suppressed inside CASE: {s:?}");
    for (sql, kw) in [
        ("SELECT CASE WHEN th| THEN 1 END FROM emp", "THEN"),
        ("SELECT CASE WHEN empno = 1 THEN el| END FROM emp", "ELSE"),
        ("SELECT CASE WHEN empno = 1 THEN en| END FROM emp", "END"),
    ] {
        let s = suggestions(sql, &[]);
        assert!(
            !has(&s, kw),
            "{kw} leaked before the CASE slot was complete for `{sql}`: {s:?}"
        );
    }

    // A column literally named like a CASE keyword is preserved even outside a
    // CASE — the filter never hides a legitimate completion.
    let s = suggestions("SELECT en| FROM emp", &["END"]);
    assert!(has(&s, "END"), "column named END was hidden: {s:?}");

    // The same flat-catalog problem applies to the window-frame boundary
    // keywords (`PRECEDING`/`FOLLOWING`/`UNBOUNDED`): they are stripped from the
    // base expression catalog and served only by the contextual frame-keyword
    // merge at actual frame slots.
    for (sql, kw) in [
        ("SELECT pr| FROM emp", "PRECEDING"),
        ("SELECT fo| FROM emp", "FOLLOWING"),
        ("SELECT un| FROM emp", "UNBOUNDED"),
        ("SELECT * FROM emp WHERE pr| = 1", "PRECEDING"),
    ] {
        let s = suggestions(sql, &[]);
        assert!(
            !has(&s, kw),
            "{kw} leaked outside window spec for `{sql}`: {s:?}"
        );
    }
    let ctx = analyze_inline_cursor_sql(
        "SELECT SUM(empno) OVER (ORDER BY empno ROWS BETWEEN un| FROM emp",
    );
    let kw = SqlEditorWidget::collect_expected_keyword_suggestions("un", &ctx, Some(Oracle));
    assert!(
        has(&kw, "UNBOUNDED"),
        "UNBOUNDED suppressed inside window frame: {kw:?}"
    );
    let ctx = analyze_inline_cursor_sql(
        "SELECT SUM(empno) OVER (ORDER BY empno ROWS BETWEEN 1 pr| FROM emp",
    );
    let kw = SqlEditorWidget::collect_expected_keyword_suggestions("pr", &ctx, Some(Oracle));
    assert!(
        has(&kw, "PRECEDING"),
        "PRECEDING suppressed inside window frame: {kw:?}"
    );
    // A column named like a frame keyword is preserved outside a window spec.
    let s = suggestions("SELECT pr| FROM emp", &["PRECEDING"]);
    assert!(
        has(&s, "PRECEDING"),
        "column named PRECEDING was hidden: {s:?}"
    );

    // `MATCH` is MySQL full-text syntax and Oracle row-pattern syntax, not a
    // generic Oracle value expression. The MERGE action keyword `MATCHED` only
    // follows `WHEN [NOT]`; neither may leak into a value/column position.
    for sql in ["SELECT ma| FROM emp", "SELECT * FROM emp WHERE ma| = 1"] {
        let s = suggestions(sql, &[]);
        assert!(
            !has(&s, "MATCH"),
            "MATCH leaked into value position for `{sql}`: {s:?}"
        );
        assert!(
            !has(&s, "MATCHED"),
            "MATCHED leaked into value position for `{sql}`: {s:?}"
        );
    }
    // Its legitimate MERGE slot is still served by the contextual keyword merge.
    let ctx =
        analyze_inline_cursor_sql("MERGE INTO emp e USING dept d ON (e.empno = d.deptno) WHEN ma|");
    let kw = SqlEditorWidget::collect_expected_keyword_suggestions("ma", &ctx, Some(Oracle));
    assert!(
        kw.iter().any(|k| k.eq_ignore_ascii_case("MATCHED")),
        "MERGE WHEN slot lost MATCHED: {kw:?}"
    );
    // A column named MATCHED is preserved in a value position.
    let s = suggestions("SELECT ma| FROM emp", &["MATCHED"]);
    assert!(has(&s, "MATCHED"), "column named MATCHED was hidden: {s:?}");
    let s = suggestions("SELECT ma| FROM emp", &["MATCH"]);
    assert!(has(&s, "MATCH"), "column named MATCH was hidden: {s:?}");

    // Clause / statement / DDL keywords never belong in a value expression and
    // are dropped from the base dump (their real slots are served by the
    // grammar-aware keyword merge).
    for (sql, kw) in [
        ("SELECT cr| FROM emp", "CREATE"),
        ("SELECT fr| FROM emp", "FROM"),
        ("SELECT ta| FROM emp", "TABLESPACE"),
        ("SELECT wh| FROM emp", "WHERE"),
        ("SELECT * FROM emp WHERE ad| = 1", "ADD"),
        ("SELECT gr| FROM emp", "GROUP"),
    ] {
        let s = suggestions(sql, &[]);
        assert!(
            !has(&s, kw),
            "{kw} leaked into value expression for `{sql}`: {s:?}"
        );
    }

    // Genuine expression keywords/functions survive where an operand is expected.
    let s = suggestions("SELECT ca| FROM emp", &[]);
    assert!(
        has(&s, "CASE") && has(&s, "CAST"),
        "expression starters dropped: {s:?}"
    );
    let s = suggestions("SELECT ex| FROM emp", &[]);
    assert!(has(&s, "EXISTS"), "EXISTS dropped at operand start: {s:?}");
    let s = suggestions("SELECT co| FROM emp", &[]);
    assert!(
        has(&s, "COALESCE"),
        "function keyword dropped at operand start: {s:?}"
    );

    // After a complete operand only operators are grammatical: no functions, no
    // columns, no operand-starters.
    let s = suggestions("SELECT ename a| FROM emp", &[]);
    assert!(has(&s, "AND"), "operator dropped after operand: {s:?}");
    let s = suggestions("SELECT ename ab| FROM emp", &[]);
    assert!(
        !has(&s, "ABS()") && !has(&s, "ABS"),
        "function leaked after operand: {s:?}"
    );
    // The implicit-alias slot (`<expr> <name>|`) no longer leaks columns/tables.
    let s = suggestions("SELECT ename e| FROM emp", &[]);
    for leaked in ["ENAME", "EMPNO", "EMP"] {
        assert!(
            !has(&s, leaked),
            "{leaked} leaked into implicit-alias slot: {s:?}"
        );
    }

    // Operators are not offered where an operand is expected (statement start).
    let s = suggestions("SELECT a| FROM emp", &[]);
    assert!(
        !has(&s, "AND") && !has(&s, "AT"),
        "operator offered at operand start: {s:?}"
    );
    // Columns are still offered where an operand is expected.
    let s = suggestions("SELECT * FROM emp WHERE en| = 1", &[]);
    assert!(has(&s, "ENAME"), "column dropped at operand-start: {s:?}");
}

#[test]
fn sql_value_expression_suppresses_relation_names() {
    use crate::db::DatabaseType::Oracle;

    fn suggestions(sql_with_cursor: &str, emp_columns: &[&str]) -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string(), "DEPT".to_string()];
        data.views = vec!["EMP_V".to_string()];
        data.set_columns_for_table(
            "EMP",
            emp_columns
                .iter()
                .map(|column| (*column).to_string())
                .collect(),
        );
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(Oracle),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(Oracle),
            expr_keyword_ctx,
        )
    }
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    for sql in [
        "SELECT a, |",
        "SELECT empno FROM emp GROUP BY empno, |",
        "SELECT * FROM emp WHERE empno = |",
        "SELECT * FROM emp WHERE empno = 1 AND |",
    ] {
        let s = suggestions(sql, &["ENAME", "EMPNO"]);
        assert!(
            !has(&s, "EMP") && !has(&s, "DEPT") && !has(&s, "EMP_V"),
            "relation names leaked into SQL value/column expression for `{sql}`: {s:?}"
        );
    }

    let rhs = suggestions("SELECT * FROM emp WHERE empno = |", &["ENAME", "EMPNO"]);
    assert!(
        has(&rhs, "ENAME"),
        "scoped column was wrongly suppressed: {rhs:?}"
    );

    let column_named_like_table = suggestions("SELECT emp| FROM emp", &["EMP", "EMPNO"]);
    assert!(
        has(&column_named_like_table, "EMP"),
        "real scoped column named like a table must be preserved: {column_named_like_table:?}"
    );

    let relation_slot = suggestions("SELECT * FROM |", &["ENAME", "EMPNO"]);
    assert!(
        has(&relation_slot, "EMP") && has(&relation_slot, "DEPT"),
        "relation names must remain available in FROM slots: {relation_slot:?}"
    );
}

/// The analytic/aggregate continuations `OVER`, `KEEP` and `WITHIN` (GROUP) are
/// only grammatical immediately after a closed call — `SUM(x) OVER (…)`,
/// `MAX(x) KEEP (DENSE_RANK …)`, `LISTAGG(…) WITHIN GROUP (…)`. After any other
/// complete operand (a plain column, a literal, a parenthesized value) they are
/// pure noise. They always follow a `)`, so gating them on a closed call removes
/// the noise without ever hiding a valid completion.
#[test]
fn analytic_continuations_offered_only_after_a_closed_call() {
    fn suggestions(sql_with_cursor: &str) -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string()];
        data.set_columns_for_table("EMP", vec!["ENAME".to_string(), "EMPNO".to_string()]);
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(crate::db::DatabaseType::Oracle),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(crate::db::DatabaseType::Oracle),
            expr_keyword_ctx,
        )
    }
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    // After a plain column / literal operand the continuations are noise.
    for (sql, kw) in [
        ("SELECT ename ov| FROM emp", "OVER"),
        ("SELECT ename ke| FROM emp", "KEEP"),
        ("SELECT ename wi| FROM emp", "WITHIN"),
        ("SELECT * FROM emp WHERE empno ov| = 1", "OVER"),
        ("SELECT 1 ov| FROM emp", "OVER"),
    ] {
        let s = suggestions(sql);
        assert!(
            !has(&s, kw),
            "{kw} leaked after a plain operand for `{sql}`: {s:?}"
        );
    }

    // A closing `)` that ends a *grouping/predicate paren* or a *subquery* — not
    // a function call — is not a call site: the continuations stay suppressed.
    // (Regression: the previous "last token is `)`" test treated every paren as a
    // call, leaking `OVER`/`KEEP`/`WITHIN` after `(a + b)`, `(SELECT …)`, etc.)
    for (sql, kw) in [
        ("SELECT (empno + 1) ov| FROM emp", "OVER"),
        ("SELECT (sum(empno)) ov| FROM emp", "OVER"),
        ("SELECT (SELECT max(empno) FROM emp) ov| FROM emp", "OVER"),
        ("SELECT (empno) ke| FROM emp", "KEEP"),
        ("SELECT (empno) wi| FROM emp", "WITHIN"),
        (
            "SELECT * FROM emp WHERE EXISTS (SELECT 1 FROM emp) ov|",
            "OVER",
        ),
        ("SELECT * FROM emp WHERE empno IN (1, 2) ov|", "OVER"),
    ] {
        let s = suggestions(sql);
        assert!(
            !has(&s, kw),
            "{kw} leaked after a non-call `)` for `{sql}`: {s:?}"
        );
    }

    // A user-defined routine call (a non-keyword identifier before `(`) is still
    // a call site, so the continuation survives.
    assert!(
        has(&suggestions("SELECT my_rank(empno) ov| FROM emp"), "OVER"),
        "OVER suppressed after a user-defined function call"
    );

    // Immediately after a closed call they are grammatical again.
    for (sql, kw) in [
        ("SELECT sum(empno) ov| FROM emp", "OVER"),
        ("SELECT max(empno) ke| FROM emp", "KEEP"),
        ("SELECT count(*) ov| FROM emp", "OVER"),
        ("SELECT listagg(ename) wi| FROM emp", "WITHIN"),
    ] {
        let s = suggestions(sql);
        assert!(
            has(&s, kw),
            "{kw} suppressed after a closed call for `{sql}`: {s:?}"
        );
    }

    // The MySQL full-text continuation `AGAINST` is even narrower:
    // `MATCH(col) AGAINST ('text')` — a closed MATCH call, never a plain operand
    // or a different function call.
    let mysql = |sql_with_cursor: &str, db_type| -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string()];
        data.set_columns_for_table("EMP", vec!["ENAME".to_string(), "EMPNO".to_string()]);
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(db_type),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(db_type),
            expr_keyword_ctx,
        )
    };
    for db in [
        crate::db::DatabaseType::MySQL,
        crate::db::DatabaseType::MariaDB,
    ] {
        assert!(
            !has(&mysql("SELECT ename ag| FROM emp", db), "AGAINST"),
            "AGAINST leaked after a plain operand for {db:?}"
        );
        assert!(
            !has(&mysql("SELECT concat(ename) ag| FROM emp", db), "AGAINST"),
            "AGAINST leaked after a non-MATCH function call for {db:?}"
        );
        assert!(
            has(&mysql("SELECT ma| FROM emp", db), "MATCH"),
            "MATCH suppressed at a full-text operand position for {db:?}"
        );
        assert!(
            has(&mysql("SELECT match(ename) ag| FROM emp", db), "AGAINST"),
            "AGAINST suppressed after a closed MATCH call for {db:?}"
        );
    }
}

#[test]
fn mysql_family_full_text_against_open_paren_slot_suppresses_columns() {
    let suppresses = |sql: &str, db_type| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
            &analyze_inline_cursor_sql(sql),
            false,
            Some(db_type),
        )
    };

    use crate::db::DatabaseType::{MariaDB, MySQL};

    for db in [MySQL, MariaDB] {
        assert!(
            suppresses("SELECT match(ename) AGAINST | FROM emp", db),
            "MATCH ... AGAINST must require an opening paren in {db:?}"
        );
        assert!(
            typed_emp_suggestions_for_db("SELECT match(ename) AGAINST | FROM emp", db).is_empty(),
            "identifier material leaked after MATCH ... AGAINST opener for {db:?}"
        );
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for("SELECT match(ename) AGAINST | FROM emp", db);
        assert_eq!(
            kind, None,
            "MATCH ... AGAINST opener should not resolve object kind for {db:?}: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.is_empty(),
            "MATCH ... AGAINST opener should not offer catalog or keywords for {db:?}: keywords={keywords:?} final={final_suggestions:?}"
        );
    }
    assert!(
        !suppresses(
            "SELECT match(ename) AGAINST | FROM emp",
            crate::db::DatabaseType::Oracle
        ),
        "Oracle must not treat AGAINST as a MySQL full-text operator"
    );
    assert!(
        !suppresses("SELECT concat(ename) AGAINST | FROM emp", MySQL),
        "only a closed MATCH call may introduce AGAINST for MySQL"
    );
    assert!(
        !suppresses("SELECT concat(ename) AGAINST | FROM emp", MariaDB),
        "only a closed MATCH call may introduce AGAINST for MariaDB"
    );

    let suggestions =
        typed_emp_suggestions_for_db("SELECT match(ename) AGAINST (|) FROM emp", MySQL);
    assert!(
        suggestions.iter().any(|value| value == "ENAME"),
        "MySQL AGAINST argument expression slot should keep columns: {suggestions:?}"
    );
}

/// MySQL `GROUP_CONCAT` admits the optional `SEPARATOR` clause only inside its
/// own argument list, after the grouped expression / order expression and before
/// a separator has already appeared. It must not leak as a generic after-operand
/// keyword in the select list or predicates.
#[test]
fn group_concat_separator_is_scoped_to_group_concat_arguments() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    fn suggestions(sql_with_cursor: &str, db: crate::db::DatabaseType) -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string()];
        data.set_columns_for_table("EMP", vec!["ENAME".to_string(), "EMPNO".to_string()]);
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(db),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(db),
            expr_keyword_ctx,
        )
    }
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    for db in [MySQL, MariaDB] {
        for sql in [
            "SELECT ename se| FROM emp",
            "SELECT concat(ename) se| FROM emp",
            "SELECT * FROM emp WHERE ename se|",
            "SELECT group_concat(concat(ename, se|)) FROM emp",
            "SELECT group_concat(ename SEPARATOR ',' se|) FROM emp",
            "SELECT group_concat(ename SEPARATOR se|) FROM emp",
        ] {
            let s = suggestions(sql, db);
            assert!(
                !has(&s, "SEPARATOR"),
                "SEPARATOR leaked for `{sql}` in {db:?}: {s:?}"
            );
        }

        for sql in [
            "SELECT group_concat(ename se|) FROM emp",
            "SELECT group_concat(DISTINCT ename se|) FROM emp",
            "SELECT group_concat(ename ORDER BY empno se|) FROM emp",
        ] {
            let s = suggestions(sql, db);
            assert!(
                has(&s, "SEPARATOR"),
                "SEPARATOR suppressed for `{sql}` in {db:?}: {s:?}"
            );
        }
    }
}

/// MySQL's phonetic comparison is the compound operator `SOUNDS LIKE`. `SOUNDS`
/// itself is not a general postfix keyword after every operand, and the `LIKE`
/// after it is a fixed continuation rather than a normal pattern `LIKE` that can
/// later take `ESCAPE`.
#[test]
fn sounds_like_operator_is_scoped_to_mysql_character_operands() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    fn suggestions(sql_with_cursor: &str, db: crate::db::DatabaseType) -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string()];
        data.set_columns_for_table("EMP", vec!["ENAME".to_string(), "EMPNO".to_string()]);
        data.set_column_meta_for_table(
            "EMP",
            HashMap::from([
                (
                    "ENAME".to_string(),
                    ColumnMeta {
                        type_display: "VARCHAR(20)".to_string(),
                        nullable: true,
                        is_primary_key: false,
                    },
                ),
                (
                    "EMPNO".to_string(),
                    ColumnMeta {
                        type_display: "INT".to_string(),
                        nullable: false,
                        is_primary_key: true,
                    },
                ),
            ]),
        );
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(db),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(db),
            expr_keyword_ctx,
        )
    }
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    for db in [MySQL, MariaDB] {
        for sql in ["SELECT empno so| FROM emp", "SELECT 1 so| FROM emp"] {
            let s = suggestions(sql, db);
            assert!(
                !has(&s, "SOUNDS"),
                "SOUNDS leaked after a non-character operand for `{sql}` in {db:?}: {s:?}"
            );
        }

        for sql in [
            "SELECT ename so| FROM emp",
            "SELECT upper(ename) so| FROM emp",
        ] {
            let s = suggestions(sql, db);
            assert!(
                has(&s, "SOUNDS"),
                "SOUNDS suppressed after a character operand for `{sql}` in {db:?}: {s:?}"
            );
        }

        let s = suggestions("SELECT ename SOUNDS li| FROM emp", db);
        assert!(
            has(&s, "LIKE"),
            "LIKE suppressed after SOUNDS in {db:?}: {s:?}"
        );

        let ctx = analyze_inline_cursor_sql("SELECT ename SOUNDS | FROM emp");
        assert_eq!(
            SqlEditorWidget::collect_expected_keyword_suggestions("", &ctx, Some(db)),
            vec!["LIKE".to_string()]
        );
        assert!(
            SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
                &ctx,
                false,
                Some(db),
            )
        );
        assert!(
            !SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
                &ctx,
                false,
                Some(Oracle),
            )
        );

        for sql in [
            "SELECT sounds | FROM emp",
            "CREATE TABLE x AS SELECT sounds | FROM emp",
        ] {
            let ctx = analyze_inline_cursor_sql(sql);
            assert!(
                !SqlEditorWidget::collect_expected_keyword_suggestions("", &ctx, Some(db))
                    .iter()
                    .any(|value| value == "LIKE"),
                "LIKE leaked after SOUNDS without a left operand for `{sql}` in {db:?}"
            );
            assert!(
                !SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
                    &ctx,
                    false,
                    Some(db),
                ),
                "SOUNDS without a left operand should not be keyword-only for `{sql}` in {db:?}"
            );
        }

        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for("SELECT * FROM emp WHERE ename SOUNDS |", db);
        assert_eq!(
            kind, None,
            "SOUNDS fixed keyword tail should not resolve object kind in {db:?}: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            has(&final_suggestions, "LIKE"),
            "LIKE missing from SOUNDS fixed keyword tail in {db:?}: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in ["EMP", "DEPT", "EMP_V", "EMPNO", "ENAME", "SAL"] {
            assert!(
                !has(&final_suggestions, leaked),
                "{leaked} leaked into SOUNDS fixed keyword tail in {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }

        let s = suggestions("SELECT ename SOUNDS LIKE 'SMTH' es| FROM emp", db);
        assert!(
            !has(&s, "ESCAPE"),
            "ESCAPE leaked after SOUNDS LIKE in {db:?}: {s:?}"
        );

        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for("SELECT * FROM emp WHERE ename SOUNDS LIKE 'SMTH' |", db);
        assert_eq!(
            kind, None,
            "completed SOUNDS LIKE tail should not resolve object kind in {db:?}: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in ["EMP", "DEPT", "EMP_V", "EMPNO", "ENAME", "SAL"] {
            assert!(
                !has(&final_suggestions, leaked),
                "{leaked} leaked after completed SOUNDS LIKE tail in {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        let (_kind, keywords, final_suggestions) =
            audit_final_suggestions_for("SELECT * FROM emp WHERE ename SOUNDS LIKE 'SMTH' n|", db);
        assert!(
            final_suggestions.is_empty(),
            "completed SOUNDS LIKE tail with prefix should not offer catalog or stale keywords in {db:?}: keywords={keywords:?} final={final_suggestions:?}"
        );
    }
}

/// MySQL/MariaDB `NEW`/`OLD` are trigger pseudo rows, not generic expression starters.
/// They are scoped by trigger event: INSERT exposes `NEW`, DELETE exposes `OLD`,
/// and UPDATE exposes both.
#[test]
fn mysql_trigger_pseudo_rows_are_scoped_to_trigger_events() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    fn suggestions(
        sql_with_cursor: &str,
        extra_emp_columns: &[&str],
        db_type: crate::db::DatabaseType,
    ) -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, word_start, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let qualifier = SqlEditorWidget::qualifier_before_word_in_text(&sql, word_start);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context_for_db(
            qualifier.as_deref(),
            &ctx,
            Some(db_type),
        );
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string(), "APP.EMP".to_string()];
        let mut emp_columns = vec!["ENAME".to_string(), "EMPNO".to_string()];
        emp_columns.extend(extra_emp_columns.iter().map(|c| c.to_string()));
        data.set_columns_for_table("EMP", emp_columns);
        data.set_columns_for_table(
            "APP.EMP",
            vec!["APP_ENAME".to_string(), "APP_EMPNO".to_string()],
        );
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(db_type),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            qualifier.as_deref(),
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(db_type),
            expr_keyword_ctx,
        )
    }
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    for db_type in [MySQL, MariaDB] {
        for (sql, kw) in [
            ("SELECT ne| FROM emp", "NEW"),
            ("SELECT ol| FROM emp", "OLD"),
            ("SELECT * FROM emp WHERE ne| = 1", "NEW"),
            ("SELECT * FROM emp WHERE ol| = 1", "OLD"),
        ] {
            let s = suggestions(sql, &[], db_type);
            assert!(
                !has(&s, kw),
                "{kw} leaked outside a trigger for {db_type:?} `{sql}`: {s:?}"
            );
        }

        let s = suggestions("SELECT ne| FROM emp", &["NEW"], db_type);
        assert!(
            has(&s, "NEW"),
            "column named NEW was hidden for {db_type:?}: {s:?}"
        );
        let s = suggestions("SELECT ol| FROM emp", &["OLD"], db_type);
        assert!(
            has(&s, "OLD"),
            "column named OLD was hidden for {db_type:?}: {s:?}"
        );

        let insert_new = suggestions(
            "CREATE TRIGGER bi_emp BEFORE INSERT ON emp FOR EACH ROW SET NEW.ename = ne|",
            &[],
            db_type,
        );
        assert!(
            has(&insert_new, "NEW"),
            "NEW suppressed in {db_type:?} INSERT trigger: {insert_new:?}"
        );
        let insert_old = suggestions(
            "CREATE TRIGGER bi_emp BEFORE INSERT ON emp FOR EACH ROW SET NEW.ename = ol|",
            &[],
            db_type,
        );
        assert!(
            !has(&insert_old, "OLD"),
            "OLD leaked in {db_type:?} INSERT trigger: {insert_old:?}"
        );

        let update_new = suggestions(
            "CREATE TRIGGER bu_emp BEFORE UPDATE ON emp FOR EACH ROW SET NEW.ename = ne|",
            &[],
            db_type,
        );
        assert!(
            has(&update_new, "NEW"),
            "NEW suppressed in {db_type:?} UPDATE trigger: {update_new:?}"
        );
        let update_old = suggestions(
            "CREATE TRIGGER bu_emp BEFORE UPDATE ON emp FOR EACH ROW SET NEW.ename = ol|",
            &[],
            db_type,
        );
        assert!(
            has(&update_old, "OLD"),
            "OLD suppressed in {db_type:?} UPDATE trigger: {update_old:?}"
        );

        let delete_new = suggestions(
            "CREATE TRIGGER bd_emp BEFORE DELETE ON emp FOR EACH ROW SET @v = ne|",
            &[],
            db_type,
        );
        assert!(
            !has(&delete_new, "NEW"),
            "NEW leaked in {db_type:?} DELETE trigger: {delete_new:?}"
        );
        let delete_old = suggestions(
            "CREATE TRIGGER bd_emp BEFORE DELETE ON emp FOR EACH ROW SET @v = ol|",
            &[],
            db_type,
        );
        assert!(
            has(&delete_old, "OLD"),
            "OLD suppressed in {db_type:?} DELETE trigger: {delete_old:?}"
        );

        for (sql, expected_columns, leaked_columns) in [
            (
                "CREATE TRIGGER bi_emp BEFORE INSERT ON emp FOR EACH ROW SET NEW.| = 1",
                &["ENAME", "EMPNO"][..],
                &["OLD", "EMP", "SELECT"][..],
            ),
            (
                "CREATE TRIGGER bu_emp BEFORE UPDATE ON emp FOR EACH ROW SET NEW.| = OLD.ename",
                &["ENAME", "EMPNO"][..],
                &["EMP", "SELECT"][..],
            ),
            (
                "CREATE TRIGGER bu_emp BEFORE UPDATE ON emp FOR EACH ROW SET NEW.ename = OLD.|",
                &["ENAME", "EMPNO"][..],
                &["EMP", "SELECT"][..],
            ),
            (
                "CREATE TRIGGER bi_emp BEFORE INSERT ON app.emp FOR EACH ROW SET NEW.| = 1",
                &["APP_ENAME", "APP_EMPNO"][..],
                &["ENAME", "EMPNO", "OLD", "EMP", "SELECT"][..],
            ),
            (
                "CREATE TRIGGER bu_emp BEFORE UPDATE ON app.emp FOR EACH ROW SET NEW.ename = OLD.|",
                &["APP_ENAME", "APP_EMPNO"][..],
                &["ENAME", "EMPNO", "EMP", "SELECT"][..],
            ),
            (
                "CREATE TRIGGER bd_emp BEFORE DELETE ON emp FOR EACH ROW SET @v = OLD.|",
                &["ENAME", "EMPNO"][..],
                &["NEW", "EMP", "SELECT"][..],
            ),
        ] {
            let s = suggestions(sql, &[], db_type);
            for expected in expected_columns {
                assert!(has(&s, expected), "{expected} missing from {db_type:?} trigger pseudo-row qualifier at `{sql}`: {s:?}");
            }
            for leaked in leaked_columns {
                assert!(
                    !has(&s, leaked),
                    "{leaked} leaked into {db_type:?} trigger pseudo-row qualifier at `{sql}`: {s:?}"
                );
            }
        }

        for sql in [
            "CREATE TRIGGER bi_emp BEFORE INSERT ON emp FOR EACH ROW SET @v = OLD.|",
            "CREATE TRIGGER bd_emp BEFORE DELETE ON emp FOR EACH ROW SET @v = NEW.|",
            "CREATE TRIGGER bi_emp BEFORE INSERT ON emp FOR EACH ROW SET @v = :NEW.|",
        ] {
            let s = suggestions(sql, &[], db_type);
            assert!(
                s.is_empty(),
                "invalid {db_type:?} trigger pseudo-row qualifier should stay silent at `{sql}`: {s:?}"
            );
        }
    }
}

/// Oracle has a `CURSOR(SELECT ...)` expression; MySQL `CURSOR` is a stored
/// program declaration keyword and must not appear as a value-expression starter.
#[test]
fn cursor_expression_keyword_is_oracle_only() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    fn suggestions(
        sql_with_cursor: &str,
        db_type: crate::db::DatabaseType,
        extra_emp_columns: &[&str],
    ) -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string()];
        let mut emp_columns = vec!["ENAME".to_string(), "EMPNO".to_string()];
        emp_columns.extend(extra_emp_columns.iter().map(|c| c.to_string()));
        data.set_columns_for_table("EMP", emp_columns);
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(db_type),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(db_type),
            expr_keyword_ctx,
        )
    }
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    for db in [MySQL, MariaDB] {
        let mysql = suggestions("SELECT cu| FROM emp", db, &[]);
        assert!(
            !has(&mysql, "CURSOR"),
            "CURSOR leaked in {db:?} value position: {mysql:?}"
        );
        let mysql = suggestions("SELECT * FROM emp WHERE cu| = 1", db, &[]);
        assert!(
            !has(&mysql, "CURSOR"),
            "CURSOR leaked in {db:?} predicate: {mysql:?}"
        );
    }

    let oracle = suggestions("SELECT cu| FROM emp", Oracle, &[]);
    assert!(
        has(&oracle, "CURSOR"),
        "Oracle CURSOR expression was hidden: {oracle:?}"
    );

    for db in [MySQL, MariaDB] {
        let mysql = suggestions("SELECT cu| FROM emp", db, &["CURSOR"]);
        assert!(
            has(&mysql, "CURSOR"),
            "column named CURSOR was hidden in {db:?}: {mysql:?}"
        );
    }
}

#[test]
fn within_group_keyword_slots_suppress_identifiers_and_offer_fixed_keywords() {
    let kw = |sql: &str, prefix: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let suppresses = |sql: &str| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(
            &analyze_inline_cursor_sql(sql),
            false,
        )
    };

    assert_eq!(
        kw("SELECT listagg(ename) WITHIN | FROM emp", ""),
        vec!["GROUP".to_string()]
    );
    assert_eq!(
        kw("SELECT percentile_cont(0.5) WITHIN g| FROM emp", "g"),
        vec!["GROUP".to_string()]
    );
    assert!(kw("SELECT listagg(ename) WITHIN GROUP | FROM emp", "").is_empty());
    assert!(suppresses("SELECT listagg(ename) WITHIN | FROM emp"));
    assert!(suppresses("SELECT listagg(ename) WITHIN GROUP | FROM emp"));
    let (kind, keywords, final_suggestions) = audit_final_suggestions_for(
        "SELECT listagg(ename) WITHIN | FROM emp",
        crate::db::DatabaseType::Oracle,
    );
    assert_eq!(
        kind, None,
        "WITHIN GROUP keyword slot should not resolve object kind; keywords={keywords:?} final={final_suggestions:?}"
    );
    assert!(final_suggestions.iter().any(|value| value == "GROUP"));
    for leaked in [
        "EMP",
        "DEPT",
        "EMP_V",
        "EMPNO",
        "ENAME",
        "RUN_JOB",
        "CALC_TOTAL",
    ] {
        assert!(
            !final_suggestions.iter().any(|value| value == leaked),
            "{leaked} leaked into WITHIN GROUP keyword slot: {final_suggestions:?}"
        );
    }

    // Lookalikes outside ordered-set aggregate syntax keep normal completion.
    let lookalike = kw("SELECT (ename) WITHIN | FROM emp", "");
    assert!(
        !lookalike
            .iter()
            .any(|value| value.eq_ignore_ascii_case("GROUP")),
        "WITHIN GROUP leaked outside ordered-set aggregate syntax: {lookalike:?}"
    );
    assert!(!suppresses("SELECT within | FROM emp"));
    assert!(!suppresses("SELECT (ename) WITHIN | FROM emp"));
}

#[test]
fn ordered_aggregate_tails_stay_keyword_only_with_prefixes() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);
    let assert_no_noise = |sql: &str, suggestions: &[String]| {
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "APP_USER",
            "SCOTT",
            "RUN_JOB",
            "CALC_TOTAL",
            "EMPNO",
            "ENAME",
            "DEPTNO",
            "DNAME",
            "N_ID",
            "N_VALUE",
            "NOT",
            "NULL",
            "NEXT",
        ] {
            assert!(
                !contains(suggestions, leaked),
                "{leaked} leaked into ordered aggregate tail at `{sql}`: {suggestions:?}"
            );
        }
    };

    for (sql, expected) in [
        (
            "SELECT max(empno) KEEP (DENSE_RANK f|) FROM emp",
            Some("FIRST"),
        ),
        (
            "SELECT max(empno) KEEP (DENSE_RANK FIRST o|) FROM emp",
            Some("ORDER"),
        ),
        (
            "SELECT max(empno) KEEP (DENSE_RANK FIRST n|) FROM emp",
            None,
        ),
        (
            "SELECT max(empno) KEEP (DENSE_RANK FIRST ORDER BY empno NULLS FIRST n|) FROM emp",
            None,
        ),
        ("SELECT listagg(ename) WITHIN g| FROM emp", Some("GROUP")),
        ("SELECT listagg(ename) WITHIN n| FROM emp", None),
        ("SELECT listagg(ename) WITHIN GROUP n| FROM emp", None),
        (
            "SELECT listagg(ename) WITHIN GROUP (ORDER BY empno NULLS FIRST n|) FROM emp",
            None,
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "ordered aggregate tail should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        if let Some(expected) = expected {
            assert!(
                contains(&final_suggestions, expected),
                "{expected} missing from ordered aggregate tail at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        assert_no_noise(sql, &final_suggestions);
    }
}

/// `<closed call> KEEP |` / `… OVER |` is an analytic continuation that still
/// awaits its parenthesised argument (`KEEP (DENSE_RANK …)`, `OVER (…)`/a window
/// name). Until the argument begins it is not a complete select item, so the
/// select-list `FROM` and all identifiers are suppressed — the same "continuation
/// needs a specific preceding operand" principle as `WITHIN GROUP`. The gating is
/// call-aware: `KEEP`/`OVER` written as a column alias (after a plain column or a
/// grouping paren, not a call) keeps normal completion, and the *completed*
/// continuation (`KEEP (…) |`, `OVER (…) |`) offers `FROM` again.
#[test]
fn analytic_continuation_awaiting_argument_suppresses_query_continuation() {
    let kw = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let suppresses = |sql: &str| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(
            &analyze_inline_cursor_sql(sql),
            false,
        ) || SqlEditorWidget::cursor_is_at_identifier_suppressing_keyword_slot_for_context(
            &analyze_inline_cursor_sql(sql),
            false,
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let has = |v: &Vec<String>, s: &str| v.iter().any(|x| x == s);

    // Pending argument: no `FROM`, identifiers suppressed.
    for sql in [
        "SELECT MAX(empno) KEEP | FROM emp",
        "SELECT MAX(empno) OVER | FROM emp",
    ] {
        assert!(
            !has(&kw(sql), "FROM"),
            "FROM leaked before analytic argument at `{sql}`: {:?}",
            kw(sql)
        );
        assert!(
            suppresses(sql),
            "identifiers not suppressed before analytic argument at `{sql}`"
        );
    }
    // Completed continuation: `FROM` returns, nothing suppressed.
    for sql in [
        "SELECT MAX(empno) KEEP (DENSE_RANK FIRST ORDER BY empno) | FROM emp",
        "SELECT MAX(empno) OVER (PARTITION BY empno) | FROM emp",
    ] {
        assert!(
            has(&kw(sql), "FROM"),
            "FROM missing after complete analytic at `{sql}`: {:?}",
            kw(sql)
        );
        assert!(
            !suppresses(sql),
            "identifiers wrongly suppressed after complete analytic at `{sql}`"
        );
    }
    // Alias lookalikes (not after a call) keep normal completion.
    assert!(
        has(&kw("SELECT empno keep | FROM emp"), "FROM"),
        "alias `keep` lost FROM: {:?}",
        kw("SELECT empno keep | FROM emp")
    );
    assert!(!suppresses("SELECT empno keep | FROM emp"));
    assert!(!suppresses("SELECT (empno) keep | FROM emp"));
}

/// `ESCAPE` is grammatical only right after a `LIKE` pattern
/// (`name LIKE 'a\_%' ESCAPE '\'`), never after a plain operand. It is gated on
/// the same "continuation that needs a specific preceding operand" principle as
/// `OVER`/`KEEP`/`WITHIN`, so the same noise must not leak.
#[test]
fn escape_offered_only_after_a_like_pattern() {
    fn suggestions(sql_with_cursor: &str) -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string()];
        data.set_columns_for_table("EMP", vec!["ENAME".to_string(), "EMPNO".to_string()]);
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(crate::db::DatabaseType::Oracle),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(crate::db::DatabaseType::Oracle),
            expr_keyword_ctx,
        )
    }
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    // No preceding LIKE in the current predicate segment → ESCAPE is noise.
    for sql in [
        "SELECT * FROM emp WHERE ename es| ",
        "SELECT * FROM emp WHERE ename = 'a' es| ",
        // A LIKE in a *different* predicate (across an AND) does not carry over.
        "SELECT * FROM emp WHERE ename LIKE 'a%' AND empno es| ",
        // A LIKE buried in a deeper paren level does not count.
        "SELECT * FROM emp WHERE upper(ename) es| ",
    ] {
        let s = suggestions(sql);
        assert!(
            !has(&s, "ESCAPE"),
            "ESCAPE leaked without a LIKE pattern for `{sql}`: {s:?}"
        );
    }

    // Right after a LIKE pattern → ESCAPE is grammatical.
    for sql in [
        "SELECT * FROM emp WHERE ename LIKE 'a%' es| ",
        "SELECT * FROM emp WHERE ename NOT LIKE 'a%' es| ",
        "SELECT * FROM emp WHERE empno = 1 AND ename LIKE 'a%' es| ",
    ] {
        let s = suggestions(sql);
        assert!(
            has(&s, "ESCAPE"),
            "ESCAPE suppressed after a LIKE pattern for `{sql}`: {s:?}"
        );
    }

    // `ESCAPE` is single-use: once the owning LIKE already carries an escape
    // clause (the keyword awaiting its char, or complete) it must not be
    // re-offered. The next legal continuation is the predicate/clause tail, not
    // another ESCAPE.
    for sql in [
        "SELECT * FROM emp WHERE ename LIKE 'a%' ESCAPE '\\' es| ",
        "SELECT * FROM emp WHERE ename NOT LIKE 'a%' ESCAPE '\\' es| ",
        "SELECT * FROM emp WHERE empno = 1 AND ename LIKE 'a%' ESCAPE '\\' es| ",
        // Cursor right after the ESCAPE keyword expects the escape *char*, not the
        // keyword again.
        "SELECT * FROM emp WHERE ename LIKE 'a%' ESCAPE es| ",
    ] {
        let s = suggestions(sql);
        assert!(
            !has(&s, "ESCAPE"),
            "single-use ESCAPE re-offered for `{sql}`: {s:?}"
        );
    }

    for sql in [
        "SELECT * FROM emp WHERE ename LIKE 'a%' |",
        "SELECT * FROM emp WHERE ename NOT LIKE 'a%' |",
        "SELECT * FROM emp WHERE ename LIKE 'a%' ESCAPE '\\' |",
        "SELECT * FROM emp WHERE empno = 1 AND ename LIKE 'a%' ESCAPE '\\' |",
    ] {
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "completed LIKE predicate should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            has(&final_suggestions, "AND") || has(&final_suggestions, "OR"),
            "completed LIKE predicate lost boolean continuation at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in ["EMP", "DEPT", "EMP_V", "EMPNO", "ENAME", "SAL", "RUN_JOB"] {
            assert!(
                !has(&final_suggestions, leaked),
                "{leaked} leaked after completed LIKE predicate at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
}

/// The single-use postfix operators `COLLATE` (character), `AT [TIME ZONE|LOCAL]`
/// (datetime) and MySQL `SOUNDS LIKE` are grammatical at most once per operand
/// chain. Each must be offered on a fresh operand but never re-offered once
/// already applied — the same single-use principle as `ESCAPE` after a `LIKE`
/// pattern, here at the operand-operator level. An operator bound to an *earlier*
/// operand (before a comparison/arithmetic boundary) must not suppress it on a new
/// operand.
#[test]
fn single_use_postfix_operators_are_not_re_offered() {
    fn suggestions(sql_with_cursor: &str, db: crate::db::DatabaseType) -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(db),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(db),
            expr_keyword_ctx,
        )
    }
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    // First-offer on a fresh operand of the matching type: still offered.
    assert!(has(
        &suggestions("SELECT * FROM t WHERE 'lit' c| ", Oracle),
        "COLLATE"
    ));
    for db in [MySQL, MariaDB] {
        assert!(
            has(&suggestions("SELECT * FROM t WHERE a s| ", db), "SOUNDS"),
            "SOUNDS missing for {db:?}"
        );
    }
    assert!(has(
        &suggestions("SELECT * FROM t WHERE ts a| ", Oracle),
        "AT"
    ));

    assert!(has(
        &suggestions("SELECT * FROM t WHERE x m| ", Oracle),
        "MEMBER"
    ));

    // Re-offer once already applied to the operand chain: suppressed.
    for (sql, db, kw) in [
        (
            "SELECT * FROM t WHERE 'lit' COLLATE my_coll c| ",
            Oracle,
            "COLLATE",
        ),
        (
            "SELECT * FROM t WHERE a SOUNDS LIKE 'b' s| ",
            MySQL,
            "SOUNDS",
        ),
        (
            "SELECT * FROM t WHERE a SOUNDS LIKE 'b' s| ",
            MariaDB,
            "SOUNDS",
        ),
        ("SELECT * FROM t WHERE ts AT TIME ZONE tz a| ", Oracle, "AT"),
        ("SELECT * FROM t WHERE ts AT LOCAL a| ", Oracle, "AT"),
        (
            "SELECT * FROM t WHERE x MEMBER OF coll m| ",
            Oracle,
            "MEMBER",
        ),
    ] {
        let s = suggestions(sql, db);
        assert!(
            !has(&s, kw),
            "single-use {kw} re-offered for `{sql}`: {s:?}"
        );
    }

    // An operator on an *earlier* operand (before a `=` boundary) does not
    // suppress it on the fresh right-hand operand.
    assert!(
        has(
            &suggestions("SELECT * FROM t WHERE 'x' COLLATE c1 = 'y' c| ", Oracle),
            "COLLATE"
        ),
        "COLLATE wrongly suppressed on a fresh operand by an earlier operand's COLLATE"
    );

    // The suppression must also survive the *full* completion pipeline, not just
    // the `base_suggestions_for_context` stage probed above: a later merge stage
    // (expected keywords, wildcards, derived columns, context names) must not
    // re-introduce a spent postfix operator. `audit_final_suggestions_for`
    // reconstructs the production merge order, so a regression that re-offers the
    // keyword downstream of the base catalog is caught here. (Mirrors the
    // end-to-end tail of `escape_offered_only_after_a_like_pattern`.)
    for (sql, db, kw) in [
        (
            "SELECT * FROM t WHERE 'lit' COLLATE my_coll c| ",
            Oracle,
            "COLLATE",
        ),
        (
            "SELECT * FROM t WHERE a SOUNDS LIKE 'b' s| ",
            MySQL,
            "SOUNDS",
        ),
        (
            "SELECT * FROM t WHERE a SOUNDS LIKE 'b' s| ",
            MariaDB,
            "SOUNDS",
        ),
        ("SELECT * FROM t WHERE ts AT TIME ZONE tz a| ", Oracle, "AT"),
        (
            "SELECT * FROM t WHERE x MEMBER OF coll m| ",
            Oracle,
            "MEMBER",
        ),
    ] {
        let (_kind, _keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert!(
            !has(&final_suggestions, kw),
            "single-use {kw} re-offered through the full merge pipeline for `{sql}`: {final_suggestions:?}"
        );
    }
}

/// Set-quantifiers are grammatical only at the start of a select list, aggregate
/// argument, or set-operation branch. Quantified-comparison keywords (`ALL`/
/// `ANY`/`SOME`) are separate: they follow a comparison operator (`x = ANY
/// (...)`), never a random operand-start.
#[test]
fn set_quantifiers_offered_only_at_a_list_or_aggregate_anchor() {
    fn suggestions(sql_with_cursor: &str) -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string()];
        data.set_columns_for_table("EMP", vec!["ENAME".to_string(), "EMPNO".to_string()]);
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(crate::db::DatabaseType::Oracle),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(crate::db::DatabaseType::Oracle),
            expr_keyword_ctx,
        )
    }
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    // General operand positions: set/quantified-comparison keywords are noise.
    // The opening `(` cases are *grouping/predicate* parens, not aggregate-call
    // parens, so the quantifier must not be offered just because the previous
    // token is `(`.
    for sql in [
        "SELECT * FROM emp WHERE empno = dis|",
        "SELECT empno + dis| FROM emp",
        "SELECT nvl(empno, dis| FROM emp",
        "SELECT ename, dis| FROM emp",
        "SELECT * FROM emp WHERE empno = uni|",
        "SELECT an| FROM emp",
        "SELECT so| FROM emp",
        "SELECT empno + al| FROM emp",
        "SELECT (dis| FROM emp",
        "SELECT (empno + 1) * (dis| FROM emp",
        "SELECT * FROM emp WHERE (dis|",
    ] {
        let s = suggestions(sql);
        assert!(
            !has(&s, "DISTINCT"),
            "DISTINCT leaked into a general operand for `{sql}`: {s:?}"
        );
        assert!(
            !has(&s, "UNIQUE"),
            "UNIQUE leaked into a general operand for `{sql}`: {s:?}"
        );
        assert!(
            !has(&s, "ANY"),
            "ANY leaked into a general operand for `{sql}`: {s:?}"
        );
        assert!(
            !has(&s, "SOME"),
            "SOME leaked into a general operand for `{sql}`: {s:?}"
        );
        assert!(
            !has(&s, "ALL"),
            "ALL leaked into a general operand for `{sql}`: {s:?}"
        );
    }

    // List / aggregate / set-operation anchors: set quantifiers are grammatical.
    for sql in [
        "SELECT dis| FROM emp",
        "SELECT al| FROM emp",
        "SELECT count(dis| FROM emp",
        "SELECT count(al| FROM emp",
        "SELECT empno FROM emp UNION dis|",
        "SELECT empno FROM emp UNION al|",
    ] {
        let s = suggestions(sql);
        if sql.contains("dis|") {
            assert!(
                has(&s, "DISTINCT"),
                "DISTINCT suppressed at a valid anchor for `{sql}`: {s:?}"
            );
        } else {
            assert!(
                has(&s, "ALL"),
                "ALL suppressed at a valid anchor for `{sql}`: {s:?}"
            );
        }
    }

    // `ALL`/`ANY`/`SOME` remain available as quantified comparisons after a
    // comparison operator.
    let s = suggestions("SELECT * FROM emp WHERE empno = an|");
    assert!(
        has(&s, "ANY"),
        "ANY wrongly suppressed in a quantified comparison: {s:?}"
    );
    let s = suggestions("SELECT * FROM emp WHERE empno <> so|");
    assert!(
        has(&s, "SOME"),
        "SOME wrongly suppressed in a quantified comparison: {s:?}"
    );
    let s = suggestions("SELECT * FROM emp WHERE empno = al|");
    assert!(
        has(&s, "ALL"),
        "ALL wrongly suppressed in a quantified comparison: {s:?}"
    );
}

#[test]
fn query_set_operator_slots_use_full_statement_tail() {
    let kw = |sql: &str, prefix: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let suppresses = |sql: &str, exclude_current_identifier_chain: bool| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(
            &analyze_inline_cursor_sql(sql),
            exclude_current_identifier_chain,
        )
    };
    let base = |sql_with_cursor: &str| {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        if SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
            &ctx,
            !prefix.is_empty(),
            Some(crate::db::DatabaseType::Oracle),
        ) {
            return Vec::new();
        }
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP_T".to_string()];
        data.procedures = vec!["EMP_PROC".to_string()];
        data.functions = vec!["EMP_FN".to_string()];
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(crate::db::DatabaseType::Oracle),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(crate::db::DatabaseType::Oracle),
            expr_keyword_ctx,
        )
    };
    let has = |suggestions: &[String], value: &str| {
        suggestions
            .iter()
            .any(|suggestion| suggestion.eq_ignore_ascii_case(value))
    };

    assert_eq!(
        kw("SELECT empno FROM emp UNION |", ""),
        vec!["SELECT".to_string(), "ALL".to_string()]
    );
    assert_eq!(
        kw("SELECT empno FROM emp UNION ALL |", ""),
        vec!["SELECT".to_string()]
    );
    assert_eq!(
        kw("SELECT empno FROM emp INTERSECT |", ""),
        vec!["SELECT".to_string(), "ALL".to_string()]
    );
    assert_eq!(
        kw("SELECT empno FROM emp UNION al|", "al"),
        vec!["ALL".to_string()]
    );

    for sql in [
        "SELECT empno FROM emp UNION |",
        "SELECT empno FROM emp UNION ALL |",
        "SELECT empno FROM emp UNION al|",
    ] {
        let exclude_current_identifier_chain = sql.contains("al|");
        assert!(
            suppresses(sql, exclude_current_identifier_chain),
            "query set-operator slot should suppress identifier base for `{sql}`"
        );
    }

    for sql in [
        "SELECT empno FROM emp UNION |",
        "SELECT empno FROM emp UNION ALL |",
    ] {
        let suggestions = kw(sql, "");
        for leaked in [
            "WITH", "INSERT", "UPDATE", "DELETE", "MERGE", "CREATE", "ALTER", "DROP",
        ] {
            assert!(
                !suggestions.iter().any(|value| value == leaked),
                "{leaked} leaked as a statement-start keyword after a query set operator for `{sql}`: {suggestions:?}"
            );
        }
    }

    for (sql, leaked) in [
        ("SELECT empno FROM emp UNION DELETE |", "FROM"),
        ("SELECT empno FROM emp UNION INSERT |", "INTO"),
        ("SELECT empno FROM emp UNION CREATE |", "TABLE"),
        ("SELECT empno FROM emp UNION DROP |", "TABLE"),
    ] {
        let suggestions = kw(sql, "");
        assert!(
            !suggestions.iter().any(|value| value == leaked),
            "{leaked} leaked from a statement-head lookalike after a query set operator for `{sql}`: {suggestions:?}"
        );
        assert!(
            suppresses(sql, false),
            "statement-head lookalike after a query set operator should suppress identifier base for `{sql}`"
        );
    }

    for sql in [
        "SELECT empno FROM emp UNION DROP TABLE emp|",
        "SELECT empno FROM emp UNION CALL emp|",
        "SELECT empno FROM emp UNION GRANT SELECT ON emp|",
    ] {
        let suggestions = base(sql);
        for leaked in ["EMP_T", "EMP_PROC", "EMP_FN"] {
            assert!(
                !has(&suggestions, leaked),
                "{leaked} leaked from the base catalog after a query set operator for `{sql}`: {suggestions:?}"
            );
        }
    }
}

#[test]
fn multiset_operators_do_not_trigger_query_set_operator_continuations() {
    let kw = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let suppresses_columns = |sql: &str| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(
            &analyze_inline_cursor_sql(sql),
            false,
        )
    };
    let base = |sql_with_cursor: &str| {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["T".to_string()];
        data.set_columns_for_table(
            "T",
            vec![
                "CHILD_NT".to_string(),
                "PARENT_NT".to_string(),
                "ELEM".to_string(),
                "TXT_COL".to_string(),
            ],
        );
        data.set_column_meta_for_table(
            "T",
            HashMap::from([
                (
                    "CHILD_NT".to_string(),
                    ColumnMeta {
                        type_display: "NESTED TABLE OF NUMBER".to_string(),
                        nullable: true,
                        is_primary_key: false,
                    },
                ),
                (
                    "PARENT_NT".to_string(),
                    ColumnMeta {
                        type_display: "NESTED TABLE OF NUMBER".to_string(),
                        nullable: true,
                        is_primary_key: false,
                    },
                ),
                (
                    "ELEM".to_string(),
                    ColumnMeta {
                        type_display: "NUMBER".to_string(),
                        nullable: true,
                        is_primary_key: false,
                    },
                ),
                (
                    "TXT_COL".to_string(),
                    ColumnMeta {
                        type_display: "VARCHAR2(20)".to_string(),
                        nullable: true,
                        is_primary_key: false,
                    },
                ),
            ]),
        );
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(crate::db::DatabaseType::Oracle),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(crate::db::DatabaseType::Oracle),
            expr_keyword_ctx,
        )
    };
    let has = |suggestions: &[String], keyword: &str| {
        suggestions
            .iter()
            .any(|value| value.eq_ignore_ascii_case(keyword))
    };

    for sql in [
        "SELECT child_nt MULTISET EXCEPT | parent_nt FROM t",
        "SELECT child_nt MULTISET UNION | parent_nt FROM t",
        "SELECT child_nt MULTISET INTERSECT | parent_nt FROM t",
        "SELECT child_nt MULTISET EXCEPT ALL | parent_nt FROM t",
        "SELECT child_nt MULTISET UNION DISTINCT | parent_nt FROM t",
    ] {
        let suggestions = kw(sql);
        assert!(
            !suggestions.iter().any(|value| value == "SELECT"),
            "query SELECT continuation leaked after a MULTISET operator for `{sql}`: {suggestions:?}"
        );
        assert!(
            !suppresses_columns(sql),
            "MULTISET operator expression slot should not suppress identifiers for `{sql}`"
        );
    }

    for sql in [
        "SELECT child_nt MULTISET EXCEPT un| parent_nt FROM t",
        "SELECT child_nt MULTISET UNION un| parent_nt FROM t",
        "SELECT child_nt MULTISET INTERSECT un| parent_nt FROM t",
    ] {
        let suggestions = base(sql);
        assert!(
            !has(&suggestions, "UNIQUE"),
            "select-list UNIQUE leaked after a MULTISET operator for `{sql}`: {suggestions:?}"
        );
    }

    for (sql, keyword) in [
        ("SELECT child_nt MULTISET UNION al| parent_nt FROM t", "ALL"),
        (
            "SELECT child_nt MULTISET UNION dis| parent_nt FROM t",
            "DISTINCT",
        ),
    ] {
        let suggestions = base(sql);
        assert!(
            has(&suggestions, keyword),
            "{keyword} was suppressed after a MULTISET operator for `{sql}`: {suggestions:?}"
        );
    }

    for sql in [
        "SELECT child_nt MULTISET EXCEPT | FROM t",
        "SELECT child_nt MULTISET UNION ALL | FROM t",
        "SELECT child_nt MULTISET INTERSECT DISTINCT | FROM t",
    ] {
        let suggestions = base(sql);
        assert!(
            has(&suggestions, "PARENT_NT") && has(&suggestions, "CHILD_NT"),
            "MULTISET RHS lost collection columns for `{sql}`: {suggestions:?}"
        );
        assert!(
            !has(&suggestions, "ELEM") && !has(&suggestions, "TXT_COL"),
            "non-collection columns leaked into MULTISET RHS for `{sql}`: {suggestions:?}"
        );
    }
    let prefixed = base("SELECT child_nt MULTISET EXCEPT par| FROM t");
    assert_eq!(
        prefixed,
        vec!["PARENT_NT".to_string()],
        "MULTISET RHS prefix should keep only matching collection columns"
    );
}

/// `EMP` with a typed schema (`ENAME` character, `EMPNO` numeric, `HIREDATE`
/// datetime) so context-dependent keyword gating can be exercised end to end.
fn typed_emp_suggestions(sql_with_cursor: &str) -> Vec<String> {
    typed_emp_suggestions_for_db(sql_with_cursor, crate::db::DatabaseType::Oracle)
}

fn typed_emp_suggestions_for_db(
    sql_with_cursor: &str,
    db_type: crate::db::DatabaseType,
) -> Vec<String> {
    let cursor = sql_with_cursor.find('|').expect("cursor marker");
    let sql = sql_with_cursor.replace('|', "");
    let ctx = analyze_inline_cursor_sql(sql_with_cursor);
    let context =
        SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
    let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
    let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
    let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
    let mut data = IntellisenseData::new();
    data.tables = vec!["EMP".to_string()];
    data.set_columns_for_table(
        "EMP",
        vec![
            "ENAME".to_string(),
            "EMPNO".to_string(),
            "HIREDATE".to_string(),
        ],
    );
    let meta = HashMap::from([
        (
            "ENAME".to_string(),
            ColumnMeta {
                type_display: "VARCHAR2(10)".to_string(),
                nullable: true,
                is_primary_key: false,
            },
        ),
        (
            "EMPNO".to_string(),
            ColumnMeta {
                type_display: "NUMBER(4)".to_string(),
                nullable: false,
                is_primary_key: true,
            },
        ),
        (
            "HIREDATE".to_string(),
            ColumnMeta {
                type_display: "DATE".to_string(),
                nullable: true,
                is_primary_key: false,
            },
        ),
    ]);
    data.set_column_meta_for_table("EMP", meta);
    data.rebuild_indices();
    let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
        &ctx,
        &data,
        &column_tables,
        !prefix.is_empty(),
        Some(db_type),
    );
    let at_keyword_only_slot = SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
        &ctx,
        !prefix.is_empty(),
        Some(db_type),
    );
    if at_keyword_only_slot {
        return Vec::new();
    }
    let at_keyword_only_identifier_slot =
        SqlEditorWidget::cursor_is_at_identifier_suppressing_keyword_slot_for_context(
            &ctx,
            !prefix.is_empty(),
            Some(db_type),
        );
    let mut suggestions = SqlEditorWidget::base_suggestions_for_context(
        &mut data,
        &prefix,
        None,
        column_scope.as_deref(),
        matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
        context,
        false,
        Some(db_type),
        expr_keyword_ctx,
    );
    let context_name_policy = CompletionSourcePolicy::new(
        false,
        at_keyword_only_identifier_slot,
        at_keyword_only_slot,
        false,
        false,
        expr_keyword_ctx,
    );
    let context_name_suggestions =
        if context_name_policy.suppresses_context_names(context, expr_keyword_ctx) {
            Vec::new()
        } else {
            SqlEditorWidget::collect_context_name_suggestions(&prefix, &ctx, context)
        };
    suggestions = SqlEditorWidget::maybe_merge_suggestions_with_context_aliases(
        suggestions,
        context_name_suggestions,
        matches!(context, SqlContext::TableName),
        false,
    );
    suggestions
}

/// Hierarchical pseudo-columns/operators (`LEVEL`, `PRIOR`, `CONNECT_BY_ROOT`,
/// `CONNECT_BY_ISCYCLE`, `CONNECT_BY_ISLEAF`) are grammatical only in a query that
/// has a `CONNECT BY` clause. `ROWNUM` stays valid everywhere.
#[test]
fn hierarchical_keywords_offered_only_in_a_connect_by_query() {
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    // No CONNECT BY → hierarchical keywords are noise.
    for (sql, kw) in [
        ("SELECT lev| FROM emp", "LEVEL"),
        ("SELECT * FROM emp WHERE empno = lev|", "LEVEL"),
        ("SELECT conn| FROM emp", "CONNECT_BY_ROOT"),
    ] {
        let s = typed_emp_suggestions(sql);
        assert!(
            !has(&s, kw),
            "{kw} leaked outside a CONNECT BY query for `{sql}`: {s:?}"
        );
    }

    // With CONNECT BY → grammatical.
    for (sql, kw) in [
        (
            "SELECT lev| FROM emp CONNECT BY PRIOR empno = empno",
            "LEVEL",
        ),
        ("SELECT empno FROM emp CONNECT BY pri|", "PRIOR"),
        (
            "SELECT conn| FROM emp CONNECT BY PRIOR empno = empno",
            "CONNECT_BY_ROOT",
        ),
    ] {
        let s = typed_emp_suggestions(sql);
        assert!(
            has(&s, kw),
            "{kw} suppressed inside a CONNECT BY query for `{sql}`: {s:?}"
        );
    }

    // ROWNUM stays valid without CONNECT BY.
    let s = typed_emp_suggestions("SELECT * FROM emp WHERE rown| = 1");
    assert!(has(&s, "ROWNUM"), "ROWNUM wrongly suppressed: {s:?}");

    // A `CONNECT BY` clause belongs to its own query level: one nested inside a
    // subquery (`… IN (SELECT … CONNECT BY …)`) must not make the hierarchical
    // keywords grammatical in the *outer* query, whose select list / predicates
    // have no `CONNECT BY` of their own.
    for (sql, kw) in [
        (
            "SELECT lev| FROM emp WHERE empno IN (SELECT empno FROM emp CONNECT BY PRIOR empno = empno)",
            "LEVEL",
        ),
        (
            "SELECT conn| FROM emp WHERE empno IN (SELECT empno FROM emp CONNECT BY PRIOR empno = empno)",
            "CONNECT_BY_ROOT",
        ),
        (
            "SELECT empno FROM emp WHERE empno IN (SELECT empno FROM emp CONNECT BY PRIOR empno = empno) AND empno = pri|",
            "PRIOR",
        ),
    ] {
        let s = typed_emp_suggestions(sql);
        assert!(
            !has(&s, kw),
            "{kw} leaked from a nested CONNECT BY subquery into the outer query for `{sql}`: {s:?}"
        );
    }
}

/// The `DEFAULT` value keyword is grammatical only in a DML value position
/// (`INSERT … VALUES (…)`, `UPDATE … SET col = …`), never in a query expression.
#[test]
fn default_value_keyword_offered_only_in_dml_value_positions() {
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    for sql in [
        "UPDATE emp SET ename = def|",
        "INSERT INTO emp VALUES (def|",
    ] {
        let s = typed_emp_suggestions(sql);
        assert!(
            has(&s, "DEFAULT"),
            "DEFAULT suppressed in a DML value position for `{sql}`: {s:?}"
        );
    }
    for sql in [
        "SELECT def| FROM emp",
        "SELECT * FROM emp WHERE empno = def|",
    ] {
        let s = typed_emp_suggestions(sql);
        assert!(
            !has(&s, "DEFAULT"),
            "DEFAULT leaked into a query expression for `{sql}`: {s:?}"
        );
    }
}

/// The operand-type postfix operators are gated on the inferred type of the
/// preceding operand: `AT` (`… AT TIME ZONE`) needs a datetime, `COLLATE` a
/// character value. After an operand of the wrong type — or one whose type is
/// unknown — they are withheld.
#[test]
fn operand_type_operators_match_the_preceding_operand_type() {
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));
    let kw = |sql: &str| {
        let cursor = sql.find('|').expect("cursor marker");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let suppresses = |sql: &str, db_type| {
        let cursor = sql.find('|').expect("cursor marker");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
            &analyze_inline_cursor_sql(sql),
            !prefix.is_empty(),
            Some(db_type),
        )
    };

    // AT after a datetime operand (column, literal, or niladic function).
    for sql in [
        "SELECT * FROM emp WHERE hiredate a|",
        "SELECT sysdate a| FROM emp",
        "SELECT DATE '2020-01-01' a| FROM emp",
        "SELECT TIMESTAMP(6) '2020-01-01 10:00:00' a| FROM emp",
        "SELECT TIMESTAMP WITH TIME ZONE '2020-01-01 10:00:00 UTC' a| FROM emp",
        "SELECT TIMESTAMP(6) WITH TIME ZONE '2020-01-01 10:00:00 UTC' a| FROM emp",
        "SELECT TIMESTAMP WITH LOCAL TIME ZONE '2020-01-01 10:00:00' a| FROM emp",
        "SELECT TIME(3) WITH TIME ZONE '10:00:00 UTC' a| FROM emp",
    ] {
        let s = typed_emp_suggestions(sql);
        assert!(
            has(&s, "AT"),
            "AT suppressed after a datetime operand for `{sql}`: {s:?}"
        );
    }
    // AT after a non-datetime operand is noise.
    for sql in [
        "SELECT * FROM emp WHERE empno a|",
        "SELECT ename a| FROM emp",
        "SELECT 'x' a| FROM emp",
        "SELECT X'ABCD' a| FROM emp",
        "SELECT B'1010' a| FROM emp",
        "SELECT LENGTH(ename) a| FROM emp",
        "SELECT DATEDIFF(hiredate, hiredate) a| FROM emp",
        "SELECT (empno) a| FROM emp",
        "SELECT ((empno)) a| FROM emp",
        "SELECT CAST(ename AS NUMBER) a| FROM emp",
        "SELECT JSON_VALUE(ename, '$.n' RETURNING NUMBER) a| FROM emp",
        "SELECT INTERVAL '1' DAY a| FROM emp",
        "SELECT INTERVAL '1' DAY(2) a| FROM emp",
        "SELECT INTERVAL '1-2' YEAR TO MONTH a| FROM emp",
        "SELECT INTERVAL '1 02:03:04.5' DAY(2) TO SECOND(6) a| FROM emp",
        "SELECT TRUE a| FROM emp",
        "SELECT FALSE a| FROM emp",
        "SELECT UNKNOWN a| FROM emp",
        "SELECT ROUND(empno) a| FROM emp",
        "SELECT TRUNC(empno) a| FROM emp",
        "SELECT COALESCE(empno, 0) a| FROM emp",
        "SELECT COALESCE(NULL, empno) a| FROM emp",
        "SELECT NVL2(ename, empno, 0) a| FROM emp",
        "SELECT LAG(empno) a| FROM emp",
        "SELECT CASE WHEN empno = 1 THEN empno ELSE 0 END a| FROM emp",
        "SELECT CASE ename WHEN 'A' THEN empno ELSE 0 END a| FROM emp",
    ] {
        let s = typed_emp_suggestions(sql);
        assert!(
            !has(&s, "AT"),
            "AT leaked after a non-datetime operand for `{sql}`: {s:?}"
        );
    }

    // COLLATE after a character operand only.
    let s = typed_emp_suggestions("SELECT ename col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a character operand: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT N'abc' col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a national character literal: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT empno col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a numeric operand: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT X'ABCD' col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a hex string literal: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT B'1010' col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a bit string literal: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT (empno) col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a parenthesized numeric operand: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT LENGTH(ename) col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a numeric function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT CAST(ename AS NUMBER) col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a numeric CAST: {s:?}"
    );
    let s = typed_emp_suggestions(
        "SELECT JSON_VALUE(ename, '$.n' RETURNING NUMBER DEFAULT 0 ON ERROR NULL ON EMPTY) col| FROM emp",
    );
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a numeric JSON RETURNING function: {s:?}"
    );
    use crate::db::DatabaseType::{MariaDB, MySQL};

    for db in [MySQL, MariaDB] {
        let s = typed_emp_suggestions_for_db("SELECT CAST(ename AS SIGNED) col| FROM emp", db);
        assert!(
            !has(&s, "COLLATE"),
            "COLLATE leaked after a numeric CAST on {db:?}: {s:?}"
        );
    }
    let s = typed_emp_suggestions("SELECT ROUND(empno) col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a numeric overloaded function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT COALESCE(empno, 0) col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a numeric polymorphic function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT NVL(NULL, empno) col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a NULL-leading numeric polymorphic function: {s:?}"
    );
    let s =
        typed_emp_suggestions("SELECT CASE WHEN empno = 1 THEN NULL ELSE empno END col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a numeric CASE expression: {s:?}"
    );
    let s = typed_emp_suggestions(
        "SELECT CASE WHEN empno = 1 THEN CASE WHEN empno = 2 THEN empno ELSE 0 END ELSE empno END col| FROM emp",
    );
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a nested numeric CASE expression: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT NVL2(ename, empno, 0) col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a numeric polymorphic function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT LAG(empno) col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a numeric analytic function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT hiredate col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a datetime operand: {s:?}"
    );
    let s = typed_emp_suggestions(
        "SELECT TIMESTAMP WITH TIME ZONE '2020-01-01 10:00:00 UTC' col| FROM emp",
    );
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a TIMESTAMP WITH TIME ZONE literal: {s:?}"
    );
    let s = typed_emp_suggestions(
        "SELECT TIMESTAMP(6) WITH TIME ZONE '2020-01-01 10:00:00 UTC' col| FROM emp",
    );
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a TIMESTAMP precision WITH TIME ZONE literal: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT TIME WITH TIME ZONE '10:00:00 UTC' col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a TIME WITH TIME ZONE literal: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT TIME(3) WITH TIME ZONE '10:00:00 UTC' col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a TIME precision WITH TIME ZONE literal: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT INTERVAL '1' DAY col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after an interval literal: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT INTERVAL '1' DAY(2) col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after an interval literal with leading precision: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT TRUE col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after TRUE literal: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT FALSE col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after FALSE literal: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT UNKNOWN col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after UNKNOWN literal: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT INTERVAL '1-2' YEAR TO MONTH col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a compound interval literal: {s:?}"
    );
    let s =
        typed_emp_suggestions("SELECT INTERVAL '1 02:03:04.5' DAY(2) TO SECOND(6) col| FROM emp");
    assert!(
        !has(&s, "COLLATE"),
        "COLLATE leaked after a compound interval literal with precision: {s:?}"
    );
    for db in [MySQL, MariaDB] {
        let s = typed_emp_suggestions_for_db("SELECT INTERVAL 1 DAY col| FROM emp", db);
        assert!(
            !has(&s, "COLLATE"),
            "COLLATE leaked after an interval expression on {db:?}: {s:?}"
        );
    }
    let s = typed_emp_suggestions("SELECT (hiredate) a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT suppressed after a parenthesized datetime operand: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT CAST(ename AS DATE) a| FROM emp");
    assert!(has(&s, "AT"), "AT suppressed after a datetime CAST: {s:?}");
    let s = typed_emp_suggestions("SELECT JSON_VALUE(ename, '$.d' RETURNING DATE) a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT suppressed after a datetime JSON RETURNING function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT XMLCAST(ename AS TIMESTAMP) a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT suppressed after a datetime XMLCAST: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT DATE_ADD(hiredate, INTERVAL 1 DAY) a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT suppressed after a datetime function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT ROUND(hiredate) a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT suppressed after a datetime overloaded function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT TRUNC(hiredate) a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT suppressed after a datetime overloaded function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT COALESCE(hiredate, sysdate) a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT suppressed after a datetime polymorphic function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT COALESCE(NULL, hiredate) a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT suppressed after a NULL-leading datetime polymorphic function: {s:?}"
    );
    let s =
        typed_emp_suggestions("SELECT CASE WHEN empno = 1 THEN NULL ELSE hiredate END a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT suppressed after a datetime CASE expression: {s:?}"
    );
    let s = typed_emp_suggestions(
        "SELECT CASE ename WHEN 'A' THEN hiredate ELSE sysdate END a| FROM emp",
    );
    assert!(
        has(&s, "AT"),
        "AT suppressed after a simple datetime CASE expression: {s:?}"
    );
    let s = typed_emp_suggestions(
        "SELECT CASE WHEN empno = 1 THEN CASE WHEN empno = 2 THEN hiredate ELSE sysdate END ELSE hiredate END a| FROM emp",
    );
    assert!(
        has(&s, "AT"),
        "AT suppressed after a nested datetime CASE expression: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT NVL2(ename, hiredate, sysdate) a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT suppressed after a datetime polymorphic function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT FIRST_VALUE(hiredate) a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT suppressed after a datetime analytic function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT DATE_FORMAT(hiredate, '%Y') col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a character function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT COALESCE(ename, 'x') col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a character polymorphic function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT COALESCE(NULL, ename) col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a NULL-leading character polymorphic function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT (ename) col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a parenthesized character operand: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT CAST(empno AS VARCHAR2(20)) col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a character CAST: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT JSON_QUERY(ename, '$' RETURNING CLOB) col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a character JSON RETURNING function: {s:?}"
    );
    let s = typed_emp_suggestions(
        "SELECT JSON_OBJECT(KEY ename VALUE empno RETURNING CLOB) col| FROM emp",
    );
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a character JSON object function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT XMLSERIALIZE(DOCUMENT ename AS CLOB) col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a character XMLSERIALIZE: {s:?}"
    );
    let s =
        typed_emp_suggestions("SELECT CASE WHEN empno = 1 THEN ename ELSE 'x' END col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a character CASE expression: {s:?}"
    );
    let s =
        typed_emp_suggestions("SELECT CASE ename WHEN 'A' THEN ename ELSE 'x' END col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a simple character CASE expression: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT NVL2(empno, ename, 'x') col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a character polymorphic function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT LAG(ename) col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE suppressed after a character analytic function: {s:?}"
    );

    // When the operand's type cannot be resolved (an unknown identifier, not an
    // in-scope typed column) the operators are kept — a provable mismatch is
    // required to suppress, so a valid completion is never hidden.
    let s = typed_emp_suggestions("SELECT unknown_col a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT wrongly suppressed after an unknown operand: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT unknown_col col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE wrongly suppressed after an unknown operand: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT ROUND(unknown_col) a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT wrongly suppressed after an unknown overloaded function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT ROUND(unknown_col) col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE wrongly suppressed after an unknown overloaded function: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT NVL2(ename, unknown_col, empno) col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE wrongly suppressed after an unknown polymorphic return: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT COALESCE(unknown_col, empno) col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE wrongly suppressed after an unknown-leading polymorphic return: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT CAST(empno AS employee_t) col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE wrongly suppressed after an unknown CAST target: {s:?}"
    );
    let s =
        typed_emp_suggestions("SELECT JSON_VALUE(ename, '$.x' RETURNING employee_t) col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE wrongly suppressed after an unknown JSON RETURNING target: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT pkg.to_char(empno) col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE wrongly suppressed by treating a qualified call as a parenthesized expression: {s:?}"
    );
    let s = typed_emp_suggestions(
        "SELECT CASE WHEN empno = 1 THEN unknown_col ELSE empno END col| FROM emp",
    );
    assert!(
        has(&s, "COLLATE"),
        "COLLATE wrongly suppressed after an unknown CASE result: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT pkg.to_char() a| FROM emp");
    assert!(
        has(&s, "AT"),
        "AT wrongly suppressed after a qualified call: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT pkg.to_date() col| FROM emp");
    assert!(
        has(&s, "COLLATE"),
        "COLLATE wrongly suppressed after a qualified call: {s:?}"
    );

    // But never at an operand-start (these are postfix operators).
    let s = typed_emp_suggestions("SELECT * FROM emp WHERE empno = a|");
    assert!(!has(&s, "AT"), "AT leaked at an operand-start: {s:?}");

    assert_eq!(
        kw("SELECT * FROM emp WHERE hiredate AT |"),
        vec!["LOCAL".to_string(), "TIME".to_string()]
    );
    assert_eq!(
        kw("SELECT * FROM emp WHERE hiredate AT ti|"),
        vec!["TIME".to_string()]
    );
    assert_eq!(
        kw("SELECT * FROM emp WHERE hiredate AT TIME |"),
        vec!["ZONE".to_string()]
    );
    for sql in [
        "SELECT * FROM emp WHERE hiredate AT |",
        "SELECT * FROM emp WHERE hiredate AT TIME |",
    ] {
        assert!(
            suppresses(sql, crate::db::DatabaseType::Oracle),
            "AT TIME ZONE fixed keyword tail leaked columns for `{sql}`"
        );
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "AT TIME ZONE fixed keyword tail should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        let expected = if sql.contains("AT TIME |") {
            &["ZONE"][..]
        } else {
            &["LOCAL", "TIME"][..]
        };
        for keyword in expected {
            assert!(
                has(&final_suggestions, keyword),
                "{keyword} missing from AT TIME ZONE fixed keyword tail at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        for leaked in ["EMP", "DEPT", "EMP_V", "EMPNO", "ENAME", "HIREDATE"] {
            assert!(
                !has(&final_suggestions, leaked),
                "{leaked} leaked into AT TIME ZONE fixed keyword tail at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
    assert!(
        !suppresses(
            "SELECT * FROM emp WHERE hiredate AT TIME ZONE |",
            crate::db::DatabaseType::Oracle
        ),
        "timezone expression slot after AT TIME ZONE must keep value completion"
    );
    let timezone_value = typed_emp_suggestions("SELECT * FROM emp WHERE hiredate AT TIME ZONE |");
    assert!(
        has(&timezone_value, "ENAME"),
        "AT TIME ZONE expression slot lost character columns: {timezone_value:?}"
    );
    assert!(
        !has(&timezone_value, "EMPNO") && !has(&timezone_value, "HIREDATE"),
        "AT TIME ZONE expression slot leaked non-character columns: {timezone_value:?}"
    );
    for sql in [
        "SELECT * FROM emp WHERE hiredate AT LOCAL |",
        "SELECT * FROM emp WHERE hiredate AT LOCAL n|",
        "SELECT * FROM emp WHERE hiredate AT TIME ZONE tz |",
        "SELECT * FROM emp WHERE hiredate AT TIME ZONE tz n|",
        "SELECT * FROM emp WHERE hiredate AT TIME ZONE 'UTC' |",
        "SELECT * FROM emp WHERE hiredate AT TIME ZONE 'UTC' n|",
        "SELECT * FROM emp WHERE hiredate AT TIME ZONE (tz) |",
        "SELECT * FROM emp WHERE hiredate AT TIME ZONE (tz) n|",
    ] {
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "completed AT TIME ZONE tail should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in ["EMP", "DEPT", "EMP_V", "EMPNO", "ENAME", "HIREDATE"] {
            assert!(
                !has(&final_suggestions, leaked),
                "{leaked} leaked after completed AT TIME ZONE tail at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }

    for sql in [
        "SELECT * FROM emp WHERE | AT TIME ZONE 'UTC'",
        "SELECT * FROM emp WHERE h| AT TIME ZONE 'UTC'",
        "SELECT * FROM emp WHERE | AT LOCAL",
    ] {
        let suggestions = typed_emp_suggestions(sql);
        assert!(
            has(&suggestions, "HIREDATE"),
            "AT TIME ZONE LHS lost datetime columns for `{sql}`: {suggestions:?}"
        );
        assert!(
            !has(&suggestions, "ENAME") && !has(&suggestions, "EMPNO"),
            "AT TIME ZONE LHS leaked non-datetime columns for `{sql}`: {suggestions:?}"
        );
    }
    assert!(
        !suppresses(
            "SELECT * FROM emp WHERE hiredate AT |",
            crate::db::DatabaseType::MySQL
        ),
        "Oracle AT TIME ZONE tail must not become a MySQL keyword-only slot"
    );

    for sql in [
        "SELECT * FROM emp WHERE ename COLLATE |",
        "SELECT * FROM emp WHERE ename COLLATE bin|",
    ] {
        assert!(
            suppresses(sql, crate::db::DatabaseType::Oracle),
            "COLLATE collation-name slot leaked columns for `{sql}`"
        );
        assert!(
            suppresses(sql, crate::db::DatabaseType::MySQL),
            "MySQL COLLATE collation-name slot leaked columns for `{sql}`"
        );
        for db_type in [
            crate::db::DatabaseType::Oracle,
            crate::db::DatabaseType::MySQL,
        ] {
            let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db_type);
            assert_eq!(
                kind, None,
                "COLLATE collation-name slot should not resolve object kind at `{sql}` {db_type:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
            assert!(
                final_suggestions.is_empty(),
                "COLLATE collation-name slot should not offer catalog or keywords at `{sql}` {db_type:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
    for (sql, db_type) in [
        (
            "SELECT * FROM emp WHERE ename COLLATE BINARY_CI |",
            crate::db::DatabaseType::Oracle,
        ),
        (
            "SELECT * FROM emp WHERE ename COLLATE BINARY_CI n|",
            crate::db::DatabaseType::Oracle,
        ),
        (
            "SELECT * FROM emp WHERE ename COLLATE utf8mb4_bin |",
            crate::db::DatabaseType::MySQL,
        ),
        (
            "SELECT * FROM emp WHERE ename COLLATE utf8mb4_bin n|",
            crate::db::DatabaseType::MySQL,
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db_type);
        assert_eq!(
            kind, None,
            "completed COLLATE tail should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in ["EMP", "DEPT", "EMP_V", "EMPNO", "ENAME", "SAL"] {
            assert!(
                !has(&final_suggestions, leaked),
                "{leaked} leaked after completed COLLATE tail at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
    for (sql, db_type) in [
        (
            "SELECT * FROM emp WHERE | COLLATE BINARY_CI",
            crate::db::DatabaseType::Oracle,
        ),
        (
            "SELECT * FROM emp WHERE e| COLLATE BINARY_CI",
            crate::db::DatabaseType::Oracle,
        ),
        (
            "SELECT * FROM emp WHERE | COLLATE utf8mb4_bin",
            crate::db::DatabaseType::MySQL,
        ),
        (
            "SELECT * FROM emp WHERE e| COLLATE utf8mb4_bin",
            crate::db::DatabaseType::MySQL,
        ),
    ] {
        let suggestions = typed_emp_suggestions_for_db(sql, db_type);
        assert!(
            has(&suggestions, "ENAME"),
            "COLLATE LHS lost character columns for `{sql}`: {suggestions:?}"
        );
        assert!(
            !has(&suggestions, "EMPNO") && !has(&suggestions, "HIREDATE"),
            "COLLATE LHS leaked non-character columns for `{sql}`: {suggestions:?}"
        );
    }
    assert!(
        !suppresses("SELECT collate | FROM emp", crate::db::DatabaseType::Oracle),
        "column or alias named COLLATE must not be mistaken for a collation-name slot"
    );
}

#[test]
fn operand_type_inference_caps_deep_call_nesting_and_resets_guard() {
    let depth = MAX_INTELLISENSE_RECURSION_DEPTH * 4;
    let sql = format!("{}1{}", "NVL(".repeat(depth), ", 0)".repeat(depth));
    let tokens = SqlEditorWidget::tokenize_sql(&sql);
    let data = IntellisenseData::new();

    assert_eq!(
        SqlEditorWidget::preceding_operand_type(&tokens, tokens.len(), &data, &[]),
        PrecedingOperandType::Unknown
    );

    let shallow = SqlEditorWidget::tokenize_sql("1");
    assert_eq!(
        SqlEditorWidget::preceding_operand_type(&shallow, shallow.len(), &data, &[]),
        PrecedingOperandType::Numeric
    );
}

#[test]
fn virtual_projection_inference_caps_deep_subqueries_and_resets_guard() {
    let mut sql = "SELECT base_col FROM base_table".to_string();
    for index in 0..MAX_INTELLISENSE_RECURSION_DEPTH * 2 {
        sql = format!("SELECT * FROM ({sql}) q{index}");
    }
    let tokens = SqlEditorWidget::tokenize_sql(&sql);
    let _ = SqlEditorWidget::extract_select_projection_members_and_source(&tokens);

    let shallow = SqlEditorWidget::tokenize_sql("SELECT base_col FROM base_table");
    let (columns, _) = SqlEditorWidget::extract_select_projection_members_and_source(&shallow);
    assert_eq!(columns, vec!["base_col"]);
}

#[test]
fn negated_and_collection_predicate_operators_are_position_aware() {
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    // After a *postfix* `NOT` (`x NOT |`) only the negated predicate operators
    // are grammatical: it is a keyword-only slot, so the operator keywords come
    // from the keyword-emission path while every identifier is suppressed (a
    // column must not leak alongside, e.g. `empno NOT e|` is not a place for
    // `ENAME`).
    let kw = |sql: &str| {
        let cursor = sql.find('|').expect("cursor marker");
        let s = sql.replace('|', "");
        let prefix = crate::ui::intellisense::get_word_at_cursor(&s, cursor).0;
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    for (sql, keyword) in [
        ("SELECT * FROM emp WHERE empno NOT in|", "IN"),
        ("SELECT * FROM emp WHERE ename NOT li|", "LIKE"),
        ("SELECT * FROM emp WHERE empno NOT bet|", "BETWEEN"),
        ("SELECT * FROM emp WHERE empno NOT mem|", "MEMBER OF"),
    ] {
        assert!(
            has(&kw(sql), keyword),
            "{keyword} not offered after postfix NOT for `{sql}`: {:?}",
            kw(sql)
        );
        assert!(
            typed_emp_suggestions(sql).is_empty(),
            "identifier leaked after postfix NOT for `{sql}`: {:?}",
            typed_emp_suggestions(sql)
        );
    }
    for (db, sql, expected, leaked) in [
        (
            crate::db::DatabaseType::Oracle,
            "SELECT * FROM emp WHERE empno NOT i|",
            &["IN"][..],
            &["INTERVAL", "INTO", "EMP", "EMPNO", "ENAME"][..],
        ),
        (
            crate::db::DatabaseType::Oracle,
            "SELECT * FROM emp WHERE ename NOT l|",
            &["LIKE"],
            &["LOCAL", "LOCKED", "EMP", "EMPNO", "ENAME"],
        ),
        (
            crate::db::DatabaseType::Oracle,
            "SELECT * FROM emp WHERE empno NOT b|",
            &["BETWEEN"],
            &["BY", "BINARY", "EMP", "EMPNO", "ENAME"],
        ),
        (
            crate::db::DatabaseType::Oracle,
            "SELECT * FROM emp WHERE empno NOT m|",
            &["MEMBER OF"],
            &["MODEL", "MATCH_RECOGNIZE", "EMP", "EMPNO", "ENAME"],
        ),
        (
            crate::db::DatabaseType::MySQL,
            "SELECT * FROM emp WHERE empno NOT r|",
            &["REGEXP", "RLIKE"],
            &["REQUIRE", "ROLE", "EMP", "EMPNO", "ENAME"],
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert_eq!(
            kind, None,
            "postfix NOT operator slot should not resolve object kind at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
        );
        for keyword in expected {
            assert!(
                has(&keywords, keyword) && has(&final_suggestions, keyword),
                "{keyword} missing from postfix NOT operator slot at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        for item in leaked {
            assert!(
                !has(&keywords, item) && !has(&final_suggestions, item),
                "{item} leaked into postfix NOT operator slot at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
    // The collection `MEMBER` operator after a bare operand (no `NOT`) is an
    // allowlist keyword, not a keyword-only slot, so it flows through the base.
    assert!(
        has(
            &typed_emp_suggestions("SELECT * FROM emp WHERE empno mem|"),
            "MEMBER"
        ),
        "MEMBER suppressed for bare-operand collection predicate"
    );

    for (sql, keyword) in [
        ("SELECT * FROM emp WHERE NOT in|", "IN"),
        ("SELECT * FROM emp WHERE NOT li|", "LIKE"),
        ("SELECT * FROM emp WHERE NOT bet|", "BETWEEN"),
        ("SELECT * FROM emp WHERE NOT mem|", "MEMBER"),
    ] {
        let suggestions = typed_emp_suggestions(sql);
        assert!(
            !has(&suggestions, keyword),
            "{keyword} leaked after unary NOT for `{sql}`: {suggestions:?}"
        );
    }

    let collection_suggestions = |sql_with_cursor: &str| -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["T".to_string()];
        data.set_columns_for_table(
            "T",
            vec![
                "ELEM".to_string(),
                "CHILD_NT".to_string(),
                "PARENT_NT".to_string(),
                "TXT_COL".to_string(),
            ],
        );
        data.set_column_meta_for_table(
            "T",
            HashMap::from([
                (
                    "ELEM".to_string(),
                    ColumnMeta {
                        type_display: "NUMBER".to_string(),
                        nullable: true,
                        is_primary_key: false,
                    },
                ),
                (
                    "CHILD_NT".to_string(),
                    ColumnMeta {
                        type_display: "NESTED TABLE OF NUMBER".to_string(),
                        nullable: true,
                        is_primary_key: false,
                    },
                ),
                (
                    "PARENT_NT".to_string(),
                    ColumnMeta {
                        type_display: "NESTED TABLE OF NUMBER".to_string(),
                        nullable: true,
                        is_primary_key: false,
                    },
                ),
                (
                    "TXT_COL".to_string(),
                    ColumnMeta {
                        type_display: "VARCHAR2(20)".to_string(),
                        nullable: true,
                        is_primary_key: false,
                    },
                ),
            ]),
        );
        data.rebuild_indices();
        let at_keyword_only_slot =
            SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
                &ctx,
                !prefix.is_empty(),
                Some(crate::db::DatabaseType::Oracle),
            );
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(crate::db::DatabaseType::Oracle),
        );
        let mut suggestions = if at_keyword_only_slot {
            Vec::new()
        } else {
            SqlEditorWidget::base_suggestions_for_context(
                &mut data,
                &prefix,
                None,
                column_scope.as_deref(),
                matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
                context,
                false,
                Some(crate::db::DatabaseType::Oracle),
                expr_keyword_ctx,
            )
        };
        for keyword in SqlEditorWidget::collect_expected_keyword_suggestions_with_expression_context(
            &prefix,
            &ctx,
            Some(crate::db::DatabaseType::Oracle),
            Some(expr_keyword_ctx),
        ) {
            if !suggestions
                .iter()
                .any(|value| value.eq_ignore_ascii_case(&keyword))
            {
                suggestions.push(keyword);
            }
        }
        suggestions
    };

    for (sql, keyword) in [
        ("SELECT * FROM t WHERE child_nt sub|", "SUBMULTISET"),
        ("SELECT * FROM t WHERE child_nt |", "SUBMULTISET OF"),
        ("SELECT * FROM t WHERE child_nt NOT sub|", "SUBMULTISET OF"),
        ("SELECT * FROM t WHERE child_nt mul|", "MULTISET"),
    ] {
        let suggestions = collection_suggestions(sql);
        assert!(
            has(&suggestions, keyword),
            "{keyword} suppressed after a collection operand for `{sql}`: {suggestions:?}"
        );
    }
    for (sql, keyword) in [
        ("SELECT * FROM t WHERE elem sub|", "SUBMULTISET"),
        ("SELECT * FROM t WHERE elem |", "SUBMULTISET OF"),
        ("SELECT * FROM t WHERE txt_col mul|", "MULTISET"),
    ] {
        let suggestions = collection_suggestions(sql);
        assert!(
            !has(&suggestions, keyword),
            "{keyword} leaked after a non-collection operand for `{sql}`: {suggestions:?}"
        );
    }

    for sql in [
        "SELECT * FROM t WHERE elem MEMBER | parent_nt",
        "SELECT * FROM t WHERE elem NOT MEMBER | parent_nt",
        "SELECT * FROM t WHERE child_nt SUBMULTISET | parent_nt",
        "SELECT * FROM t WHERE child_nt NOT SUBMULTISET | parent_nt",
    ] {
        assert_eq!(
            collection_suggestions(sql),
            vec!["OF".to_string()],
            "fixed OF continuation for `{sql}`"
        );
    }
    for sql in [
        "SELECT * FROM t WHERE elem MEMBER |",
        "SELECT * FROM t WHERE elem NOT MEMBER |",
        "SELECT * FROM t WHERE child_nt SUBMULTISET |",
        "SELECT * FROM t WHERE child_nt NOT SUBMULTISET |",
    ] {
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "collection fixed OF tail should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            has(&final_suggestions, "OF"),
            "OF missing from collection fixed tail at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "EMPNO",
            "ENAME",
            "CHILD_NT",
            "PARENT_NT",
            "ELEM",
            "TXT_COL",
        ] {
            assert!(
                !has(&final_suggestions, leaked),
                "{leaked} leaked into collection fixed OF tail at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }

    for sql in [
        "SELECT * FROM t WHERE elem MEMBER OF |",
        "SELECT * FROM t WHERE child_nt SUBMULTISET OF |",
    ] {
        let suggestions = collection_suggestions(sql);
        assert!(
            has(&suggestions, "PARENT_NT") && has(&suggestions, "CHILD_NT"),
            "collection RHS slot lost collection columns for `{sql}`: {suggestions:?}"
        );
        assert!(
            !has(&suggestions, "ELEM") && !has(&suggestions, "TXT_COL"),
            "non-collection columns leaked into collection RHS slot for `{sql}`: {suggestions:?}"
        );
    }

    for sql in [
        "SELECT * FROM t WHERE | SUBMULTISET OF parent_nt",
        "SELECT * FROM t WHERE c| SUBMULTISET OF parent_nt",
        "SELECT * FROM t WHERE | NOT SUBMULTISET OF parent_nt",
    ] {
        let suggestions = collection_suggestions(sql);
        assert!(
            has(&suggestions, "CHILD_NT") || has(&suggestions, "PARENT_NT"),
            "SUBMULTISET LHS slot lost collection columns for `{sql}`: {suggestions:?}"
        );
        assert!(
            !has(&suggestions, "ELEM") && !has(&suggestions, "TXT_COL"),
            "non-collection columns leaked into SUBMULTISET LHS slot for `{sql}`: {suggestions:?}"
        );
    }

    for sql in [
        "SELECT * FROM t WHERE | MEMBER OF parent_nt",
        "SELECT * FROM t WHERE e| MEMBER OF parent_nt",
        "SELECT * FROM t WHERE | NOT MEMBER OF parent_nt",
    ] {
        let suggestions = collection_suggestions(sql);
        assert!(
            has(&suggestions, "ELEM"),
            "MEMBER OF LHS slot lost element-compatible columns for `{sql}`: {suggestions:?}"
        );
        assert!(
            !has(&suggestions, "CHILD_NT")
                && !has(&suggestions, "PARENT_NT")
                && !has(&suggestions, "TXT_COL"),
            "non-element columns leaked into MEMBER OF LHS slot for `{sql}`: {suggestions:?}"
        );
    }

    for sql in [
        "SELECT * FROM t WHERE elem MEMBER OF parent_nt |",
        "SELECT * FROM t WHERE elem NOT MEMBER OF parent_nt |",
        "SELECT * FROM t WHERE child_nt SUBMULTISET OF parent_nt |",
        "SELECT * FROM t WHERE child_nt NOT SUBMULTISET OF parent_nt |",
        "SELECT * FROM t WHERE child_nt IS EMPTY |",
        "SELECT * FROM t WHERE child_nt IS A SET |",
        "SELECT * FROM t WHERE child_nt MULTISET EXCEPT parent_nt IS EMPTY |",
    ] {
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "completed collection predicate should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            has(&final_suggestions, "AND") || has(&final_suggestions, "OR"),
            "completed collection predicate lost boolean continuation at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "EMPNO",
            "ENAME",
            "CHILD_NT",
            "PARENT_NT",
            "ELEM",
            "TXT_COL",
            "RUN_JOB",
            "CALC_TOTAL",
        ] {
            assert!(
                !has(&final_suggestions, leaked),
                "{leaked} leaked after completed collection predicate at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
}

/// Oracle's row-pattern `FIRST`/`LAST` calls are valid only inside
/// `MATCH_RECOGNIZE`. They must not be treated as general value-producing
/// functions and leak into an ordinary operand position, while the keyword forms
/// remain available where they are grammatical.
#[test]
fn first_last_are_not_value_functions() {
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    // Not offered as an operand (the old `is_language_function` leak).
    let s = typed_emp_suggestions("SELECT * FROM emp WHERE empno = fir|");
    assert!(
        !has(&s, "FIRST"),
        "FIRST leaked into an operand position: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT las| FROM emp");
    assert!(
        !has(&s, "LAST"),
        "LAST leaked into an operand position: {s:?}"
    );

    // Still served where grammatical: the `NULLS FIRST/LAST` ordering slot.
    let ctx = analyze_inline_cursor_sql("SELECT * FROM emp ORDER BY ename NULLS fir|");
    let kw = SqlEditorWidget::collect_expected_keyword_suggestions(
        "fir",
        &ctx,
        Some(crate::db::DatabaseType::Oracle),
    );
    assert!(
        kw.iter().any(|k| k.eq_ignore_ascii_case("FIRST")),
        "NULLS FIRST ordering slot lost FIRST: {kw:?}"
    );
}

#[test]
fn row_pattern_functions_are_suggested_only_inside_match_recognize() {
    let has = |suggestions: &[String], expected: &str| {
        suggestions
            .iter()
            .any(|suggestion| suggestion.eq_ignore_ascii_case(expected))
    };

    for (name, prefix) in [
        ("CLASSIFIER", "clas"),
        ("FIRST", "fir"),
        ("LAST", "las"),
        ("MATCH_NUMBER", "matc"),
        ("NEXT", "nex"),
        ("PREV", "pre"),
    ] {
        let ordinary = typed_emp_suggestions(&format!("SELECT {prefix}| FROM emp"));
        assert!(
            !has(&ordinary, name) && !has(&ordinary, &format!("{name}()")),
            "{name} leaked outside MATCH_RECOGNIZE: {ordinary:?}"
        );

        let sql = format!(
            "SELECT * FROM emp MATCH_RECOGNIZE (MEASURES {prefix}|() AS m PATTERN (A) DEFINE A AS 1 = 1)"
        );
        let (_, _, inside) = audit_final_suggestions_for(&sql, crate::db::DatabaseType::Oracle);
        assert!(
            has(&inside, &format!("{name}()")),
            "{name} was not suggested inside MATCH_RECOGNIZE: {inside:?}"
        );
    }
}

/// MySQL `RLIKE` is an infix regexp operator, not a standalone value-producing
/// function. It must therefore appear only after a complete operand while still
/// preserving a real column named `RLIKE` at operand-start positions.
#[test]
fn rlike_is_not_a_value_function() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    fn suggestions(
        sql_with_cursor: &str,
        extra_emp_columns: &[&str],
        db: crate::db::DatabaseType,
    ) -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let column_scope = (!column_tables.is_empty()).then(|| column_tables.clone());
        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string()];
        let mut emp_columns = vec!["ENAME".to_string(), "EMPNO".to_string()];
        emp_columns.extend(extra_emp_columns.iter().map(|c| c.to_string()));
        data.set_columns_for_table("EMP", emp_columns);
        data.rebuild_indices();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            !prefix.is_empty(),
            Some(db),
        );
        SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            None,
            column_scope.as_deref(),
            matches!(context, SqlContext::ColumnName | SqlContext::ColumnOrAll),
            context,
            false,
            Some(db),
            expr_keyword_ctx,
        )
    }
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    for db in [MySQL, MariaDB] {
        for sql in ["SELECT rl| FROM emp", "SELECT * FROM emp WHERE empno = rl|"] {
            let s = suggestions(sql, &[], db);
            assert!(
                !has(&s, "RLIKE"),
                "RLIKE leaked as an operand for `{sql}` in {db:?}: {s:?}"
            );
        }

        for sql in [
            "SELECT ename rl| FROM emp",
            "SELECT * FROM emp WHERE empno rl|",
        ] {
            let s = suggestions(sql, &[], db);
            assert!(
                has(&s, "RLIKE"),
                "RLIKE suppressed as an infix operator for `{sql}` in {db:?}: {s:?}"
            );
        }

        let s = suggestions("SELECT rl| FROM emp", &["RLIKE"], db);
        assert!(
            has(&s, "RLIKE"),
            "column named RLIKE was hidden in {db:?}: {s:?}"
        );
    }
}

/// MySQL `BINARY` is a prefix operator (`BINARY expr`). Immediately after it the
/// cursor expects a fresh operand, so postfix operators such as `AND` must not be
/// offered while column operands still complete.
#[test]
fn binary_prefix_operator_expects_an_operand() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));
    let suggest = |sql: &str, db| typed_emp_suggestions_for_db(sql, db);

    for db in [MySQL, MariaDB] {
        let start = suggest("SELECT bi| FROM emp", db);
        assert!(
            has(&start, "BINARY"),
            "BINARY missing at operand start for {db:?}: {start:?}"
        );

        let operand = suggest("SELECT BINARY en| FROM emp", db);
        assert!(
            has(&operand, "ENAME"),
            "column operand missing after BINARY for {db:?}: {operand:?}"
        );

        let operator = suggest("SELECT BINARY a| FROM emp", db);
        assert!(
            !has(&operator, "AND"),
            "AND leaked immediately after BINARY for {db:?}: {operator:?}"
        );
    }
}

/// `CAST`, `EXISTS`, and Oracle `CURSOR` introduce parenthesized constructs.
/// Immediately after the keyword, neither a column nor a postfix operator is
/// grammatical; the UI apply path suppresses the identifier base, while the
/// expression keyword filter also treats the position as operand-starting so
/// `AND`/`OR` do not leak.
#[test]
fn parenthesized_expression_constructs_suppress_identifier_base() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));
    let exclude_flag = |sql_with_cursor: &str| {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        !prefix.is_empty()
    };
    let suppresses = |sql: &str, db_type| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
            &analyze_inline_cursor_sql(sql),
            exclude_flag(sql),
            Some(db_type),
        )
    };

    for sql in [
        "SELECT CAST en| FROM emp",
        "SELECT * FROM emp WHERE EXISTS en|",
        "SELECT CURSOR en| FROM emp",
        "SELECT EXTRACT en| FROM emp",
        "SELECT JSON_EXISTS en| FROM emp",
        "SELECT TREAT en| FROM emp",
        "SELECT XMLCAST en| FROM emp",
    ] {
        assert!(
            suppresses(sql, Oracle),
            "identifier base leaked for `{sql}`"
        );
        let suggestions = typed_emp_suggestions_for_db(sql, Oracle);
        assert!(
            !has(&suggestions, "AND"),
            "AND leaked for `{sql}`: {suggestions:?}"
        );
    }

    for db in [MySQL, MariaDB] {
        assert!(
            !suppresses("SELECT CURSOR en| FROM emp", db),
            "{db:?} CURSOR is not a value-expression construct"
        );
    }
    assert!(
        !suppresses("CREATE TABLE IF NOT EXISTS emp|", Oracle),
        "DDL IF NOT EXISTS name slot must keep identifier/object completion"
    );
    assert!(
        !suppresses("SELECT CASE en| FROM emp", Oracle),
        "CASE can accept a selector expression"
    );
    for db in [MySQL, MariaDB] {
        assert!(
            !suppresses("SELECT BINARY en| FROM emp", db),
            "BINARY is a prefix operator, not a parenthesized construct in {db:?}"
        );
    }
}

#[test]
fn analytic_null_treatment_keywords_are_scoped_to_analytic_call_tails() {
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));
    let kw = |sql: &str, prefix: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let suppresses = |sql: &str| {
        let cursor = sql.find('|').expect("cursor marker");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(
            &analyze_inline_cursor_sql(sql),
            !prefix.is_empty(),
        )
    };

    // `IGNORE`/`RESPECT NULLS` belongs to the analytic function tail before
    // `OVER`, not inside the `OVER (...)` window specification.
    let s = typed_emp_suggestions("SELECT sum(empno) OVER (ORDER BY hiredate ign|) FROM emp");
    assert!(
        !has(&s, "IGNORE"),
        "IGNORE leaked inside an OVER window spec: {s:?}"
    );
    let s = typed_emp_suggestions("SELECT sum(empno) OVER (ORDER BY hiredate res|) FROM emp");
    assert!(
        !has(&s, "RESPECT"),
        "RESPECT leaked inside an OVER window spec: {s:?}"
    );

    assert_eq!(
        kw("SELECT first_value(empno) ign| FROM emp", "ign"),
        vec!["IGNORE".to_string()]
    );
    assert_eq!(
        kw("SELECT last_value(empno) RESPECT | FROM emp", ""),
        vec!["NULLS".to_string()]
    );
    assert_eq!(
        kw("SELECT nth_value(empno, 1) FROM fir| FROM emp", "fir"),
        vec!["FIRST".to_string()]
    );
    assert_eq!(
        kw("SELECT nth_value(empno, 1) FROM LAST IGNORE | FROM emp", ""),
        vec!["NULLS".to_string()]
    );
    assert_eq!(
        kw(
            "SELECT nth_value(NVL(empno, 0), 1) FROM FIRST RESPECT NULLS | FROM emp",
            ""
        ),
        vec!["OVER".to_string()]
    );

    assert!(suppresses("SELECT last_value(empno) IGNORE | FROM emp"));
    assert!(suppresses("SELECT nth_value(empno, 1) FROM fir| FROM emp"));
    assert!(suppresses(
        "SELECT nth_value(empno, 1) FROM LAST IGNORE NULLS | FROM emp"
    ));
    for (sql, expected) in [
        ("SELECT last_value(empno) RESPECT | FROM emp", "NULLS"),
        (
            "SELECT nth_value(empno, 1) FROM LAST IGNORE | FROM emp",
            "NULLS",
        ),
        (
            "SELECT nth_value(empno, 1) FROM LAST IGNORE NULLS | FROM emp",
            "OVER",
        ),
    ] {
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "analytic null-treatment keyword slot should not resolve object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.iter().any(|value| value == expected),
            "{expected} missing from analytic null-treatment keyword slot at `{sql}`: {final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "EMPNO",
            "ENAME",
            "RUN_JOB",
            "CALC_TOTAL",
        ] {
            assert!(
                !final_suggestions.iter().any(|value| value == leaked),
                "{leaked} leaked into analytic null-treatment keyword slot at `{sql}`: {final_suggestions:?}"
            );
        }
    }
    assert!(!suppresses("SELECT ignore | FROM emp"));
}

#[test]
fn analytic_null_treatment_completed_tails_stay_keyword_only_with_prefixes() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);
    let assert_no_noise = |sql: &str, suggestions: &[String]| {
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "APP_USER",
            "SCOTT",
            "RUN_JOB",
            "CALC_TOTAL",
            "EMPNO",
            "ENAME",
            "DEPTNO",
            "DNAME",
            "N_ID",
            "N_VALUE",
            "NOT",
            "NULL",
            "NEXT",
        ] {
            assert!(
                !contains(suggestions, leaked),
                "{leaked} leaked into analytic null-treatment tail at `{sql}`: {suggestions:?}"
            );
        }
    };

    for (sql, expected) in [
        ("SELECT last_value(empno) IGNORE n| FROM emp", Some("NULLS")),
        (
            "SELECT last_value(empno) RESPECT n| FROM emp",
            Some("NULLS"),
        ),
        (
            "SELECT nth_value(empno, 1) FROM LAST IGNORE n| FROM emp",
            Some("NULLS"),
        ),
        (
            "SELECT nth_value(empno, 1) FROM FIRST RESPECT n| FROM emp",
            Some("NULLS"),
        ),
        (
            "SELECT nth_value(empno, 1) FROM LAST IGNORE NULLS o| FROM emp",
            Some("OVER"),
        ),
        (
            "SELECT nth_value(empno, 1) FROM FIRST RESPECT NULLS o| FROM emp",
            Some("OVER"),
        ),
        ("SELECT nth_value(empno, 1) FROM f| FROM emp", Some("FIRST")),
        ("SELECT nth_value(empno, 1) FROM l| FROM emp", Some("LAST")),
        ("SELECT last_value(empno) IGNORE NULLS n| FROM emp", None),
        ("SELECT last_value(empno) RESPECT NULLS n| FROM emp", None),
        (
            "SELECT nth_value(empno, 1) FROM LAST IGNORE NULLS n| FROM emp",
            None,
        ),
        (
            "SELECT nth_value(empno, 1) FROM FIRST RESPECT NULLS n| FROM emp",
            None,
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "analytic null-treatment tail should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        if let Some(expected) = expected {
            assert!(
                contains(&final_suggestions, expected),
                "{expected} missing from analytic null-treatment tail at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        assert_no_noise(sql, &final_suggestions);
    }
}

#[test]
fn keep_dense_rank_keyword_slots_suppress_columns_and_offer_fixed_keywords() {
    let kw = |sql: &str, prefix: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let suppresses = |sql: &str| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(
            &analyze_inline_cursor_sql(sql),
            false,
        )
    };

    assert_eq!(
        kw("SELECT max(empno) KEEP (DENSE_RANK |) FROM emp", ""),
        vec!["FIRST".to_string(), "LAST".to_string()]
    );
    assert_eq!(
        kw("SELECT max(empno) KEEP (DENSE_RANK fir|) FROM emp", "fir"),
        vec!["FIRST".to_string()]
    );
    assert_eq!(
        kw("SELECT max(empno) KEEP (DENSE_RANK FIRST |) FROM emp", ""),
        vec!["ORDER".to_string()]
    );
    assert_eq!(
        kw("SELECT max(empno) KEEP (DENSE_RANK LAST |) FROM emp", ""),
        vec!["ORDER".to_string()]
    );
    assert!(suppresses("SELECT max(empno) KEEP (DENSE_RANK |) FROM emp"));
    assert!(suppresses(
        "SELECT max(empno) KEEP (DENSE_RANK FIRST |) FROM emp"
    ));
    for (sql, expected) in [
        ("SELECT max(empno) KEEP (DENSE_RANK |) FROM emp", "FIRST"),
        (
            "SELECT max(empno) KEEP (DENSE_RANK FIRST |) FROM emp",
            "ORDER",
        ),
    ] {
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "KEEP DENSE_RANK keyword slot should not resolve object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.iter().any(|value| value == expected),
            "{expected} missing from KEEP DENSE_RANK keyword slot at `{sql}`: {final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "EMPNO",
            "ENAME",
            "RUN_JOB",
            "CALC_TOTAL",
        ] {
            assert!(
                !final_suggestions.iter().any(|value| value == leaked),
                "{leaked} leaked into KEEP DENSE_RANK keyword slot at `{sql}`: {final_suggestions:?}"
            );
        }
    }

    // Outside KEEP's dense-rank aggregate syntax these words keep their normal
    // meaning and do not become keyword-only slots.
    assert!(!suppresses("SELECT dense_rank | FROM emp"));
    let lookalike = kw("SELECT dense_rank | FROM emp", "");
    for unexpected in ["FIRST", "LAST", "ORDER"] {
        assert!(
            !lookalike
                .iter()
                .any(|value| value.eq_ignore_ascii_case(unexpected)),
            "KEEP DENSE_RANK keyword `{unexpected}` leaked outside KEEP syntax: {lookalike:?}"
        );
    }
}

#[test]
fn analytic_extension_keywords_are_dialect_precise() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let has = |values: &[String], needle: &str| {
        values
            .iter()
            .any(|value| value.eq_ignore_ascii_case(needle))
    };
    let suppresses = |sql: &str, db| {
        let cursor = sql.find('|').expect("cursor marker");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        let ctx = analyze_inline_cursor_sql(sql);
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
            &ctx,
            !prefix.is_empty(),
            Some(db),
        ) || SqlEditorWidget::cursor_is_at_identifier_suppressing_keyword_slot_for_context(
            &ctx,
            !prefix.is_empty(),
            Some(db),
        )
    };

    for db in [MySQL, MariaDB] {
        for (sql, leaked, should_keep_identifiers) in [
            (
                "SELECT LISTAGG(ename, ',') WITHIN | FROM emp",
                "GROUP",
                true,
            ),
            (
                "SELECT MAX(empno) KEEP (DENSE_RANK |) FROM emp",
                "FIRST",
                true,
            ),
            (
                "SELECT MAX(empno) KEEP (DENSE_RANK FIRST |) FROM emp",
                "ORDER",
                true,
            ),
            ("SELECT first_value(empno) ign| FROM emp", "IGNORE", true),
            (
                "SELECT nth_value(empno, 1) FROM LAST IGNORE | FROM emp",
                "NULLS",
                false,
            ),
        ] {
            let suggestions = query_keyword_completion_suggestions(sql, db);
            assert!(
                !has(&suggestions, leaked),
                "Oracle analytic keyword `{leaked}` leaked in {db:?} mode at `{sql}`: {suggestions:?}"
            );
            if should_keep_identifiers {
                assert!(
                    !suppresses(sql, db),
                    "Oracle analytic keyword slot suppressed identifiers in {db:?} mode at `{sql}`"
                );
            }
        }
    }

    // MySQL 8 executes the explicit RESPECT NULLS spelling, while MariaDB does
    // not. Once RESPECT is present this is a keyword-only continuation.
    let mysql_respect =
        query_keyword_completion_suggestions("SELECT last_value(empno) RESPECT | FROM emp", MySQL);
    assert!(suppresses(
        "SELECT last_value(empno) RESPECT | FROM emp",
        MySQL
    ));
    assert_eq!(mysql_respect, vec!["NULLS".to_string()]);
    assert_eq!(
        query_keyword_completion_suggestions(
            "SELECT last_value(empno) RESPECT NULLS | FROM emp",
            MySQL,
        ),
        vec!["OVER".to_string()]
    );

    let mariadb_respect = query_keyword_completion_suggestions(
        "SELECT last_value(empno) RESPECT | FROM emp",
        MariaDB,
    );
    assert!(
        !has(&mariadb_respect, "NULLS"),
        "MySQL-only explicit RESPECT NULLS leaked in MariaDB mode: {mariadb_respect:?}"
    );
    assert!(!suppresses(
        "SELECT last_value(empno) RESPECT | FROM emp",
        MariaDB
    ));
}

/// The top-level statement keywords (`SELECT`, `INSERT`, `CREATE`, `BEGIN`, …)
/// are grammatical only where a new statement can begin. They must never appear
/// mid-clause. The regression: `previous_meaningful_words_upper` stops at a
/// value token, so an operand whose last token is a string literal left the
/// keyword machinery with an empty word list, which it mistook for a statement
/// start and dumped the statement keywords into a `WHERE`/`VALUES`/`IN` slot.
#[test]
fn statement_keywords_offered_only_at_a_real_statement_start() {
    let kw = |sql: &str| {
        let ctx = analyze_inline_cursor_sql(sql);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &ctx,
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    // A genuine statement start still offers them.
    let s = kw("|");
    assert!(
        has(&s, "SELECT") && has(&s, "CREATE") && has(&s, "BEGIN"),
        "statement start lost the top-level keywords: {s:?}"
    );

    // Mid-expression, right after a value operand — pure noise. A preceding
    // string literal, a parenthesised value list and a `VALUES` row all used to
    // leak the statement keywords through the empty-word-list path.
    for sql in [
        "SELECT * FROM emp WHERE ename = 'x' |",
        "SELECT ename FROM emp WHERE ename LIKE 'a%' |",
        "SELECT * FROM emp WHERE empno IN ('a', |",
        "INSERT INTO emp VALUES ('a', |",
    ] {
        let s = kw(sql);
        for keyword in [
            "SELECT", "INSERT", "UPDATE", "CREATE", "ALTER", "DROP", "BEGIN", "MERGE",
        ] {
            assert!(
                !has(&s, keyword),
                "{keyword} leaked mid-clause for `{sql}`: {s:?}"
            );
        }
    }
}

/// A column wildcard (`*` / `t.*`) is column/operand material. It must be
/// suppressed in a column-suppressing keyword-only slot (an `EXTRACT` field, a
/// data-type slot, …) and right after a complete operand, while staying
/// available at an operand-start select position.
#[test]
fn select_wildcard_is_position_aware() {
    // Mirrors the apply-path wildcard gate.
    fn wildcard(sql_with_cursor: &str) -> Vec<String> {
        let cursor = sql_with_cursor.find('|').expect("cursor marker");
        let sql = sql_with_cursor.replace('|', "");
        let ctx = analyze_inline_cursor_sql(sql_with_cursor);
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&sql, cursor);
        let has_prefix = !prefix.is_empty();
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(None, &ctx);
        let data = IntellisenseData::new();
        let expr_keyword_ctx = SqlEditorWidget::expression_keyword_context(
            &ctx,
            &data,
            &column_tables,
            has_prefix,
            None,
        );
        let at_keyword_only_slot =
            SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot(&ctx, has_prefix);
        if at_keyword_only_slot || expr_keyword_ctx.follows_operand == Some(true) {
            Vec::new()
        } else {
            SqlEditorWidget::collect_clause_wildcard_suggestions(&prefix, None, &ctx)
        }
    }
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    // Operand-start select positions keep the wildcard.
    assert!(
        has(&wildcard("SELECT | FROM emp"), "*"),
        "wildcard lost at select start"
    );
    assert!(
        has(&wildcard("SELECT ename, | FROM emp"), "*"),
        "wildcard lost after a comma"
    );

    // Right after a complete select item, the wildcard is noise.
    assert!(
        wildcard("SELECT ename | FROM emp").is_empty(),
        "wildcard leaked after a column operand"
    );
    assert!(
        wildcard("SELECT 'x' | FROM emp").is_empty(),
        "wildcard leaked after a literal operand"
    );

    // A keyword-only value slot (EXTRACT field) never admits the wildcard.
    assert!(
        wildcard("SELECT EXTRACT(| FROM hiredate) FROM emp").is_empty(),
        "wildcard leaked into the EXTRACT field slot"
    );
}

/// Operand material (columns, `*`, bare identifiers) is grammatical only where a
/// new operand is expected. With an empty prefix the cursor sits *after* the
/// completed operand, so it must be dropped — the regression was that the
/// expression-keyword context excluded the finished operand from its window and
/// misread the position as an operand-start, leaking columns after
/// `SELECT ename `, `ORDER BY ename `, `WHERE c = 'x' `.
#[test]
fn columns_suppressed_immediately_after_a_complete_operand() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));

    // After a complete operand (empty prefix): no operand material.
    for sql in [
        "SELECT ename | FROM emp",
        "SELECT * FROM emp ORDER BY ename |",
        "SELECT * FROM emp WHERE ename = 'x' |",
        "SELECT * FROM emp WHERE empno = empno |",
        "SELECT CURRENT_DATE | FROM emp",
        "SELECT CURRENT_TIMESTAMP | FROM emp",
        "SELECT LOCALTIMESTAMP | FROM emp",
        "SELECT SYSDATE | FROM emp",
        "SELECT SYSTIMESTAMP | FROM emp",
        "SELECT CASE WHEN empno = 1 THEN 1 END | FROM emp",
        "SELECT CASE WHEN empno = 1 THEN CASE WHEN empno = 2 THEN 1 END | END FROM emp",
    ] {
        let s = typed_emp_suggestions(sql);
        assert!(
            !has(&s, "ENAME") && !has(&s, "EMPNO") && !has(&s, "HIREDATE"),
            "operand material leaked after a complete operand for `{sql}`: {s:?}"
        );
    }

    for sql in [
        "SELECT CURRENT_DATE | FROM emp",
        "SELECT CURRENT_TIME | FROM emp",
        "SELECT CURRENT_TIMESTAMP | FROM emp",
        "SELECT LOCALTIME | FROM emp",
        "SELECT LOCALTIMESTAMP | FROM emp",
    ] {
        for db in [MySQL, MariaDB] {
            let s = typed_emp_suggestions_for_db(sql, db);
            assert!(
                !has(&s, "ENAME") && !has(&s, "EMPNO") && !has(&s, "HIREDATE"),
                "operand material leaked after a complete temporal value for `{sql}` on {db:?}: {s:?}"
            );
        }
    }

    // At an operand-start the same columns are still offered.
    assert!(
        has(&typed_emp_suggestions("SELECT | FROM emp"), "ENAME"),
        "columns lost at an operand-start select position"
    );
    let comparison_rhs = typed_emp_suggestions("SELECT * FROM emp WHERE empno = | ");
    assert!(
        has(&comparison_rhs, "EMPNO"),
        "matching columns lost after a comparison operator: {comparison_rhs:?}"
    );
    assert!(
        !has(&comparison_rhs, "ENAME") && !has(&comparison_rhs, "HIREDATE"),
        "non-matching columns leaked after a comparison operator: {comparison_rhs:?}"
    );
    // And typing a column prefix still completes it.
    assert!(
        has(&typed_emp_suggestions("SELECT en| FROM emp"), "ENAME"),
        "column prefix completion broke"
    );
}

/// Predicate operators that require a parenthesized operand (`IN`, quantified
/// comparison `ANY`/`SOME`/`ALL`) have a punctuation-only slot immediately after
/// the operator. Once an `IN` list's `(` is present, the list body is a real
/// operand position again.
#[test]
fn predicate_open_paren_slots_suppress_columns_only_before_the_list() {
    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));
    let keywords = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    for sql in [
        "SELECT * FROM emp WHERE empno IN |",
        "SELECT * FROM emp WHERE empno NOT IN |",
        "SELECT * FROM emp WHERE empno = ANY |",
        "SELECT * FROM emp WHERE empno <> SOME |",
        "SELECT * FROM emp WHERE empno > ALL |",
    ] {
        let suggestions = typed_emp_suggestions(sql);
        assert!(
            suggestions.is_empty(),
            "IN-list opener slot should not offer identifier material for `{sql}`: {suggestions:?}"
        );
        assert!(
            keywords(sql).is_empty(),
            "IN-list opener slot should not offer expression keywords for `{sql}`: {:?}",
            keywords(sql)
        );
        let (kind, final_keywords, final_suggestions) =
            audit_final_suggestions_for(sql, crate::db::DatabaseType::Oracle);
        assert_eq!(
            kind, None,
            "IN-list opener slot should not resolve object kind for `{sql}`: keywords={final_keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.is_empty(),
            "IN-list opener slot should not offer catalog or keywords for `{sql}`: keywords={final_keywords:?} final={final_suggestions:?}"
        );
    }

    for sql in [
        "SELECT * FROM emp WHERE empno IN|",
        "SELECT * FROM emp WHERE empno NOT IN|",
        "SELECT * FROM emp WHERE empno = ANY|",
        "SELECT * FROM emp WHERE empno <> SOME|",
        "SELECT * FROM emp WHERE empno > ALL|",
    ] {
        let suggestions = typed_emp_suggestions(sql);
        assert!(
            !has(&suggestions, "ENAME")
                && !has(&suggestions, "EMPNO")
                && !has(&suggestions, "HIREDATE"),
            "columns leaked before an IN-list opener for `{sql}`: {suggestions:?}"
        );
    }

    for sql in [
        "SELECT * FROM emp WHERE empno IN (|)",
        "SELECT * FROM emp WHERE empno NOT IN (|)",
        "SELECT * FROM emp WHERE empno IN (1, |)",
    ] {
        let suggestions = typed_emp_suggestions(sql);
        assert!(
            has(&suggestions, "EMPNO"),
            "columns were suppressed inside an IN-list operand slot for `{sql}`: {suggestions:?}"
        );
        assert!(
            !has(&suggestions, "ENAME") && !has(&suggestions, "HIREDATE"),
            "non-matching columns leaked inside an IN-list operand slot for `{sql}`: {suggestions:?}"
        );
    }

    assert!(
        has(
            &data_type_suggestions(
                "CREATE FUNCTION f(p IN |) RETURN NUMBER IS BEGIN RETURN 1; END;",
                "",
                crate::db::DatabaseType::Oracle,
            ),
            "NUMBER"
        ),
        "PL/SQL parameter mode `IN |` must remain a type slot"
    );
}

#[test]
fn string_pattern_slots_filter_columns_to_character_operands() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let has = |v: &[String], s: &str| v.iter().any(|x| x.eq_ignore_ascii_case(s));
    let assert_character_only = |sql: &str, db_type| {
        let suggestions = typed_emp_suggestions_for_db(sql, db_type);
        assert!(
            has(&suggestions, "ENAME"),
            "character RHS slot lost character columns for `{sql}`: {suggestions:?}"
        );
        assert!(
            !has(&suggestions, "EMPNO") && !has(&suggestions, "HIREDATE"),
            "non-character columns leaked into character RHS slot for `{sql}`: {suggestions:?}"
        );
    };

    for sql in [
        "SELECT * FROM emp WHERE ename LIKE |",
        "SELECT * FROM emp WHERE ename NOT LIKE |",
        "SELECT * FROM emp WHERE ename LIKEC |",
        "SELECT * FROM emp WHERE ename LIKE 'A%' ESCAPE |",
        "SELECT * FROM emp WHERE ename LIKE e|",
    ] {
        assert_character_only(sql, Oracle);
    }

    for db_type in [MySQL, MariaDB] {
        for sql in [
            "SELECT * FROM emp WHERE ename LIKE |",
            "SELECT * FROM emp WHERE ename REGEXP |",
            "SELECT * FROM emp WHERE ename RLIKE |",
            "SELECT group_concat(ename SEPARATOR |) FROM emp",
            "SELECT group_concat(ename SEPARATOR e|) FROM emp",
        ] {
            assert_character_only(sql, db_type);
        }
    }
}

