fn mysql_family_fixture_word_completion_suggestions(
    file_name: &str,
    db_type: crate::db::DatabaseType,
    context: &str,
    word: &str,
    prefix: &str,
) -> Vec<String> {
    let script = match db_type {
        crate::db::DatabaseType::MySQL => load_mysql_intellisense_test_file(file_name),
        crate::db::DatabaseType::MariaDB => load_mariadb_intellisense_test_file(file_name),
        crate::db::DatabaseType::Oracle => panic!("MySQL-family fixture helper received Oracle"),
    };
    assert_eq!(
        script.matches(context).count(),
        1,
        "fixture context must be unique in {file_name}: `{context}`"
    );
    let context_start = script.find(context).expect("fixture context");
    let word_in_context = context.find(word).expect("word in fixture context");
    let word_start = context_start + word_in_context;
    let marked = format!(
        "{}{}__CODEX_CURSOR__{}",
        script.get(..word_start).unwrap_or(""),
        prefix,
        script.get(word_start + word.len()..).unwrap_or("")
    );
    let mut data = mysql_family_test_intellisense_data(file_name, db_type);
    query_completion_suggestions_with_data(&marked, db_type, true, &mut data)
}

#[test]
fn mysql_family_all_fixture_sweep_gaps_use_production_completion() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let cases = [
        (
            "test10.txt",
            MariaDB,
            "END outer_block//\n\nDELIMITER ;\n\nCALL mb_run_gauntlet_2();",
            "DELIMITER",
            "DELI",
            "DELIMITER",
        ),
        (
            "test11.txt",
            MariaDB,
            "FROM mb3_contract FOR SYSTEM_TIME BETWEEN(@history_cutover-INTERVAL 1 SECOND)AND NOW(6)",
            "SECOND",
            "SECO",
            "SECOND",
        ),
        (
            "test6.txt",
            MySQL,
            "END outer_block$$\n\nDELIMITER ;\n\nINSERT INTO gx_place",
            "DELIMITER",
            "DELI",
            "DELIMITER",
        ),
        (
            "test6.txt",
            MySQL,
            "AGAINST('database search'WITH QUERY EXPANSION)AS expansion_score",
            "EXPANSION",
            "EXPA",
            "EXPANSION",
        ),
        (
            "final_hardcore.sql",
            MariaDB,
            "RETURNING id, INET6_NTOA(addr) AS printable",
            "AS",
            "A",
            "AS",
        ),
        (
            "final_hardcore.sql",
            MariaDB,
            "HANDLER metric_handle READ FIRST",
            "metric_handle",
            "metr",
            "metric_handle",
        ),
        (
            "final_hardcore.sql",
            MySQL,
            "SUM(metric_value) OVER w_run",
            "w_run",
            "w_ru",
            "w_run",
        ),
        (
            "final_hardcore.sql",
            MySQL,
            "LAG(metric_value, 1, 0) OVER w_ord",
            "w_ord",
            "w_or",
            "w_ord",
        ),
        (
            "final_hardcore.sql",
            MySQL,
            "hard_document.payload,",
            "hard_document",
            "hard",
            "hard_document",
        ),
        (
            "final_hardcore.sql",
            MySQL,
            ") top_item ON TRUE",
            "TRUE",
            "TRU",
            "TRUE",
        ),
    ];

    let mut failures = Vec::new();
    for (file_name, db_type, context, word, prefix, expected) in cases {
        let suggestions = mysql_family_fixture_word_completion_suggestions(
            file_name, db_type, context, word, prefix,
        );
        if !suggestions
            .iter()
            .any(|suggestion| suggestion.eq_ignore_ascii_case(expected))
        {
            failures.push(format!(
                "{db_type:?} {file_name} `{context}` lost `{expected}`: {suggestions:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "MySQL-family fixture production-path gaps:\n{}",
        failures.join("\n")
    );
}

#[test]
fn mariadb_handler_alias_reference_uses_prior_open_statement() {
    use crate::db::DatabaseType::MariaDB;

    let text_before_cursor = "HANDLER metric OPEN AS metric_handle;\nHANDLER metr";
    assert!(
        SqlEditorWidget::cursor_is_at_mysql_handler_alias_reference_slot_from_bounded_text(
            text_before_cursor,
            "metr",
            " READ FIRST;",
            Some(MariaDB),
        )
    );
    assert_eq!(
        SqlEditorWidget::mysql_handler_alias_suggestions_from_text(
            text_before_cursor,
            "metr",
            Some(MariaDB),
        ),
        vec!["metric_handle".to_string()]
    );

    let script = load_mariadb_intellisense_test_file("final_hardcore.sql");
    let context = "HANDLER metric_handle READ FIRST";
    let cursor = script.find(context).expect("handler read") + "HANDLER metr".len();
    let scan = signature_scan_text_before_cursor_from_snapshot_for_test(
        &ChunkedText::from_str(script),
        cursor,
        true,
    );
    assert!(scan.contains("HANDLER metric OPEN AS metric_handle;"));
    assert!(
        SqlEditorWidget::cursor_is_at_mysql_handler_alias_reference_slot_from_bounded_text(
            &scan,
            "metr",
            script.get(cursor..).unwrap_or(""),
            Some(MariaDB),
        )
    );
    assert_eq!(
        SqlEditorWidget::mysql_handler_alias_suggestions_from_text(&scan, "metr", Some(MariaDB)),
        vec!["metric_handle".to_string()]
    );
}

#[derive(Debug)]
struct IntellisenseSweepMissing {
    start: usize,
    end: usize,
    line: usize,
    column: usize,
    word: String,
    prefix: String,
    suggestion_sample: Vec<String>,
    suggestion_count: usize,
}

struct IntellisenseSweepRun {
    checked: usize,
    suggestions_checked: usize,
    missing: Vec<IntellisenseSweepMissing>,
    untyped_suggestions: Vec<IntellisenseSweepUntypedSuggestion>,
}

#[derive(Debug)]
struct IntellisenseSweepUntypedSuggestion {
    start: usize,
    line: usize,
    column: usize,
    word: String,
    prefix: String,
    suggestion: String,
}

struct IntellisenseSweepCandidate {
    start: usize,
    end: usize,
    word: String,
    prefix: String,
    replacement: String,
    cursor: usize,
}

struct IntellisenseSweepCandidateResult {
    checked: bool,
    suggestions_checked: usize,
    missing: Option<IntellisenseSweepMissing>,
    untyped_suggestions: Vec<IntellisenseSweepUntypedSuggestion>,
}

struct IntellisenseSweepStatementDependencies {
    text_bind_names: Vec<String>,
    package_spec_symbols: Vec<ParsedDeclarationSymbol>,
}

struct IntellisenseSweepStatementIndex {
    dependency_start: usize,
    start: usize,
    end: usize,
    dependencies: OnceLock<IntellisenseSweepStatementDependencies>,
}

struct IntellisenseSweepFileIndex {
    statements: Vec<IntellisenseSweepStatementIndex>,
    lexical_spans: Vec<crate::sql_parser_engine::LexicalSpan>,
}

impl IntellisenseSweepFileIndex {
    fn new(
        script: &str,
        base_snapshot: &ChunkedText,
        db_type: crate::db::DatabaseType,
        lexical_spans: Vec<crate::sql_parser_engine::LexicalSpan>,
    ) -> Self {
        let (lookbehind_bytes, _) = SqlEditorWidget::intellisense_context_lookaround(
            wide_intellisense_test_context_window_bytes(),
        );
        let statements =
            super::query_text::statement_spans_in_text_for_db_type(script, Some(db_type))
                .into_iter()
                .map(|(start, end)| IntellisenseSweepStatementIndex {
                    dependency_start: base_snapshot
                        .clamp_boundary(start.saturating_sub(lookbehind_bytes)),
                    start,
                    end,
                    dependencies: OnceLock::new(),
                })
                .collect();
        Self {
            statements,
            lexical_spans,
        }
    }

    fn statement_at(&self, offset: usize) -> Option<&IntellisenseSweepStatementIndex> {
        let idx = self
            .statements
            .partition_point(|statement| statement.end <= offset);
        self.statements
            .get(idx)
            .filter(|statement| statement.start <= offset && offset < statement.end)
    }

    fn signature_scan_start(&self, script: &str, cursor: usize) -> usize {
        const SIGNATURE_SCAN_WINDOW: usize = 4000;
        let mut window_start = cursor.saturating_sub(SIGNATURE_SCAN_WINDOW);
        while window_start < cursor && !script.is_char_boundary(window_start) {
            window_start += 1;
        }
        if window_start > 0 {
            if let Some(newline) = script
                .get(window_start..cursor)
                .and_then(|raw| raw.find('\n'))
            {
                window_start = window_start.saturating_add(newline + 1);
            }
        }
        while window_start < cursor {
            let idx = self
                .lexical_spans
                .partition_point(|span| span.end <= window_start);
            let starts_inside_non_code = self
                .lexical_spans
                .get(idx)
                .is_some_and(|span| span.start < window_start && window_start < span.end);
            if !starts_inside_non_code {
                break;
            }
            let Some(newline) = script
                .get(window_start..cursor)
                .and_then(|tail| tail.find('\n'))
            else {
                window_start = cursor;
                break;
            };
            window_start = window_start.saturating_add(newline + 1);
        }
        window_start
    }

    fn analysis_for_candidate(
        &self,
        script: &str,
        snapshot: &ChunkedText,
        candidate: &IntellisenseSweepCandidate,
        db_type: crate::db::DatabaseType,
    ) -> (ExpandedStatementWindow, IntellisenseAnalysis) {
        let Some(statement) = self.statement_at(candidate.start) else {
            return intellisense_analysis_from_snapshot_for_test_with_context_window(
                snapshot,
                candidate.cursor,
                db_type,
                wide_intellisense_test_context_window_bytes(),
            );
        };
        let removed_len = candidate.end.saturating_sub(candidate.start);
        let statement_end = statement
            .end
            .saturating_sub(removed_len)
            .saturating_add(candidate.replacement.len());
        let text = snapshot
            .range_string(statement.start, statement_end)
            .unwrap_or_default();
        let expanded = ExpandedStatementWindow {
            dependency_start: statement.dependency_start,
            statement_start: statement.start,
            statement_end,
            cursor_in_statement: candidate
                .cursor
                .saturating_sub(statement.start)
                .min(text.len()),
            text,
        };
        let dependencies = statement.dependencies.get_or_init(|| {
            let context = script
                .get(statement.dependency_start..statement.end)
                .unwrap_or("");
            let relative_statement_start =
                statement.start.saturating_sub(statement.dependency_start);
            let statement_text = script.get(statement.start..statement.end).unwrap_or("");
            let text_bind_names = SqlEditorWidget::collect_text_bind_names_before_statement(
                context,
                relative_statement_start,
                Some(db_type),
            );
            let mut package_spec_symbols = SqlEditorWidget::package_spec_symbols_for_body(
                context,
                statement_text,
                relative_statement_start,
            );
            package_spec_symbols.extend(
                SqlEditorWidget::package_spec_symbols_for_qualified_type_references(
                    context,
                    statement_text,
                    relative_statement_start,
                ),
            );
            IntellisenseSweepStatementDependencies {
                text_bind_names,
                package_spec_symbols,
            }
        });
        let analysis = intellisense_analysis_from_expanded_for_test(
            &expanded,
            db_type,
            dependencies.text_bind_names.clone(),
            &dependencies.package_spec_symbols,
        );
        (expanded, analysis)
    }
}

struct IntellisenseSweepWorkerResources {
    data: Arc<Mutex<IntellisenseData>>,
    column_sender: mpsc::Sender<ColumnLoadUpdate>,
    _column_receiver: mpsc::Receiver<ColumnLoadUpdate>,
    connection: SharedConnection,
    runtime: IntellisenseRuntimeState,
}

impl IntellisenseSweepWorkerResources {
    fn new(base_data: &IntellisenseData) -> Self {
        let (column_sender, column_receiver) = mpsc::channel();
        Self {
            data: Arc::new(Mutex::new(base_data.clone())),
            column_sender,
            _column_receiver: column_receiver,
            connection: create_shared_connection(),
            runtime: IntellisenseRuntimeState::new(),
        }
    }
}

#[test]
fn intellisense_sweep_file_index_matches_wide_analysis_for_compound_statements() {
    use crate::db::DatabaseType::{MySQL, Oracle};

    for (db_type, script, word) in [
        (
            Oracle,
            concat!(
                "CREATE PACKAGE p AS FUNCTION f RETURN NUMBER; END p;\n/\n",
                "CREATE PACKAGE BODY p AS FUNCTION f RETURN NUMBER IS BEGIN ",
                "RETURN 1; END; END p;\n/\nSELECT 1 FROM dual;"
            ),
            "RETURN",
        ),
        (
            MySQL,
            concat!(
                "DELIMITER $$\nCREATE PROCEDURE p() BEGIN SELECT 1; ",
                "SELECT col FROM t WHERE col IS NOT NULL; END$$\n",
                "DELIMITER ;\nSELECT 2;"
            ),
            "WHERE",
        ),
    ] {
        let start = script.rfind(word).expect("indexed sweep word");
        let prefix = intellisense_sweep_completion_prefix(word).expect("completion prefix");
        let candidate = IntellisenseSweepCandidate {
            start,
            end: start + word.len(),
            word: word.to_string(),
            replacement: prefix.clone(),
            cursor: start + prefix.len(),
            prefix,
        };
        let base_snapshot = ChunkedText::from_str(script);
        let mut edited = base_snapshot.clone();
        assert!(edited.replace_range(candidate.start, candidate.end, &candidate.replacement));
        let file_index = IntellisenseSweepFileIndex::new(
            script,
            &base_snapshot,
            db_type,
            crate::sql_parser_engine::lexical_spans(script, db_type.is_mysql_or_mariadb()),
        );
        let (indexed, indexed_analysis) =
            file_index.analysis_for_candidate(script, &edited, &candidate, db_type);
        let (wide, wide_analysis) =
            intellisense_analysis_from_snapshot_for_test(&edited, candidate.cursor, db_type);

        assert_eq!(
            (
                indexed.statement_start,
                indexed.statement_end,
                &indexed.text
            ),
            (wide.statement_start, wide.statement_end, &wide.text),
            "{db_type:?} indexed statement differs from the wide analysis"
        );
        assert_eq!(
            (
                indexed_analysis.statement_start,
                indexed_analysis.statement_end,
                indexed_analysis.context.phase
            ),
            (
                wide_analysis.statement_start,
                wide_analysis.statement_end,
                wide_analysis.context.phase
            ),
            "{db_type:?} indexed analysis differs from the wide analysis"
        );
    }
}

#[test]
fn intellisense_sweep_lexical_index_matches_legacy_signature_window() {
    let script = format!(
        "{}\nq'[first line\nsecond line\nthird line]'\nSELECT DBMS_OUTPUT.PUT_LINE('x') FROM dual",
        "SELECT 1 FROM dual;\n".repeat(260)
    );
    let snapshot = ChunkedText::from_str(&script);
    let index = IntellisenseSweepFileIndex::new(
        &script,
        &snapshot,
        crate::db::DatabaseType::Oracle,
        crate::sql_parser_engine::lexical_spans(&script, false),
    );
    let cursor = script.len();

    assert_eq!(
        index.signature_scan_start(&script, cursor),
        signature_scan_start_before_cursor_from_snapshot_for_test(&snapshot, cursor, false)
    );
}

fn oracle_test1_intellisense_data() -> IntellisenseData {
    let catalog = oracle_catalog_from_test1_script();
    oracle_intellisense_data_from_catalog(&catalog)
}

fn oracle_test_all_intellisense_data() -> IntellisenseData {
    let catalog = oracle_catalog_from_test_all_scripts();
    oracle_intellisense_data_from_catalog(&catalog)
}

/// The shared "all test scripts" catalog merges every fixture file; on table
/// name collisions (several files re-create `qt_sales` with different columns)
/// the file being swept must see ITS OWN column definitions, or the sweep
/// reports misses that are metadata artifacts rather than completion bugs.
/// Overlay the file-local catalog on top of the shared one.
fn oracle_test_file_scoped_intellisense_data(file_name: &str) -> IntellisenseData {
    static CACHE: OnceLock<Mutex<HashMap<String, IntellisenseData>>> = OnceLock::new();
    let cache = CACHE.get_or_init(|| Mutex::new(HashMap::new()));
    if let Some(data) = lock_or_recover(cache).get(file_name) {
        return data.clone();
    }
    let mut catalog = oracle_catalog_from_test_all_scripts();
    oracle_collect_script_catalog_entries(load_intellisense_test_file(file_name), &mut catalog);
    let data = oracle_intellisense_data_from_catalog(&catalog);
    lock_or_recover(cache).insert(file_name.to_string(), data.clone());
    data
}

#[test]
fn oracle_file_scoped_sweep_metadata_includes_file_local_non_relation_objects() {
    let mut data = oracle_test_file_scoped_intellisense_data("test15.sql");

    assert!(
        data.packages
            .iter()
            .any(|name| name.eq_ignore_ascii_case("QT_SPLITTER_PKG")),
        "file-local package was not included in sweep metadata"
    );
    let members = data.get_member_suggestions("QT_SPLITTER_PKG", "norm", false);
    assert!(
        members
            .iter()
            .any(|name| name.eq_ignore_ascii_case("NORMALIZE_NAME")),
        "file-local package member was not included in sweep metadata: {members:?}"
    );
}

