#[test]
fn wave26_mysql_partition_alias_routine_and_transaction_slots_use_production_completion() {
    use crate::db::DatabaseType::MySQL;

    let data = mysql_family_test_intellisense_data("final_hardcore.sql", MySQL);
    let cases = [
        (
            "CREATE TABLE demo (id INT) PARTITION BY RANGE (id) \
             SUBPARTITION BY LINE__CODEX_CURSOR__AR HASH (id) \
             (PARTITION p0 VALUES LESS THAN MAXVALUE)",
            "LINEAR",
        ),
        (
            "CREATE TABLE demo (id INT) PARTITION BY RANGE (id) \
             SUBPARTITION BY LINEAR HAS__CODEX_CURSOR__H (id) \
             (PARTITION p0 VALUES LESS THAN MAXVALUE)",
            "HASH",
        ),
        (
            "INSERT INTO sq_hard_w26_event PART__CODEX_CURSOR__ITION (p_low) \
             (tenant_id, event_id) VALUES (1, 1)",
            "PARTITION",
        ),
        (
            "UPDATE sq_hard_w26_event PART__CODEX_CURSOR__ITION (`p_low$0`) \
             AS `update` SET amount = 1",
            "PARTITION",
        ),
        (
            "UPDATE sq_hard_w26_event AS `update` \
             SET amount = `upda__CODEX_CURSOR__`.amount + 1",
            "update",
        ),
        (
            "DELETE FROM sq_hard_w26_event AS `delete` \
             WHERE `dele__CODEX_CURSOR__`.`condition` = 'discard'",
            "delete",
        ),
        (
            "SELECT `row`.event_id FROM sq_hard_w26_event AS `row` \
             WHERE ROW(`ro__CODEX_CURSOR__`.`condition`, `row`.event_id) IN (ROW('x', 1))",
            "row",
        ),
        (
            "CREATE PROCEDURE demo() MODIFIES SQ__CODEX_CURSOR__L DATA SELECT 1",
            "SQL",
        ),
        (
            "ROLLBACK WORK T__CODEX_CURSOR__ SAVEPOINT `save;--/*#*/`",
            "TO",
        ),
        (
            "SELECT (SELECT COUNT(*) FROM sq_hard_w8_s__CODEX_CURSOR__)",
            "sq_hard_w8_swap",
        ),
        (
            "SELECT (SELECT COUNT(*) FROM sq_hard_w9_n__CODEX_CURSOR__)",
            "sq_hard_w9_note",
        ),
        (
            "SELECT (SELECT COUNT(*) FROM sq_hard_w9_s__CODEX_CURSOR__)",
            "sq_hard_w9_shape",
        ),
        (
            "CREATE PROCEDURE demo() BEGIN \
             SET @dynamic_sql = 'SELECT 1'; \
             PREPARE stmt FROM @dynamic__CODEX_CURSOR___sql; END",
            "dynamic_sql",
        ),
    ];

    for (sql, expected) in cases {
        let mut data = data.clone();
        let suggestions =
            query_completion_suggestions_with_data(sql, MySQL, true, &mut data);
        assert!(
            suggestions
                .iter()
                .any(|suggestion| intellisense_sweep_suggestion_matches_word(suggestion, expected)),
            "`{expected}` missing at `{sql}`: {suggestions:?}"
        );
    }

    let fixture_cases = [
        (
            "INSERT INTO sq_hard_w26_event\nPARTITION (p_low) (",
            "PARTITION",
            "PART",
        ),
        (
            "INSERT INTO sq_hard_w26_event\nPARTITION (p_high) (",
            "PARTITION",
            "PART",
        ),
        (
            "UPDATE sq_hard_w26_event\nPARTITION (`p_low$0`, `p_low$1`) AS `update`",
            "PARTITION",
            "PART",
        ),
        (
            "(SELECT COUNT(*) FROM sq_hard_w8_swap) AS wave8_swapped_rows",
            "sq_hard_w8_swap",
            "sq_h",
        ),
        (
            "(SELECT COUNT(*) FROM sq_hard_w9_note) AS wave9_notes",
            "sq_hard_w9_note",
            "sq_h",
        ),
        (
            "(SELECT COUNT(*) FROM sq_hard_w9_shape) AS wave9_shapes",
            "sq_hard_w9_shape",
            "sq_h",
        ),
    ];
    for (context, word, prefix) in fixture_cases {
        let suggestions = mysql_family_fixture_word_completion_suggestions(
            "final_hardcore.sql",
            MySQL,
            context,
            word,
            prefix,
        );
        assert!(
            suggestions
                .iter()
                .any(|suggestion| intellisense_sweep_suggestion_matches_word(suggestion, word)),
            "`{word}` missing in fixture context `{context}`: {suggestions:?}"
        );
    }
}

