#[test]
fn sweep_skips_include_paths_and_routine_or_cursor_parameter_definitions() {
    use crate::db::DatabaseType::{MariaDB, Oracle};

    let data = IntellisenseData::new();
    let include_run = intellisense_sweep_run("@test/test1.txt;\n", Oracle, &data);
    assert_eq!(
        include_run.checked, 0,
        "SQL*Plus include paths are not completion reference slots"
    );
    assert!(intellisense_sweep_word_skip_context(
        "CREATE TYPE BODY demo_t AS MEMBER FUNCTION rend__CODEX_CURSOR__ RETURN VARCHAR2 IS BEGIN RETURN NULL; END; END;",
        Oracle,
        "render",
    ));
    assert!(intellisense_sweep_word_skip_context(
        "BEGIN NOT ATOMIC DECLARE cur_prices CURSOR(p_as__CODEX_CURSOR__ INT) FOR SELECT 1; END",
        MariaDB,
        "p_asset_id",
    ));
}

fn intellisense_sweep_word_starts_line(sql: &str, word_start: usize) -> bool {
    let line_start = sql
        .get(..word_start)
        .and_then(|text| text.rfind('\n'))
        .map_or(0, |idx| idx + 1);
    sql.get(line_start..word_start)
        .unwrap_or("")
        .trim()
        .is_empty()
}

fn intellisense_sweep_line_prefix_after_last_separator(sql: &str, word_start: usize) -> String {
    let line_start = sql
        .get(..word_start)
        .and_then(|text| text.rfind('\n'))
        .map_or(0, |idx| idx + 1);
    let prefix = sql.get(line_start..word_start).unwrap_or("");
    let start = prefix.rfind(['(', ',']).map_or(0, |idx| idx + 1);
    prefix
        .get(start..)
        .unwrap_or("")
        .trim()
        .to_ascii_uppercase()
}

fn intellisense_sweep_next_meaningful_word(sql: &str, start: usize) -> Option<String> {
    let after = sql.get(start..)?;
    super::query_text::tokenize_sql(after)
        .into_iter()
        .find_map(|token| token_word_text(Some(&token)).map(str::to_string))
}

fn intellisense_sweep_next_meaningful_word_after_candidate(
    sql: &str,
    cursor: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
) -> Option<String> {
    let mut after = sql.get(cursor..)?.trim_start();
    if let Some(quote) = original_word
        .starts_with(['"', '`'])
        .then(|| original_word.chars().next())
        .flatten()
        .filter(|quote| original_word.ends_with(*quote))
    {
        after = after.strip_prefix(quote).unwrap_or(after).trim_start();
    }
    super::query_text::tokenize_sql_with_mysql_compat(after, db_type.is_mysql_or_mariadb())
        .into_iter()
        .find_map(|token| token_word_text(Some(&token)).map(str::to_string))
}

fn intellisense_sweep_previous_meaningful_word(tokens: &[SqlToken], end: usize) -> Option<&str> {
    tokens
        .get(..end.min(tokens.len()))
        .unwrap_or(tokens)
        .iter()
        .rev()
        .find_map(|token| token_word_text(Some(token)))
}

fn intellisense_sweep_current_statement_tokens_before_cursor(
    sql: &str,
    cursor: usize,
) -> Vec<SqlToken> {
    let before_cursor = sql.get(..cursor).unwrap_or("");
    let tokens = super::query_text::tokenize_sql(before_cursor);
    let start = tokens
        .iter()
        .rposition(
            |token| matches!(token, SqlToken::Symbol(symbol) if symbol == ";" || symbol == "/"),
        )
        .map_or(0, |idx| idx + 1);
    tokens.get(start..).unwrap_or(&[]).to_vec()
}

fn intellisense_sweep_is_create_element_name_definition(
    sql: &str,
    cursor: usize,
    word_start: usize,
    original_word: &str,
) -> bool {
    let starts_line = intellisense_sweep_word_starts_line(sql, word_start);
    let inline_column_definition =
        intellisense_sweep_line_prefix_after_last_separator(sql, word_start).is_empty()
            && intellisense_sweep_next_meaningful_word(
                sql,
                word_start.saturating_add(original_word.len()),
            )
            .is_some_and(|word| intellisense_sweep_is_mysql_type_lead(&word));
    if !starts_line && !inline_column_definition {
        return false;
    }
    let tokens = intellisense_sweep_current_statement_tokens_before_cursor(sql, cursor);
    let Some(create_idx) = tokens
        .iter()
        .position(|token| token_word_eq(Some(token), "CREATE"))
    else {
        return false;
    };
    let Some((kind, name_idx)) = oracle_create_kind_and_name_idx(&tokens, create_idx) else {
        return false;
    };
    let Some((_, after_name_idx)) = script_object_name_at(&tokens, name_idx) else {
        return false;
    };
    let tail = tokens.get(after_name_idx..).unwrap_or(&[]);
    if !tail
        .iter()
        .any(|token| matches!(token, SqlToken::Symbol(symbol) if symbol == "("))
    {
        return false;
    }

    kind == "TABLE"
        || (kind == "TYPE"
            && tail
                .iter()
                .any(|token| token_word_eq(Some(token), "OBJECT")))
}

fn intellisense_sweep_is_oracle_non_catalog_value_or_definition(
    sql: &str,
    word_start: usize,
    db_type: crate::db::DatabaseType,
) -> bool {
    if db_type != crate::db::DatabaseType::Oracle {
        return false;
    }
    let before_cursor = sql.get(..word_start).unwrap_or("");
    let all_tokens = super::query_text::tokenize_sql_with_mysql_compat(before_cursor, false);
    let start = all_tokens
        .iter()
        .rposition(
            |token| matches!(token, SqlToken::Symbol(symbol) if symbol == ";" || symbol == "/"),
        )
        .map_or(0, |idx| idx + 1);
    let tokens = all_tokens.get(start..).unwrap_or(&[]).to_vec();
    let words = tokens
        .iter()
        .filter_map(|token| token_word_text(Some(token)).map(str::to_ascii_uppercase))
        .collect::<Vec<_>>();
    let previous = words.last().map(String::as_str);
    let first = words.first().map(String::as_str);
    let previous_token = tokens
        .iter()
        .rev()
        .find(|token| !matches!(token, SqlToken::Comment(_)));
    let preceded_by_substitution_marker = sql
        .get(..word_start)
        .is_some_and(|before| before.ends_with('&'));

    previous == Some("TABLESPACE")
        || (matches!(
            words.as_slice(),
            [.., identified, by] if identified == "IDENTIFIED" && by == "BY"
        ) || matches!(
            words.as_slice(),
            [.., identified, by, quote]
                if identified == "IDENTIFIED" && by == "BY" && quote == "\""
        ))
        || (previous == Some("ON")
            && words.iter().any(|word| word == "USER")
            && words.iter().any(|word| word == "QUOTA"))
        || (matches!(first, Some("BREAK" | "COMPUTE"))
            && matches!(previous, Some("ON" | "OF")))
        || first == Some("UNDEFINE")
        || preceded_by_substitution_marker
        || (previous == Some("LABEL")
            && words.windows(2).any(
                |window| matches!(window, [property, graph] if property == "PROPERTY" && graph == "GRAPH"),
            ))
        || (matches!(previous, Some("ADD" | "COLUMN"))
            && matches!(words.as_slice(), [alter, table, ..] if alter == "ALTER" && table == "TABLE"))
        || (matches!(previous_token, Some(SqlToken::Symbol(symbol)) if symbol == ")")
            && words.iter().any(|word| word == "FROM")
            && words.iter().any(|word| word == "PARTITION"))
        || (matches!(previous_token, Some(SqlToken::Symbol(symbol)) if symbol == "(")
            && previous == Some("IN")
            && words.iter().any(|word| word == "STORE"))
        || (matches!(previous_token, Some(SqlToken::Symbol(symbol)) if symbol == "(")
            && words.iter().any(|word| word == "NESTED")
            && words.iter().any(|word| word == "COLUMNS"))
        || (matches!(previous_token, Some(SqlToken::Symbol(symbol)) if symbol == ")")
            && words.iter().any(|word| word == "NESTED")
            && words.iter().any(|word| word == "COLUMNS"))
}

fn intellisense_sweep_is_mysql_type_lead(word: &str) -> bool {
    matches!(
        word.to_ascii_uppercase().as_str(),
        "BIGINT"
            | "BINARY"
            | "BIT"
            | "BLOB"
            | "BOOL"
            | "BOOLEAN"
            | "CHAR"
            | "DATE"
            | "DATETIME"
            | "DEC"
            | "DECIMAL"
            | "DOUBLE"
            | "ENUM"
            | "FLOAT"
            | "INT"
            | "INTEGER"
            | "INET4"
            | "INET6"
            | "JSON"
            | "LONGBLOB"
            | "LONGTEXT"
            | "MEDIUMBLOB"
            | "MEDIUMINT"
            | "MEDIUMTEXT"
            | "BINARY_DOUBLE"
            | "BINARY_FLOAT"
            | "CLOB"
            | "NCLOB"
            | "NCHAR"
            | "NUMBER"
            | "NUMERIC"
            | "NVARCHAR2"
            | "PLS_INTEGER"
            | "RAW"
            | "REFCURSOR"
            | "REAL"
            | "SET"
            | "SMALLINT"
            | "TEXT"
            | "TIME"
            | "TIMESTAMP"
            | "TINYBLOB"
            | "TINYINT"
            | "TINYTEXT"
            | "VARBINARY"
            | "VARCHAR"
            | "VARCHAR2"
            | "VECTOR"
            | "XMLTYPE"
            | "UUID"
            | "YEAR"
    )
}

fn intellisense_sweep_is_mysql_routine_parameter_definition(
    sql: &str,
    cursor: usize,
    word_start: usize,
    db_type: crate::db::DatabaseType,
) -> bool {
    if !crate::sql_text::mysql_compatibility_for_sql("", Some(db_type)) {
        return false;
    }

    let before = sql.get(..word_start).unwrap_or("").to_ascii_uppercase();
    let create_idx = [
        before.rfind("CREATE PROCEDURE"),
        before.rfind("CREATE FUNCTION"),
    ]
    .into_iter()
    .flatten()
    .max();
    let Some(create_idx) = create_idx else {
        return false;
    };
    if before
        .get(create_idx..)
        .is_some_and(|tail| tail.contains("BEGIN"))
    {
        return false;
    }

    let prefix = intellisense_sweep_line_prefix_after_last_separator(sql, word_start);
    if !(prefix.is_empty() || matches!(prefix.as_str(), "IN" | "OUT" | "INOUT")) {
        return false;
    }

    let next = intellisense_sweep_next_meaningful_word(sql, cursor);
    next.as_deref()
        .is_some_and(intellisense_sweep_is_mysql_type_lead)
        || (db_type == crate::db::DatabaseType::MariaDB
            && matches!(next.as_deref(), Some("IN" | "OUT" | "INOUT"))
            && super::query_text::tokenize_sql_with_mysql_compat(
                sql.get(cursor..).unwrap_or(""),
                true,
            )
            .into_iter()
            .filter_map(|token| match token {
                SqlToken::Word(word) => Some(word),
                SqlToken::Comment(_) | SqlToken::String(_) | SqlToken::Symbol(_) => None,
            })
            .nth(1)
            .is_some_and(|word| intellisense_sweep_is_mysql_type_lead(&word)))
}

fn intellisense_sweep_is_mysql_user_variable_assignment_target(
    sql: &str,
    cursor: usize,
    word_start: usize,
    db_type: crate::db::DatabaseType,
) -> bool {
    if !crate::sql_text::mysql_compatibility_for_sql("", Some(db_type))
        || !sql
            .get(..word_start)
            .unwrap_or("")
            .trim_end()
            .ends_with('@')
    {
        return false;
    }

    let tokens = intellisense_sweep_current_statement_tokens_before_cursor(sql, cursor);
    if !tokens
        .iter()
        .find_map(|token| token_word_text(Some(token)))
        .is_some_and(|word| word.eq_ignore_ascii_case("SET"))
    {
        return false;
    }

    cursor <= sql.len()
        && sql
            .get(cursor..)
            .unwrap_or("")
            .trim_start()
            .starts_with('=')
}

fn intellisense_sweep_is_mysql_first_user_variable(
    sql: &str,
    word_start: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
) -> bool {
    if !crate::sql_text::mysql_compatibility_for_sql("", Some(db_type))
        || word_start == 0
        || sql.as_bytes().get(word_start - 1) != Some(&b'@')
    {
        return false;
    }
    let needle = format!("@{}", original_word.trim_matches('`'));
    !sql.get(..word_start - 1)
        .unwrap_or("")
        .to_ascii_uppercase()
        .contains(&needle.to_ascii_uppercase())
}

fn intellisense_sweep_is_mysql_window_name_forward_reference(
    sql: &str,
    cursor: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
) -> bool {
    if !crate::sql_text::mysql_compatibility_for_sql("", Some(db_type)) {
        return false;
    }
    let tokens = intellisense_sweep_current_statement_tokens_before_cursor(sql, cursor);
    let current_idx = tokens.len().saturating_sub(1);
    if !intellisense_sweep_previous_meaningful_word(&tokens, current_idx)
        .is_some_and(|word| word.eq_ignore_ascii_case("OVER"))
    {
        return false;
    }
    let upper_tail = sql.get(cursor..).unwrap_or("").to_ascii_uppercase();
    let name = original_word.trim_matches('`').to_ascii_uppercase();
    upper_tail.contains("WINDOW") && upper_tail.contains(&format!("{name} AS"))
}

fn intellisense_sweep_is_mysql_name_definition_by_previous_word(
    tokens: &[SqlToken],
    current_idx: usize,
    db_type: crate::db::DatabaseType,
) -> bool {
    if !crate::sql_text::mysql_compatibility_for_sql("", Some(db_type)) {
        return false;
    }
    matches!(
        intellisense_sweep_previous_meaningful_word(tokens, current_idx)
            .map(|word| word.to_ascii_uppercase())
            .as_deref(),
        Some("SAVEPOINT" | "PREPARE" | "DECLARE" | "AS" | "WITH" | "RECURSIVE")
    )
}

fn intellisense_sweep_is_cte_name_definition(
    sql: &str,
    cursor: usize,
    _word_start: usize,
    tokens: &[SqlToken],
    current_idx: usize,
) -> bool {
    if !intellisense_sweep_next_meaningful_word(sql, cursor)
        .is_some_and(|word| word.eq_ignore_ascii_case("AS"))
    {
        return false;
    }
    let before_current = tokens
        .get(..current_idx.min(tokens.len()))
        .unwrap_or(tokens);
    let has_with = before_current
        .iter()
        .any(|token| token_word_eq(Some(token), "WITH"));
    if !has_with {
        return false;
    }
    before_current
        .iter()
        .rev()
        .find(|token| !matches!(token, SqlToken::Comment(_)))
        .is_some_and(|token| {
            matches!(token, SqlToken::Symbol(symbol) if symbol == ",")
                || token_word_eq(Some(token), "WITH")
                || token_word_eq(Some(token), "RECURSIVE")
        })
}

fn intellisense_sweep_is_cte_column_definition(
    sql: &str,
    cursor: usize,
    tokens: &[SqlToken],
    current_idx: usize,
) -> bool {
    let next_char = sql.get(cursor..).unwrap_or("").trim_start().chars().next();
    if !matches!(next_char, Some(',' | ')')) {
        return false;
    }
    let before_current = tokens
        .get(..current_idx.min(tokens.len()))
        .unwrap_or(tokens);
    let Some(open_idx) = before_current
        .iter()
        .rposition(|token| matches!(token, SqlToken::Symbol(symbol) if symbol == "("))
    else {
        return false;
    };
    let before_open = before_current.get(..open_idx).unwrap_or(&[]);
    let has_with = before_open
        .iter()
        .any(|token| token_word_eq(Some(token), "WITH"));
    if !has_with {
        return false;
    }
    before_open
        .iter()
        .rev()
        .find(|token| !matches!(token, SqlToken::Comment(_)))
        .is_some_and(|token| matches!(token, SqlToken::Word(_)))
}

fn intellisense_sweep_is_oracle_create_table_column_definition(
    sql: &str,
    cursor: usize,
    word_start: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
) -> bool {
    if crate::sql_text::mysql_compatibility_for_sql("", Some(db_type))
        || !intellisense_sweep_word_starts_line(sql, word_start)
        || crate::sql_text::is_sql_keyword_for_db(&original_word.to_ascii_uppercase(), db_type)
    {
        return false;
    }
    let before = sql.get(..word_start).unwrap_or("").to_ascii_uppercase();
    let Some(create_idx) = before.rfind("CREATE TABLE") else {
        return false;
    };
    if before
        .get(create_idx..)
        .is_some_and(|tail| tail.contains(");"))
    {
        return false;
    }
    intellisense_sweep_next_meaningful_word(sql, cursor).is_some_and(|word| {
        intellisense_sweep_is_mysql_type_lead(&word) || word.eq_ignore_ascii_case("CONSTRAINT")
    })
}

fn intellisense_sweep_is_oracle_routine_parameter_definition(
    sql: &str,
    cursor: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
) -> bool {
    if crate::sql_text::mysql_compatibility_for_sql("", Some(db_type))
        || crate::sql_text::is_sql_keyword_for_db(&original_word.to_ascii_uppercase(), db_type)
    {
        return false;
    }
    let before = sql.get(..cursor).unwrap_or("").to_ascii_uppercase();
    let last_routine = [before.rfind("PROCEDURE"), before.rfind("FUNCTION")]
        .into_iter()
        .flatten()
        .max();
    let Some(routine_idx) = last_routine else {
        return false;
    };
    let tail = before.get(routine_idx..).unwrap_or("");
    if tail.contains(";") || tail.contains("BEGIN") {
        return false;
    }
    let next =
        intellisense_sweep_next_meaningful_word(sql, cursor).map(|word| word.to_ascii_uppercase());
    next.is_some_and(|word| {
        matches!(word.as_str(), "IN" | "OUT" | "INOUT")
            || intellisense_sweep_is_mysql_type_lead(&word)
            || matches!(word.as_str(), "SYS_REFCURSOR" | "TABLE")
    })
}

fn intellisense_sweep_is_sqlplus_definition(
    sql: &str,
    word_start: usize,
    original_word: &str,
) -> bool {
    let line_start = sql
        .get(..word_start)
        .and_then(|text| text.rfind('\n'))
        .map_or(0, |idx| idx + 1);
    let prefix = sql.get(line_start..word_start).unwrap_or("").trim_start();
    let words = prefix
        .split_whitespace()
        .map(|word| word.to_ascii_uppercase())
        .collect::<Vec<_>>();
    words
        .first()
        .is_some_and(|word| matches!(word.as_str(), "VAR" | "VARIABLE" | "DEFINE"))
        && !crate::sql_text::is_sql_keyword_for_db(
            &original_word.to_ascii_uppercase(),
            crate::db::DatabaseType::Oracle,
        )
}

fn intellisense_sweep_is_select_alias_definition(
    sql: &str,
    cursor: usize,
    tokens: &[SqlToken],
    current_idx: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
) -> bool {
    let previous_token = tokens
        .get(..current_idx.min(tokens.len()))
        .unwrap_or(tokens)
        .iter()
        .rev()
        .find(|token| !matches!(token, SqlToken::Comment(_)));
    let before_current = tokens
        .get(..current_idx.min(tokens.len()))
        .unwrap_or(tokens);
    let depths = crate::ui::sql_depth::paren_depths(before_current);
    let current_depth = crate::ui::sql_depth::paren_depth_after(before_current);
    let last_select = before_current
        .iter()
        .enumerate()
        .rfind(|(idx, token)| {
            depths.get(*idx).copied().unwrap_or_default() == current_depth
                && token_word_eq(Some(token), "SELECT")
        })
        .map(|(idx, _)| idx);
    let last_from = before_current
        .iter()
        .enumerate()
        .rfind(|(idx, token)| {
            depths.get(*idx).copied().unwrap_or_default() == current_depth
                && token_word_eq(Some(token), "FROM")
        })
        .map(|(idx, _)| idx);
    let in_select_list = last_select
        .is_some_and(|select_idx| last_from.is_none_or(|from_idx| select_idx > from_idx));
    let tail_starts_alias_boundary = sql
        .get(cursor..)
        .unwrap_or("")
        .trim_start()
        .starts_with([',', ';'])
        || intellisense_sweep_next_meaningful_word(sql, cursor)
            .is_some_and(|word| word.eq_ignore_ascii_case("FROM"));
    if in_select_list
        && tail_starts_alias_boundary
        && previous_token.is_some_and(|token| {
            matches!(
                token,
                SqlToken::Word(_) | SqlToken::String(_) | SqlToken::Symbol(_)
            )
        })
    {
        return true;
    }
    if crate::sql_text::is_sql_keyword_for_db(&original_word.to_ascii_uppercase(), db_type) {
        return false;
    }
    let previous = before_current
        .iter()
        .rev()
        .find(|token| !matches!(token, SqlToken::Comment(_)));
    if matches!(previous, Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("AS"))
        && !SqlEditorWidget::innermost_open_paren_preceding_word(
            before_current,
            before_current.len(),
        )
        .is_some_and(|word| {
            matches!(
                word.to_ascii_uppercase().as_str(),
                "CAST" | "TREAT" | "XMLCAST" | "XMLSERIALIZE" | "VALIDATE_CONVERSION"
            )
        })
    {
        return true;
    }
    let next =
        intellisense_sweep_next_meaningful_word(sql, cursor).map(|word| word.to_ascii_uppercase());
    let next_char = sql.get(cursor..).unwrap_or("").trim_start().chars().next();
    if !matches!(
        next.as_deref(),
        Some(
            "," | "FROM"
                | "WHERE"
                | "GROUP"
                | "HAVING"
                | "ORDER"
                | "MODEL"
                | "UNION"
                | "INTERSECT"
                | "MINUS"
        )
    ) && !matches!(next_char, None | Some(',' | ';' | ')'))
    {
        return false;
    }
    matches!(previous, Some(SqlToken::Symbol(symbol)) if symbol == ")")
        || matches!(previous, Some(SqlToken::Word(word)) if !crate::sql_text::is_sql_keyword_for_db(&word.to_ascii_uppercase(), db_type))
}

fn intellisense_sweep_is_table_function_column_definition(
    sql: &str,
    cursor: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
) -> bool {
    if !intellisense_sweep_next_meaningful_word_after_candidate(
        sql,
        cursor,
        original_word,
        db_type,
    )
    .is_some_and(|word| {
        intellisense_sweep_is_mysql_type_lead(&word) || word.eq_ignore_ascii_case("FOR")
    }) {
        return false;
    }
    let tokens = match db_type {
        crate::db::DatabaseType::MySQL | crate::db::DatabaseType::MariaDB => {
            super::query_text::tokenize_sql_with_mysql_compat(sql.get(..cursor).unwrap_or(""), true)
        }
        crate::db::DatabaseType::Oracle => {
            super::query_text::tokenize_sql(sql.get(..cursor).unwrap_or(""))
        }
    };
    SqlEditorWidget::cursor_is_in_table_function_columns_type(&tokens, tokens.len(), Some(db_type))
        || SqlEditorWidget::innermost_open_paren_preceding_word(&tokens, tokens.len())
            .is_some_and(|word| word.eq_ignore_ascii_case("COLUMNS"))
}

fn intellisense_sweep_is_mysql_label_definition(
    sql: &str,
    cursor: usize,
    db_type: crate::db::DatabaseType,
) -> bool {
    crate::sql_text::mysql_compatibility_for_sql("", Some(db_type))
        && sql
            .get(cursor..)
            .unwrap_or("")
            .trim_start()
            .starts_with(':')
        && intellisense_sweep_next_meaningful_word(sql, cursor).is_some_and(|word| {
            matches!(
                word.to_ascii_uppercase().as_str(),
                "BEGIN" | "LOOP" | "WHILE" | "REPEAT"
            )
        })
}

fn intellisense_sweep_is_temporal_period_name(
    sql: &str,
    cursor: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
) -> bool {
    let original = original_word.trim_matches('`');
    let tokens = super::query_text::tokenize_sql(sql);
    let definition_words = tokens
        .iter()
        .filter_map(|token| token_word_text(Some(token)))
        .collect::<Vec<_>>();
    let declared_elsewhere = definition_words.windows(3).any(|window| {
        window[0].eq_ignore_ascii_case("PERIOD")
            && window[1].eq_ignore_ascii_case("FOR")
            && window[2].eq_ignore_ascii_case(original)
    });
    if declared_elsewhere {
        return true;
    }

    let before = super::query_text::tokenize_sql(sql.get(..cursor).unwrap_or(""));
    let words = before
        .iter()
        .filter_map(|token| token_word_text(Some(token)).map(str::to_ascii_uppercase))
        .collect::<Vec<_>>();
    let original_upper = original.to_ascii_uppercase();
    let period_declaration = words.len() >= 3
        && words
            .get(words.len() - 3)
            .is_some_and(|word| word == "PERIOD")
        && words.get(words.len() - 2).is_some_and(|word| word == "FOR")
        && words
            .last()
            .is_some_and(|word| original_upper.starts_with(word.as_str()))
        && sql
            .get(cursor..)
            .unwrap_or("")
            .trim_start()
            .starts_with('(');
    let period_reference = ((words.len() >= 5
        && words
            .get(words.len() - 5..words.len() - 1)
            .is_some_and(|tail| tail == ["AS", "OF", "PERIOD", "FOR"]))
        || (words.len() >= 4
            && words
                .get(words.len() - 4..words.len() - 1)
                .is_some_and(|tail| tail == ["VERSIONS", "PERIOD", "FOR"])))
        && words
            .last()
            .is_some_and(|word| original_upper.starts_with(word.as_str()));
    let portion_reference = words.len() >= 4
        && words.get(words.len() - 4).is_some_and(|word| word == "FOR")
        && words
            .get(words.len() - 3)
            .is_some_and(|word| word == "PORTION")
        && words.get(words.len() - 2).is_some_and(|word| word == "OF")
        && words
            .last()
            .is_some_and(|word| original_upper.starts_with(word.as_str()))
        && intellisense_sweep_next_meaningful_word(sql, cursor)
            .is_some_and(|word| word.eq_ignore_ascii_case("FROM"));
    period_declaration
        || period_reference
        || (crate::sql_text::mysql_compatibility_for_sql("", Some(db_type)) && portion_reference)
}

fn intellisense_sweep_is_mysql_index_name_definition(
    sql: &str,
    cursor: usize,
    db_type: crate::db::DatabaseType,
) -> bool {
    if !crate::sql_text::mysql_compatibility_for_sql("", Some(db_type))
        || !sql
            .get(cursor..)
            .unwrap_or("")
            .trim_start()
            .starts_with('(')
    {
        return false;
    }
    let tokens = super::query_text::tokenize_sql(sql.get(..cursor).unwrap_or(""));
    let words = tokens
        .iter()
        .filter_map(|token| token_word_text(Some(token)).map(str::to_ascii_uppercase))
        .collect::<Vec<_>>();
    words.len() >= 2
        && words
            .last()
            .is_some_and(|word| !crate::sql_text::is_sql_keyword_for_db(word, db_type))
        && words
            .get(words.len().saturating_sub(2))
            .is_some_and(|word| matches!(word.as_str(), "INDEX" | "KEY"))
}

fn intellisense_sweep_is_mysql_window_name_definition(
    sql: &str,
    cursor: usize,
    db_type: crate::db::DatabaseType,
) -> bool {
    if !crate::sql_text::mysql_compatibility_for_sql("", Some(db_type))
        || !intellisense_sweep_next_meaningful_word(sql, cursor)
            .is_some_and(|word| word.eq_ignore_ascii_case("AS"))
    {
        return false;
    }
    let before = sql.get(..cursor).unwrap_or("").to_ascii_uppercase();
    before.rfind("WINDOW").is_some_and(|window_idx| {
        before
            .rfind("SELECT")
            .is_some_and(|select_idx| select_idx < window_idx)
    })
}

fn intellisense_sweep_is_mysql_handler_index_reference(
    sql: &str,
    cursor: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
) -> bool {
    let tail = sql
        .get(cursor..)
        .unwrap_or("")
        .trim_start_matches(|ch: char| ch.is_whitespace() || matches!(ch, '`' | '"' | ']'));
    let following = tail
        .split(|ch: char| !crate::sql_text::is_identifier_char(ch))
        .next()
        .unwrap_or("");
    if !crate::sql_text::mysql_compatibility_for_sql("", Some(db_type))
        || (!matches!(
            following.to_ascii_uppercase().as_str(),
            "FIRST" | "LAST" | "NEXT" | "PREV"
        ) && !tail.starts_with(['=', '<', '>']))
    {
        return false;
    }
    let words = sql
        .get(..cursor)
        .unwrap_or("")
        .split(|ch: char| !crate::sql_text::is_identifier_char(ch))
        .filter(|word| !word.is_empty())
        .map(str::to_ascii_uppercase)
        .collect::<Vec<_>>();
    matches!(
        words.as_slice(),
        [.., handler, _table, read, partial]
            if handler == "HANDLER"
                && read == "READ"
                && original_word
                    .trim_matches(|ch| matches!(ch, '`' | '"' | '[' | ']'))
                    .to_ascii_uppercase()
                    .starts_with(partial.as_str())
    )
}

fn intellisense_sweep_is_mysql_custom_delimiter_fragment(
    sql: &str,
    word_start: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
) -> bool {
    if !db_type.is_mysql_or_mariadb() {
        return false;
    }
    let delimiter = sql
        .get(..word_start)
        .unwrap_or("")
        .lines()
        .rev()
        .find_map(|line| {
            let mut words = line.split_whitespace();
            words
                .next()
                .is_some_and(|word| word.eq_ignore_ascii_case("DELIMITER"))
                .then(|| words.next().unwrap_or(";").to_string())
        })
        .unwrap_or_else(|| ";".to_string());
    delimiter != ";" && original_word.ends_with(&delimiter)
}

fn intellisense_sweep_is_cte_name_with_column_list_definition(sql: &str, cursor: usize) -> bool {
    let tail_tokens = super::query_text::tokenize_sql(sql.get(cursor..).unwrap_or(""));
    if !matches!(tail_tokens.first(), Some(SqlToken::Symbol(symbol)) if symbol == "(") {
        return false;
    }
    let mut depth = 0usize;
    let mut close_idx = None;
    for (idx, token) in tail_tokens.iter().enumerate() {
        match token {
            SqlToken::Symbol(symbol) if symbol == "(" => depth = depth.saturating_add(1),
            SqlToken::Symbol(symbol) if symbol == ")" => {
                depth = depth.saturating_sub(1);
                if depth == 0 {
                    close_idx = Some(idx);
                    break;
                }
            }
            _ => {}
        }
    }
    let Some(close_idx) = close_idx else {
        return false;
    };
    let followed_by_as = tail_tokens
        .get(close_idx + 1..)
        .unwrap_or(&[])
        .iter()
        .find_map(|token| token_word_text(Some(token)))
        .is_some_and(|word| word.eq_ignore_ascii_case("AS"));
    followed_by_as
        && sql
            .get(..cursor)
            .unwrap_or("")
            .to_ascii_uppercase()
            .contains("WITH")
}

fn intellisense_sweep_is_relation_alias_definition(
    tokens: &[SqlToken],
    current_idx: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
) -> bool {
    let previous_idx = tokens
        .get(..current_idx.min(tokens.len()))
        .unwrap_or(tokens)
        .iter()
        .rposition(|token| !matches!(token, SqlToken::Comment(_)));
    if previous_idx.is_some_and(
        |idx| matches!(tokens.get(idx), Some(SqlToken::Symbol(symbol)) if symbol == ")"),
    ) {
        let close_idx = previous_idx.unwrap_or_default();
        let mut depth = 0usize;
        let open_idx = (0..close_idx).rev().find(|idx| match tokens.get(*idx) {
            Some(SqlToken::Symbol(symbol)) if symbol == ")" => {
                depth += 1;
                false
            }
            Some(SqlToken::Symbol(symbol)) if symbol == "(" => {
                if depth == 0 {
                    true
                } else {
                    depth -= 1;
                    false
                }
            }
            _ => false,
        });
        let table_function_alias = open_idx
            .and_then(|idx| {
                tokens
                    .get(..idx)
                    .unwrap_or(&[])
                    .iter()
                    .rev()
                    .find(|token| !matches!(token, SqlToken::Comment(_)))
            })
            .is_some_and(|token| {
                matches!(
                    token_word_text(Some(token))
                        .map(str::to_ascii_uppercase)
                        .as_deref(),
                    Some("JSON_TABLE" | "XMLTABLE" | "TABLE")
                )
            });
        let derived_query_alias = open_idx.is_some_and(|open_idx| {
            tokens
                .get(open_idx.saturating_add(1)..close_idx)
                .unwrap_or(&[])
                .iter()
                .any(|token| {
                    token_word_eq(Some(token), "SELECT") || token_word_eq(Some(token), "VALUES")
                })
        });
        if table_function_alias || derived_query_alias {
            return true;
        }
    }
    if crate::sql_text::is_sql_keyword_for_db(&original_word.to_ascii_uppercase(), db_type) {
        return false;
    }
    let words = tokens
        .get(..current_idx.min(tokens.len()))
        .unwrap_or(tokens)
        .iter()
        .filter_map(|token| token_word_text(Some(token)).map(|word| word.to_ascii_uppercase()))
        .collect::<Vec<_>>();
    matches!(
        words.iter().rev().nth(1).map(String::as_str),
        Some("FROM" | "JOIN" | "STRAIGHT_JOIN" | "UPDATE" | "INTO" | "TABLE")
    )
}

#[test]
fn intellisense_sweep_skips_plain_relation_alias_definition() {
    use crate::db::DatabaseType::Oracle;

    let script = "WITH events AS (SELECT 1 event_id FROM dual), metric_rows AS (SELECT e.event_id FROM events e CROSS APPLY JSON_TABLE('{}', '$' COLUMNS (value NUMBER PATH '$.value')) j) SELECT * FROM metric_rows";
    let alias_start = script.find("events e CROSS").expect("relation alias") + "events ".len();
    let candidate = IntellisenseSweepCandidate {
        start: alias_start,
        end: alias_start + 1,
        word: "e".to_string(),
        prefix: "e".to_string(),
        replacement: "e".to_string(),
        cursor: alias_start + 1,
    };
    let direct_tokens = super::query_text::tokenize_sql(script.get(..candidate.cursor).unwrap());
    assert!(
        intellisense_sweep_is_relation_alias_definition(
            &direct_tokens,
            direct_tokens.len().saturating_sub(1),
            "e",
            Oracle,
        ),
        "direct alias recognition failed: keyword={} tokens={direct_tokens:?}",
        crate::sql_text::is_sql_keyword_for_db("E", Oracle),
    );
    let result = intellisense_sweep_check_candidate(
        script,
        &ChunkedText::from_str(script),
        Oracle,
        &IntellisenseData::new(),
        &candidate,
    );

    assert!(
        !result.checked && result.missing.is_none(),
        "a newly declared relation alias is not a completion candidate"
    );
}

#[test]
fn intellisense_sweep_skips_literal_select_alias_definitions() {
    use crate::db::DatabaseType::Oracle;

    for (sql, original) in [
        ("SELECT 'x' text__CODEX_CURSOR__ FROM dual", "text_value"),
        ("SELECT 2 erro__CODEX_CURSOR__ FROM dual", "errors"),
        (
            "BEGIN FOR ddl_text IN (SELECT 'DROP TABLE t' text__CODEX_CURSOR__ FROM dual UNION ALL SELECT 'DROP VIEW v' FROM dual) LOOP NULL; END LOOP; END;",
            "text_value",
        ),
        (
            "MERGE INTO t USING (SELECT 'DML' cate__CODEX_CURSOR__, 25 amount FROM dual UNION ALL SELECT 'INSERT', 70 FROM dual) source ON (t.category = source.category) WHEN MATCHED THEN UPDATE SET t.amount = source.amount",
            "category",
        ),
        (
            "SELECT node_id FROM (SELECT 1 node_id, 10 latency, 2 erro__CODEX_CURSOR__ FROM dual) UNPIVOT INCLUDE NULLS (metric_value FOR metric_name IN (latency AS 'LATENCY', errors AS 'ERRORS'))",
            "errors",
        ),
        (
            "SELECT CASE WHEN 1 = 1 THEN 1 ELSE 0 END json__CODEX_CURSOR__, 2 FROM dual",
            "json_exists_value",
        ),
    ] {
        assert!(
            intellisense_sweep_word_skip_context(sql, Oracle, original),
            "SELECT-list alias definition must not be certified as a completion reference: {sql}"
        );
    }
}

#[test]
fn intellisense_sweep_skips_oracle_non_catalog_definition_and_value_slots() {
    use crate::db::DatabaseType::Oracle;

    for (sql, original) in [
        (
            "CREATE TABLE t (id NUMBER) TABLESPACE user__CODEX_CURSOR__",
            "users",
        ),
        (
            "CREATE PROPERTY GRAPH g VERTEX TABLES (t KEY (id) LABEL no__CODEX_CURSOR__ PROPERTIES (id))",
            "node",
        ),
        (
            "SELECT * FROM GRAPH_TABLE (g MATCH (a IS node) -[e IS li__CODEX_CURSOR__]-> (b IS node) COLUMNS (e.cost AS cost))",
            "links",
        ),
        (
            "ALTER TABLE t ADD (crea__CODEX_CURSOR__ TIMESTAMP)",
            "created_at",
        ),
        (
            "CREATE USER c##app IDENTIFIED BY \"Str0ng#Pass__CODEX_CURSOR__\"",
            "Str0ng#Password",
        ),
        (
            "CREATE USER c##app IDENTIFIED BY secret QUOTA 5M ON user__CODEX_CURSOR__",
            "users",
        ),
        (
            "CREATE DOMAIN sq_hard_share__CODEX_CURSOR__ AS NUMBER",
            "sq_hard_share_d",
        ),
    ] {
        assert!(
            intellisense_sweep_word_skip_context(sql, Oracle, original),
            "definition or non-catalog value must not be certified as a completion reference: {sql}"
        );
    }
}

fn intellisense_sweep_is_drop_object_without_create_metadata(
    sql: &str,
    cursor: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
) -> bool {
    let tokens = intellisense_sweep_current_statement_tokens_before_cursor(sql, cursor);
    let words = tokens
        .iter()
        .filter_map(|token| token_word_text(Some(token)).map(|word| word.to_ascii_uppercase()))
        .collect::<Vec<_>>();
    let (kind, has_if_exists) = match words.as_slice() {
        [drop_kw, kind, if_kw, exists_kw, ..]
            if drop_kw == "DROP" && if_kw == "IF" && exists_kw == "EXISTS" =>
        {
            (kind.as_str(), true)
        }
        [drop_kw, kind, ..] if drop_kw == "DROP" => (kind.as_str(), false),
        _ => return false,
    };
    if !has_if_exists
        && (!crate::sql_text::mysql_compatibility_for_sql("", Some(db_type))
            || !matches!(kind, "FUNCTION" | "PROCEDURE" | "TRIGGER" | "EVENT"))
    {
        return false;
    }
    let object_name = original_word.trim_matches(|ch| matches!(ch, '`' | '"'));
    let create_needle = format!("CREATE {kind} {object_name}").to_ascii_uppercase();
    let create_or_replace_needle =
        format!("CREATE OR REPLACE {kind} {object_name}").to_ascii_uppercase();
    let script_upper = sql.to_ascii_uppercase();
    !script_upper.contains(&create_needle) && !script_upper.contains(&create_or_replace_needle)
}

fn intellisense_sweep_is_oracle_graph_pattern_definition(
    tokens_before_word: &[SqlToken],
    sql: &str,
    cursor: usize,
    word_start: usize,
    db_type: crate::db::DatabaseType,
) -> bool {
    if crate::sql_text::mysql_compatibility_for_sql("", Some(db_type)) {
        return false;
    }
    let words = tokens_before_word
        .iter()
        .filter_map(|token| token_word_text(Some(token)).map(str::to_ascii_uppercase))
        .collect::<Vec<_>>();
    let Some(match_idx) = words.iter().rposition(|word| word == "MATCH") else {
        return false;
    };
    if words
        .iter()
        .rposition(|word| word == "COLUMNS")
        .is_some_and(|columns_idx| columns_idx > match_idx)
    {
        return false;
    }
    let previous = tokens_before_word
        .iter()
        .rev()
        .find(|token| !matches!(token, SqlToken::Comment(_)));
    let next =
        intellisense_sweep_next_meaningful_word(sql, cursor).map(|word| word.to_ascii_uppercase());
    let text_previous_word = sql
        .get(..word_start)
        .unwrap_or("")
        .rsplit(|ch: char| !crate::sql_text::is_identifier_char(ch))
        .find(|word| !word.is_empty())
        .map(str::to_ascii_uppercase);
    if matches!(
        previous,
        Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("MATCH")
    ) && sql
        .get(cursor..)
        .unwrap_or("")
        .trim_start()
        .starts_with('=')
    {
        return true;
    }
    (next.as_deref() == Some("IS")
        && !matches!(
            previous,
            Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("MATCH")
        ))
        || matches!(
            previous,
            Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("IS")
        )
        || text_previous_word.as_deref() == Some("IS")
}

fn intellisense_sweep_is_definition_slot(
    sql: &str,
    cursor: usize,
    word_start: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
    deep_ctx: &intellisense_context::CursorContext,
) -> bool {
    let tokens = super::query_text::tokenize_sql(sql.get(..cursor).unwrap_or(""));
    let current_idx = tokens.len().saturating_sub(1);
    let tokens_before_word = super::query_text::tokenize_sql(sql.get(..word_start).unwrap_or(""));
    let original_upper = original_word
        .trim_matches(|ch| matches!(ch, '"' | '`'))
        .to_ascii_uppercase();
    let next_word =
        intellisense_sweep_next_meaningful_word_after_candidate(sql, cursor, original_word, db_type);
    if !crate::sql_text::is_sql_keyword_for_db(&original_upper, db_type) {
        let statement_words = tokens_before_word
            .iter()
            .filter_map(|token| token_word_text(Some(token)).map(str::to_ascii_uppercase))
            .collect::<Vec<_>>();
        let previous_word = statement_words.last().map(String::as_str);
        let statement_has = |word: &str| statement_words.iter().any(|item| item == word);
        let statement_text = sql
            .get(..word_start)
            .unwrap_or("")
            .rsplit_once(';')
            .map_or_else(
                || sql.get(..word_start).unwrap_or(""),
                |(_, statement)| statement,
            )
            .to_ascii_uppercase();
        if (statement_has("ANNOTATIONS")
            && statement_text.matches('(').count() > statement_text.matches(')').count())
            || (statement_has("CREATE")
                && statement_has("DOMAIN")
                && next_word
                    .as_deref()
                    .is_some_and(|word| word.eq_ignore_ascii_case("AS"))
                && statement_text.matches('(').count() > statement_text.matches(')').count())
            || (previous_word == Some("LEVEL")
                && statement_has("ATTRIBUTE")
                && statement_has("DIMENSION"))
            || (next_word
                .as_deref()
                .is_some_and(|word| word.eq_ignore_ascii_case("FACT"))
                && statement_has("ANALYTIC")
                && statement_has("MEASURES"))
            || (previous_word == Some("PARTITION")
                && statement_has("ALTER")
                && statement_has("EXCHANGE"))
            // `PARTITION p0 VALUES LESS THAN (...)` names a partition the
            // statement is creating.
            || (previous_word == Some("PARTITION")
                && next_word
                    .as_deref()
                    .is_some_and(|word| word.eq_ignore_ascii_case("VALUES")))
            // `... MAXVALUE v` binds the flashback row source to a new alias.
            || (matches!(previous_word, Some("MAXVALUE" | "MINVALUE"))
                && statement_has("VERSIONS"))
            // `CREATE CLUSTER c (cluster_key NUMBER)` declares the cluster key.
            || (statement_has("CREATE")
                && statement_has("CLUSTER")
                && statement_text.matches('(').count() > statement_text.matches(')').count())
            // `RENAME COLUMN old TO new` introduces the new column name.
            || (previous_word == Some("TO")
                && statement_has("RENAME")
                && statement_has("COLUMN"))
            || (matches!(
                tokens_before_word.last(),
                Some(SqlToken::Symbol(symbol)) if symbol == "."
            ) && sql.get(cursor..).unwrap_or("").trim_start().starts_with('.')
                && next_word.as_deref().is_some_and(|word| {
                    matches!(
                        word.to_ascii_uppercase().as_str(),
                        "BOOLEAN" | "DATE" | "NUMBER" | "SIZE" | "STRING" | "TIMESTAMP" | "TYPE"
                    )
                }))
        {
            return true;
        }
    }

    if db_type == crate::db::DatabaseType::MariaDB {
        let statement_words = tokens_before_word
            .iter()
            .filter_map(|token| token_word_text(Some(token)).map(str::to_ascii_uppercase))
            .collect::<Vec<_>>();
        let previous_word = statement_words.last().map(String::as_str);
        let creates_package = statement_words.iter().any(|word| word == "CREATE")
            && statement_words.iter().any(|word| word == "PACKAGE");
        let next_is_routine_tail = sql
            .get(cursor..)
            .unwrap_or("")
            .trim_start_matches(|ch: char| ch.is_whitespace() || ch == '`')
            .starts_with('(')
            || next_word.as_deref().is_some_and(|word| {
                matches!(word.to_ascii_uppercase().as_str(), "RETURNS" | "AS" | "IS")
            });
        if creates_package
            && matches!(previous_word, Some("PROCEDURE" | "FUNCTION"))
            && next_is_routine_tail
        {
            return true;
        }
    }

    // A MySQL block label (`LEAVE wrapper` / `END wrapper`) names the enclosing
    // labelled block. The completion snapshot for a routine's *inner* statement
    // does not span that enclosing block, so the label is not reachable from the
    // slot's analysis window - a property of the window, not a missing source.
    if matches!(
        db_type,
        crate::db::DatabaseType::MySQL | crate::db::DatabaseType::MariaDB
    ) {
        let previous_upper = tokens_before_word
            .iter()
            .rev()
            .find_map(|token| token_word_text(Some(token)))
            .map(str::to_ascii_uppercase);
        if matches!(
            previous_upper.as_deref(),
            Some("LEAVE") | Some("ITERATE") | Some("END")
        ) {
            return true;
        }
    }

    // An inquiry directive (`$$my_flag`) names a PL/SQL conditional-compilation
    // flag that lives in a session setting, not in any catalog, so a user-defined
    // one cannot be completed from metadata.
    if original_word.starts_with("$$") {
        return true;
    }

    // A quoted / backtick identifier is a name the author types explicitly, so
    // it is never "completed" when it introduces a brand-new object. This covers
    // reserved words used as identifiers (`CREATE TABLE `select``, a PL/SQL
    // `"BEGIN" PLS_INTEGER` declaration), which the keyword-guarded rules below
    // deliberately skip. The engine already returns nothing at these slots; this
    // records that the empty result is correct rather than a gap.
    let word_is_quoted = original_word.starts_with('"') || original_word.starts_with('`');
    if word_is_quoted {
        let stmt_start = tokens_before_word
            .iter()
            .rposition(|token| matches!(token, SqlToken::Symbol(sym) if sym == ";"))
            .map_or(0, |idx| idx + 1);
        let segment = &tokens_before_word[stmt_start..];
        let segment_first_word = segment.iter().find_map(|token| match token {
            SqlToken::Word(word) => Some(word.to_ascii_uppercase()),
            _ => None,
        });
        let segment_last_meaningful = segment
            .iter()
            .rev()
            .find(|token| !matches!(token, SqlToken::Comment(_)));
        const CREATE_NAME_INTRODUCERS: &[&str] = &[
            "TABLE",
            "VIEW",
            "INDEX",
            "SEQUENCE",
            "EVENT",
            "TRIGGER",
            "PROCEDURE",
            "FUNCTION",
            "PACKAGE",
            "TYPE",
            "DATABASE",
            "SCHEMA",
            "ROLE",
            "USER",
            "SYNONYM",
            "EXISTS",
        ];
        // `CREATE <object-type> "quoted new name"`.
        if segment_first_word.as_deref() == Some("CREATE")
            && matches!(
                segment_last_meaningful,
                Some(SqlToken::Word(word))
                    if CREATE_NAME_INTRODUCERS.contains(&word.to_ascii_uppercase().as_str())
            )
        {
            return true;
        }
        // A quoted identifier that opens a statement and is followed by another
        // word is a PL/SQL declaration name (`"BEGIN" PLS_INTEGER := 0;`).
        if segment_last_meaningful.is_none() && next_word.is_some() {
            return true;
        }
        let text_before_word = sql.get(..word_start).unwrap_or("");
        let immediately_preceding = text_before_word.chars().next_back();
        let numeric_trailing_dot = immediately_preceding == Some('.')
            && text_before_word
                .get(..text_before_word.len().saturating_sub(1))
                .and_then(|head| head.chars().next_back())
                .is_some_and(|ch| ch.is_ascii_digit());
        let tail_after_identifier = sql
            .get(cursor..)
            .unwrap_or("")
            .trim_start_matches(|ch: char| ch.is_whitespace() || matches!(ch, '"' | '`'));
        let followed_by_projection_boundary = tail_after_identifier.starts_with([',', ';'])
            || tail_after_identifier
                .get(.."FROM".len().min(tail_after_identifier.len()))
                .is_some_and(|word| word.eq_ignore_ascii_case("FROM"))
            || next_word
                .as_deref()
                .is_some_and(|word| word.eq_ignore_ascii_case("FROM"));
        if (immediately_preceding
            .is_some_and(|ch| !ch.is_whitespace() && !matches!(ch, ',' | '(' | '.'))
            || numeric_trailing_dot)
            && followed_by_projection_boundary
        {
            return true;
        }
    }

    // A character-set introducer glued to a string literal (`_utf8mb4'…'`) is
    // literal syntax, not a completion slot.
    if original_word.starts_with('_')
        && sql
            .get(cursor..)
            .unwrap_or("")
            .trim_start_matches(|ch: char| ch.is_alphanumeric() || ch == '_')
            .starts_with('\'')
    {
        return true;
    }
    if original_word.starts_with('_') {
        let tail_after_introducer = sql
            .get(cursor..)
            .unwrap_or("")
            .trim_start_matches(|ch: char| ch.is_alphanumeric() || ch == '_')
            .trim_start();
        if tail_after_introducer.get(..2).is_some_and(|prefix| {
            prefix.eq_ignore_ascii_case("0x") || prefix.eq_ignore_ascii_case("0b")
        }) {
            return true;
        }

        let tail = sql.get(cursor..).unwrap_or("").trim_start();
        if tail
            .chars()
            .next()
            .is_some_and(|ch| matches!(ch, 'B' | 'N' | 'X' | 'b' | 'n' | 'x'))
            && tail.get(1..).unwrap_or("").trim_start().starts_with('\'')
        {
            return true;
        }
    }

    // The RHS of a `COLLATE` operator is a collation name drawn from the live
    // catalog (see `operand_type_operators_match_the_preceding_operand_type`,
    // which pins the slot as catalog-only). The sweep's file-inferred catalog
    // carries no collations, so an empty result here is expected, not a gap.
    if matches!(
        tokens_before_word
            .iter()
            .rev()
            .find(|token| !matches!(token, SqlToken::Comment(_))),
        Some(SqlToken::Word(word)) if word.eq_ignore_ascii_case("COLLATE")
    ) {
        return true;
    }

    if matches!(
        deep_ctx.phase,
        intellisense_context::SqlPhase::DerivedAliasColumnList
    ) {
        return true;
    }

    if intellisense_sweep_is_oracle_graph_pattern_definition(
        &tokens_before_word,
        sql,
        cursor,
        word_start,
        db_type,
    ) {
        return true;
    }

    let next_is_type = next_word
        .as_deref()
        .is_some_and(intellisense_sweep_is_mysql_type_lead);
    if next_is_type
        && (intellisense_sweep_word_starts_line(sql, word_start)
            || SqlEditorWidget::cursor_is_inside_routine_param_list(
                &tokens_before_word,
                tokens_before_word.len(),
            )
            || (crate::sql_text::mysql_compatibility_for_sql("", Some(db_type))
                && SqlEditorWidget::innermost_open_paren_preceding_word(
                    &tokens_before_word,
                    tokens_before_word.len(),
                )
                .is_some_and(|word| word.eq_ignore_ascii_case("CURSOR"))))
    {
        return true;
    }
    if !crate::sql_text::is_sql_keyword_for_db(&original_upper, db_type)
        && intellisense_sweep_word_starts_line(sql, word_start)
        && next_word.as_deref().is_some_and(|type_name| {
            tokens_before_word.windows(2).any(|window| {
                token_word_eq(window.first(), "TYPE")
                    && token_word_text(window.get(1))
                        .is_some_and(|declared| declared.eq_ignore_ascii_case(type_name))
            })
        })
    {
        return true;
    }
    if !crate::sql_text::is_sql_keyword_for_db(&original_upper, db_type)
        && next_is_type
        && matches!(
            tokens_before_word
                .iter()
                .rev()
                .find(|token| !matches!(token, SqlToken::Comment(_))),
            Some(SqlToken::Symbol(symbol)) if matches!(symbol.as_str(), "(" | ",")
        )
    {
        let words_before = tokens_before_word
            .iter()
            .filter_map(|token| token_word_text(Some(token)).map(|word| word.to_ascii_uppercase()))
            .collect::<Vec<_>>();
        if words_before.windows(2).any(
            |window| matches!(window, [create, table] if create == "CREATE" && table == "TABLE"),
        ) {
            return true;
        }
    }
    if !crate::sql_text::is_sql_keyword_for_db(&original_upper, db_type)
        && sql
            .get(cursor..)
            .unwrap_or("")
            .trim_start()
            .starts_with('(')
    {
        let previous = intellisense_sweep_previous_meaningful_word(&tokens, current_idx);
        if previous.is_some_and(|word| {
            word.eq_ignore_ascii_case("WITH") || word.eq_ignore_ascii_case("RECURSIVE")
        }) {
            return true;
        }
    }
    let before_upper = sql.get(..word_start).unwrap_or("").to_ascii_uppercase();
    let statement_start = before_upper
        .rfind(';')
        .map_or(0, |idx| idx.saturating_add(1));
    let statement_tail = before_upper.get(statement_start..).unwrap_or("");
    if statement_tail.rfind("PATTERN").is_some_and(|pattern_idx| {
        statement_tail
            .rfind("DEFINE")
            .is_none_or(|define_idx| pattern_idx > define_idx)
    }) && statement_tail.matches('(').count() > statement_tail.matches(')').count()
    {
        return true;
    }
    if !crate::sql_text::is_sql_keyword_for_db(&original_upper, db_type)
        && statement_tail.rfind("UNPIVOT").is_some()
        && statement_tail.matches('(').count() > statement_tail.matches(')').count()
    {
        return true;
    }
    if original_word.starts_with('"')
        && original_word.ends_with('"')
        && SqlEditorWidget::innermost_open_paren_preceding_word(
            &tokens_before_word,
            tokens_before_word.len(),
        )
        .is_some_and(|word| word.eq_ignore_ascii_case("XMLELEMENT"))
    {
        return true;
    }
    if !crate::sql_text::mysql_compatibility_for_sql("", Some(db_type))
        && !crate::sql_text::is_sql_keyword_for_db(&original_upper, db_type)
        && SqlEditorWidget::cursor_is_at_plsql_declaration_start(
            &tokens_before_word,
            tokens_before_word.len(),
            Some(db_type),
        )
        && intellisense_sweep_next_meaningful_word(sql, cursor).is_some()
    {
        return true;
    }
    if !crate::sql_text::mysql_compatibility_for_sql("", Some(db_type))
        && SqlEditorWidget::innermost_open_paren_preceding_word(
            &tokens_before_word,
            tokens_before_word.len(),
        )
        .is_some_and(|word| matches!(word.to_ascii_uppercase().as_str(), "OBJECT" | "RECORD"))
        && matches!(
            tokens_before_word
                .iter()
                .rev()
                .find(|token| !matches!(token, SqlToken::Comment(_))),
            Some(SqlToken::Symbol(symbol)) if matches!(symbol.as_str(), "(" | ",")
        )
    {
        return true;
    }
    if intellisense_sweep_previous_meaningful_word(&tokens, current_idx)
        .is_some_and(|word| word.eq_ignore_ascii_case("SAVEPOINT"))
    {
        let statement_start = tokens
            .get(..current_idx.min(tokens.len()))
            .unwrap_or(&[])
            .iter()
            .rposition(|token| matches!(token, SqlToken::Symbol(symbol) if symbol == ";"))
            .map_or(0, |idx| idx + 1);
        if !tokens
            .get(statement_start..current_idx.min(tokens.len()))
            .unwrap_or(&[])
            .iter()
            .any(|token| token_word_eq(Some(token), "ROLLBACK"))
        {
            return true;
        }
    }
    if !crate::sql_text::is_sql_keyword_for_db(&original_upper, db_type) {
        let previous_word = intellisense_sweep_previous_meaningful_word(&tokens, current_idx)
            .map(str::to_ascii_uppercase);
        let next_is_open_paren = sql
            .get(cursor..)
            .unwrap_or("")
            .trim_start()
            .starts_with('(');
        if previous_word
            .as_deref()
            .is_some_and(|word| matches!(word, "FUNCTION" | "PROCEDURE"))
            && (next_is_open_paren
                || next_word.as_deref().is_some_and(|word| {
                    matches!(word.to_ascii_uppercase().as_str(), "RETURN" | "IS" | "AS")
                }))
        {
            return true;
        }
        if previous_word.as_deref() == Some("SET") {
            let before_upper = sql.get(..word_start).unwrap_or("").to_ascii_uppercase();
            if before_upper.rfind("WITH").is_some_and(|with_idx| {
                before_upper
                    .get(with_idx..)
                    .is_some_and(|tail| tail.contains("SEARCH") || tail.contains("CYCLE"))
            }) {
                return true;
            }
        }
    }
    if intellisense_sweep_is_mysql_name_definition_by_previous_word(&tokens, current_idx, db_type) {
        return true;
    }
    if db_type.is_mysql_or_mariadb()
        && intellisense_sweep_previous_meaningful_word(&tokens, current_idx)
            .is_some_and(|word| word.eq_ignore_ascii_case("SUBPARTITION"))
        && tokens_before_word.windows(2).any(|words| {
            token_word_eq(words.first(), "CREATE") && token_word_eq(words.get(1), "TABLE")
        })
    {
        return true;
    }
    if intellisense_sweep_is_cte_name_definition(sql, cursor, word_start, &tokens, current_idx) {
        return true;
    }
    if intellisense_sweep_is_cte_column_definition(sql, cursor, &tokens, current_idx) {
        return true;
    }
    if intellisense_sweep_is_oracle_create_table_column_definition(
        sql,
        cursor,
        word_start,
        original_word,
        db_type,
    ) {
        return true;
    }
    if intellisense_sweep_is_oracle_routine_parameter_definition(
        sql,
        cursor,
        original_word,
        db_type,
    ) {
        return true;
    }
    if intellisense_sweep_is_sqlplus_definition(sql, word_start, original_word) {
        return true;
    }
    if intellisense_sweep_is_select_alias_definition(
        sql,
        cursor,
        &tokens,
        current_idx,
        original_word,
        db_type,
    ) {
        return true;
    }
    if intellisense_sweep_is_table_function_column_definition(
        sql,
        cursor,
        original_word,
        db_type,
    ) {
        return true;
    }
    if intellisense_sweep_is_mysql_label_definition(sql, cursor, db_type) {
        return true;
    }
    if intellisense_sweep_is_temporal_period_name(sql, cursor, original_word, db_type) {
        return true;
    }
    if intellisense_sweep_is_mysql_index_name_definition(sql, cursor, db_type) {
        return true;
    }
    if intellisense_sweep_is_mysql_window_name_definition(sql, cursor, db_type) {
        return true;
    }
    if intellisense_sweep_is_mysql_handler_index_reference(sql, cursor, original_word, db_type) {
        return true;
    }
    if intellisense_sweep_is_cte_name_with_column_list_definition(sql, cursor) {
        return true;
    }
    if intellisense_sweep_is_relation_alias_definition(&tokens, current_idx, original_word, db_type)
    {
        return true;
    }
    if intellisense_sweep_is_drop_object_without_create_metadata(
        sql,
        cursor,
        original_word,
        db_type,
    ) {
        return true;
    }
    if intellisense_sweep_is_mysql_first_user_variable(sql, word_start, original_word, db_type) {
        return true;
    }
    if intellisense_sweep_is_mysql_window_name_forward_reference(
        sql,
        cursor,
        original_word,
        db_type,
    ) {
        return true;
    }
    if intellisense_sweep_previous_meaningful_word(&tokens, current_idx)
        .is_some_and(|word| word.eq_ignore_ascii_case("CONSTRAINT"))
    {
        return true;
    }
    if intellisense_sweep_previous_meaningful_word(&tokens, current_idx)
        .is_some_and(|word| word.eq_ignore_ascii_case("END"))
        && tokens
            .get(..current_idx.min(tokens.len()))
            .unwrap_or(&[])
            .iter()
            .rev()
            .find_map(|token| {
                token_word_text(Some(token)).and_then(|word| {
                    matches!(
                        word.to_ascii_uppercase().as_str(),
                        "TRIGGER" | "PROCEDURE" | "FUNCTION" | "PACKAGE"
                    )
                    .then(|| word.to_ascii_uppercase())
                })
            })
            .is_some_and(|kind| kind == "TRIGGER")
    {
        return true;
    }
    if intellisense_sweep_previous_meaningful_word(&tokens, current_idx)
        .is_some_and(|word| word.eq_ignore_ascii_case("FOR") || word.eq_ignore_ascii_case("FORALL"))
        && intellisense_sweep_next_meaningful_word(sql, cursor)
            .is_some_and(|word| word.eq_ignore_ascii_case("IN"))
    {
        return true;
    }
    if intellisense_sweep_is_create_element_name_definition(sql, cursor, word_start, original_word)
    {
        return true;
    }
    if intellisense_sweep_is_mysql_routine_parameter_definition(sql, cursor, word_start, db_type) {
        return true;
    }
    if intellisense_sweep_is_mysql_user_variable_assignment_target(sql, cursor, word_start, db_type)
    {
        return true;
    }

    if crate::sql_text::is_sql_keyword_for_db(&original_upper, db_type)
        || !intellisense_sweep_word_starts_line(sql, word_start)
    {
        return false;
    }

    let statement_tokens = deep_ctx.statement_tokens.as_ref();
    let statement_end = SqlEditorWidget::expected_suggestion_context_end(
        statement_tokens,
        deep_ctx.cursor_token_len,
        true,
    );
    if !SqlEditorWidget::cursor_is_in_plsql_declaration_region(statement_tokens, statement_end) {
        return false;
    }

    intellisense_sweep_next_meaningful_word(sql, cursor).is_some()
}

fn intellisense_sweep_is_out_of_scope_relation_qualifier(
    sql: &str,
    cursor: usize,
    word_start: usize,
    original_word: &str,
    deep_ctx: &intellisense_context::CursorContext,
) -> bool {
    let qualifier = if sql.get(cursor..).is_some_and(|tail| tail.starts_with('.')) {
        original_word
            .trim_matches(|ch| matches!(ch, '"' | '`' | '[' | ']'))
            .to_string()
    } else {
        let Some(qualifier) = SqlEditorWidget::qualifier_before_word_in_text(sql, word_start)
        else {
            return false;
        };
        qualifier
    };
    if !intellisense_context::resolve_qualifier_tables(&qualifier, &deep_ctx.tables_in_scope)
        .is_empty()
    {
        return false;
    }

    intellisense_context::collect_tables_in_statement_declared_before_cursor(
        deep_ctx.statement_tokens.as_ref(),
        deep_ctx.statement_tokens.len(),
    )
    .iter()
    .any(|table| {
        table
            .alias
            .as_deref()
            .is_some_and(|alias| alias.eq_ignore_ascii_case(&qualifier))
    })
}

fn intellisense_sweep_mysql_double_quoted_string(
    sql: &str,
    word_start: usize,
    original_word: &str,
    db_type: crate::db::DatabaseType,
) -> bool {
    if !db_type.is_mysql_or_mariadb()
        || !original_word.starts_with('"')
        || !original_word.ends_with('"')
    {
        return false;
    }

    let tokens = super::query_text::tokenize_sql_with_mysql_compat(
        sql.get(..word_start).unwrap_or(sql),
        true,
    );
    let mut ansi_quotes = false;
    for (idx, token) in tokens.iter().enumerate() {
        if !token_word_eq(Some(token), "SQL_MODE") {
            continue;
        }
        let statement_start = tokens
            .get(..idx)
            .unwrap_or(&[])
            .iter()
            .rposition(|token| matches!(token, SqlToken::Symbol(symbol) if symbol == ";"))
            .map_or(0, |idx| idx + 1);
        if !tokens
            .get(statement_start..idx)
            .unwrap_or(&[])
            .iter()
            .any(|token| token_word_eq(Some(token), "SET"))
        {
            continue;
        }
        let statement_end = tokens
            .iter()
            .enumerate()
            .skip(idx + 1)
            .find_map(|(idx, token)| {
                matches!(token, SqlToken::Symbol(symbol) if symbol == ";").then_some(idx)
            })
            .unwrap_or(tokens.len());
        if let Some(mode) = tokens
            .get(idx + 1..statement_end)
            .unwrap_or(&[])
            .iter()
            .find_map(|token| match token {
                SqlToken::String(value) => Some(value),
                _ => None,
            })
        {
            ansi_quotes = mode
                .split(',')
                .any(|mode| mode.trim().eq_ignore_ascii_case("ANSI_QUOTES"));
        }
    }

    !ansi_quotes
}

fn intellisense_sweep_word_skip_context(
    script_with_cursor: &str,
    db_type: crate::db::DatabaseType,
    original_word: &str,
) -> bool {
    const MARKER: &str = "__CODEX_CURSOR__";
    let Some(cursor) = script_with_cursor.find(MARKER) else {
        return true;
    };
    let sql = script_with_cursor.replacen(MARKER, "", 1);
    let snapshot = ChunkedText::from_str(&sql);
    let (_, analysis) = intellisense_analysis_from_snapshot_for_test(&snapshot, cursor, db_type);
    intellisense_sweep_word_skip_context_from_analysis(
        &sql,
        cursor,
        db_type,
        original_word,
        &analysis,
    )
}

fn intellisense_sweep_word_skip_context_from_analysis(
    sql: &str,
    cursor: usize,
    db_type: crate::db::DatabaseType,
    original_word: &str,
    analysis: &IntellisenseAnalysis,
) -> bool {
    let deep_ctx = analysis.context.as_ref();
    let (prefix, word_start, _) = crate::ui::intellisense::get_word_at_cursor(sql, cursor);
    let cursor_lex_mode = intellisense_test_lex_mode_at(sql, cursor, db_type.is_mysql_or_mariadb());
    let cursor_in_literal_or_comment = matches!(
        cursor_lex_mode,
        crate::sql_parser_engine::LexMode::SingleQuote
            | crate::sql_parser_engine::LexMode::LineComment
            | crate::sql_parser_engine::LexMode::BlockComment
            | crate::sql_parser_engine::LexMode::QQuote { .. }
            | crate::sql_parser_engine::LexMode::DollarQuote { .. }
    );

    cursor_in_literal_or_comment
        || intellisense_sweep_mysql_double_quoted_string(
            sql,
            word_start,
            original_word,
            db_type,
        )
        || analysis.cursor_in_alias_declaration
        || deep_ctx.ddl_new_name_position
        || intellisense_sweep_is_mysql_custom_delimiter_fragment(
            sql,
            word_start,
            original_word,
            db_type,
        )
        || intellisense_sweep_is_out_of_scope_relation_qualifier(
            sql,
            cursor,
            word_start,
            original_word,
            deep_ctx,
        )
        || SqlEditorWidget::cursor_is_at_create_object_new_name(
            deep_ctx,
            true,
            Some(db_type),
        )
        || SqlEditorWidget::cursor_is_at_rename_target_new_name_slot_for_context(deep_ctx, true)
        || SqlEditorWidget::cursor_is_at_ddl_partition_new_name_slot_for_context(deep_ctx, true)
        || SqlEditorWidget::cursor_is_at_ddl_table_index_new_name_slot_for_context(deep_ctx, true)
        || SqlEditorWidget::cursor_is_at_create_view_column_alias_list_slot_for_context(
            deep_ctx, true,
        )
        || SqlEditorWidget::cursor_is_inside_post_table_modifier_value_slot_for_context(deep_ctx, true)
        || SqlEditorWidget::cursor_is_at_mysql_oracle_only_ddl_value_slot_for_context(
            deep_ctx,
            true,
            Some(db_type),
        )
        || SqlEditorWidget::cursor_is_at_plsql_named_end_target_slot_for_context(
            deep_ctx,
            true,
            Some(db_type),
        )
        || SqlEditorWidget::cursor_is_at_plsql_declaration_object_name_slot_for_context(
            deep_ctx,
            true,
            Some(db_type),
        )
        // A routine parameter name is a brand-new name. The production predicate
        // knows the whole parameter list shape, so it also covers parameters typed
        // with a user-defined type (`other money_t`), which the text heuristics
        // below only recognize for built-in type leads.
        || SqlEditorWidget::cursor_is_at_plsql_routine_parameter_name_slot_for_context(
            deep_ctx,
            true,
            Some(db_type),
        )
        // `ALTER TYPE t ADD ATTRIBUTE (name …)` introduces the attribute name.
        || SqlEditorWidget::cursor_is_at_alter_type_attribute_name_slot_for_context(deep_ctx, true)
        || SqlEditorWidget::cursor_is_at_oracle_create_dimension_declaration_name_slot_for_context(
            deep_ctx,
            true,
            Some(db_type),
        )
        || (SqlEditorWidget::cursor_is_at_ddl_identifier_suppression_slot_for_context(
            deep_ctx, true,
        ) && !matches!(
            SqlEditorWidget::expected_object_suggestion_kind_for_db(
                &prefix,
                None,
                deep_ctx,
                Some(db_type),
            ),
            Some(ExpectedObjectSuggestionKind::Constraint)
        ))
        || intellisense_sweep_is_oracle_non_catalog_value_or_definition(
            sql,
            word_start,
            db_type,
        )
        || intellisense_sweep_is_tool_free_form_value(sql, word_start)
        || intellisense_sweep_is_definition_slot(
            sql,
            cursor,
            word_start,
            original_word,
            db_type,
            deep_ctx,
        )
}

fn intellisense_sweep_is_tool_free_form_value(sql: &str, word_start: usize) -> bool {
    let line_start = sql
        .get(..word_start)
        .and_then(|text| text.rfind('\n'))
        .map_or(0, |idx| idx + 1);
    let line_end = sql
        .get(word_start..)
        .and_then(|text| text.find('\n'))
        .map_or(sql.len(), |idx| word_start + idx);
    let line = sql.get(line_start..line_end).unwrap_or("");
    let relative_start = word_start.saturating_sub(line_start);
    let spans = super::query_text::tokenize_sql_spanned(line);
    let Some(candidate_idx) = spans
        .iter()
        .position(|span| span.start <= relative_start && relative_start < span.end)
    else {
        return false;
    };
    let meaningful = spans
        .iter()
        .enumerate()
        .filter(|(_, span)| !matches!(span.token, SqlToken::Comment(_)))
        .collect::<Vec<_>>();
    let Some(position) = meaningful
        .iter()
        .position(|(span_idx, _)| *span_idx == candidate_idx)
    else {
        return false;
    };
    let head = meaningful.first().and_then(|(_, span)| match &span.token {
        SqlToken::Word(word) => Some(word.as_str()),
        _ => None,
    });
    if head.is_some_and(|word| word.eq_ignore_ascii_case("COLUMN")) {
        if position == 1 {
            return true;
        }
        return meaningful
            .get(position.saturating_sub(1))
            .and_then(|(_, span)| match &span.token {
                SqlToken::Word(word) => Some(word.as_str()),
                _ => None,
            })
            .is_some_and(|word| word.eq_ignore_ascii_case("FORMAT"));
    }
    false
}

fn intellisense_sweep_render_out(
    script: &str,
    checked: usize,
    suggestions_checked: usize,
    missing: &[IntellisenseSweepMissing],
    untyped_suggestions: &[IntellisenseSweepUntypedSuggestion],
    source_label: &str,
    db_type: crate::db::DatabaseType,
    metadata_label: Option<&str>,
) -> String {
    let mut output = String::with_capacity(
        script.len() + missing.len() * 96 + untyped_suggestions.len() * 96 + 640,
    );
    let mut cursor = 0usize;
    for miss in missing {
        output.push_str(script.get(cursor..miss.start).unwrap_or(""));
        output.push_str("[[");
        output.push_str(script.get(miss.start..miss.end).unwrap_or(&miss.word));
        output.push_str("]]");
        cursor = miss.end;
    }
    output.push_str(script.get(cursor..).unwrap_or(""));

    output.push_str("\n\n-- =========================================================\n");
    output.push_str("-- IntelliSense sweep report generated by intellisense sweep\n");
    output.push_str(&format!("-- source: {source_label}\n"));
    output.push_str(&format!("-- db: {db_type:?}\n"));
    if let Some(metadata_label) = metadata_label {
        output.push_str(&format!("-- metadata: {metadata_label}\n"));
    }
    output.push_str(&format!("-- checked: {checked}\n"));
    output.push_str(&format!("-- suggestions checked: {suggestions_checked}\n"));
    output.push_str(&format!("-- missing: {}\n", missing.len()));
    output.push_str(&format!(
        "-- suggestions without type labels: {}\n",
        untyped_suggestions.len()
    ));
    output.push_str("-- marker: [[word]] means not suggested for the tested prefix\n");
    if missing.is_empty() {
        output.push_str("-- missing tokens: none\n");
    } else {
        output.push_str("-- missing tokens:\n");
        for miss in missing {
            let suggestions = if miss.suggestion_sample.is_empty() {
                "[]".to_string()
            } else {
                format!("[{}]", miss.suggestion_sample.join(", "))
            };
            output.push_str(&format!(
                "--   {}:{} word={} prefix={} suggestions={} total={} line={}\n",
                miss.line,
                miss.column,
                miss.word,
                miss.prefix,
                suggestions,
                miss.suggestion_count,
                intellisense_sweep_line_text(script, miss.start)
            ));
        }
    }
    if untyped_suggestions.is_empty() {
        output.push_str("-- suggestions without type labels: none\n");
    } else {
        output.push_str("-- suggestions without type labels:\n");
        for untyped in untyped_suggestions {
            output.push_str(&format!(
                "--   {}:{} word={} prefix={} suggestion={} line={}\n",
                untyped.line,
                untyped.column,
                untyped.word,
                untyped.prefix,
                untyped.suggestion,
                intellisense_sweep_line_text(script, untyped.start)
            ));
        }
    }
    output.push_str("-- =========================================================\n");
    output
}

fn intellisense_sweep_panic_payload_text(err: &(dyn std::any::Any + Send)) -> String {
    if let Some(message) = err.downcast_ref::<&str>() {
        return (*message).to_string();
    }
    if let Some(message) = err.downcast_ref::<String>() {
        return message.clone();
    }
    "panic".to_string()
}

fn intellisense_sweep_check_candidate(
    script: &str,
    base_snapshot: &ChunkedText,
    db_type: crate::db::DatabaseType,
    base_data: &IntellisenseData,
    candidate: &IntellisenseSweepCandidate,
) -> IntellisenseSweepCandidateResult {
    let mysql_compatible = db_type.is_mysql_or_mariadb();
    let lexical_spans = crate::sql_parser_engine::lexical_spans(script, mysql_compatible);
    let file_index = IntellisenseSweepFileIndex::new(script, base_snapshot, db_type, lexical_spans);
    let worker = IntellisenseSweepWorkerResources::new(base_data);
    intellisense_sweep_check_candidate_with_resources(
        script,
        base_snapshot,
        db_type,
        candidate,
        &file_index,
        &worker,
    )
}

fn intellisense_sweep_check_candidate_with_resources(
    script: &str,
    base_snapshot: &ChunkedText,
    db_type: crate::db::DatabaseType,
    candidate: &IntellisenseSweepCandidate,
    file_index: &IntellisenseSweepFileIndex,
    worker: &IntellisenseSweepWorkerResources,
) -> IntellisenseSweepCandidateResult {
    if intellisense_sweep_is_mysql_custom_delimiter_fragment(
        script,
        candidate.start,
        &candidate.word,
        db_type,
    ) {
        return IntellisenseSweepCandidateResult {
            checked: false,
            suggestions_checked: 0,
            missing: None,
            untyped_suggestions: Vec::new(),
        };
    }
    let mut snapshot = base_snapshot.clone();
    assert!(snapshot.replace_range(candidate.start, candidate.end, &candidate.replacement,));
    let prepared = panic::catch_unwind(AssertUnwindSafe(|| {
        file_index.analysis_for_candidate(script, &snapshot, candidate, db_type)
    }));
    let (expanded, analysis) = match prepared {
        Ok(prepared) => prepared,
        Err(err) => {
            let (line, column) = intellisense_sweep_line_column(script, candidate.start);
            return IntellisenseSweepCandidateResult {
                checked: true,
                suggestions_checked: 0,
                missing: Some(IntellisenseSweepMissing {
                    start: candidate.start,
                    end: candidate.end,
                    line,
                    column,
                    word: candidate.word.clone(),
                    prefix: candidate.prefix.clone(),
                    suggestion_sample: vec![format!(
                        "<panic: {}>",
                        intellisense_sweep_panic_payload_text(err.as_ref())
                    )],
                    suggestion_count: 0,
                }),
                untyped_suggestions: Vec::new(),
            };
        }
    };
    let skip = panic::catch_unwind(AssertUnwindSafe(|| {
        intellisense_sweep_word_skip_context_from_analysis(
            &expanded.text,
            expanded.cursor_in_statement,
            db_type,
            &candidate.word,
            &analysis,
        )
    }))
    .unwrap_or(false);
    if skip {
        return IntellisenseSweepCandidateResult {
            checked: false,
            suggestions_checked: 0,
            missing: None,
            untyped_suggestions: Vec::new(),
        };
    }

    let result = panic::catch_unwind(AssertUnwindSafe(|| {
        lock_or_recover(&worker.data).clear_virtual_tables();
        query_completion_popup_from_prepared_snapshot_with_resources(
            &snapshot,
            candidate.cursor,
            db_type,
            true,
            &worker.data,
            &worker.column_sender,
            &worker.connection,
            &worker.runtime,
            &expanded,
            &analysis,
            Some(file_index.signature_scan_start(script, candidate.cursor)),
        )
    }));
    let (matched, suggestion_sample, suggestion_count, untyped_suggestions) = match result {
        Ok(popup) => {
            let matched = popup.suggestions.iter().any(|suggestion| {
                intellisense_sweep_suggestion_matches_word(suggestion, &candidate.word)
            });
            let count = popup.suggestions.len();
            let (line, column) = intellisense_sweep_line_column(script, candidate.start);
            let untyped = intellisense_sweep_untyped_popup_suggestion_names(&popup)
                .into_iter()
                .map(|suggestion| IntellisenseSweepUntypedSuggestion {
                    start: candidate.start,
                    line,
                    column,
                    word: candidate.word.clone(),
                    prefix: candidate.prefix.clone(),
                    suggestion,
                })
                .collect::<Vec<_>>();
            let sample = popup.suggestions.into_iter().take(16).collect::<Vec<_>>();
            (matched, sample, count, untyped)
        }
        Err(err) => (
            false,
            vec![format!(
                "<panic: {}>",
                intellisense_sweep_panic_payload_text(err.as_ref())
            )],
            0,
            Vec::new(),
        ),
    };
    let missing = (!matched).then(|| {
        let (line, column) = intellisense_sweep_line_column(script, candidate.start);
        IntellisenseSweepMissing {
            start: candidate.start,
            end: candidate.end,
            line,
            column,
            word: candidate.word.clone(),
            prefix: candidate.prefix.clone(),
            suggestion_sample,
            suggestion_count,
        }
    });
    IntellisenseSweepCandidateResult {
        checked: true,
        suggestions_checked: suggestion_count,
        missing,
        untyped_suggestions,
    }
}

fn intellisense_sweep_run(
    script: &str,
    db_type: crate::db::DatabaseType,
    base_data: &IntellisenseData,
) -> IntellisenseSweepRun {
    let mysql_compatible = matches!(
        db_type,
        crate::db::DatabaseType::MySQL | crate::db::DatabaseType::MariaDB
    );
    let spans = match db_type {
        crate::db::DatabaseType::MySQL | crate::db::DatabaseType::MariaDB => {
            super::query_text::tokenize_sql_spanned_with_mysql_compat(script, true)
        }
        crate::db::DatabaseType::Oracle => {
            super::query_text::tokenize_sql_spanned_with_mysql_compat(script, false)
        }
    };
    let lexical_spans = crate::sql_parser_engine::lexical_spans(script, mysql_compatible);
    let literal_or_comment_ranges = lexical_spans
        .iter()
        .filter(|span| span.kind != crate::sql_parser_engine::LexicalKind::QuotedIdentifier)
        .map(|span| (span.start, span.end))
        .collect::<Vec<_>>();
    let base_snapshot = ChunkedText::from_str(script);
    let file_index =
        IntellisenseSweepFileIndex::new(script, &base_snapshot, db_type, lexical_spans);
    let mut candidates = Vec::new();
    for span in spans {
        let SqlToken::Word(word) = &span.token else {
            continue;
        };
        let Some(prefix) = intellisense_sweep_completion_prefix(word) else {
            continue;
        };
        if intellisense_sweep_word_is_prompt_body(script, &span)
            || intellisense_sweep_word_is_sqlplus_include_path(script, &span)
        {
            continue;
        }
        if intellisense_sweep_offset_is_literal_or_comment(&literal_or_comment_ranges, span.start) {
            continue;
        }

        let identifier_quote = if (word.starts_with('`') && word.ends_with('`'))
            || (word.starts_with('"') && word.ends_with('"'))
        {
            word.get(..1).unwrap_or("")
        } else {
            ""
        };
        let replacement = format!("{identifier_quote}{prefix}{identifier_quote}");
        let cursor = span
            .start
            .saturating_add(identifier_quote.len())
            .saturating_add(prefix.len());
        candidates.push(IntellisenseSweepCandidate {
            start: span.start,
            end: span.end,
            word: word.clone(),
            prefix,
            replacement,
            cursor,
        });
    }

    let worker_count = std::thread::available_parallelism()
        .map(|count| count.get())
        .unwrap_or(1)
        .min(8)
        .min(candidates.len().max(1));
    let next = AtomicUsize::new(0);
    let results = Mutex::new(Vec::with_capacity(candidates.len()));
    std::thread::scope(|scope| {
        for _ in 0..worker_count {
            let next = &next;
            let results = &results;
            let candidates = &candidates;
            let base_snapshot = &base_snapshot;
            let file_index = &file_index;
            scope.spawn(move || {
                let worker = IntellisenseSweepWorkerResources::new(base_data);
                loop {
                    let idx = next.fetch_add(1, Ordering::Relaxed);
                    let Some(candidate) = candidates.get(idx) else {
                        break;
                    };
                    let result = intellisense_sweep_check_candidate_with_resources(
                        script,
                        base_snapshot,
                        db_type,
                        candidate,
                        file_index,
                        &worker,
                    );
                    lock_or_recover(results).push(result);
                }
            });
        }
    });
    let results = results
        .into_inner()
        .unwrap_or_else(|poisoned| poisoned.into_inner());
    let checked = results.iter().filter(|result| result.checked).count();
    let suggestions_checked = results
        .iter()
        .map(|result| result.suggestions_checked)
        .sum();
    let mut missing = Vec::new();
    let mut untyped_suggestions = Vec::new();
    for result in results {
        if let Some(item) = result.missing {
            missing.push(item);
        }
        untyped_suggestions.extend(result.untyped_suggestions);
    }
    missing.sort_by_key(|item| item.start);
    untyped_suggestions.sort_by(|left, right| {
        (left.start, left.suggestion.as_str()).cmp(&(right.start, right.suggestion.as_str()))
    });
    IntellisenseSweepRun {
        checked,
        suggestions_checked,
        missing,
        untyped_suggestions,
    }
}

fn intellisense_sweep_db_type_from_env(value: &str) -> Option<crate::db::DatabaseType> {
    match value.trim().to_ascii_lowercase().as_str() {
        "oracle" | "ora" => Some(crate::db::DatabaseType::Oracle),
        "mysql" => Some(crate::db::DatabaseType::MySQL),
        "mariadb" | "maria" => Some(crate::db::DatabaseType::MariaDB),
        _ => None,
    }
}

fn intellisense_sweep_add_names(target: &mut Vec<String>, value: Option<&serde_json::Value>) {
    let Some(value) = value else {
        return;
    };
    match value {
        serde_json::Value::Array(items) => {
            for item in items {
                if let Some(name) = item.as_str() {
                    push_unique_case_insensitive(target, name);
                } else if let Some(name) = item.get("name").and_then(serde_json::Value::as_str) {
                    push_unique_case_insensitive(target, name);
                }
            }
        }
        serde_json::Value::Object(map) => {
            for key in map.keys() {
                push_unique_case_insensitive(target, key);
            }
        }
        serde_json::Value::String(name) => push_unique_case_insensitive(target, name),
        _ => {}
    }
}

fn intellisense_sweep_string_array(value: &serde_json::Value) -> Vec<String> {
    match value {
        serde_json::Value::Array(items) => items
            .iter()
            .filter_map(|item| {
                item.as_str()
                    .or_else(|| item.get("name").and_then(serde_json::Value::as_str))
                    .map(str::to_string)
            })
            .collect(),
        serde_json::Value::String(value) => vec![value.to_string()],
        _ => Vec::new(),
    }
}

fn intellisense_sweep_apply_columns_from_map(
    data: &mut IntellisenseData,
    value: &serde_json::Value,
) {
    let Some(map) = value.as_object() else {
        return;
    };
    for (table, columns_value) in map {
        let columns = intellisense_sweep_string_array(columns_value);
        if !columns.is_empty() {
            data.set_columns_for_table(table, columns);
        }
    }
}

fn intellisense_sweep_kind_from_value(
    value: Option<&serde_json::Value>,
) -> Option<QualifiedMemberKind> {
    value
        .and_then(serde_json::Value::as_str)
        .and_then(QualifiedMemberKind::from_object_type_name)
}

fn intellisense_sweep_member_with_kind(
    value: &serde_json::Value,
) -> Option<(String, Option<QualifiedMemberKind>)> {
    if let Some(name) = value.as_str() {
        return Some((name.to_string(), None));
    }
    let name = value.get("name").and_then(serde_json::Value::as_str)?;
    let kind = intellisense_sweep_kind_from_value(value.get("type").or_else(|| value.get("kind")));
    Some((name.to_string(), kind))
}

fn intellisense_sweep_apply_members(
    data: &mut IntellisenseData,
    value: Option<&serde_json::Value>,
) {
    let Some(serde_json::Value::Object(map)) = value else {
        return;
    };
    for (qualifier, members_value) in map {
        let members = match members_value {
            serde_json::Value::Array(items) => items
                .iter()
                .filter_map(intellisense_sweep_member_with_kind)
                .collect::<Vec<_>>(),
            _ => Vec::new(),
        };
        if members.is_empty() {
            continue;
        }
        if members.iter().any(|(_, kind)| kind.is_some()) {
            data.set_members_for_qualifier_with_kinds(qualifier, members);
        } else {
            data.set_members_for_qualifier(
                qualifier,
                members.into_iter().map(|(name, _)| name).collect(),
            );
        }
    }
}

fn intellisense_sweep_apply_relation_members(
    data: &mut IntellisenseData,
    value: Option<&serde_json::Value>,
) {
    let Some(serde_json::Value::Object(map)) = value else {
        return;
    };
    for (qualifier, members_value) in map {
        let members = intellisense_sweep_string_array(members_value);
        if !members.is_empty() {
            data.set_relation_members_for_qualifier(qualifier, members);
        }
    }
}

fn intellisense_sweep_signature_label_from_value(
    key: &str,
    value: &serde_json::Value,
) -> Option<SignatureLabel> {
    if let Some(text) = value.as_str() {
        return Some(SignatureLabel {
            text: text.to_string(),
            arg_spans: Vec::new(),
            overloads: Vec::new(),
        });
    }

    let text = value
        .get("text")
        .or_else(|| value.get("label"))
        .and_then(serde_json::Value::as_str)
        .map(str::to_string)
        .or_else(|| {
            let args = value.get("args").map(intellisense_sweep_string_array)?;
            if args.is_empty() {
                None
            } else {
                Some(format!("{}({})", key, args.join(", ")))
            }
        })?;

    Some(SignatureLabel {
        text,
        arg_spans: Vec::new(),
        overloads: Vec::new(),
    })
}

fn intellisense_sweep_apply_signatures(
    data: &mut IntellisenseData,
    value: Option<&serde_json::Value>,
) {
    let Some(value) = value else {
        return;
    };
    match value {
        serde_json::Value::Object(map) => {
            for (key, label_value) in map {
                data.set_signature(
                    key.to_ascii_uppercase(),
                    intellisense_sweep_signature_label_from_value(key, label_value),
                );
            }
        }
        serde_json::Value::Array(items) => {
            for item in items {
                let Some(key) = item
                    .get("key")
                    .or_else(|| item.get("name"))
                    .and_then(serde_json::Value::as_str)
                else {
                    continue;
                };
                data.set_signature(
                    key.to_ascii_uppercase(),
                    intellisense_sweep_signature_label_from_value(key, item),
                );
            }
        }
        _ => {}
    }
}

fn intellisense_sweep_column_meta_from_value(value: &serde_json::Value) -> Option<ColumnMeta> {
    let object = value.as_object()?;
    Some(ColumnMeta {
        type_display: object
            .get("type")
            .or_else(|| object.get("data_type"))
            .or_else(|| object.get("type_display"))
            .and_then(serde_json::Value::as_str)
            .unwrap_or("")
            .to_string(),
        nullable: object
            .get("nullable")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(true),
        is_primary_key: object
            .get("primary_key")
            .or_else(|| object.get("is_primary_key"))
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false),
    })
}

fn intellisense_sweep_apply_column_meta(
    data: &mut IntellisenseData,
    value: Option<&serde_json::Value>,
) {
    let Some(serde_json::Value::Object(tables)) = value else {
        return;
    };
    for (table, columns_value) in tables {
        let Some(columns) = columns_value.as_object() else {
            continue;
        };
        let meta = columns
            .iter()
            .filter_map(|(column, meta_value)| {
                intellisense_sweep_column_meta_from_value(meta_value)
                    .map(|meta| (column.clone(), meta))
            })
            .collect::<HashMap<_, _>>();
        if !meta.is_empty() {
            data.set_column_meta_for_table(table, meta);
        }
    }
}

fn intellisense_sweep_fk_from_value(value: &serde_json::Value) -> Option<ForeignKeyMeta> {
    Some(ForeignKeyMeta {
        columns: intellisense_sweep_string_array(value.get("columns")?),
        ref_table: value
            .get("ref_table")
            .or_else(|| value.get("referenced_table"))
            .and_then(serde_json::Value::as_str)?
            .to_string(),
        ref_columns: intellisense_sweep_string_array(
            value
                .get("ref_columns")
                .or_else(|| value.get("referenced_columns"))?,
        ),
    })
}

fn intellisense_sweep_apply_foreign_keys(
    data: &mut IntellisenseData,
    value: Option<&serde_json::Value>,
) {
    let Some(serde_json::Value::Object(tables)) = value else {
        return;
    };
    for (table, fks_value) in tables {
        let fks = match fks_value {
            serde_json::Value::Array(items) => items
                .iter()
                .filter_map(intellisense_sweep_fk_from_value)
                .collect::<Vec<_>>(),
            _ => Vec::new(),
        };
        if !fks.is_empty() {
            data.set_foreign_keys_for_table(table, fks);
        }
    }
}

fn intellisense_sweep_apply_collection_element_types(
    data: &mut IntellisenseData,
    value: Option<&serde_json::Value>,
) {
    let Some(serde_json::Value::Object(types)) = value else {
        return;
    };
    for (collection_type, element_type) in types {
        if let Some(element_type) = element_type.as_str() {
            data.set_collection_element_type_for_type(collection_type, element_type);
        }
    }
}

fn intellisense_sweep_apply_synonym_targets(
    data: &mut IntellisenseData,
    value: Option<&serde_json::Value>,
) {
    let Some(serde_json::Value::Object(synonyms)) = value else {
        return;
    };
    for (synonym, target) in synonyms {
        if let Some(target) = target.as_str() {
            data.set_synonym_target(synonym, target);
        }
    }
}

fn intellisense_sweep_apply_object_entry(
    data: &mut IntellisenseData,
    object: &serde_json::Map<String, serde_json::Value>,
) {
    let Some(name) = object.get("name").and_then(serde_json::Value::as_str) else {
        return;
    };
    let kind = object
        .get("type")
        .or_else(|| object.get("kind"))
        .and_then(serde_json::Value::as_str)
        .unwrap_or("TABLE")
        .to_ascii_uppercase();

    match kind.as_str() {
        "TABLE" | "BASE TABLE" => push_unique_case_insensitive(&mut data.tables, name),
        "VIEW" | "EDITIONING VIEW" => push_unique_case_insensitive(&mut data.views, name),
        "MATERIALIZED VIEW" | "MVIEW" => {
            push_unique_case_insensitive(&mut data.materialized_views, name)
        }
        "TYPE" | "TYPE BODY" => push_unique_case_insensitive(&mut data.types, name),
        "TRIGGER" => push_unique_case_insensitive(&mut data.triggers, name),
        "EVENT" => push_unique_case_insensitive(&mut data.events, name),
        "INDEX" => push_unique_case_insensitive(&mut data.indexes, name),
        "PROCEDURE" => push_unique_case_insensitive(&mut data.procedures, name),
        "FUNCTION" => push_unique_case_insensitive(&mut data.functions, name),
        "PACKAGE" | "PACKAGE BODY" => push_unique_case_insensitive(&mut data.packages, name),
        "SEQUENCE" => push_unique_case_insensitive(&mut data.sequences, name),
        "SYNONYM" => push_unique_case_insensitive(&mut data.synonyms, name),
        "PUBLIC SYNONYM" => push_unique_case_insensitive(&mut data.public_synonyms, name),
        "DATABASE LINK" => push_unique_case_insensitive(&mut data.database_links, name),
        "DIRECTORY" => push_unique_case_insensitive(&mut data.directories, name),
        "LIBRARY" => push_unique_case_insensitive(&mut data.libraries, name),
        "CLUSTER" => push_unique_case_insensitive(&mut data.clusters, name),
        "CONTEXT" => push_unique_case_insensitive(&mut data.contexts, name),
        "DIMENSION" => push_unique_case_insensitive(&mut data.dimensions, name),
        "OPERATOR" => push_unique_case_insensitive(&mut data.operators, name),
        "INDEXTYPE" => push_unique_case_insensitive(&mut data.indextypes, name),
        "EDITION" => push_unique_case_insensitive(&mut data.editions, name),
        "JAVA SOURCE" => push_unique_case_insensitive(&mut data.java_sources, name),
        "JAVA CLASS" => push_unique_case_insensitive(&mut data.java_classes, name),
        "JAVA RESOURCE" => push_unique_case_insensitive(&mut data.java_resources, name),
        "USER" | "SCHEMA" => push_unique_case_insensitive(&mut data.users, name),
        _ => {}
    }

    if let Some(columns) = object.get("columns") {
        let columns = intellisense_sweep_string_array(columns);
        if !columns.is_empty() {
            data.set_columns_for_table(name, columns);
        }
    }
    if let Some(members) = object.get("members") {
        let members = match members {
            serde_json::Value::Array(items) => items
                .iter()
                .filter_map(intellisense_sweep_member_with_kind)
                .collect::<Vec<_>>(),
            _ => Vec::new(),
        };
        if !members.is_empty() {
            if members.iter().any(|(_, kind)| kind.is_some()) {
                data.set_members_for_qualifier_with_kinds(name, members);
            } else {
                data.set_members_for_qualifier(
                    name,
                    members.into_iter().map(|(name, _)| name).collect(),
                );
            }
        }
    }
    if let Some(relation_members) = object.get("relation_members") {
        let relation_members = intellisense_sweep_string_array(relation_members);
        if !relation_members.is_empty() {
            data.set_relation_members_for_qualifier(name, relation_members);
        }
    }
    if let Some(element_type) = object
        .get("collection_element_type")
        .or_else(|| object.get("element_type"))
        .and_then(serde_json::Value::as_str)
    {
        data.set_collection_element_type_for_type(name, element_type);
    }
    if matches!(kind.as_str(), "SYNONYM" | "PUBLIC SYNONYM") {
        if let Some(target) = object
            .get("target")
            .or_else(|| object.get("target_name"))
            .or_else(|| object.get("table_name"))
            .and_then(serde_json::Value::as_str)
        {
            data.set_synonym_target(name, target);
        }
    }
}

fn intellisense_sweep_apply_metadata_value(data: &mut IntellisenseData, value: &serde_json::Value) {
    intellisense_sweep_add_names(&mut data.tables, value.get("tables"));
    intellisense_sweep_add_names(&mut data.views, value.get("views"));
    intellisense_sweep_add_names(
        &mut data.materialized_views,
        value.get("materialized_views"),
    );
    intellisense_sweep_add_names(&mut data.types, value.get("types"));
    intellisense_sweep_add_names(&mut data.triggers, value.get("triggers"));
    intellisense_sweep_add_names(&mut data.events, value.get("events"));
    intellisense_sweep_add_names(&mut data.indexes, value.get("indexes"));
    intellisense_sweep_add_names(&mut data.procedures, value.get("procedures"));
    intellisense_sweep_add_names(&mut data.functions, value.get("functions"));
    intellisense_sweep_add_names(&mut data.packages, value.get("packages"));
    intellisense_sweep_add_names(&mut data.sequences, value.get("sequences"));
    intellisense_sweep_add_names(&mut data.synonyms, value.get("synonyms"));
    intellisense_sweep_add_names(&mut data.public_synonyms, value.get("public_synonyms"));
    intellisense_sweep_add_names(&mut data.database_links, value.get("database_links"));
    intellisense_sweep_add_names(&mut data.directories, value.get("directories"));
    intellisense_sweep_add_names(&mut data.libraries, value.get("libraries"));
    intellisense_sweep_add_names(&mut data.clusters, value.get("clusters"));
    intellisense_sweep_add_names(&mut data.contexts, value.get("contexts"));
    intellisense_sweep_add_names(&mut data.dimensions, value.get("dimensions"));
    intellisense_sweep_add_names(&mut data.operators, value.get("operators"));
    intellisense_sweep_add_names(&mut data.indextypes, value.get("indextypes"));
    intellisense_sweep_add_names(&mut data.editions, value.get("editions"));
    intellisense_sweep_add_names(&mut data.java_sources, value.get("java_sources"));
    intellisense_sweep_add_names(&mut data.java_classes, value.get("java_classes"));
    intellisense_sweep_add_names(&mut data.java_resources, value.get("java_resources"));
    intellisense_sweep_add_names(&mut data.users, value.get("users"));

    if let Some(columns) = value.get("columns") {
        intellisense_sweep_apply_columns_from_map(data, columns);
    }
    if let Some(objects) = value.get("objects").and_then(serde_json::Value::as_array) {
        for object in objects.iter().filter_map(serde_json::Value::as_object) {
            intellisense_sweep_apply_object_entry(data, object);
        }
    }
    intellisense_sweep_apply_members(data, value.get("members"));
    intellisense_sweep_apply_relation_members(data, value.get("relation_members"));
    intellisense_sweep_apply_collection_element_types(
        data,
        value
            .get("collection_element_types")
            .or_else(|| value.get("collection_types")),
    );
    intellisense_sweep_apply_synonym_targets(
        data,
        value
            .get("synonym_targets")
            .or_else(|| value.get("synonym_target_by_name")),
    );
    intellisense_sweep_apply_signatures(data, value.get("signatures"));
    intellisense_sweep_apply_column_meta(data, value.get("column_meta"));
    intellisense_sweep_apply_foreign_keys(data, value.get("foreign_keys"));
    data.rebuild_indices();
}

fn intellisense_sweep_data_from_metadata_path(path: &PathBuf) -> IntellisenseData {
    let text = std::fs::read_to_string(path)
        .unwrap_or_else(|err| panic!("failed to read metadata `{}`: {err}", path.display()));
    let value: serde_json::Value = serde_json::from_str(&text)
        .unwrap_or_else(|err| panic!("failed to parse metadata `{}`: {err}", path.display()));
    let mut data = IntellisenseData::new();
    intellisense_sweep_apply_metadata_value(&mut data, &value);
    data
}

fn intellisense_sweep_metadata_path_from_config(config: &serde_json::Value) -> Option<PathBuf> {
    config
        .get("metadata_file")
        .or_else(|| config.get("metadata_path"))
        .or_else(|| config.get("meta_file"))
        .or_else(|| config.get("meta_path"))
        .and_then(serde_json::Value::as_str)
        .map(PathBuf::from)
}

fn intellisense_sweep_data_from_config(
    config: &serde_json::Value,
    metadata_path: Option<&PathBuf>,
) -> (IntellisenseData, Option<String>) {
    let mut data = metadata_path
        .map(intellisense_sweep_data_from_metadata_path)
        .unwrap_or_default();

    let explicit_metadata_label = config
        .get("metadata_label")
        .and_then(serde_json::Value::as_str)
        .map(str::to_string);
    let mut metadata_label = explicit_metadata_label
        .clone()
        .or_else(|| metadata_path.map(|path| path.display().to_string()));
    if let Some(metadata) = config.get("metadata") {
        intellisense_sweep_apply_metadata_value(&mut data, metadata);
        metadata_label =
            explicit_metadata_label.or_else(|| Some("inline config metadata".to_string()));
    } else if metadata_path.is_none() {
        intellisense_sweep_apply_metadata_value(&mut data, config);
        metadata_label =
            explicit_metadata_label.or_else(|| Some("top-level config metadata".to_string()));
    }
    data.rebuild_indices();
    (data, metadata_label)
}

fn intellisense_sweep_path_from_config(
    config: &serde_json::Value,
    keys: &[&str],
) -> Option<PathBuf> {
    keys.iter()
        .find_map(|key| config.get(*key).and_then(serde_json::Value::as_str))
        .map(PathBuf::from)
}

fn intellisense_sweep_bool_from_str(value: &str) -> bool {
    !matches!(
        value.trim(),
        "0" | "false" | "FALSE" | "False" | "no" | "NO" | "No"
    )
}

fn intellisense_sweep_bool_from_config(
    config: &serde_json::Value,
    key: &str,
    default: bool,
) -> bool {
    match config.get(key) {
        Some(serde_json::Value::Bool(value)) => *value,
        Some(serde_json::Value::Number(value)) => value.as_i64().unwrap_or(0) != 0,
        Some(serde_json::Value::String(value)) => intellisense_sweep_bool_from_str(value),
        _ => default,
    }
}

fn intellisense_sweep_db_type_from_config(
    config: &serde_json::Value,
) -> Option<crate::db::DatabaseType> {
    config
        .get("db")
        .or_else(|| config.get("database"))
        .or_else(|| config.get("database_type"))
        .and_then(serde_json::Value::as_str)
        .and_then(intellisense_sweep_db_type_from_env)
}

fn intellisense_sweep_config_from_path(path: &PathBuf) -> serde_json::Value {
    let text = std::fs::read_to_string(path)
        .unwrap_or_else(|err| panic!("failed to read sweep config `{}`: {err}", path.display()));
    serde_json::from_str(&text)
        .unwrap_or_else(|err| panic!("failed to parse sweep config `{}`: {err}", path.display()))
}

fn intellisense_sweep_out_path(input_path: &Path) -> PathBuf {
    let file_name = input_path
        .file_name()
        .and_then(|name| name.to_str())
        .unwrap_or("intellisense.sql");
    input_path.with_file_name(format!("{file_name}.out"))
}

fn intellisense_sweep_source_label(input_path: &Path) -> String {
    let manifest = PathBuf::from(env!("CARGO_MANIFEST_DIR"));
    input_path
        .strip_prefix(&manifest)
        .ok()
        .and_then(|path| path.to_str())
        .map(str::to_string)
        .unwrap_or_else(|| input_path.display().to_string())
}

fn intellisense_sweep_generate_report_for_file(
    input_path: &PathBuf,
    db_type: crate::db::DatabaseType,
    data: &IntellisenseData,
    metadata_label: Option<&str>,
    out_path: &PathBuf,
    fail_on_missing: bool,
) -> IntellisenseSweepRun {
    let script = std::fs::read_to_string(input_path)
        .unwrap_or_else(|err| panic!("failed to read `{}`: {err}", input_path.display()));
    let run = intellisense_sweep_run(&script, db_type, data);
    let source_label = intellisense_sweep_source_label(input_path);
    let out = intellisense_sweep_render_out(
        &script,
        run.checked,
        run.suggestions_checked,
        &run.missing,
        &run.untyped_suggestions,
        &source_label,
        db_type,
        metadata_label,
    );
    std::fs::write(out_path, out)
        .unwrap_or_else(|err| panic!("failed to write `{}`: {err}", out_path.display()));

    let contains_sql_statement = super::query_text::split_script_items_for_db_type(
        &script,
        Some(db_type),
    )
    .iter()
    .any(|item| matches!(item, crate::db::ScriptItem::Statement(statement) if !statement.trim().is_empty()));
    assert!(
        run.checked > 0 || !contains_sql_statement,
        "IntelliSense sweep did not check any tokens for `{}`",
        input_path.display()
    );
    if fail_on_missing {
        assert!(
            run.missing.is_empty() && run.untyped_suggestions.is_empty(),
            "IntelliSense sweep found {} missing tokens and {} suggestions without type labels; report written to `{}`",
            run.missing.len(),
            run.untyped_suggestions.len(),
            out_path.display()
        );
    }
    run
}

fn intellisense_sweep_fixture_paths(directory: &str, extensions: &[&str]) -> Vec<PathBuf> {
    let directory = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(directory);
    let mut paths = std::fs::read_dir(&directory)
        .unwrap_or_else(|err| panic!("failed to read `{}`: {err}", directory.display()))
        .map(|entry| {
            entry
                .unwrap_or_else(|err| {
                    panic!(
                        "failed to read entry under `{}`: {err}",
                        directory.display()
                    )
                })
                .path()
        })
        .filter(|path| {
            path.is_file()
                && path
                    .extension()
                    .and_then(|extension| extension.to_str())
                    .is_some_and(|extension| extensions.contains(&extension))
        })
        .collect::<Vec<_>>();
    paths.sort();
    paths
}

fn intellisense_sweep_fixture_groups() -> [(
    &'static str,
    &'static [&'static str],
    crate::db::DatabaseType,
); 3] {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    [
        ("test", &["txt", "sql"], Oracle),
        ("test_mariadb", &["txt", "sql"], MariaDB),
        ("test_mysql", &["txt", "sql"], MySQL),
    ]
}

#[test]
fn intellisense_sweep_fixture_groups_include_manual_final_scripts() {
    for (directory, extensions, _) in intellisense_sweep_fixture_groups() {
        let final_path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join(directory)
            .join("final.sql");
        assert!(
            intellisense_sweep_fixture_paths(directory, extensions).contains(&final_path),
            "{directory}/final.sql is excluded from the all-fixture IntelliSense sweep"
        );
    }
}

#[test]
#[ignore = "generates IntelliSense sweep reports for every Oracle/MySQL/MariaDB fixture"]
fn intellisense_sweep_generate_reports_for_all_fixture_files() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let custom_configuration = [
        "SPACE_QUERY_INTELLISENSE_SWEEP_CONFIG",
        "SPACE_QUERY_INTELLISENSE_SWEEP_META",
        "SPACE_QUERY_INTELLISENSE_SWEEP_OUT",
        "SPACE_QUERY_INTELLISENSE_SWEEP_DB",
    ]
    .iter()
    .any(|name| std::env::var_os(name).is_some());
    let requested_path = std::env::var_os("SPACE_QUERY_INTELLISENSE_SWEEP_FILE")
        .map(PathBuf::from)
        .map(|path| {
            if path.is_absolute() {
                path
            } else {
                PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(path)
            }
        });
    let requested_fixture = requested_path.as_ref().is_none_or(|requested_path| {
        intellisense_sweep_fixture_groups()
            .iter()
            .any(|(directory, extensions, _)| {
                intellisense_sweep_fixture_paths(directory, extensions).contains(requested_path)
            })
    });
    if custom_configuration || !requested_fixture {
        intellisense_words_generate_out_report_from_env();
        return;
    }
    let mut failures = Vec::new();
    for (directory, extensions, db_type) in intellisense_sweep_fixture_groups() {
        for input_path in intellisense_sweep_fixture_paths(directory, extensions) {
            if requested_path
                .as_ref()
                .is_some_and(|requested_path| requested_path != &input_path)
            {
                continue;
            }
            let file_name = input_path
                .file_name()
                .and_then(|name| name.to_str())
                .unwrap_or_else(|| panic!("non-UTF8 fixture path `{}`", input_path.display()));
            let data = match db_type {
                Oracle => oracle_test_file_scoped_intellisense_data(file_name),
                MySQL | MariaDB => mysql_family_test_intellisense_data(file_name, db_type),
            };
            let relative_path = format!("{directory}/{file_name}");
            let metadata_label = match db_type {
                Oracle => "test Oracle inferred catalog (file-scoped overlay) + Oracle built-ins"
                    .to_string(),
                MySQL | MariaDB => format!("{relative_path} inferred catalog"),
            };
            let out_path = intellisense_sweep_out_path(&input_path);
            let run = intellisense_sweep_generate_report_for_file(
                &input_path,
                db_type,
                &data,
                Some(&metadata_label),
                &out_path,
                false,
            );
            eprintln!(
                "IntelliSense sweep: {relative_path}: checked={} suggestions={} missing={} untyped={}",
                run.checked,
                run.suggestions_checked,
                run.missing.len(),
                run.untyped_suggestions.len()
            );
            if !run.missing.is_empty() || !run.untyped_suggestions.is_empty() {
                failures.push(format!(
                    "{relative_path}: missing={} untyped={}",
                    run.missing.len(),
                    run.untyped_suggestions.len()
                ));
            }
        }
    }

    assert!(
        failures.is_empty(),
        "IntelliSense sweep found missing tokens or suggestions without type labels:\n{}",
        failures.join("\n")
    );
}

#[test]
fn mysql_member_of_continuation_uses_production_completion() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let suggestions = query_keyword_completion_suggestions(
        "SELECT COALESCE('critical' MEMBER O| (JSON_ARRAY('critical')), FALSE)",
        MySQL,
    );
    assert!(
        suggestions
            .iter()
            .any(|suggestion| suggestion.eq_ignore_ascii_case("OF")),
        "MySQL MEMBER OF continuation missing from production completion: {suggestions:?}"
    );

    let mariadb_suggestions = query_keyword_completion_suggestions(
        "SELECT COALESCE('critical' MEMBER O| (JSON_ARRAY('critical')), FALSE)",
        MariaDB,
    );
    assert!(
        mariadb_suggestions
            .iter()
            .all(|suggestion| !suggestion.eq_ignore_ascii_case("OF")),
        "MySQL-only MEMBER OF continuation leaked into MariaDB: {mariadb_suggestions:?}"
    );
}

#[test]
fn final_boss_structural_keywords_use_production_completion() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    for (db_type, sql, expected) in [
        (
            Oracle,
            "WITH x AS (SELECT 1 a FROM dual UNIO| ALL SELECT 2 FROM dual) SELECT * FROM x",
            "UNION",
        ),
        (
            Oracle,
            "SELECT * FROM (SELECT 1 customer_id, DATE '2026-01-01' day_value, 1 day_amount FROM dual) MATCH_RECOGNIZE (PARTITION BY customer_id ORDER BY day_value MEASURES COUNT(*) AS matched_days ON| ROW PER MATCH PATTERN (seed rise*) DEFINE rise AS rise.day_amount >= PREV(rise.day_amount))",
            "ONE",
        ),
        (
            Oracle,
            "SELECT JSON_OBJECT('x' VALU| 1 RETURNING CLOB) FROM dual",
            "VALUE",
        ),
        (
            Oracle,
            "SELECT XMLSERIALIZE(CONTEN| XMLELEMENT(\"x\", 'y') AS VARCHAR2(20)) FROM dual",
            "CONTENT",
        ),
        (
            MySQL,
            "SELECT * FROM JSON_TABLE('[1]', '$[*]' COLUMNS(NESTE| PATH '$' COLUMNS(v INT PATH '$'))) jt",
            "NESTED",
        ),
        (
            MySQL,
            "SELECT customer_id FROM emp GROUP BY customer_id WIT| ROLLUP",
            "WITH",
        ),
        (
            MySQL,
            "SELECT * FROM emp e LEFT JOIN LATERA| (SELECT 1 AS x) top_line ON TRUE",
            "LATERAL",
        ),
        (
            MariaDB,
            "SELECT CASE WHEN 1 I| NULL THEN 0 ELSE 1 END",
            "IS",
        ),
    ] {
        let suggestions = query_keyword_completion_suggestions(sql, db_type);
        assert!(
            suggestions
                .iter()
                .any(|suggestion| suggestion.eq_ignore_ascii_case(expected)),
            "{db_type:?} `{expected}` missing for `{sql}`: {suggestions:?}"
        );
    }
}

#[test]
fn manual_final_structural_words_use_production_completion() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let cases = [
        (Oracle, "CREATE DOMA__CODEX_CURSOR__ app_domain AS VARCHAR2(32)", "DOMAIN"),
        (Oracle, "CREATE TABLE t (id NUMBER) TABL__CODEX_CURSOR__ users", "TABLESPACE"),
        (Oracle, "CREATE TABLE t (id NUMBER) PARTITION BY RANG__CODEX_CURSOR__ (id)", "RANGE"),
        (Oracle, "CREATE TABLE t (id NUMBER) PARTITION BY RANGE (id) (PARTITION p VALU__CODEX_CURSOR__ LESS THAN (10))", "VALUES"),
        (Oracle, "CREATE TABLE t (id NUMBER) PARTITION BY RANGE (id) (PARTITION p VALUES LES__CODEX_CURSOR__ THAN (10))", "LESS"),
        (Oracle, "CREATE TABLE t (id NUMBER) PARTITION BY RANGE (id) (PARTITION p VALUES LESS THA__CODEX_CURSOR__ (10))", "THAN"),
        (Oracle, "CREATE GLOB__CODEX_CURSOR__ TEMPORARY TABLE t (id NUMBER)", "GLOBAL"),
        (Oracle, "CREATE GLOBAL TEMPORARY TABLE t (id NUMBER) O__CODEX_CURSOR__ COMMIT DELETE ROWS", "ON"),
        (Oracle, "CREATE GLOBAL TEMPORARY TABLE t (id NUMBER) ON COMM__CODEX_CURSOR__ DELETE ROWS", "COMMIT"),
        (Oracle, "CREATE GLOBAL TEMPORARY TABLE t (id NUMBER) ON COMMIT DELE__CODEX_CURSOR__ ROWS", "DELETE"),
        (Oracle, "CREATE GLOBAL TEMPORARY TABLE t (id NUMBER) ON COMMIT DELETE ROW__CODEX_CURSOR__", "ROWS"),
        (Oracle, "CREATE TABLE t (id NUMBER GENERATED BY DEFAULT ON NULL A__CODEX_CURSOR__ IDENTITY)", "AS"),
        (Oracle, "CREATE TABLE t (embedding VECT__CODEX_CURSOR__(3, FLOAT32))", "VECTOR"),
        (Oracle, "CREATE INDEX ix ON t (id DES__CODEX_CURSOR__) INVISIBLE", "DESC"),
        (Oracle, "CREATE INDEX ix ON t (id DESC) INVI__CODEX_CURSOR__", "INVISIBLE"),
        (Oracle, "ALTER INDEX ix VISI__CODEX_CURSOR__", "VISIBLE"),
        (Oracle, "ALTER INDEX ix MONITORING USA__CODEX_CURSOR__", "USAGE"),
        (Oracle, "CREATE TRIGGER trg BEFORE UPDATE OF id O__CODEX_CURSOR__ t BEGIN NULL; END;", "ON"),
        (Oracle, "CREATE VIEW v AS SELECT id FROM t WIT__CODEX_CURSOR__ READ ONLY", "WITH"),
        (Oracle, "CREATE VIEW v AS SELECT id FROM t WITH REA__CODEX_CURSOR__ ONLY", "READ"),
        (Oracle, "CREATE PROP__CODEX_CURSOR__ GRAPH app_graph VERTEX TABLES (t KEY (id))", "PROPERTY"),
        (Oracle, "CREATE PROPERTY GRAPH g EDGE TABLES (e KEY (id) SOURCE KE__CODEX_CURSOR__ (source_id) REFERENCES t (id))", "KEY"),
        (Oracle, "SET TRANSACTION READ WRITE NAM__CODEX_CURSOR__ 'tx'", "NAME"),
        (Oracle, "ANALYZE TABLE t COMPUTE STAT__CODEX_CURSOR__ FOR TABLE FOR ALL INDEXED COLUMNS", "STATISTICS"),
        (Oracle, "ANALYZE TABLE t COMPUTE STATISTICS FO__CODEX_CURSOR__ TABLE FOR ALL INDEXED COLUMNS", "FOR"),
        (Oracle, "ANALYZE TABLE t COMPUTE STATISTICS FOR TABL__CODEX_CURSOR__ FOR ALL INDEXED COLUMNS", "TABLE"),
        (Oracle, "ANALYZE TABLE t COMPUTE STATISTICS FOR TABLE FOR AL__CODEX_CURSOR__ INDEXED COLUMNS", "ALL"),
        (Oracle, "ANALYZE TABLE t COMPUTE STATISTICS FOR TABLE FOR ALL INDE__CODEX_CURSOR__ COLUMNS", "INDEXED"),
        (Oracle, "ANALYZE TABLE t COMPUTE STATISTICS FOR TABLE FOR ALL INDEXED COLU__CODEX_CURSOR__", "COLUMNS"),
        (Oracle, "SELECT CONNECT_BY_ISLEA__CODEX_CURSOR__ leaf_flag FROM t CONNECT BY PRIOR id = parent_id", "CONNECT_BY_ISLEAF"),
        (Oracle, "SELECT id FROM t START WIT__CODEX_CURSOR__ parent_id IS NULL CONNECT BY PRIOR id = parent_id", "WITH"),
        (Oracle, "SELECT JSON_SERIALIZE(payload RETURNING VARCHAR2 PRET__CODEX_CURSOR__) FROM t", "PRETTY"),
        (Oracle, "SELECT VECTOR_DISTANCE(v1, v2, COSI__CODEX_CURSOR__) FROM t", "COSINE"),
        (Oracle, "VARIABLE flashback_scn NUMB__CODEX_CURSOR__", "NUMBER"),
        (Oracle, "WHENEVER SQLERROR EXIT SQL.SQLCODE ROLL__CODEX_CURSOR__", "ROLLBACK"),
        (MySQL, "SET SESSION TRANSACTION ISOLATION LEVEL READ COMM__CODEX_CURSOR__", "COMMITTED"),
        (MySQL, "CREATE TABLE t (path VARCHAR(10) CHARACTER SE__CODEX_CURSOR__ ascii)", "SET"),
        (MySQL, "ALTER TABLE t ADD COLUMN note VARCHAR(10) AFTE__CODEX_CURSOR__ category", "AFTER"),
        (MySQL, "ALTER TABLE t RENAME COLUMN note T__CODEX_CURSOR__ detail", "TO"),
        (MySQL, "CREATE INDEX ix ON t (amount DES__CODEX_CURSOR__)", "DESC"),
        (MySQL, "ALTER TABLE t ALTER INDE__CODEX_CURSOR__ ix INVISIBLE", "INDEX"),
        (MySQL, "ALTER TABLE t ALTER INDEX ix INVI__CODEX_CURSOR__", "INVISIBLE"),
        (MySQL, "ALTER TABLE t ALTER INDEX ix VISI__CODEX_CURSOR__", "VISIBLE"),
        (MySQL, "INSERT INTO t SE__CODEX_CURSOR__ id = 1", "SET"),
        (MySQL, "CREATE VIEW v AS SELECT id FROM t WIT__CODEX_CURSOR__ CASCADED CHECK OPTION", "WITH"),
        (MySQL, "CREATE FUNCTION f() RETURNS INT RETURN CAS__CODEX_CURSOR__ WHEN 1 = 1 THEN 1 END", "CASE"),
        (MySQL, "SELECT GROUP__CODEX_CURSOR__(id) FROM t GROUP BY id WITH ROLLUP", "GROUPING"),
        (MySQL, "CREATE EVENT e ON SCHEDULE AT CURRENT_TIMESTAMP + INTE__CODEX_CURSOR__ 1 DAY DO SELECT 1", "INTERVAL"),
        (MySQL, "CREATE EVENT e ON SCHEDULE AT CURRENT_TIMESTAMP DO__CODEX_CURSOR__ UPDATE t SET id = id", "DO"),
        (MySQL, "ALTER USER app_user PASSWORD EXPI__CODEX_CURSOR__ INTERVAL 30 DAY ACCOUNT UNLOCK", "EXPIRE"),
        (MySQL, "ALTER USER app_user PASSWORD EXPIRE INTE__CODEX_CURSOR__ 30 DAY ACCOUNT UNLOCK", "INTERVAL"),
        (MySQL, "ALTER USER app_user PASSWORD EXPIRE INTERVAL 30 DAY ACCO__CODEX_CURSOR__ UNLOCK", "ACCOUNT"),
        (MySQL, "GRANT app_reader T__CODEX_CURSOR__ app_user", "TO"),
        (MariaDB, "CREATE SEQUENCE s START WIT__CODEX_CURSOR__ 100", "WITH"),
        (MariaDB, "ALTER SEQU__CODEX_CURSOR__ s RESTART WITH 100", "SEQUENCE"),
    ];

    let mut failures = Vec::new();
    for (db_type, sql, expected) in cases {
        let suggestions = query_completion_suggestions_with_locals(sql, db_type);
        if !suggestions
            .iter()
            .any(|suggestion| intellisense_sweep_suggestion_matches_word(suggestion, expected))
        {
            failures.push(format!(
                "{db_type:?} `{expected}` missing for `{sql}`: {suggestions:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "manual final production completion gaps:\n{}",
        failures.join("\n")
    );
}

