/// The DML `RETURNING … INTO` clause is statement-level; a `RETURNING <type>`
/// inside an open function-call paren (`JSON_VALUE(… RETURNING NUMBER |)`) is a
/// different grammar and must not have `INTO` leaked into it, while a real DML
/// RETURNING at the top level still offers it.
#[test]
fn returning_into_does_not_leak_into_a_function_call_returning() {
    let kw = |sql: &str| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let has_into = |sql: &str| kw(sql).iter().any(|x| x == "INTO");
    for sql in [
        "SELECT JSON_VALUE(j, '$.a' RETURNING NUMBER |) FROM t",
        "SELECT JSON_QUERY(j, '$.a' RETURNING VARCHAR2(100) |) FROM t",
    ] {
        assert!(
            !has_into(sql),
            "INTO leaked into a function RETURNING `{sql}`: {:?}",
            kw(sql)
        );
    }
    for sql in [
        "UPDATE t SET a=1 RETURNING a |",
        "INSERT INTO t (a) VALUES (1) RETURNING a |",
        "DELETE FROM t WHERE x=1 RETURNING a |",
    ] {
        assert!(
            has_into(sql),
            "DML RETURNING INTO dropped `{sql}`: {:?}",
            kw(sql)
        );
    }
}

/// Root-cause invariant for the "scope-unaware handler" bug class: a query-level
/// clause continuation must NOT leak into a function-call / grouping paren (where
/// the keyword is not at any query's top level), yet must still fire inside a
/// genuine subquery paren. Locks the whole class — any handler that gates on a
/// flat `has(KEYWORD)` without scoping fails here rather than shipping the
/// `decode(… UNION |) → SELECT` / `JSON_VALUE(… RETURNING NUMBER |) → INTO` noise.
#[test]
fn query_level_continuations_do_not_leak_into_non_query_parens() {
    let kw = |sql: &str| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let has = |v: &[String], s: &str| v.iter().any(|x| x == s);

    // (keyword that must NOT leak, a function-call/grouping-paren SQL that buries
    // the trigger keyword).
    let leak_cases: &[(&str, &str)] = &[
        ("SELECT", "SELECT decode(x, 1, 2 UNION |) FROM t"),
        ("SELECT", "SELECT decode(x, 1, 2 MINUS |) FROM t"),
        ("SELECT", "SELECT greatest(a, b INTERSECT |) FROM t"),
        (
            "INTO",
            "SELECT json_value(j, '$.a' RETURNING NUMBER |) FROM t",
        ),
        (
            "INTO",
            "SELECT json_query(j, '$.a' RETURNING VARCHAR2(10) |) FROM t",
        ),
        // a grouping paren is not a query block either
        ("SELECT", "SELECT (a + b UNION |) FROM t"),
        // every other query/statement-level clause opener is likewise scoped out of
        // a function-call argument list (these are already guarded by the
        // continuation/handler paren checks; the matrix locks them against drift).
        ("UPDATE", "SELECT f(x FOR |) FROM t"),
        ("SHARE", "SELECT f(x FOR |) FROM t"),
        ("BY", "SELECT f(a GROUP |) FROM t"),
        ("BY", "SELECT f(a ORDER |) FROM t"),
        ("FIRST", "SELECT f(a FETCH |) FROM t"),
        ("NEXT", "SELECT f(a FETCH |) FROM t"),
        ("DELETE", "SELECT f(a ON |) FROM t"),
        ("UPDATE", "SELECT f(a ON |) FROM t"),
        ("WHERE", "SELECT f(a GROUP BY b |) FROM t"),
        ("ORDER BY", "SELECT f(a GROUP BY b |) FROM t"),
    ];
    for (keyword, sql) in leak_cases {
        assert!(
            !has(&kw(sql), keyword),
            "query-level `{keyword}` leaked into a non-query paren `{sql}`: {:?}",
            kw(sql)
        );
    }

    // The same keywords inside a real subquery paren still drive the continuation.
    assert!(has(
        &kw("SELECT * FROM (SELECT a FROM u UNION |) v"),
        "SELECT"
    ));
    assert!(has(
        &kw("SELECT * FROM t WHERE x IN (SELECT a FROM u UNION |)"),
        "SELECT"
    ));
    assert!(has(
        &kw("SELECT f((SELECT a FROM t UNION |)) FROM dual"),
        "SELECT"
    ));
    assert!(has(
        &kw("SELECT * FROM (SELECT a FROM u GROUP BY a |) v"),
        "HAVING"
    ));
    assert!(has(
        &kw("SELECT * FROM t WHERE x IN (SELECT a FROM u WHERE y = 1 |)"),
        "GROUP BY"
    ));
    // And the top-level forms are unaffected.
    assert!(has(&kw("SELECT a FROM t UNION |"), "SELECT"));
    assert!(has(&kw("UPDATE t SET a = 1 RETURNING a |"), "INTO"));
}

/// A structural `IS` that opens a declaration / routine body (`CURSOR c IS …`,
/// `TYPE t IS …`, `CREATE PROCEDURE p IS …`, `CREATE PACKAGE pkg IS …`) is not the
/// boolean `x IS NULL` predicate, so its tails (`NULL`/`JSON`/`NAN`/…) must not
/// leak; a real predicate `IS` still offers them. Oracle 26ai's native `JSON` is
/// nevertheless a valid subtype base type. Separately, a routine header stops
/// offering its options (`AUTHID`/`IS`/`AS`/…) once the body keyword appears.
#[test]
fn structural_is_and_routine_header_do_not_leak_predicate_or_header_keywords() {
    let kw = |sql: &str| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let has = |v: &[String], s: &str| v.iter().any(|x| x == s);

    // Structural `IS` — no boolean-predicate tails, no header re-offer.
    for sql in [
        "DECLARE CURSOR c IS |",
        "DECLARE TYPE t IS |",
        "DECLARE SUBTYPE s IS |",
        "CREATE PROCEDURE p AS |",
        "CREATE OR REPLACE PROCEDURE p IS |",
        "CREATE FUNCTION f RETURN NUMBER IS |",
        "CREATE PACKAGE pkg IS |",
        "CREATE PACKAGE BODY pkg IS |",
    ] {
        let s = kw(sql);
        for noise in ["NULL", "NAN", "AUTHID", "IS", "AS"] {
            assert!(
                !has(&s, noise),
                "`{noise}` leaked at a structural IS/body `{sql}`: {s:?}"
            );
        }
        if sql == "DECLARE SUBTYPE s IS |" {
            assert!(
                has(&s, "JSON"),
                "native JSON subtype base type missing at `{sql}`: {s:?}"
            );
        } else {
            assert!(
                !has(&s, "JSON"),
                "`JSON` leaked at a structural IS/body `{sql}`: {s:?}"
            );
        }
    }

    // A real predicate `IS` still offers its tails.
    assert!(has(&kw("SELECT a FROM t WHERE x IS |"), "NULL"));
    assert!(has(&kw("SELECT a FROM t WHERE x IS NOT |"), "JSON"));

    // The routine header before the body keyword still offers its options.
    assert!(has(&kw("CREATE PROCEDURE p |"), "AS"));
    assert!(has(
        &kw("CREATE FUNCTION f (p IN NUMBER) RETURN NUMBER |"),
        "DETERMINISTIC"
    ));
}

/// `GRANT … TO grantee` ends with the option phrase appropriate to the privilege
/// kind — `WITH GRANT OPTION` for object privileges (`… ON obj …`), `WITH ADMIN
/// OPTION` for system privileges / roles — and once `WITH` is typed only the bare
/// option remains (never the whole `WITH … OPTION` again). Multi-table `INSERT
/// ALL`/`FIRST` has no `RETURNING`, and its `WHEN` branch expects a predicate.
#[test]
fn grant_option_and_insert_all_do_not_offer_wrong_tail() {
    let kw = |sql: &str| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };

    assert_eq!(
        kw("GRANT SELECT ON t TO u |"),
        vec!["WITH GRANT OPTION".to_string()]
    );
    assert_eq!(
        kw("GRANT SELECT ON t TO u WITH |"),
        vec!["GRANT OPTION".to_string()]
    );
    assert_eq!(
        kw("GRANT CREATE SESSION TO u |"),
        vec!["WITH ADMIN OPTION".to_string()]
    );
    assert_eq!(
        kw("GRANT CREATE SESSION TO u WITH |"),
        vec!["ADMIN OPTION".to_string()]
    );
    assert_eq!(
        kw("GRANT CREATE SESSION TO on |"),
        vec!["WITH ADMIN OPTION".to_string()]
    );
    assert_eq!(
        kw("GRANT CREATE SESSION TO with |"),
        vec!["WITH ADMIN OPTION".to_string()]
    );

    let has = |v: &[String], s: &str| v.iter().any(|x| x == s);
    // Single-table INSERT keeps RETURNING; multi-table conditional/unconditional
    // INSERT ALL/FIRST never offers it.
    assert!(has(&kw("INSERT INTO t VALUES (1) |"), "RETURNING"));
    for sql in [
        "INSERT ALL INTO t1 VALUES (1) WHEN |",
        "INSERT ALL INTO t1 VALUES (1) INTO t2 VALUES (2) |",
        "INSERT FIRST WHEN x > 1 THEN INTO t1 VALUES (1) |",
    ] {
        assert!(
            !has(&kw(sql), "RETURNING"),
            "RETURNING leaked into multi-table INSERT `{sql}`: {:?}",
            kw(sql)
        );
    }
}

/// A binary set / collection operator in the select list (`a UNION |`, `a MULTISET
/// UNION |`) leaves its right operand pending, so `FROM` is premature — the query
/// set operators are also handled by the set-op continuation (which offers
/// `SELECT`), but the collection (`MULTISET …`) operators must not leak `FROM`.
/// Ordinary complete items still offer it.
#[test]
fn from_is_not_offered_after_a_set_or_collection_operator() {
    let kw = |sql: &str| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let has_from = |sql: &str| kw(sql).iter().any(|x| x == "FROM");

    for sql in [
        "SELECT a UNION |",
        "SELECT a INTERSECT |",
        "SELECT a MINUS |",
        "SELECT a MULTISET UNION |",
        "SELECT a MULTISET INTERSECT |",
        "SELECT a MULTISET EXCEPT |",
        "SELECT a MULTISET |",
    ] {
        assert!(
            !has_from(sql),
            "FROM offered after a set/collection operator `{sql}`: {:?}",
            kw(sql)
        );
    }
    // Ordinary complete items still offer FROM.
    assert!(has_from("SELECT a |"));
    assert!(has_from("SELECT a, b |"));
}

/// A MySQL index hint after a table reference (`FROM t USE |`) offers `INDEX`/`KEY`
/// instead of leaking the query-clause continuation (the trailing `USE`/`IGNORE`/
/// `FORCE` was previously mistaken for a table alias). It stays scoped: a
/// statement-initial `USE db`, a DML modifier (`DELETE IGNORE`), and the same
/// keyword in DDL (`CREATE TABLESPACE … USE LOGFILE`) are untouched.
#[test]
fn mysql_family_index_hint_after_table_offers_index_not_clause_continuation() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let kw = |sql: &str, db| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |v: &[String], s: &str| v.iter().any(|x| x == s);

    for db in [MySQL, MariaDB] {
        for sql in [
            "SELECT a FROM t USE |",
            "SELECT a FROM t IGNORE |",
            "SELECT a FROM t alias FORCE |",
        ] {
            let s = kw(sql, db);
            assert!(
                has(&s, "INDEX") && has(&s, "KEY"),
                "index hint missing INDEX/KEY `{sql}` {db:?}: {s:?}"
            );
            assert!(
                !has(&s, "WHERE") && !has(&s, "JOIN"),
                "clause continuation leaked at hint `{sql}` {db:?}: {s:?}"
            );
        }
        assert_eq!(
            kw("SELECT a FROM t USE INDEX |", db),
            vec!["FOR".to_string()]
        );
        assert_eq!(
            kw("SELECT a FROM t USE INDEX FOR |", db),
            vec![
                "JOIN".to_string(),
                "ORDER BY".to_string(),
                "GROUP BY".to_string()
            ]
        );
        assert_eq!(
            kw("SELECT a FROM t USE INDEX FOR ORDER |", db),
            vec!["BY".to_string()]
        );
        assert_eq!(
            kw("SELECT a FROM t USE INDEX FOR GROUP |", db),
            vec!["BY".to_string()]
        );
        for leaked in ["UPDATE", "SHARE"] {
            assert!(
                !has(&kw("SELECT a FROM t USE INDEX FOR |", db), leaked),
                "row-locking keyword leaked into index-hint purpose slot: {leaked} {db:?}"
            );
        }

        // Not an index hint: keep the existing meaning.
        assert!(has(&kw("DELETE IGNORE |", db), "FROM")); // DML modifier
        assert!(
            has(&kw("CREATE TABLESPACE ts USE |", db), "LOGFILE"),
            "DDL USE lost LOGFILE in {db:?}"
        );
        assert!(
            !has(&kw("SELECT a FROM t |", db), "INDEX"),
            "ordinary table continuation leaked INDEX in {db:?}"
        );
    }
}

#[test]
fn oracle_mode_mysql_index_hint_keyword_tails_do_not_offer_catalog_or_hint_keywords() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for sql in [
        "SELECT a FROM t USE |",
        "SELECT a FROM t IGNORE |",
        "SELECT a FROM t FORCE |",
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "Oracle table-alias tail should stay a query continuation at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            contains(&final_suggestions, "JOIN") && contains(&final_suggestions, "WHERE"),
            "Oracle table-alias tail lost query continuation at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in ["INDEX", "KEY"] {
            assert!(
                !contains(&keywords, leaked) && !contains(&final_suggestions, leaked),
                "{leaked} leaked as a MySQL index-hint keyword in Oracle mode at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }

    for sql in [
        "SELECT a FROM t USE |",
        "SELECT a FROM t IGNORE |",
        "SELECT a FROM t FORCE |",
        "SELECT a FROM t USE INDEX |",
        "SELECT a FROM t USE INDEX FOR |",
        "SELECT a FROM t USE INDEX FOR ORDER |",
        "SELECT a FROM t USE INDEX FOR GROUP |",
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert!(
            kind.is_none() || matches!(kind, Some(ExpectedObjectSuggestionKind::NoSuggestions)),
            "Oracle-mode MySQL index-hint tail resolved object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "APP_USER",
            "SCOTT",
            "RUN_JOB",
            "CALC_TOTAL",
            "EMPNO",
            "ENAME",
            "INDEX",
            "KEY",
            "BY",
        ] {
            assert!(
                !contains(&keywords, leaked) && !contains(&final_suggestions, leaked),
                "{leaked} leaked into Oracle-mode MySQL index-hint tail at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
}

#[test]
fn mysql_family_index_hint_prefixed_final_suggestions_stay_slot_specific() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for db in [MySQL, MariaDB] {
        for (sql, expected, leaked) in [
            (
                "SELECT * FROM t USE I|",
                "INDEX",
                &[
                    "INNER JOIN",
                    "INTERVAL",
                    "INTO OUTFILE",
                    "EMP",
                    "EMPNO",
                    "IDX_EMP_NAME",
                ][..],
            ),
            (
                "SELECT * FROM t USE K|",
                "KEY",
                &["KEEP", "KEYS", "EMP", "EMPNO", "IDX_EMP_NAME"][..],
            ),
            (
                "SELECT * FROM t USE INDEX F|",
                "FOR",
                &["FETCH FIRST", "FROM", "FULL OUTER JOIN", "EMP", "EMPNO"][..],
            ),
            (
                "SELECT * FROM t USE INDEX FOR J|",
                "JOIN",
                &[
                    "JSON_TABLE",
                    "INNER JOIN",
                    "NATURAL JOIN",
                    "ON",
                    "USING",
                    "UPDATE",
                    "SHARE",
                    "EMP",
                    "EMPNO",
                ][..],
            ),
            (
                "SELECT * FROM t USE INDEX FOR O|",
                "ORDER BY",
                &["OFFSET", "ON", "OR", "EMP", "EMPNO"][..],
            ),
            (
                "SELECT * FROM t USE INDEX FOR ORDER B|",
                "BY",
                &["BETWEEN", "BY VALUE", "EMP", "EMPNO"][..],
            ),
            (
                "SELECT * FROM t USE INDEX FOR G|",
                "GROUP BY",
                &["GRANT", "GROUPING SETS", "EMP", "EMPNO"][..],
            ),
            (
                "SELECT * FROM t USE INDEX FOR GROUP B|",
                "BY",
                &["BETWEEN", "BY VALUE", "EMP", "EMPNO"][..],
            ),
        ] {
            let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
            assert_eq!(
                kind, None,
                "index-hint keyword slot should not resolve object kind at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
            assert!(
                contains(&keywords, expected) && contains(&final_suggestions, expected),
                "{expected} missing from index-hint final suggestions at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
            for unexpected in leaked {
                assert!(
                    !contains(&keywords, unexpected) && !contains(&final_suggestions, unexpected),
                    "{unexpected} leaked into index-hint keyword slot at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
                );
            }
        }
    }
}

#[test]
fn mysql_family_select_modifiers_continue_until_projection_starts() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let kw = |sql: &str, db| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |values: &[String], keyword: &str| values.iter().any(|value| value == keyword);

    for db in [MySQL, MariaDB] {
        let after_distinct = kw("SELECT DISTINCT |", db);
        for expected in [
            "HIGH_PRIORITY",
            "STRAIGHT_JOIN",
            "SQL_SMALL_RESULT",
            "SQL_BIG_RESULT",
        ] {
            assert!(
                has(&after_distinct, expected),
                "{expected} missing after MySQL-family SELECT DISTINCT for {db:?}: {after_distinct:?}"
            );
        }
        for invalid in ["ALL", "DISTINCT", "DISTINCTROW", "FROM"] {
            assert!(
                !has(&after_distinct, invalid),
                "{invalid} leaked after MySQL-family SELECT DISTINCT for {db:?}: {after_distinct:?}"
            );
        }

        let after_priority = kw("SELECT HIGH_PRIORITY |", db);
        for expected in ["STRAIGHT_JOIN", "SQL_BUFFER_RESULT", "SQL_CALC_FOUND_ROWS"] {
            assert!(
                has(&after_priority, expected),
                "{expected} missing after MySQL-family SELECT HIGH_PRIORITY for {db:?}: {after_priority:?}"
            );
        }
        assert!(
            !has(&after_priority, "FROM"),
            "FROM leaked before a projection after MySQL-family SELECT HIGH_PRIORITY for {db:?}: {after_priority:?}"
        );

        let after_result = kw("SELECT SQL_SMALL_RESULT |", db);
        assert!(has(&after_result, "SQL_BUFFER_RESULT"), "{after_result:?}");
        for invalid in ["HIGH_PRIORITY", "STRAIGHT_JOIN", "SQL_BIG_RESULT"] {
            assert!(
                !has(&after_result, invalid),
                "{invalid} leaked after SQL_SMALL_RESULT for {db:?}: {after_result:?}"
            );
        }

        let after_cache = kw("SELECT SQL_NO_CACHE |", db);
        assert!(has(&after_cache, "SQL_CALC_FOUND_ROWS"), "{after_cache:?}");
        for invalid in ["HIGH_PRIORITY", "SQL_BUFFER_RESULT", "SQL_CACHE"] {
            assert!(
                !has(&after_cache, invalid),
                "{invalid} leaked after SQL_NO_CACHE for {db:?}: {after_cache:?}"
            );
        }

        let prefixed_modifier_head = kw("SELECT s|", db);
        assert!(
            has(&prefixed_modifier_head, "SQL_BIG_RESULT"),
            "MySQL-family SELECT modifier prefix should stay available before projection starts for {db:?}: {prefixed_modifier_head:?}"
        );
        let (_, _, prefixed_projection) = audit_final_suggestions_for("SELECT s| FROM emp", db);
        for invalid in ["STRAIGHT_JOIN", "SQL_SMALL_RESULT", "SQL_BIG_RESULT"] {
            assert!(
                !has(&prefixed_projection, invalid),
                "{invalid} leaked into final prefixed MySQL-family select-list expression suggestions for {db:?}: {prefixed_projection:?}"
            );
        }

        let after_wildcard = kw("SELECT HIGH_PRIORITY * |", db);
        assert!(
            has(&after_wildcard, "FROM"),
            "FROM missing after MySQL-family SELECT modifier plus wildcard projection for {db:?}: {after_wildcard:?}"
        );
    }

    for sql in [
        "SELECT |",
        "SELECT ALL |",
        "SELECT DISTINCT |",
        "SELECT UNIQUE |",
        "SELECT s|",
    ] {
        let oracle = kw(sql, Oracle);
        for mysql_only in [
            "HIGH_PRIORITY",
            "STRAIGHT_JOIN",
            "SQL_SMALL_RESULT",
            "SQL_BIG_RESULT",
            "SQL_BUFFER_RESULT",
            "SQL_CACHE",
            "SQL_NO_CACHE",
            "SQL_CALC_FOUND_ROWS",
        ] {
            assert!(
                !has(&oracle, mysql_only),
                "{mysql_only} leaked into Oracle SELECT modifier slot at `{sql}`: {oracle:?}"
            );
        }
    }
}

#[test]
fn select_start_production_suggestions_include_distinct_for_every_database() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    for db in [Oracle, MySQL, MariaDB] {
        for sql in ["SELECT |", "SELECT | FROM emp"] {
            let suggestions = query_keyword_completion_suggestions(sql, db);
            assert!(
                suggestions
                    .iter()
                    .any(|suggestion| suggestion.eq_ignore_ascii_case("DISTINCT")),
                "DISTINCT missing from production suggestions at `{sql}` for {db:?}: {suggestions:?}"
            );
        }
    }
}

/// `FROM` in the select list is gated on a *top-level* `SELECT`: a `SELECT` buried
/// in a sub-paren (a CTE body, a scalar subquery) does not put the cursor in a
/// projection, so `WITH c AS (SELECT …) … |` (in the WITH clause) must not offer
/// `FROM`, while the main query and a real (current-query-scoped) subquery select
/// list still do.
#[test]
fn select_list_from_requires_a_top_level_select() {
    let kw = |sql: &str| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let has_from = |sql: &str| kw(sql).iter().any(|x| x == "FROM");

    // WITH-clause positions (only the CTE body has a SELECT, at depth > 0).
    assert!(!has_from("WITH c (a) AS (SELECT 1 FROM dual) |"));
    assert!(!has_from(
        "WITH c (a) AS (SELECT 1 FROM dual) SEARCH DEPTH FIRST BY a SET sq CYCLE |"
    ));
    // Real select lists (top-level SELECT, or a current-query-scoped subquery).
    assert!(has_from("WITH c AS (SELECT 1 FROM dual) SELECT a |"));
    assert!(has_from("SELECT a |"));
    assert!(has_from("SELECT * FROM (SELECT a |) x"));
    assert!(has_from("SELECT (SELECT a |) FROM dual"));
}

/// Two Oracle inline / DML clauses that previously fell through to the wrong tail:
/// the identity chain `GENERATED ALWAYS |`→`AS` (was the whole column catalog), and
/// the DML error-logging clause `… LOG |`→`ERRORS` (was `RETURNING`). Once `LOG`
/// appears in a DML statement, `RETURNING` is no longer offered (it precedes it),
/// while a plain DML still offers `RETURNING`. The materialized-view `LOG` is
/// unaffected (DML-gated).
#[test]
fn identity_chain_and_dml_error_logging_offer_the_right_tail() {
    let kw = |sql: &str| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let has = |v: &[String], s: &str| v.iter().any(|x| x == s);

    // Identity chain.
    assert_eq!(
        kw("CREATE TABLE t (a INT GENERATED ALWAYS |)"),
        vec!["AS".to_string()]
    );
    assert!(has(
        &kw("CREATE TABLE t (a INT GENERATED BY DEFAULT |)"),
        "AS"
    ));
    assert_eq!(
        kw("CREATE TABLE t (a INT GENERATED |)"),
        vec!["ALWAYS".to_string(), "BY".to_string()]
    );

    // DML error logging.
    assert_eq!(
        kw("INSERT INTO t VALUES (1) LOG |"),
        vec!["ERRORS".to_string()]
    );
    assert_eq!(kw("UPDATE t SET a = 1 LOG |"), vec!["ERRORS".to_string()]);
    assert_eq!(
        kw("DELETE FROM t WHERE x = 1 LOG |"),
        vec!["ERRORS".to_string()]
    );
    assert!(!has(&kw("UPDATE t SET log |"), "ERRORS"));
    assert!(!has(&kw("UPDATE t SET a = log |"), "ERRORS"));
    assert_eq!(
        kw("INSERT INTO t VALUES (1) LOG ERRORS REJECT LIMIT |"),
        vec!["UNLIMITED".to_string()]
    );
    assert_eq!(
        kw("INSERT INTO t VALUES (1) LOG ERRORS REJECT |"),
        vec!["LIMIT".to_string()]
    );
    let into_reject_tail = kw("INSERT INTO t VALUES (1) LOG ERRORS INTO reject |");
    assert!(!has(&into_reject_tail, "LIMIT"), "{into_reject_tail:?}");
    assert!(!has(&into_reject_tail, "VALUES"), "{into_reject_tail:?}");
    assert!(!has(&into_reject_tail, "SELECT"), "{into_reject_tail:?}");
    assert!(
        has(&into_reject_tail, "REJECT LIMIT"),
        "{into_reject_tail:?}"
    );
    assert!(!has(
        &kw("INSERT INTO t VALUES (1) LOG ERRORS INTO reject LIMIT |"),
        "UNLIMITED"
    ));
    assert!(has(
        &kw("INSERT INTO t VALUES (1) LOG ERRORS INTO err$_t REJECT LIMIT |"),
        "UNLIMITED"
    ));
    for sql in [
        "INSERT INTO t VALUES (1) LOG ERRORS |",
        "UPDATE t SET a = 1 WHERE x = 1 LOG ERRORS INTO el |",
    ] {
        assert!(
            !has(&kw(sql), "RETURNING"),
            "RETURNING leaked after LOG ERRORS `{sql}`: {:?}",
            kw(sql)
        );
    }
    // Plain DML still offers RETURNING.
    assert!(has(&kw("INSERT INTO t VALUES (1) |"), "RETURNING"));
    assert!(has(&kw("DELETE FROM t WHERE x = 1 |"), "RETURNING"));
}

#[test]
fn dml_error_logging_final_suggestions_stay_slot_specific() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);
    let assert_no_catalog_noise = |sql: &str, suggestions: &[String]| {
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "APP_USER",
            "SCOTT",
            "RUN_JOB",
            "CALC_TOTAL",
            "EMPNO",
            "ENAME",
            "DEPTNO",
            "DNAME",
        ] {
            assert!(
                !contains(suggestions, leaked),
                "{leaked} leaked into LOG ERRORS keyword slot at `{sql}`: {suggestions:?}"
            );
        }
    };

    for (sql, expected) in [
        ("INSERT INTO emp VALUES (1) LOG |", &["ERRORS"][..]),
        ("UPDATE emp SET sal = 1 LOG |", &["ERRORS"]),
        ("DELETE FROM emp WHERE empno = 1 LOG |", &["ERRORS"]),
        (
            "INSERT INTO emp VALUES (1) LOG ERRORS |",
            &["INTO", "REJECT LIMIT"],
        ),
        (
            "INSERT INTO emp VALUES (1) LOG ERRORS INTO err$_emp |",
            &["REJECT LIMIT"],
        ),
        ("INSERT INTO emp VALUES (1) LOG ERRORS REJECT |", &["LIMIT"]),
        (
            "INSERT INTO emp VALUES (1) LOG ERRORS REJECT LIMIT |",
            &["UNLIMITED"],
        ),
        (
            "INSERT INTO emp VALUES (1) LOG ERRORS INTO err$_emp REJECT LIMIT |",
            &["UNLIMITED"],
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "LOG ERRORS keyword slot should not resolve an object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        for keyword in expected {
            assert!(
                contains(&final_suggestions, keyword),
                "{keyword} missing from LOG ERRORS keyword slot at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        assert_no_catalog_noise(sql, &final_suggestions);
    }

    let (_kind, keywords, final_suggestions) = audit_final_suggestions_for(
        "INSERT INTO emp VALUES (1) LOG ERRORS REJECT LIMIT UNLIMITED |",
        Oracle,
    );
    for leaked in ["RETURNING", "INTO", "REJECT LIMIT", "UNLIMITED"] {
        assert!(
            !contains(&final_suggestions, leaked),
            "{leaked} re-offered after completed LOG ERRORS tail: keywords={keywords:?} final={final_suggestions:?}"
        );
    }
    let (_kind, keywords, final_suggestions) = audit_final_suggestions_for(
        "INSERT INTO emp VALUES (1) LOG ERRORS REJECT LIMIT UNLIMITED n|",
        Oracle,
    );
    assert!(
        final_suggestions.is_empty(),
        "completed LOG ERRORS tail with prefix should not offer catalog or stale keywords: keywords={keywords:?} final={final_suggestions:?}"
    );

    let (kind, keywords, final_suggestions) = audit_final_suggestions_for(
        "INSERT INTO emp VALUES (1) LOG ERRORS INTO err$_emp REJECT LIMIT 10 |",
        Oracle,
    );
    assert_eq!(
        kind, None,
        "completed numeric LOG ERRORS tail should not resolve object kind: keywords={keywords:?} final={final_suggestions:?}"
    );
    assert!(
        final_suggestions.is_empty(),
        "completed numeric LOG ERRORS tail should not offer catalog or stale keywords: keywords={keywords:?} final={final_suggestions:?}"
    );
    let (_kind, keywords, final_suggestions) = audit_final_suggestions_for(
        "INSERT INTO emp VALUES (1) LOG ERRORS INTO err$_emp REJECT LIMIT 10 n|",
        Oracle,
    );
    assert!(
        final_suggestions.is_empty(),
        "completed numeric LOG ERRORS tail with prefix should not offer catalog or stale keywords: keywords={keywords:?} final={final_suggestions:?}"
    );

    for db in [MySQL, MariaDB] {
        for sql in [
            "INSERT INTO emp VALUES (1) LOG |",
            "INSERT INTO emp VALUES (1) LOG ERRORS |",
            "INSERT INTO emp VALUES (1) LOG ERRORS INTO |",
            "INSERT INTO emp VALUES (1) LOG ERRORS INTO app.|",
            "INSERT INTO emp VALUES (1) LOG ERRORS REJECT |",
            "INSERT INTO emp VALUES (1) LOG ERRORS REJECT LIMIT |",
            "INSERT INTO emp VALUES (1) LOG ERRORS REJECT LIMIT UNLIMITED |",
            "UPDATE emp SET sal = 1 LOG |",
            "DELETE FROM emp WHERE empno = 1 LOG ERRORS |",
        ] {
            let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
            assert!(
                matches!(kind, None | Some(ExpectedObjectSuggestionKind::NoSuggestions)),
                "Oracle-only LOG ERRORS slot should not resolve object kind in {db:?} at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
            assert!(
                final_suggestions.is_empty(),
                "Oracle-only LOG ERRORS slot leaked suggestions in {db:?} at `{sql}`: kind={kind:?} keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
}

/// `SET TRANSACTION` is dialect-scoped: MySQL offers only `ISOLATION`/`READ` (the
/// Oracle `USE ROLLBACK SEGMENT` / `NAME` are not valid there) and its full set of
/// four isolation levels, while Oracle keeps `USE`/`NAME` and its two levels.
#[test]
fn set_transaction_options_are_dialect_scoped() {
    let kw = |sql: &str, db: crate::db::DatabaseType| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |v: &[String], s: &str| v.iter().any(|x| x == s);
    use crate::db::DatabaseType::{MySQL, Oracle};

    // MySQL: no Oracle-only USE/NAME; all four isolation levels.
    let m = kw("SET TRANSACTION |", MySQL);
    assert!(
        has(&m, "ISOLATION") && has(&m, "READ"),
        "MySQL SET TRANSACTION missing option: {m:?}"
    );
    assert!(
        !has(&m, "USE") && !has(&m, "NAME"),
        "Oracle-only SET TRANSACTION option leaked into MySQL: {m:?}"
    );
    let m_root = kw("SET |", MySQL);
    for lead in [
        "TRANSACTION",
        "GLOBAL",
        "SESSION",
        "NAMES",
        "CHARSET",
        "PERSIST",
        "PERSIST_ONLY",
    ] {
        assert!(
            has(&m_root, lead),
            "MySQL SET tail missing `{lead}`: {m_root:?}"
        );
    }
    let m_global = kw("SET GLOBAL |", MySQL);
    assert!(
        has(&m_global, "TRANSACTION"),
        "MySQL SET GLOBAL tail missing TRANSACTION: {m_global:?}"
    );
    let m_session = kw("SET SESSION |", MySQL);
    assert!(
        has(&m_session, "TRANSACTION"),
        "MySQL SET SESSION tail missing TRANSACTION: {m_session:?}"
    );
    let m_global_tx = kw("SET GLOBAL TRANSACTION |", MySQL);
    assert!(
        has(&m_global_tx, "ISOLATION") && has(&m_global_tx, "READ"),
        "MySQL SET GLOBAL TRANSACTION missing option: {m_global_tx:?}"
    );
    let m_session_tx = kw("SET SESSION TRANSACTION |", MySQL);
    assert!(
        has(&m_session_tx, "ISOLATION") && has(&m_session_tx, "READ"),
        "MySQL SET SESSION TRANSACTION missing option: {m_session_tx:?}"
    );
    let m_global_tx_read = kw("SET GLOBAL TRANSACTION READ |", MySQL);
    assert!(
        has(&m_global_tx_read, "ONLY") && has(&m_global_tx_read, "WRITE"),
        "MySQL SET GLOBAL TRANSACTION READ options missing: {m_global_tx_read:?}"
    );
    let m_session_tx_read = kw("SET SESSION TRANSACTION READ |", MySQL);
    assert!(
        has(&m_session_tx_read, "ONLY") && has(&m_session_tx_read, "WRITE"),
        "MySQL SET SESSION TRANSACTION READ options missing: {m_session_tx_read:?}"
    );
    let ml = kw("SET TRANSACTION ISOLATION LEVEL |", MySQL);
    for level in [
        "SERIALIZABLE",
        "READ COMMITTED",
        "REPEATABLE READ",
        "READ UNCOMMITTED",
    ] {
        assert!(
            has(&ml, level),
            "MySQL isolation level `{level}` missing: {ml:?}"
        );
    }
    let mysql_commit_write = kw("COMMIT WRITE |", MySQL);
    for oracle_only in ["WAIT", "NOWAIT", "IMMEDIATE", "BATCH"] {
        assert!(
            !has(&mysql_commit_write, oracle_only),
            "Oracle COMMIT WRITE option leaked into MySQL: {mysql_commit_write:?}"
        );
    }

    // Oracle: keeps USE/NAME and its two levels (no REPEATABLE READ).
    let o = kw("SET TRANSACTION |", Oracle);
    assert!(has(&o, "USE") && has(&o, "NAME"));
    let ol = kw("SET TRANSACTION ISOLATION LEVEL |", Oracle);
    assert!(has(&ol, "SERIALIZABLE") && has(&ol, "READ COMMITTED") && !has(&ol, "REPEATABLE READ"));

    let o_root = kw("SET |", Oracle);
    assert!(
        has(&o_root, "TRANSACTION"),
        "Oracle SET root missing TRANSACTION: {o_root:?}"
    );

    let o_tx_use = kw("SET TRANSACTION USE |", Oracle);
    assert!(
        has(&o_tx_use, "ROLLBACK"),
        "Oracle SET TRANSACTION USE missing ROLLBACK: {o_tx_use:?}"
    );
    let o_tx_use_rollback = kw("SET TRANSACTION USE ROLLBACK |", Oracle);
    assert!(
        has(&o_tx_use_rollback, "SEGMENT"),
        "Oracle SET TRANSACTION USE ROLLBACK missing SEGMENT: {o_tx_use_rollback:?}"
    );
}

/// The row-locking tail is dialect-scoped: Oracle has `FOR UPDATE [WAIT n]`,
/// while MySQL also has `FOR SHARE` but no Oracle `WAIT <n>` wait-mode.
#[test]
fn for_update_wait_mode_is_oracle_only() {
    let kw = |sql: &str, db: crate::db::DatabaseType| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |v: &[String], s: &str| v.iter().any(|x| x == s);
    use crate::db::DatabaseType::{MySQL, Oracle};

    for sql in [
        "SELECT a FROM t FOR UPDATE |",
        "SELECT a FROM t FOR SHARE |",
    ] {
        let m = kw(sql, MySQL);
        assert!(
            has(&m, "NOWAIT") && has(&m, "SKIP") && has(&m, "OF"),
            "MySQL lock option missing `{sql}`: {m:?}"
        );
        assert!(
            !has(&m, "WAIT"),
            "Oracle-only WAIT leaked into MySQL `{sql}`: {m:?}"
        );
    }
    let o = kw("SELECT a FROM t FOR UPDATE |", Oracle);
    assert!(
        has(&o, "WAIT") && has(&o, "NOWAIT") && has(&o, "SKIP"),
        "Oracle lock option missing: {o:?}"
    );
    let oracle_share = kw("SELECT a FROM t FOR SHARE |", Oracle);
    for leaked in ["OF", "NOWAIT", "WAIT", "SKIP", "SELECT", "WHERE"] {
        assert!(
            !has(&oracle_share, leaked),
            "{leaked} leaked after unsupported Oracle FOR SHARE: {oracle_share:?}"
        );
    }
}

/// MySQL-family `CREATE INDEX` offers `ON <table>` before the indexed-column list,
/// then the dialect-specific index options after the list closes. `ON` itself is
/// single-use; `USING` remains available as an index option after the column list.
#[test]
fn mysql_family_create_index_on_and_using_are_single_use() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let kw = |sql: &str, db| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    for db in [MySQL, MariaDB] {
        assert_eq!(
            kw("CREATE INDEX i |", db),
            vec!["ON".to_string(), "USING".to_string()],
            "fresh CREATE INDEX slot failed for {db:?}"
        );
        assert_eq!(
            kw("CREATE INDEX on |", db),
            vec!["ON".to_string(), "USING".to_string()],
            "prefix CREATE INDEX on failed for {db:?}"
        );
        assert_eq!(
            kw("CREATE INDEX using |", db),
            vec!["ON".to_string(), "USING".to_string()],
            "prefix CREATE INDEX using failed for {db:?}"
        );
        // `USING` follows the indexed-column list, not the bare table — so `ON t |`
        // (before the `(…)`) must not offer it, while `ON t (a) |` does.
        assert!(kw("CREATE INDEX i ON t |", db).is_empty());
        assert!(kw("CREATE INDEX i ON on |", db).is_empty());
        assert!(kw("CREATE INDEX i ON using |", db).is_empty());
        assert!(kw("CREATE INDEX i ON scott.using |", db).is_empty());
        assert!(kw("CREATE INDEX i ON t USING |", db).is_empty());
        let after_columns = kw("CREATE INDEX i ON t (a) |", db);
        for expected in [
            "ALGORITHM",
            "COMMENT",
            "KEY_BLOCK_SIZE",
            "LOCK",
            "USING",
            "WITH",
        ] {
            assert!(
                after_columns.iter().any(|keyword| keyword == expected),
                "{expected} missing after CREATE INDEX column list for {db:?}: {after_columns:?}"
            );
        }
        assert!(
            !after_columns.iter().any(|keyword| keyword == "ON"),
            "ON re-offered after CREATE INDEX column list for {db:?}: {after_columns:?}"
        );
        assert_eq!(
            kw("CREATE INDEX i USING BTREE |", db),
            vec!["ON".to_string()],
            "ON should be available only after USING BTREE for {db:?}"
        );
        let using_types = kw("CREATE INDEX i USING |", db);
        for expected in ["BTREE", "HASH"] {
            assert!(
                using_types.iter().any(|keyword| keyword == expected),
                "{expected} missing from CREATE INDEX USING types for {db:?}: {using_types:?}"
            );
        }
        if db == MariaDB {
            assert!(
                using_types.iter().any(|keyword| keyword == "RTREE"),
                "RTREE missing from MariaDB CREATE INDEX USING types: {using_types:?}"
            );
        }
        assert!(kw("CREATE INDEX i USING BTREE ON using |", db).is_empty());
        assert!(!kw("CREATE INDEX i ON t (a) USING BTREE |", db)
            .iter()
            .any(|keyword| keyword == "USING"));
        assert!(!kw("CREATE INDEX i USING BTREE ON t (a) |", db)
            .iter()
            .any(|keyword| keyword == "ON"));
    }
}

/// The `GRANT … WITH {GRANT|ADMIN} OPTION` clause is single-use and progresses
/// `WITH`→`GRANT OPTION`→(typed `WITH GRANT`)→`OPTION`→complete. Once complete it
/// offers nothing — and must not let the privilege `SELECT` in `GRANT SELECT …`
/// fall through to leak the select-list `FROM`.
#[test]
fn grant_with_option_clause_is_single_use_and_does_not_leak_from() {
    let kw = |sql: &str, db: crate::db::DatabaseType| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    use crate::db::DatabaseType::{MySQL, Oracle};

    assert_eq!(
        kw("GRANT SELECT ON t TO u WITH GRANT |", Oracle),
        vec!["OPTION".to_string()]
    );
    for sql in [
        "GRANT SELECT ON t TO u WITH GRANT OPTION |",
        "GRANT CREATE SESSION TO u WITH ADMIN OPTION |",
    ] {
        assert!(
            kw(sql, Oracle).is_empty(),
            "completed GRANT re-offered `{sql}`: {:?}",
            kw(sql, Oracle)
        );
    }
    assert!(kw("GRANT SELECT ON t.* TO u WITH GRANT OPTION |", MySQL).is_empty());
    // The earlier-stage outputs are unchanged.
    assert_eq!(
        kw("GRANT SELECT ON t TO u |", Oracle),
        vec!["WITH GRANT OPTION".to_string()]
    );
    assert_eq!(
        kw("GRANT SELECT ON t TO u WITH |", Oracle),
        vec!["GRANT OPTION".to_string()]
    );
}

/// `CREATE [OR REPLACE] TYPE ty AS|IS |` offers the type-spec kind (`OBJECT`,
/// `TABLE OF`, `VARRAY`) — the entry into an otherwise-complete grammar (`TABLE OF`
/// → types already works). A TYPE *body* (`CREATE TYPE BODY ty AS |`, the method
/// implementations) and an unrelated `AS` (a column alias) must not get it.
#[test]
fn create_type_spec_offers_object_table_varray() {
    let kw = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let has = |v: &Vec<String>, s: &str| v.iter().any(|x| x == s);
    let is_kind = |v: &Vec<String>| has(v, "OBJECT") && has(v, "TABLE OF") && has(v, "VARRAY");

    assert!(is_kind(&kw("CREATE TYPE ty AS |")));
    assert!(is_kind(&kw("CREATE OR REPLACE TYPE ty AS |")));
    assert!(is_kind(&kw("CREATE TYPE ty IS |")));
    // Type body and unrelated `AS` must not get the kind keywords.
    assert!(!has(&kw("CREATE TYPE BODY ty AS |"), "OBJECT"));
    assert!(!has(&kw("SELECT a FROM t WHERE x AS |"), "OBJECT"));
    // Downstream is unchanged: `TABLE OF` still leads to the type catalog.
    assert!(has(&kw("CREATE TYPE ty AS TABLE OF |"), "NUMBER"));
}

/// MySQL table options after `CREATE TABLE (…) |` are each single-use, so an
/// option already specified must drop out of the continuation while the others
/// stay valid. Mirrors the column-property and clause single-use guards.
#[test]
fn mysql_family_create_table_options_are_single_use() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let kw = |sql: &str, db| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |v: &Vec<String>, s: &str| v.iter().any(|x| x == s);

    for db in [MySQL, MariaDB] {
        // Before the definition/source, table options are not grammatical.
        let before_definition = kw("CREATE TABLE engine |", db);
        for opt in [
            "ENGINE",
            "DEFAULT CHARSET",
            "COLLATE",
            "AUTO_INCREMENT",
            "COMMENT",
            "ROW_FORMAT",
        ] {
            assert!(
                !has(&before_definition, opt),
                "pre-definition CREATE TABLE slot leaked `{opt}` for {db:?}: {before_definition:?}"
            );
        }

        // Fresh option slot: the whole catalog.
        let all = kw("CREATE TABLE t (a INT) |", db);
        for opt in [
            "ENGINE",
            "DEFAULT CHARSET",
            "COLLATE",
            "AUTO_INCREMENT",
            "COMMENT",
            "ROW_FORMAT",
        ] {
            assert!(
                has(&all, opt),
                "fresh option slot missing `{opt}` for {db:?}: {all:?}"
            );
        }
        // A specified option is not re-offered; the others remain.
        let after_engine = kw("CREATE TABLE t (a INT) ENGINE = InnoDB |", db);
        assert!(
            !has(&after_engine, "ENGINE"),
            "ENGINE re-offered for {db:?}: {after_engine:?}"
        );
        assert!(
            has(&after_engine, "AUTO_INCREMENT") && has(&after_engine, "COMMENT"),
            "unexpected table option drop for {db:?}: {after_engine:?}"
        );
        // The character-set slot is shared between its two spellings.
        let after_charset = kw("CREATE TABLE t (a INT) DEFAULT CHARSET = utf8mb4 |", db);
        assert!(
            !has(&after_charset, "DEFAULT CHARSET") && !has(&after_charset, "CHARACTER SET"),
            "charset re-offered for {db:?}: {after_charset:?}"
        );
        assert!(has(&after_charset, "ENGINE"));
        let after_char_set = kw("CREATE TABLE t (a INT) CHARACTER SET utf8 |", db);
        assert!(!has(&after_char_set, "DEFAULT CHARSET") && !has(&after_char_set, "CHARACTER SET"));
        let after_collate = kw("CREATE TABLE t (a INT) COLLATE = utf8mb4_bin |", db);
        assert!(!has(&after_collate, "COLLATE"));
        let after_comment = kw("CREATE TABLE t (a INT) COMMENT = 'doc' |", db);
        assert!(!has(&after_comment, "COMMENT"));
        let after_row_format = kw("CREATE TABLE t (a INT) ROW_FORMAT = DYNAMIC |", db);
        assert!(!has(&after_row_format, "ROW_FORMAT"));
        // Several stacked options each drop out individually.
        let stacked = kw(
            "CREATE TABLE t (a INT) ENGINE = InnoDB AUTO_INCREMENT = 5 |",
            db,
        );
        assert!(
            !has(&stacked, "ENGINE") && !has(&stacked, "AUTO_INCREMENT"),
            "stacked options should remain dropped for {db:?}: {stacked:?}"
        );
        assert!(has(&stacked, "COMMENT") && has(&stacked, "ROW_FORMAT"));
    }
}

/// A MySQL index hint (`{USE|IGNORE|FORCE} {INDEX|KEY} [FOR {JOIN|ORDER BY|GROUP
/// BY}] (list)`) closes the table reference just like a plain table, so the query
/// continuation follows it. Its `FOR JOIN` purpose is not a join clause (no
/// spurious `ON`/`USING`), and its `FOR ORDER BY`/`FOR GROUP BY` purpose is not the
/// statement clause (it does not spend the `ORDER BY`/`GROUP BY` continuation).
#[test]
fn mysql_index_hint_completes_the_table_reference() {
    let has = |v: &Vec<String>, s: &str| v.iter().any(|x| x == s);

    for db_type in [
        crate::db::DatabaseType::MySQL,
        crate::db::DatabaseType::MariaDB,
    ] {
        let kw = |sql: &str| {
            SqlEditorWidget::collect_expected_keyword_suggestions(
                "",
                &analyze_inline_cursor_sql(sql),
                Some(db_type),
            )
        };

        // The completed hint admits the same continuation as a bare table.
        for sql in [
            "SELECT * FROM t USE INDEX (i) |",
            "SELECT * FROM t FORCE KEY (i) |",
            "SELECT * FROM t USE INDEX FOR JOIN (i) |",
            "SELECT * FROM t USE INDEX FOR ORDER BY (i) |",
            "SELECT * FROM t USE INDEX FOR GROUP BY (i) |",
            "SELECT * FROM t IGNORE KEY (i) USE INDEX (j) |",
        ] {
            let s = kw(sql);
            assert!(
                has(&s, "WHERE") && has(&s, "JOIN") && has(&s, "ORDER BY") && has(&s, "GROUP BY"),
                "index-hint continuation incomplete at `{sql}` for {db_type:?}: {s:?}"
            );
            // `FOR JOIN` is an index-hint purpose, never a real join target.
            assert!(
                !has(&s, "ON") && !has(&s, "USING"),
                "index hint mistaken for a join target at `{sql}` for {db_type:?}: {s:?}"
            );
        }
        // Mid-hint slots are unaffected (the hint sub-grammar still drives them).
        assert_eq!(
            kw("SELECT * FROM t USE |"),
            vec!["INDEX".to_string(), "KEY".to_string()]
        );
        assert_eq!(kw("SELECT * FROM t USE INDEX |"), vec!["FOR".to_string()]);
        assert_eq!(
            kw("SELECT * FROM t USE INDEX FOR |"),
            vec![
                "JOIN".to_string(),
                "ORDER BY".to_string(),
                "GROUP BY".to_string()
            ]
        );
        assert_eq!(
            kw("SELECT * FROM t USE INDEX FOR ORDER |"),
            vec!["BY".to_string()]
        );
        assert_eq!(
            kw("SELECT * FROM t USE INDEX FOR GROUP |"),
            vec!["BY".to_string()]
        );
        for sql in [
            "SELECT * FROM t USE INDEX FOR JOIN |",
            "SELECT * FROM t USE INDEX FOR ORDER BY |",
            "SELECT * FROM t USE INDEX FOR GROUP BY |",
        ] {
            let s = kw(sql);
            for leaked in [
                "ON", "USING", "WHERE", "JOIN", "ORDER BY", "GROUP BY", "UPDATE", "SHARE",
            ] {
                assert!(
                    !has(&s, leaked),
                    "{db_type:?} index-hint leaked token `{leaked}` into index-list slot at `{sql}`: {s:?}"
                );
            }
        }
        // A real `ORDER BY`/`GROUP BY` after the hint is still single-use.
        assert!(!has(
            &kw("SELECT * FROM t USE INDEX (i) ORDER BY a |"),
            "ORDER BY"
        ));
        // A genuine JOIN target carrying an index hint still needs its join condition:
        // the hint tokens are walked over and the real `JOIN` is found.
        let join_hint = kw("SELECT * FROM a JOIN b USE INDEX (i) |");
        assert!(
            has(&join_hint, "ON") && has(&join_hint, "USING"),
            "join target with index hint lost ON/USING for {db_type:?}: {join_hint:?}"
        );
    }
}

/// A clause keyword that *also* occurs inside a function call — `GROUP`/`BY` in
/// `WITHIN GROUP (ORDER BY …)`, a function `RETURNING` (`JSON_VALUE(j RETURNING
/// NUMBER)`), the math function `LOG(…)` — must not be mistaken for the
/// statement-level clause (`GROUP BY ROLLUP/CUBE`, the DML `RETURNING … INTO`, the
/// `LOG ERRORS` clause). A flat `contains()` is depth-blind; the detectors are
/// scoped to the statement's top paren level. The genuine top-level clauses, and
/// the same clause inside a *real* subquery (its own token scope), still work.
#[test]
fn clause_keywords_inside_function_calls_do_not_leak_to_statement_level() {
    let kw = |sql: &str, db: crate::db::DatabaseType| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    use crate::db::DatabaseType::Oracle;
    let has = |v: &Vec<String>, s: &str| v.iter().any(|x| x == s);

    // GROUP BY's ROLLUP/CUBE/GROUPING SETS must not leak into a WITHIN GROUP ORDER BY.
    assert!(
        kw("SELECT listagg(x,',') WITHIN GROUP (ORDER BY |", Oracle).is_empty(),
        "GROUP BY extras leaked into WITHIN GROUP ORDER BY"
    );
    for sql in [
        "SELECT group FROM t ORDER BY |",
        "SELECT a FROM t ORDER BY group |",
    ] {
        let s = kw(sql, Oracle);
        assert!(
            !has(&s, "ROLLUP") && !has(&s, "CUBE") && !has(&s, "GROUPING SETS"),
            "GROUP BY extras leaked from identifier named GROUP at `{sql}`: {s:?}"
        );
    }
    let order_by_grouping = kw(
        "SELECT grouping FROM t GROUP BY grouping ORDER BY GROUPING |",
        Oracle,
    );
    assert!(
        !has(&order_by_grouping, "SETS"),
        "GROUPING SETS tail leaked into ORDER BY: {order_by_grouping:?}"
    );
    // …but a real (sub)query GROUP BY still offers them.
    assert!(has(
        &kw("SELECT count(*) FROM t GROUP BY |", Oracle),
        "ROLLUP"
    ));
    assert!(has(
        &kw("SELECT count(*) FROM t GROUP BY GROUPING |", Oracle),
        "SETS"
    ));
    assert!(has(
        &kw(
            "SELECT a FROM t WHERE x IN (SELECT b FROM s GROUP BY |",
            Oracle
        ),
        "CUBE"
    ));

    // A function `RETURNING` must not make the select item offer the DML `INTO`.
    assert!(!has(
        &kw("SELECT json_value(j, '$.a' RETURNING NUMBER) |", Oracle),
        "INTO"
    ));
    assert!(has(
        &kw("SELECT json_value(j, '$.a' RETURNING NUMBER) |", Oracle),
        "FROM"
    ));
    // …but a top-level DML RETURNING still offers INTO.
    assert!(has(&kw("UPDATE t SET a=1 RETURNING a |", Oracle), "INTO"));

    // A function-internal RETURNING / the math function LOG must not withdraw the
    // UPDATE SET tail (WHERE/RETURNING).
    for sql in [
        "UPDATE t SET a = f(x RETURNING y) |",
        "UPDATE t SET a = log(10, x) |",
    ] {
        let s = kw(sql, Oracle);
        assert!(
            has(&s, "WHERE") && has(&s, "RETURNING"),
            "UPDATE SET tail withdrawn by function-internal keyword at `{sql}`: {s:?}"
        );
    }
    // …but the genuine `LOG ERRORS` clause is still recognised and spends RETURNING.
    assert!(has(&kw("INSERT INTO t VALUES (1) LOG |", Oracle), "ERRORS"));
    assert!(has(
        &kw("INSERT INTO t VALUES (1) LOG ERRORS |", Oracle),
        "INTO"
    ));

    // A `WHERE` inside a subquery in a SET value is not the UPDATE's own `WHERE`, so
    // the statement-level `WHERE` must still be offered.
    let s = kw("UPDATE t SET a = (SELECT x FROM s WHERE y=1) |", Oracle);
    assert!(
        has(&s, "WHERE") && has(&s, "RETURNING"),
        "outer WHERE dropped by a subquery WHERE in SET value: {s:?}"
    );
    // …and once the statement's own top-level WHERE exists it is not re-offered.
    assert!(!has(
        &kw(
            "UPDATE t SET a = (SELECT x FROM s WHERE y=1) WHERE z=2 |",
            Oracle
        ),
        "WHERE"
    ));
}

/// After a *complete* GROUP BY grouping element the clause continues
/// (`HAVING`/`ORDER BY`/…) — including the extended-grouping forms `ROLLUP(…)`,
/// `CUBE(…)`, `GROUPING SETS(…)`, whose keywords are part of the item (so the
/// walk-back to the `BY` head must not treat them as a trailing-clause boundary).
/// The empty slot and a fresh post-comma item still suppress the continuation, and
/// ORDER BY is unaffected.
#[test]
fn group_by_extended_grouping_elements_offer_clause_continuation() {
    let kw = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(crate::db::DatabaseType::Oracle),
        )
    };
    let has = |v: &Vec<String>, s: &str| v.iter().any(|x| x == s);

    for sql in [
        "SELECT a FROM t GROUP BY a |",
        "SELECT a FROM t GROUP BY ROLLUP(a) |",
        "SELECT a FROM t GROUP BY CUBE(a, b) |",
        "SELECT a FROM t GROUP BY GROUPING SETS ((a), (b)) |",
        "SELECT a FROM t GROUP BY a, ROLLUP(b) |",
    ] {
        let s = kw(sql);
        assert!(
            has(&s, "HAVING") && has(&s, "ORDER BY"),
            "GROUP BY element missing continuation at `{sql}`: {s:?}"
        );
    }
    // The empty slot offers the grouping-type keywords, not the continuation;
    // a fresh post-comma item offers nothing; ORDER BY tails are unchanged.
    assert!(
        has(&kw("SELECT a FROM t GROUP BY |"), "ROLLUP")
            && !has(&kw("SELECT a FROM t GROUP BY |"), "HAVING")
    );
    assert!(!has(&kw("SELECT a FROM t GROUP BY ROLLUP(a), |"), "HAVING"));
    assert!(
        has(&kw("SELECT a FROM t ORDER BY a |"), "ASC")
            && has(&kw("SELECT a FROM t ORDER BY a |"), "OFFSET")
    );
}

/// A parenthesised FROM-list table source — a derived table `(SELECT …)` (with or
/// without an alias), a comma/JOIN-introduced one, or `TABLE(coll)` — completes the
/// relation just like a named table, so the same query continuation follows. As a
/// JOIN target it offers `ON`/`USING` (unless `CROSS`/`NATURAL`), exactly like a
/// plain table.
#[test]
fn derived_table_and_parenthesised_source_offer_query_continuation() {
    let kw = |sql: &str, db: crate::db::DatabaseType| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    use crate::db::DatabaseType::{MySQL, Oracle};
    let has = |v: &Vec<String>, s: &str| v.iter().any(|x| x == s);
    let offers_continuation =
        |v: &Vec<String>| has(v, "WHERE") && has(v, "GROUP BY") && has(v, "JOIN");

    // Derived table, with/without alias; comma list; collection source — all offer
    // the same continuation as a plain table (`FROM t |`).
    for sql in [
        "SELECT a FROM (SELECT b FROM s) |",
        "SELECT a FROM (SELECT b FROM s) v |",
        "SELECT a FROM t, (SELECT b FROM s) v |",
        "SELECT a FROM TABLE(f(1)) |",
    ] {
        assert!(
            offers_continuation(&kw(sql, Oracle)),
            "derived/parenthesised source missing continuation at `{sql}`: {:?}",
            kw(sql, Oracle)
        );
    }
    assert!(offers_continuation(&kw(
        "SELECT a FROM (SELECT b FROM s) AS v |",
        MySQL
    )));

    // As a JOIN target it offers ON/USING (like a plain table), with or without alias.
    for sql in [
        "SELECT a FROM t1 JOIN (SELECT b FROM s) |",
        "SELECT a FROM t1 JOIN (SELECT b FROM s) v |",
    ] {
        let s = kw(sql, Oracle);
        assert!(
            has(&s, "ON") && has(&s, "USING") && !has(&s, "WHERE"),
            "derived JOIN target should offer ON/USING at `{sql}`: {s:?}"
        );
    }
    // CROSS JOIN takes no condition, so the continuation follows instead.
    assert!(offers_continuation(&kw(
        "SELECT a FROM t1 CROSS JOIN (SELECT b FROM s) |",
        Oracle
    )));
    // The cursor inside the derived table is still its own column context (no leak).
    assert!(!offers_continuation(&kw(
        "SELECT a FROM (SELECT b FROM s WHERE |",
        Oracle
    )));

    // Table functions are FROM sources too: TABLE/XMLTABLE/JSON_TABLE and a
    // (possibly dotted) pipelined UDF. After the call the continuation follows; as a
    // JOIN target it offers ON/USING.
    for sql in [
        "SELECT * FROM my_func(x) |",
        "SELECT * FROM pkg.my_func(x) |",
        "SELECT * FROM XMLTABLE('/a' PASSING c COLUMNS d NUMBER PATH '/b') |",
        "SELECT * FROM t, JSON_TABLE(j, '$' COLUMNS (c NUMBER PATH '$.x')) |",
    ] {
        assert!(
            offers_continuation(&kw(sql, Oracle)),
            "table function source missing continuation at `{sql}`: {:?}",
            kw(sql, Oracle)
        );
    }
    assert!(has(&kw("SELECT * FROM t1 JOIN my_func(x) |", Oracle), "ON"));
}

#[test]
fn derived_table_and_table_function_tail_slots_do_not_offer_catalog() {
    use crate::db::DatabaseType::{MySQL, Oracle};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);
    let assert_no_catalog_noise = |sql: &str,
                                   db: crate::db::DatabaseType,
                                   final_suggestions: &[String]| {
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "APP_USER",
            "SCOTT",
            "RUN_JOB",
            "CALC_TOTAL",
            "EMPNO",
            "ENAME",
            "DEPTNO",
            "DNAME",
            "MY_FUNC",
        ] {
            assert!(
                    !contains(final_suggestions, leaked),
                    "{leaked} leaked into derived/table-function tail at `{sql}` {db:?}: {final_suggestions:?}"
                );
        }
    };

    for (db, sql, expected_keywords) in [
        (
            Oracle,
            "SELECT a FROM (SELECT b FROM s) |",
            &["JOIN", "WHERE", "GROUP BY", "ORDER BY"][..],
        ),
        (
            Oracle,
            "SELECT a FROM (SELECT b FROM s) v |",
            &["JOIN", "WHERE", "GROUP BY", "ORDER BY"],
        ),
        (
            Oracle,
            "SELECT a FROM t, (SELECT b FROM s) v |",
            &["JOIN", "WHERE", "GROUP BY", "ORDER BY"],
        ),
        (
            MySQL,
            "SELECT a FROM (SELECT b FROM s) AS v |",
            &["JOIN", "WHERE", "GROUP BY", "ORDER BY"],
        ),
        (
            MySQL,
            "SELECT * FROM JSON_TABLE(j, '$' COLUMNS (c INT PATH '$.x')) AS v |",
            &["JOIN", "WHERE", "GROUP BY", "ORDER BY"],
        ),
        (
            Oracle,
            "SELECT a FROM t1 JOIN (SELECT b FROM s) |",
            &["ON", "USING"],
        ),
        (
            Oracle,
            "SELECT a FROM t1 JOIN (SELECT b FROM s) v |",
            &["ON", "USING"],
        ),
        (
            Oracle,
            "SELECT a FROM t1 CROSS JOIN (SELECT b FROM s) |",
            &["JOIN", "WHERE", "GROUP BY", "ORDER BY"],
        ),
        (
            Oracle,
            "SELECT * FROM TABLE(f(1)) |",
            &["JOIN", "WHERE", "GROUP BY", "ORDER BY"],
        ),
        (
            Oracle,
            "SELECT * FROM XMLTABLE('/a' COLUMNS d NUMBER PATH '/b') |",
            &["JOIN", "WHERE", "GROUP BY", "ORDER BY"],
        ),
        (
            Oracle,
            "SELECT * FROM t1 JOIN my_func(x) |",
            &["ON", "USING"],
        ),
        (
            MySQL,
            "SELECT * FROM emp JOIN JSON_TABLE(j, '$' COLUMNS (c INT PATH '$.x')) AS v |",
            &["ON", "USING"],
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert_eq!(
            kind, None,
            "derived/table-function tail should not resolve an object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        for expected in expected_keywords {
            assert!(
                contains(&final_suggestions, expected),
                "{expected} missing from derived/table-function tail at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        assert_no_catalog_noise(sql, db, &final_suggestions);
    }
}

/// A post-table modifier — Oracle's partition-extension (`PARTITION (…)`,
/// `SUBPARTITION (…)`, `… FOR (…)`) or row-sampling (`SAMPLE [BLOCK] (…)`,
/// `TABLESAMPLE [method] (…)`) clause — attaches to a table reference without
/// changing its completeness: the relation is just as finished as the bare
/// `FROM t |`, so the same query continuation follows (and as a JOIN target it
/// offers `ON`/`USING`). It is NOT a new FROM-list source, so a table-function
/// call whose name merely *looks* like a modifier (`FROM sample(10)`) is still
/// treated as a source, and the cursor inside the still-open modifier paren gets
/// no query continuation.
#[test]
fn post_table_modifier_completes_the_relation() {
    let kw = |sql: &str, db: crate::db::DatabaseType| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    use crate::db::DatabaseType::Oracle;
    let has = |v: &Vec<String>, s: &str| v.iter().any(|x| x == s);
    let offers_continuation =
        |v: &Vec<String>| has(v, "WHERE") && has(v, "GROUP BY") && has(v, "JOIN");

    // Every modifier form — alone or stacked, with or without a trailing alias —
    // leaves a complete relation that offers the query continuation.
    for sql in [
        "SELECT * FROM t SAMPLE (10) |",
        "SELECT * FROM t SAMPLE BLOCK (10) |",
        "SELECT * FROM t TABLESAMPLE BERNOULLI (10) |",
        "SELECT * FROM t PARTITION (p1) |",
        "SELECT * FROM t SUBPARTITION (s1) |",
        "SELECT * FROM t PARTITION FOR (1) |",
        "SELECT * FROM t PARTITION (p1) x |", // trailing alias
        "SELECT * FROM s.t PARTITION (p1) |", // dotted table name
        "SELECT * FROM t PARTITION (p1) SAMPLE (10) |", // stacked modifiers
    ] {
        assert!(
            offers_continuation(&kw(sql, Oracle)),
            "post-table modifier missing continuation at `{sql}`: {:?}",
            kw(sql, Oracle)
        );
    }
    // As a JOIN target the modified relation still expects the join condition.
    let s = kw("SELECT * FROM t1 JOIN t2 PARTITION (p1) |", Oracle);
    assert!(
        has(&s, "ON") && has(&s, "USING") && !has(&s, "WHERE"),
        "modified JOIN target should offer ON/USING: {s:?}"
    );

    // A table-function call whose name resembles a modifier keyword is still a
    // FROM-list source, not a modifier — the continuation still follows, proving it
    // was classified as a source (the discriminator is the missing table name).
    assert!(offers_continuation(&kw(
        "SELECT * FROM sample (10) |",
        Oracle
    )));
    // Inside the still-open modifier paren there is no query continuation.
    assert!(!offers_continuation(&kw(
        "SELECT * FROM t PARTITION (|",
        Oracle
    )));
    assert!(!offers_continuation(&kw(
        "SELECT * FROM t SAMPLE (|",
        Oracle
    )));
}

#[test]
fn deeply_stacked_post_table_modifiers_do_not_recurse() {
    let sql = format!("t{}", " SAMPLE (1)".repeat(2_048));
    let tokens = SqlEditorWidget::tokenize_sql(&sql);
    let token_refs = tokens.iter().collect::<Vec<_>>();

    assert!(SqlEditorWidget::paren_closes_post_table_modifier(
        &token_refs,
        token_refs.len() - 1,
    ));
}

#[test]
fn post_table_modifier_tail_slots_do_not_offer_catalog() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);
    let assert_no_catalog_noise = |sql: &str, final_suggestions: &[String]| {
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "APP_USER",
            "SCOTT",
            "RUN_JOB",
            "CALC_TOTAL",
            "EMPNO",
            "ENAME",
            "DEPTNO",
            "DNAME",
        ] {
            assert!(
                !contains(final_suggestions, leaked),
                "{leaked} leaked into post-table modifier tail at `{sql}`: {final_suggestions:?}"
            );
        }
    };

    for (sql, expected_keywords) in [
        (
            "SELECT * FROM t SAMPLE (10) |",
            &["JOIN", "WHERE", "GROUP BY", "ORDER BY"][..],
        ),
        (
            "SELECT * FROM t SAMPLE BLOCK (10) |",
            &["JOIN", "WHERE", "GROUP BY", "ORDER BY"],
        ),
        (
            "SELECT * FROM t PARTITION (p1) |",
            &["JOIN", "WHERE", "GROUP BY", "ORDER BY"],
        ),
        (
            "SELECT * FROM t PARTITION (p1) x |",
            &["JOIN", "WHERE", "GROUP BY", "ORDER BY"],
        ),
        (
            "SELECT * FROM t PARTITION (p1) SAMPLE (10) |",
            &["JOIN", "WHERE", "GROUP BY", "ORDER BY"],
        ),
        (
            "SELECT * FROM t1 JOIN t2 PARTITION (p1) |",
            &["ON", "USING"],
        ),
        (
            "SELECT * FROM t1 JOIN t2 SAMPLE BLOCK (5) |",
            &["ON", "USING"],
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "post-table modifier tail should not resolve an object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        for expected in expected_keywords {
            assert!(
                contains(&final_suggestions, expected),
                "{expected} missing from post-table modifier tail at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        assert_no_catalog_noise(sql, &final_suggestions);
    }
}

#[test]
fn table_sample_prefixed_final_suggestions_are_oracle_only() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    let (kind, keywords, final_suggestions) =
        audit_final_suggestions_for("SELECT * FROM t SAMPLE B|", Oracle);
    assert_eq!(
        kind, None,
        "SAMPLE BLOCK slot should not resolve object kind: keywords={keywords:?} final={final_suggestions:?}"
    );
    assert!(
        contains(&keywords, "BLOCK") && contains(&final_suggestions, "BLOCK"),
        "BLOCK missing from Oracle SAMPLE prefix slot: keywords={keywords:?} final={final_suggestions:?}"
    );
    for leaked in [
        "BETWEEN", "BY", "EMP", "DEPT", "EMP_V", "APP_USER", "EMPNO", "ENAME",
    ] {
        assert!(
            !contains(&final_suggestions, leaked),
            "{leaked} leaked into Oracle SAMPLE prefix slot: {final_suggestions:?}"
        );
    }

    for db in [MySQL, MariaDB] {
        let (_kind, keywords, final_suggestions) =
            audit_final_suggestions_for("SELECT * FROM t SAMPLE B|", db);
        assert!(
            !contains(&keywords, "BLOCK") && !contains(&final_suggestions, "BLOCK"),
            "Oracle SAMPLE BLOCK leaked into MySQL-family mode {db:?}: keywords={keywords:?} final={final_suggestions:?}"
        );
    }
}

