/// Past the object name of a single-object `DROP`/`CREATE`/`ALTER` a bare
/// relation is no longer grammatical, so the completed/option-region tail
/// suppresses the catalog (and offers the real option keywords where the grammar
/// is unambiguous). The object-name slot itself and the defining-query/relation
/// slots (`CREATE INDEX i ON |`, `CREATE SYNONYM s FOR |`, `… AS SELECT … FROM |`,
/// the `GRANT … ON|TO` identifier slots) keep the catalog available. Guards
/// against the broad relation-catalog leak at DDL statement tails, including
/// schema-qualified names and multi-word object types.
#[test]
fn ddl_statement_tails_suppress_relations_and_offer_object_options() {
    use crate::db::DatabaseType::Oracle;
    let idsupp = |sql: &str| {
        let excl = sql
            .strip_suffix('|')
            .and_then(|s| s.chars().last())
            .is_some_and(|c| c.is_alphanumeric());
        SqlEditorWidget::cursor_is_at_identifier_suppressing_keyword_slot_for_context(
            &analyze_inline_cursor_sql(sql),
            excl,
            Some(Oracle),
        )
    };
    let kw = |sql: &str| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(Oracle),
        )
    };
    let has = |v: &Vec<String>, s: &str| v.iter().any(|x| x == s);

    // DROP single-object tails: catalog suppressed; options where unambiguous.
    for sql in [
        "DROP VIEW v |",
        "DROP INDEX i |",
        "DROP SEQUENCE s |",
        "DROP SYNONYM s |",
        "DROP PROCEDURE p |",
        "DROP USER u |",
        "DROP TYPE t |",
        "DROP TABLESPACE ts |",
        "DROP MATERIALIZED VIEW mv |",
        "DROP PACKAGE BODY pb |",
        "DROP TABLE s.t |",     // schema-qualified
        "DROP TABLE t PURGE |", // trailing option
        "DROP TABLE t CASCADE CONSTRAINTS |",
    ] {
        assert!(idsupp(sql), "relation must be suppressed at `{sql}`");
    }
    assert_eq!(kw("DROP USER u |"), vec!["CASCADE".to_string()]);
    assert_eq!(
        kw("DROP TYPE t |"),
        vec!["FORCE".to_string(), "VALIDATE".to_string()]
    );
    assert_eq!(
        kw("DROP TABLE s.t |"),
        vec!["CASCADE".to_string(), "PURGE".to_string()]
    );
    assert_eq!(
        kw("DROP TABLE purge |"),
        vec!["CASCADE".to_string(), "PURGE".to_string()]
    );
    assert_eq!(
        kw("DROP TABLE cascade |"),
        vec!["CASCADE".to_string(), "PURGE".to_string()]
    );
    assert_eq!(
        kw("DROP TABLE t CASCADE |"),
        vec!["CONSTRAINTS".to_string()]
    );

    // DROP object-name slot keeps objects available (no name written yet).
    assert!(
        !idsupp("DROP VIEW |"),
        "object-name slot must keep the catalog"
    );
    assert!(!idsupp("DROP TABLE |"));

    // CREATE non-relational object tails: suppressed, first keyword offered.
    assert!(idsupp("CREATE USER u |") && has(&kw("CREATE USER u |"), "IDENTIFIED"));
    assert!(idsupp("CREATE ROLE r |") && has(&kw("CREATE ROLE r |"), "IDENTIFIED"));
    assert!(idsupp("CREATE TABLESPACE ts |") && has(&kw("CREATE TABLESPACE ts |"), "DATAFILE"));
    assert!(idsupp("CREATE PROFILE p |") && has(&kw("CREATE PROFILE p |"), "LIMIT"));
    assert!(idsupp("CREATE DIRECTORY d |") && has(&kw("CREATE DIRECTORY d |"), "AS"));
    assert!(
        idsupp("CREATE ROLLBACK SEGMENT r |")
            && has(&kw("CREATE ROLLBACK SEGMENT r |"), "TABLESPACE")
    );
    assert!(idsupp("CREATE VIEW v (a, b) |") && has(&kw("CREATE VIEW v (a, b) |"), "AS"));
    // Deeper into the option region the catalog stays suppressed (no re-offer).
    assert!(idsupp("CREATE USER u IDENTIFIED BY p |"));
    assert!(idsupp("CREATE TABLE t (a NUMBER) TABLESPACE |")); // tablespace-name slot
    assert!(idsupp(
        "CREATE TABLE t (a NUMBER) TABLESPACE users LOGGING |"
    ));

    // CREATE SYNONYM: target slot keeps the catalog, completed target suppresses.
    assert!(
        !idsupp("CREATE SYNONYM s FOR |"),
        "synonym target slot keeps catalog"
    );
    assert!(idsupp("CREATE SYNONYM s FOR x.y |"));

    // ALTER object tails: suppressed with primary actions; ALTER TABLE keeps its
    // dedicated arm; the object-name slot keeps the catalog.
    assert!(idsupp("ALTER INDEX i |") && has(&kw("ALTER INDEX i |"), "REBUILD"));
    assert!(idsupp("ALTER SEQUENCE s |") && has(&kw("ALTER SEQUENCE s |"), "INCREMENT BY"));
    assert!(idsupp("ALTER USER u |") && has(&kw("ALTER USER u |"), "IDENTIFIED"));
    assert!(idsupp("ALTER PROCEDURE p |") && has(&kw("ALTER PROCEDURE p |"), "COMPILE"));
    assert!(idsupp("ALTER EDITION ed |") && has(&kw("ALTER EDITION ed |"), "USABLE"));
    assert!(
        idsupp("ALTER ROLLBACK SEGMENT r |") && has(&kw("ALTER ROLLBACK SEGMENT r |"), "ONLINE")
    );
    for sql in [
        "ALTER DATABASE LINK link |",
        "ALTER CLUSTER c |",
        "ALTER LIBRARY lib |",
        "ALTER DIMENSION dim |",
        "ALTER OPERATOR op |",
        "ALTER INDEXTYPE it |",
        "ALTER JAVA SOURCE js |",
        "ALTER JAVA CLASS jc |",
    ] {
        assert!(
            idsupp(sql),
            "relation must be suppressed at extended ALTER tail `{sql}`"
        );
    }
    for sql in [
        "ALTER LIBRARY lib |",
        "ALTER DIMENSION dim |",
        "ALTER OPERATOR op |",
        "ALTER INDEXTYPE it |",
        "ALTER JAVA SOURCE js |",
        "ALTER JAVA CLASS jc |",
    ] {
        assert!(
            has(&kw(sql), "COMPILE"),
            "COMPILE missing at `{sql}`: {:?}",
            kw(sql)
        );
    }
    assert!(idsupp("DROP ROLLBACK SEGMENT r |"));
    let alter_table = kw("ALTER TABLE t |");
    assert!(
        has(&alter_table, "ADD") && has(&alter_table, "MODIFY"),
        "{alter_table:?}"
    );
    assert!(
        !idsupp("ALTER TABLE |"),
        "ALTER TABLE name slot must keep the catalog"
    );

    // GRANT/REVOKE: identifier slots keep the catalog, keyword tails suppress.
    assert!(!idsupp("GRANT SELECT ON |"), "object slot keeps catalog");
    assert!(
        !idsupp("GRANT SELECT ON emp TO |"),
        "grantee slot keeps catalog"
    );
    assert!(
        !idsupp("GRANT SELECT ON emp TO scott, |"),
        "grantee list keeps catalog"
    );
    assert!(!idsupp("REVOKE SELECT ON emp FROM |"));
    assert!(
        idsupp("GRANT SELECT ON emp TO scott |")
            && has(&kw("GRANT SELECT ON emp TO scott |"), "WITH GRANT OPTION")
    );
    assert!(idsupp("REVOKE SELECT ON emp FROM scott |"));

    // A `MATERIALIZED VIEW LOG` is a distinct object, not a completed MV.
    assert!(
        has(&kw("CREATE MATERIALIZED VIEW LOG |"), "ON"),
        "MV LOG must still offer ON, not be treated as a completed view"
    );
}

#[test]
fn extended_ddl_completed_tails_do_not_offer_object_catalog_in_final_suggestions() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for (sql, expected_keyword) in [
        ("DROP SEQUENCE emp_seq |", None),
        ("DROP PACKAGE BODY hr_pkg |", None),
        ("DROP PUBLIC SYNONYM public_emp |", None),
        ("DROP DATABASE LINK app_link |", None),
        ("DROP PUBLIC DATABASE LINK app_link |", None),
        ("DROP DIRECTORY data_pump_dir |", None),
        ("DROP JAVA SOURCE welcome |", None),
        ("ALTER DATABASE LINK app_link |", None),
        ("ALTER PUBLIC DATABASE LINK app_link |", None),
        ("ALTER CLUSTER emp_cluster |", None),
        ("ALTER LIBRARY app_lib |", Some("COMPILE")),
        ("ALTER DIMENSION sales_dim |", Some("COMPILE")),
        ("ALTER OPERATOR text_op |", Some("COMPILE")),
        ("ALTER INDEXTYPE text_itype |", Some("COMPILE")),
        ("ALTER JAVA SOURCE welcome |", Some("COMPILE")),
        ("ALTER JAVA CLASS welcomeclass |", Some("COMPILE")),
        ("ALTER EDITION ora_edition |", Some("USABLE")),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "completed extended DDL tail should not resolve object kind at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        if let Some(expected_keyword) = expected_keyword {
            assert!(
                contains(&final_suggestions, expected_keyword),
                "{expected_keyword} missing from completed extended DDL tail at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "MVIEW_SALES",
            "EMP_SEQ",
            "EMP_SYN",
            "PUBLIC_EMP",
            "APP_USER",
            "SCOTT",
            "RUN_JOB",
            "CALC_TOTAL",
            "HR_PKG",
            "ADDRESS_T",
            "BI_EMP",
            "CLEANUP_EVENT",
            "IDX_EMP_NAME",
            "APP_LINK",
            "DATA_PUMP_DIR",
            "APP_LIB",
            "EMP_CLUSTER",
            "APP_CTX",
            "SALES_DIM",
            "TEXT_OP",
            "TEXT_ITYPE",
            "ORA_EDITION",
            "Welcome",
            "WelcomeClass",
            "WelcomeRes",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into completed extended DDL tail at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
}

#[test]
fn prefixed_statement_tail_keyword_slots_do_not_offer_object_catalog() {
    use crate::db::DatabaseType::{MySQL, Oracle};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for (db, sql, expected_keyword) in [
        (Oracle, "DROP TABLE emp CAS|", "CASCADE"),
        (Oracle, "DROP TABLE scott.emp CAS|", "CASCADE"),
        (Oracle, "DROP TABLE emp PUR|", "PURGE"),
        (Oracle, "DROP TABLE scott.emp PUR|", "PURGE"),
        (Oracle, "DROP TABLE emp CASCADE CON|", "CONSTRAINTS"),
        (Oracle, "DROP TABLE scott.emp CASCADE CON|", "CONSTRAINTS"),
        (Oracle, "COMMENT ON TABLE emp I|", "IS"),
        (Oracle, "COMMENT ON TABLE scott.emp I|", "IS"),
        (Oracle, "COMMENT ON COLUMN emp.sal I|", "IS"),
        (Oracle, "COMMENT ON COLUMN scott.emp.sal I|", "IS"),
        (Oracle, "CREATE VIEW emp_v A|", "AS"),
        (Oracle, "CREATE VIEW scott.emp_v A|", "AS"),
        (Oracle, "CREATE INDEX emp_idx O|", "ON"),
        (Oracle, "ALTER TABLE emp R|", "RENAME"),
        (Oracle, "ALTER TABLE scott.emp R|", "RENAME"),
        (
            Oracle,
            "GRANT SELECT ON emp TO scott W|",
            "WITH GRANT OPTION",
        ),
        (
            Oracle,
            "GRANT SELECT ON scott.emp TO app_user W|",
            "WITH GRANT OPTION",
        ),
        (MySQL, "CREATE VIEW emp_v A|", "AS"),
        (MySQL, "CREATE TABLE t (a INT) ENG|", "ENGINE"),
        (MySQL, "CREATE INDEX emp_idx ON emp (empno) US|", "USING"),
        (MySQL, "RENAME TABLE emp T|", "TO"),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert!(
            contains(&final_suggestions, expected_keyword),
            "{expected_keyword} missing from tail slot at `{sql}`: kind={kind:?} keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "APP_USER",
            "SCOTT",
            "RUN_JOB",
            "CALC_TOTAL",
            "BI_EMP",
            "CLEANUP_EVENT",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into prefixed tail keyword slot at `{sql}`: kind={kind:?} keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
}

