/// MySQL DDL statement tails suppress the relation catalog past the object name,
/// the same leak class as the Oracle dialect. The object-name slots, the
/// comma-separated list continuations (`DROP TABLE a, |`, multi-pair `RENAME`),
/// and the relation slots (`DROP INDEX … ON |`, `TRUNCATE TABLE |`) keep the
/// catalog available. `RENAME TABLE … TO |` is a brand-new-name target and is
/// suppressed through `ddl_new_name_position`. Guards against the broad MySQL
/// DDL-tail leak and the stray `IF` re-offer past a written `DROP USER` name.
#[test]
fn mysql_family_ddl_statement_tails_suppress_relations() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let idsupp = |sql: &str, db| {
        let excl = sql
            .strip_suffix('|')
            .and_then(|s| s.chars().last())
            .is_some_and(|c| c.is_alphanumeric());
        SqlEditorWidget::cursor_is_at_identifier_suppressing_keyword_slot_for_context(
            &analyze_inline_cursor_sql(sql),
            excl,
            Some(db),
        )
    };
    let kw = |sql: &str, db| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |v: &Vec<String>, s: &str| v.iter().any(|x| x == s);

    for db in [MySQL, MariaDB] {
        // DROP single-object tails: catalog suppressed past the name (incl.
        // schema-qualified) with no stray keywords.
        for sql in [
            "DROP TABLE t |",
            "DROP TABLE s.t |",
            "DROP VIEW v |",
            "DROP DATABASE d |",
            "DROP SCHEMA s |",
            "DROP PROCEDURE p |",
            "DROP FUNCTION f |",
            "DROP TRIGGER tg |",
            "DROP EVENT e |",
            "DROP SERVER srv |",
            "DROP USER u |",
        ] {
            assert!(
                idsupp(sql, db),
                "relation must be suppressed at `{sql}` ({db:?})"
            );
            assert!(
                kw(sql, db).is_empty(),
                "no keyword tail expected at `{sql}` ({db:?}): {:?}",
                kw(sql, db)
            );
        }

        // The `IF [EXISTS]` flow is grammatical only before the name.
        assert!(has(&kw("DROP USER |", db), "IF"));
        assert!(has(&kw("DROP USER IF |", db), "EXISTS"));
        assert!(kw("DROP USER IF EXISTS |", db).is_empty());

        // Relation / list-continuation slots keep the catalog. (The bare
        // object-name slot `DROP TABLE |` offers `IF [EXISTS]` and is a
        // separate pre-existing suppression, not part of this leak class.)
        assert!(
            !idsupp("DROP TABLE a, |", db),
            "drop list continuation keeps catalog ({db:?})"
        );
        assert!(
            !idsupp("DROP INDEX i ON |", db),
            "DROP INDEX table slot keeps catalog ({db:?})"
        );

        // CREATE VIEW with a column-alias list still awaits `AS`.
        assert!(
            idsupp("CREATE VIEW v (a, b) |", db) && has(&kw("CREATE VIEW v (a, b) |", db), "AS"),
            "CREATE VIEW alias-list table slot leaks for {db:?}"
        );

        // TRUNCATE: `TRUNCATE |`→TABLE, the table slot keeps the catalog, the
        // tail suppresses.
        assert!(has(&kw("TRUNCATE |", db), "TABLE"));
        assert!(
            !idsupp("TRUNCATE TABLE |", db),
            "truncate table slot keeps catalog ({db:?})"
        );
        assert!(idsupp("TRUNCATE TABLE t |", db));

        // RENAME pairs: `TO` after the old name, suppress the brand-new target
        // name and past the completed new name; keep catalog only at
        // source/list slots.
        assert!(!idsupp("RENAME TABLE |", db));
        assert!(idsupp("RENAME TABLE emp |", db) && has(&kw("RENAME TABLE emp |", db), "TO"));
        assert!(idsupp("RENAME TABLE to |", db) && has(&kw("RENAME TABLE to |", db), "TO"));
        assert!(analyze_inline_cursor_sql("RENAME TABLE emp TO |").ddl_new_name_position);
        assert!(audit_final_suggestions_for("RENAME TABLE emp TO |", db)
            .2
            .is_empty());
        assert!(idsupp("RENAME TABLE emp TO x |", db));
        assert!(idsupp("RENAME TABLE emp TO to |", db));
        assert!(!idsupp("RENAME TABLE emp TO x, |", db));
        assert!(has(&kw("RENAME TABLE emp TO x, dept |", db), "TO"));
        assert!(has(&kw("RENAME TABLE emp TO x, to |", db), "TO"));
        assert!(idsupp("RENAME TABLE emp TO x, dept TO y |", db));
        assert!(idsupp("RENAME TABLE emp TO x, dept TO to |", db));

        // Pre-existing grammars unaffected.
        assert!(has(&kw("CREATE TABLE t (a INT) |", db), "ENGINE"));
        assert!(has(&kw("CREATE USER u |", db), "IDENTIFIED"));
    }
}

#[test]
fn create_view_column_alias_list_slots_do_not_offer_catalog() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for (db, sql) in [
        (Oracle, "CREATE VIEW v (|) AS SELECT empno FROM emp"),
        (
            Oracle,
            "CREATE VIEW v (out_col, |) AS SELECT empno, ename FROM emp",
        ),
        (
            Oracle,
            "CREATE OR REPLACE VIEW v (out_col, n|) AS SELECT empno, ename FROM emp",
        ),
        (
            Oracle,
            "CREATE MATERIALIZED VIEW mv (|) AS SELECT empno FROM emp",
        ),
        (
            Oracle,
            "CREATE EDITIONING VIEW ev (out_col, |) AS SELECT empno, ename FROM emp",
        ),
        (MySQL, "CREATE VIEW v (|) AS SELECT empno FROM emp"),
        (
            MySQL,
            "CREATE VIEW v (out_col, |) AS SELECT empno, ename FROM emp",
        ),
        (
            MySQL,
            "CREATE OR REPLACE VIEW v (out_col, n|) AS SELECT empno, ename FROM emp",
        ),
        (
            MySQL,
            "CREATE ALGORITHM = MERGE SQL SECURITY INVOKER VIEW v (out_col, |) AS SELECT empno, ename FROM emp",
        ),
        (
            MySQL,
            "ALTER ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW v (out_col, |) AS SELECT empno, ename FROM emp",
        ),
        (MariaDB, "CREATE VIEW v (|) AS SELECT empno FROM emp"),
        (
            MariaDB,
            "CREATE VIEW v (out_col, |) AS SELECT empno, ename FROM emp",
        ),
        (
            MariaDB,
            "CREATE OR REPLACE VIEW v (out_col, n|) AS SELECT empno, ename FROM emp",
        ),
        (
            MariaDB,
            "CREATE ALGORITHM = MERGE SQL SECURITY INVOKER VIEW v (out_col, |) AS SELECT empno, ename FROM emp",
        ),
        (
            MariaDB,
            "ALTER ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW v (out_col, |) AS SELECT empno, ename FROM emp",
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert_eq!(
            kind, None,
            "CREATE VIEW column-alias slot should not resolve object kind at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "EMPNO",
            "ENAME",
            "RUN_JOB",
            "CALC_TOTAL",
            "AS",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into CREATE VIEW column-alias slot at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
}

#[test]
fn mariadb_view_csv_and_concurrent_lock_keywords_are_dialect_scoped() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let has = |values: &[String], needle: &str| {
        values
            .iter()
            .any(|value| value.eq_ignore_ascii_case(needle))
    };
    let keywords = |sql: &str, db| query_keyword_completion_suggestions(sql, db);

    let repair_mysql = analyze_inline_cursor_sql("REPAIR VIEW emp FROM MYS|");
    let repair_end = SqlEditorWidget::expected_suggestion_context_end(
        repair_mysql.statement_tokens.as_ref(),
        repair_mysql.cursor_token_len,
        true,
    );
    let direct_repair = SqlEditorWidget::expected_mysql_schema_object_keyword_candidates(
        repair_mysql.statement_tokens.as_ref(),
        repair_end,
        Some(MariaDB),
    );
    assert!(
        direct_repair.is_some_and(|candidates| candidates.contains(&"MYSQL")),
        "direct REPAIR VIEW grammar did not reach MYSQL: direct={direct_repair:?} tokens={:?} end={repair_end}",
        repair_mysql.statement_tokens
    );

    for (sql, expected) in [
        ("CHECK |", "VIEW"),
        ("CHECK VIEW emp |", "FOR"),
        ("CHECK VIEW emp FOR |", "UPGRADE"),
        ("REPAIR |", "VIEW"),
        ("REPAIR LOCAL |", "VIEW"),
        ("REPAIR VIEW emp |", "FROM"),
        ("REPAIR VIEW emp FROM MYS|", "MYSQL"),
        (
            "CREATE TABLE csv_t (id INT NOT NULL) ENGINE = CSV |",
            "IETF_QUOTES",
        ),
        (
            "CREATE TABLE csv_t (id INT NOT NULL) ENGINE = CSV IETF_QUOTES = YE|",
            "YES",
        ),
        ("LOCK TABLES emp WRITE CONC|", "CONCURRENT"),
        ("LOCK TABLES emp WRITE CONCURRENT NOWA|", "NOWAIT"),
        ("LOCK TABLES emp READ LOCAL WA|", "WAIT"),
        ("LOCK TABLES emp LOW_|", "LOW_PRIORITY"),
        ("LOCK TABLES emp LOW_PRIORITY WR|", "WRITE"),
    ] {
        let got = keywords(sql, MariaDB);
        let context = analyze_inline_cursor_sql(sql);
        assert!(
            has(&got, expected),
            "{expected} missing from MariaDB `{sql}`: {got:?}; tokens={:?}",
            context.statement_tokens
        );
    }

    for sql in ["CHECK VIEW |", "CHECK VIEW emp, |", "REPAIR LOCAL VIEW |"] {
        let (kind, _, suggestions) = audit_final_suggestions_for(sql, MariaDB);
        assert_eq!(
            kind,
            Some(ExpectedObjectSuggestionKind::View),
            "MariaDB view-maintenance object kind missing at `{sql}`: {suggestions:?}"
        );
        assert!(
            has(&suggestions, "EMP_V"),
            "MariaDB view catalog missing at `{sql}`: {suggestions:?}"
        );
    }

    for (sql, forbidden) in [
        ("CHECK |", "VIEW"),
        ("REPAIR |", "VIEW"),
        (
            "CREATE TABLE csv_t (id INT NOT NULL) ENGINE = CSV |",
            "IETF_QUOTES",
        ),
        ("LOCK TABLES emp WRITE |", "CONCURRENT"),
        ("LOCK TABLES emp WRITE |", "NOWAIT"),
        ("LOCK TABLES emp |", "LOW_PRIORITY"),
    ] {
        let got = keywords(sql, MySQL);
        assert!(
            !has(&got, forbidden),
            "MariaDB-only {forbidden} leaked into MySQL `{sql}`: {got:?}"
        );
    }
}

/// Non-query admin/utility statement tails suppress the relation catalog past the
/// object name (and never leak the select-list `FROM` into `AUDIT`), while the
/// object/identifier slots keep the catalog available. Also locks the MySQL
/// `DROP <object> |` name slot offering the table catalog alongside `IF EXISTS`
/// (an existing object is named there, unlike a `CREATE` slot).
#[test]
fn admin_statement_tails_suppress_relations_without_select_noise() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};
    let idsupp = |sql: &str, db: crate::db::DatabaseType| {
        let excl = sql
            .strip_suffix('|')
            .and_then(|s| s.chars().last())
            .is_some_and(|c| c.is_alphanumeric());
        SqlEditorWidget::cursor_is_at_identifier_suppressing_keyword_slot_for_context(
            &analyze_inline_cursor_sql(sql),
            excl,
            Some(db),
        )
    };
    let kw = |sql: &str, db: crate::db::DatabaseType| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |v: &Vec<String>, s: &str| v.iter().any(|x| x == s);

    // Oracle admin tails: suppressed, with the real continuation keywords.
    assert!(idsupp("COMMENT ON COLUMN emp.sal IS 'x' |", Oracle));
    assert!(has(&kw("ANALYZE |", Oracle), "TABLE"));
    assert!(has(&kw("ANALYZE |", Oracle), "INDEX"));
    assert!(has(&kw("ANALYZE |", Oracle), "CLUSTER"));
    assert!(
        idsupp("ANALYZE TABLE emp |", Oracle)
            && has(&kw("ANALYZE TABLE emp |", Oracle), "COMPUTE STATISTICS")
    );
    assert!(idsupp("ANALYZE TABLE emp COMPUTE STATISTICS |", Oracle));
    assert!(has(&kw("FLASHBACK |", Oracle), "TABLE"));
    assert!(has(&kw("FLASHBACK |", Oracle), "DATABASE"));
    assert!(
        !idsupp("FLASHBACK TABLE |", Oracle),
        "flashback table slot keeps catalog"
    );
    assert!(
        idsupp("FLASHBACK DATABASE |", Oracle) && has(&kw("FLASHBACK DATABASE |", Oracle), "TO")
    );
    assert!(idsupp("FLASHBACK DATABASE TO |", Oracle));
    assert!(
        idsupp("FLASHBACK TABLE emp TO |", Oracle)
            && has(&kw("FLASHBACK TABLE emp TO |", Oracle), "BEFORE DROP")
    );
    assert!(
        idsupp("FLASHBACK TABLE emp TO BEFORE |", Oracle)
            && has(&kw("FLASHBACK TABLE emp TO BEFORE |", Oracle), "DROP")
    );
    assert!(idsupp("FLASHBACK TABLE emp TO BEFORE DROP |", Oracle));
    assert!(idsupp(
        "FLASHBACK TABLE emp TO BEFORE DROP RENAME TO |",
        Oracle
    ));
    assert!(has(&kw("PURGE |", Oracle), "TABLE"));
    assert!(has(&kw("PURGE |", Oracle), "INDEX"));
    assert!(has(&kw("PURGE |", Oracle), "RECYCLEBIN"));
    assert!(idsupp("PURGE RECYCLEBIN |", Oracle));
    assert!(idsupp("PURGE TABLESPACE |", Oracle));
    assert!(idsupp("PURGE TABLE emp |", Oracle));
    assert!(idsupp("CALL my_proc(1) |", Oracle));
    let (kind, keywords, final_suggestions) =
        audit_final_suggestions_for("CALL my_proc(1) |", Oracle);
    assert_eq!(
        kind, None,
        "completed Oracle CALL tail should not resolve object kind: keywords={keywords:?} final={final_suggestions:?}"
    );
    assert!(
        final_suggestions.is_empty(),
        "completed Oracle CALL tail should not offer catalog or stale keywords: keywords={keywords:?} final={final_suggestions:?}"
    );
    assert!(
        idsupp("ASSOCIATE STATISTICS WITH COLUMNS emp.sal |", Oracle)
            && has(
                &kw("ASSOCIATE STATISTICS WITH COLUMNS emp.sal |", Oracle),
                "USING"
            )
    );

    // `AUDIT` is not a query: it offers its clause keywords, never `FROM`.
    let audit = kw("AUDIT SELECT ON emp |", Oracle);
    assert!(idsupp("AUDIT SELECT ON emp |", Oracle));
    assert!(has(&audit, "BY") && has(&audit, "WHENEVER"), "{audit:?}");
    assert!(
        !has(&audit, "FROM"),
        "select-list FROM leaked into AUDIT: {audit:?}"
    );

    // Admin object/argument slots keep the catalog.
    assert!(
        !idsupp("ANALYZE TABLE |", Oracle),
        "analyze table slot keeps catalog"
    );
    assert!(
        !idsupp("CALL |", Oracle),
        "call proc-name slot keeps catalog"
    );
    assert!(
        !idsupp("AUDIT SELECT ON |", Oracle),
        "audit object slot keeps catalog"
    );

    // MySQL-family admin tails.
    for db in [MySQL, MariaDB] {
        for sql in [
            "FLUSH PRIVILEGES |",
            "FLUSH LOCAL |",
            "FLUSH LOCAL PRIVILEGES |",
            "FLUSH TABLES FOR EXPORT |",
            "CHECK TABLE emp QUICK |",
            "CHECK TABLE emp FOR UPGRADE |",
            "REPAIR TABLE emp QUICK EXTENDED |",
            "OPTIMIZE TABLE emp |",
            "ANALYZE TABLE emp UPDATE HISTOGRAM ON salary WITH 32 BUCKETS AUTO UPDATE |",
            "CACHE INDEX emp IN keycache |",
            "LOAD INDEX INTO CACHE emp IGNORE LEAVES |",
            "LOAD DATA INFILE data_csv REPLACE INTO TABLE emp |",
            "RESET BINARY LOGS AND GTIDS |",
            "RESET REPLICA FOR CHANNEL ch |",
            "RESET REPLICA ALL FOR CHANNEL ch |",
            "PURGE BINARY LOGS BEFORE ts |",
            "PURGE BINARY LOGS TO binlog |",
            "PURGE MASTER LOGS BEFORE ts |",
            "PURGE MASTER LOGS TO binlog |",
            "LOCK INSTANCE FOR BACKUP |",
            "UNLOCK INSTANCE |",
            "UNLOCK TABLES |",
            "START GROUP_REPLICATION USER repl PASSWORD secret |",
            "START REPLICA IO_THREAD SQL_THREAD |",
            "START REPLICA UNTIL SQL_BEFORE_GTIDS gtid_set |",
            "START REPLICA UNTIL SOURCE_LOG_FILE binlog_000001 |",
            "STOP REPLICA IO_THREAD SQL_THREAD |",
            "CHANGE REPLICATION SOURCE TO SOURCE_HOST host SOURCE_PORT 3306 |",
            "CHANGE REPLICATION FILTER REPLICATE_DO_DB db1 |",
            "CHANGE REPLICATION FILTER REPLICATE_IGNORE_TABLE db1_t1 |",
            "SET NAMES utf8mb4 COLLATE utf8mb4_bin |",
            "SET DEFAULT ROLE ALL TO alice |",
            "SET ROLE ALL EXCEPT admin |",
            "SET PASSWORD TO RANDOM RETAIN CURRENT PASSWORD |",
        ] {
            assert!(
                idsupp(sql, db),
                "{db:?} admin tail must suppress catalog at `{sql}`"
            );
        }
        assert!(
            has(&kw("FLUSH LOCAL |", db), "PRIVILEGES"),
            "FLUSH option list lost for {db:?}"
        );
        assert!(
            !idsupp("OPTIMIZE TABLE |", db),
            "optimize table slot keeps catalog for {db:?}"
        );
        assert!(idsupp("CALL my_proc(1) |", db));
        let (kind, keywords, final_suggestions) =
            audit_final_suggestions_for("CALL my_proc(1) |", db);
        assert_eq!(
            kind, None,
            "completed {db:?} CALL tail should not resolve object kind: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.is_empty(),
            "completed {db:?} CALL tail should not offer catalog or stale keywords: keywords={keywords:?} final={final_suggestions:?}"
        );

        // `DROP <object> |` name slot offers the catalog alongside `IF`.
        assert!(
            !idsupp("DROP TABLE |", db),
            "drop-table name slot keeps catalog for {db:?}"
        );
        assert!(!idsupp("DROP VIEW |", db));
        assert!(!idsupp("DROP TEMPORARY TABLE |", db));
        assert!(
            has(&kw("DROP TABLE |", db), "IF"),
            "IF EXISTS still offered"
        );
        // Past the name it suppresses again.
        assert!(idsupp("DROP TABLE t |", db));
    }
}

