#[test]
fn mysql_family_rename_user_source_slots_offer_only_users_in_final_suggestions() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for db in [MySQL, MariaDB] {
        for sql in [
            "RENAME USER |",
            "RENAME USER alice TO bob, |",
            "RENAME USER 'alice'@'localhost' TO bob, |",
        ] {
            let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
            assert_eq!(
                kind,
                Some(ExpectedObjectSuggestionKind::User),
                "RENAME USER source slot should resolve to user objects at `{sql}` ({db:?}); keywords={keywords:?} final={final_suggestions:?}"
            );
            assert!(
                contains(&final_suggestions, "APP_USER") && contains(&final_suggestions, "SCOTT"),
                "RENAME USER source slot lost user catalog at `{sql}` ({db:?}): {final_suggestions:?}"
            );
            for leaked in ["EMP", "DEPT", "EMP_V", "RUN_JOB", "SELECT", "WHERE"] {
                assert!(
                    !contains(&final_suggestions, leaked),
                    "{leaked} leaked into RENAME USER source slot at `{sql}` ({db:?}): {final_suggestions:?}"
                );
            }
        }

        for sql in [
            "RENAME USER alice TO |",
            "RENAME USER alice TO bob|",
            "RENAME USER alice TO bob@|",
            "RENAME USER alice TO bob@localhost|",
            "RENAME USER 'alice'@'localhost' TO |",
            "RENAME USER 'alice'@'localhost' TO bob|",
            "RENAME USER 'alice'@'localhost' TO bob@|",
        ] {
            let (_kind, _keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
            assert!(
                final_suggestions.is_empty(),
                "RENAME USER target is a new-name slot and should not offer existing identifiers at `{sql}` ({db:?}): {final_suggestions:?}"
            );
        }
    }
}

#[test]
fn mysql_family_user_account_slots_are_precise_in_final_suggestions() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for db in [MySQL, MariaDB] {
        for sql in [
            "ALTER USER |",
            "ALTER USER IF EXISTS |",
            "ALTER USER alice, |",
            "ALTER USER alice IDENTIFIED BY 'secret', |",
            "DROP USER |",
            "DROP USER IF EXISTS |",
            "DROP USER alice, |",
            "DROP USER 'alice'@'localhost', |",
            "DROP ROLE |",
            "DROP ROLE IF EXISTS |",
            "DROP ROLE report_reader, |",
            "SET ROLE |",
            "SET ROLE admin, |",
            "SET ROLE ALL EXCEPT |",
            "SET ROLE ALL EXCEPT admin, |",
            "SET DEFAULT ROLE |",
            "SET DEFAULT ROLE admin, |",
            "SET DEFAULT ROLE ALL TO |",
            "SET DEFAULT ROLE admin TO |",
            "SET DEFAULT ROLE admin TO alice, |",
        ] {
            let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
            assert_eq!(
                kind,
                Some(ExpectedObjectSuggestionKind::User),
                "existing MySQL-family account slot should resolve to user objects at `{sql}` {db:?}; keywords={keywords:?} final={final_suggestions:?}"
            );
            assert!(
                contains(&final_suggestions, "APP_USER") && contains(&final_suggestions, "SCOTT"),
                "existing MySQL-family account slot lost user catalog at `{sql}` {db:?}: {final_suggestions:?}"
            );
            for leaked in ["EMP", "DEPT", "EMP_V", "RUN_JOB", "SELECT", "WHERE"] {
                assert!(
                    !contains(&final_suggestions, leaked),
                    "{leaked} leaked into existing MySQL-family account slot at `{sql}` {db:?}: {final_suggestions:?}"
            );
            }
        }

        for sql in [
            "CREATE USER |",
            "CREATE USER IF NOT EXISTS |",
            "CREATE USER app|",
            "CREATE USER alice, |",
            "CREATE USER alice IDENTIFIED BY 'secret', |",
            "CREATE USER 'alice'@ |",
            "CREATE USER alice@localhost |",
            "CREATE USER alice@scott.|",
            "ALTER USER alice@ |",
            "ALTER USER alice@localhost |",
            "ALTER USER alice@scott.|",
            "ALTER USER 'alice'@'localhost' |",
            "CREATE ROLE |",
            "CREATE ROLE IF NOT EXISTS |",
            "CREATE ROLE report_reader, |",
            "CREATE ROLE app|",
        ] {
            let (_kind, _keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
            for leaked in ["APP_USER", "SCOTT", "EMP", "DEPT", "EMP_V", "RUN_JOB"] {
                assert!(
                    !contains(&final_suggestions, leaked),
                    "{leaked} leaked into new MySQL-family account name slot at `{sql}` {db:?}: {final_suggestions:?}"
            );
            }
        }
    }

    for sql in [
        "CREATE ROLE report_reader WITH ADMIN |",
        "CREATE ROLE IF NOT EXISTS report_reader WITH ADMIN |",
        "CREATE OR REPLACE ROLE report_reader WITH ADMIN |",
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, MariaDB);
        assert_eq!(
            kind,
            Some(ExpectedObjectSuggestionKind::User),
            "MariaDB CREATE ROLE WITH ADMIN should resolve the admin target as a user/role slot at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            contains(&final_suggestions, "APP_USER") && contains(&final_suggestions, "SCOTT"),
            "MariaDB CREATE ROLE WITH ADMIN lost user/role catalog at `{sql}`: {final_suggestions:?}"
        );
        for leaked in ["EMP", "DEPT", "EMP_V", "RUN_JOB", "SELECT", "WHERE"] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into MariaDB CREATE ROLE WITH ADMIN target at `{sql}`: {final_suggestions:?}"
            );
        }
    }

    for sql in [
        "CREATE ROLE report_reader WITH ADMIN app|",
        "CREATE OR REPLACE ROLE report_reader WITH ADMIN app|",
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, MariaDB);
        assert_eq!(
            kind,
            Some(ExpectedObjectSuggestionKind::User),
            "prefixed MariaDB CREATE ROLE WITH ADMIN should resolve the admin target as a user/role slot at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            contains(&final_suggestions, "APP_USER"),
            "prefixed MariaDB CREATE ROLE WITH ADMIN lost matching user/role catalog at `{sql}`: {final_suggestions:?}"
        );
        for leaked in [
            "SCOTT", "EMP", "DEPT", "EMP_V", "RUN_JOB", "SELECT", "WHERE",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into prefixed MariaDB CREATE ROLE WITH ADMIN target at `{sql}`: {final_suggestions:?}"
            );
        }
    }

    let (kind, _keywords, _final_suggestions) =
        audit_final_suggestions_for("CREATE ROLE report_reader WITH ADMIN |", MySQL);
    assert_ne!(
        kind,
        Some(ExpectedObjectSuggestionKind::User),
        "MySQL CREATE ROLE should not enable MariaDB-only WITH ADMIN account slots"
    );
}

#[test]
fn mysql_family_definer_account_slots_offer_only_users_in_final_suggestions() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for db in [MySQL, MariaDB] {
        for sql in [
            "CREATE DEFINER |",
            "CREATE DEFINER = |",
            "CREATE DEFINER app|",
            "CREATE DEFINER = app|",
            "CREATE OR REPLACE DEFINER |",
            "CREATE OR REPLACE DEFINER app|",
            "CREATE ALGORITHM MERGE DEFINER |",
            "CREATE ALGORITHM MERGE DEFINER app|",
            "CREATE DEFINER | FUNCTION f RETURNS INT",
            "CREATE DEFINER app| FUNCTION f RETURNS INT",
            "CREATE DEFINER | PROCEDURE p",
            "CREATE DEFINER app| PROCEDURE p",
            "CREATE DEFINER | EVENT ev ON SCHEDULE EVERY 1 DAY",
            "CREATE DEFINER app| EVENT ev ON SCHEDULE EVERY 1 DAY",
            "CREATE DEFINER | TRIGGER trg BEFORE INSERT ON emp FOR EACH ROW SET @x = 1",
            "CREATE DEFINER app| TRIGGER trg BEFORE INSERT ON emp FOR EACH ROW SET @x = 1",
            "ALTER DEFINER |",
            "ALTER DEFINER = |",
            "ALTER DEFINER app|",
            "ALTER DEFINER = app|",
            "ALTER ALGORITHM MERGE DEFINER |",
            "ALTER ALGORITHM MERGE DEFINER app|",
            "ALTER DEFINER | EVENT ev ON SCHEDULE EVERY 1 DAY",
            "ALTER DEFINER app| EVENT ev ON SCHEDULE EVERY 1 DAY",
        ] {
            let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
            assert_eq!(
                kind,
                Some(ExpectedObjectSuggestionKind::User),
                "MySQL-family DEFINER account slot should resolve to users at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
            assert!(
                contains(&final_suggestions, "APP_USER") || contains(&final_suggestions, "SCOTT"),
                "MySQL-family DEFINER account slot lost user suggestions at `{sql}` {db:?}: {final_suggestions:?}"
            );
            for leaked in [
                "EMP",
                "DEPT",
                "EMP_V",
                "RUN_JOB",
                "CALC_TOTAL",
                "HR_PKG",
                "SELECT",
                "WHERE",
                "NOT",
                "NULL",
                "NTH_VALUE",
                "NTILE",
                "NOW()",
                "NULLIF()",
            ] {
                assert!(
                    !contains(&final_suggestions, leaked),
                    "{leaked} leaked into MySQL-family DEFINER account slot at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
                );
            }
        }

        for sql in [
            "CREATE SQL SECURITY |",
            "CREATE SQL SECURITY D|",
            "CREATE SQL SECURITY I|",
            "CREATE SQL SECURITY DEFINER |",
            "CREATE SQL SECURITY DEFINER VIEW v |",
            "CREATE SQL SECURITY INVOKER |",
            "CREATE SQL SECURITY INVOKER VIEW v |",
            "CREATE FUNCTION f RETURNS INT SQL SECURITY |",
            "CREATE FUNCTION f RETURNS INT SQL SECURITY D|",
            "CREATE FUNCTION f RETURNS INT SQL SECURITY DEFINER |",
            "CREATE FUNCTION f RETURNS INT SQL SECURITY INVOKER |",
            "ALTER SQL SECURITY |",
            "ALTER SQL SECURITY D|",
            "ALTER SQL SECURITY DEFINER |",
            "ALTER SQL SECURITY DEFINER VIEW v |",
            "ALTER SQL SECURITY INVOKER |",
            "ALTER SQL SECURITY INVOKER VIEW v |",
        ] {
            let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
            assert_ne!(
                kind,
                Some(ExpectedObjectSuggestionKind::User),
                "SQL SECURITY DEFINER is a fixed keyword value, not an account slot at `{sql}` {db:?}"
            );
            for leaked in ["APP_USER", "SCOTT", "EMP", "DEPT", "EMP_V", "RUN_JOB"] {
                assert!(
                    !contains(&final_suggestions, leaked),
                    "{leaked} leaked into SQL SECURITY keyword/value slot at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
                );
            }
            assert!(
                !keywords.is_empty() || !final_suggestions.is_empty(),
                "SQL SECURITY DEFINER tail should keep structural keywords at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
}

