#[test]
fn oracle_synonym_target_final_suggestions_offer_objects_without_keywords() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for (sql, expected) in [
        (
            "CREATE SYNONYM emp_syn FOR |",
            &[
                "EMP",
                "EMP_V",
                "MVIEW_SALES",
                "EMP_SEQ",
                "HR_PKG",
                "CALC_TOTAL",
            ][..],
        ),
        (
            "CREATE PUBLIC SYNONYM emp_syn FOR |",
            &[
                "EMP",
                "EMP_V",
                "MVIEW_SALES",
                "EMP_SEQ",
                "HR_PKG",
                "CALC_TOTAL",
            ],
        ),
        (
            "CREATE OR REPLACE SYNONYM emp_syn FOR |",
            &[
                "EMP",
                "EMP_V",
                "MVIEW_SALES",
                "EMP_SEQ",
                "HR_PKG",
                "CALC_TOTAL",
            ],
        ),
        (
            "CREATE OR REPLACE PUBLIC SYNONYM emp_syn FOR |",
            &[
                "EMP",
                "EMP_V",
                "MVIEW_SALES",
                "EMP_SEQ",
                "HR_PKG",
                "CALC_TOTAL",
            ],
        ),
        (
            "CREATE SYNONYM emp_syn FOR e|",
            &["EMP", "EMP_V", "EMP_SEQ"],
        ),
        (
            "CREATE SYNONYM emp_syn FOR app.|",
            &[
                "EMP", "EMP_VIEW", "EMP_MV", "EMP_SEQ", "EMP_PKG", "EMP_FUNC",
            ],
        ),
        (
            "CREATE PUBLIC SYNONYM emp_syn FOR app.emp|",
            &[
                "EMP", "EMP_VIEW", "EMP_MV", "EMP_SEQ", "EMP_PKG", "EMP_FUNC",
            ],
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind,
            Some(ExpectedObjectSuggestionKind::SchemaObject),
            "synonym target should resolve to schema objects at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            keywords.is_empty(),
            "synonym target should not merge keywords at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for expected in expected {
            assert!(
                contains(&final_suggestions, expected),
                "{expected} missing from synonym target at `{sql}`: {final_suggestions:?}"
            );
        }
        for leaked in [
            "APP_USER",
            "SCOTT",
            "EMP_USER",
            "SELECT",
            "CREATE",
            "WHERE",
            "FROM",
            "JOIN",
            "NOT",
            "NULL",
            "NTH_VALUE",
            "NTILE",
            "NVL",
            "NVL()",
            "NEXT_DAY()",
            "NULLIF()",
        ] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into synonym target at `{sql}`: {final_suggestions:?}"
            );
        }
    }
}

#[test]
fn broad_schema_object_prefix_slots_do_not_merge_users() {
    use crate::db::DatabaseType::Oracle;

    let contains = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for sql in [
        "DESC app|",
        "DESCRIBE app|",
        "CREATE SYNONYM emp_syn FOR app|",
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind,
            Some(ExpectedObjectSuggestionKind::SchemaObject),
            "schema-object prefix slot should resolve to schema objects at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        for leaked in ["APP_USER", "SCOTT"] {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into schema-object prefix slot at `{sql}`: {final_suggestions:?}"
            );
        }
    }

    for (sql, expected_kind, expected, leaked) in [
        (
            "AUDIT SELECT ON emp|",
            ExpectedObjectSuggestionKind::RelationOrSequence,
            "EMP",
            &["APP_USER", "SCOTT", "EMP_FUNC", "EMP_PKG"][..],
        ),
        (
            "NOAUDIT EXECUTE ON run|",
            ExpectedObjectSuggestionKind::Executable,
            "RUN_JOB",
            &["APP_USER", "SCOTT", "EMP", "EMP_VIEW", "EMP_SEQ"],
        ),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind,
            Some(expected_kind),
            "audit object prefix slot should resolve to precise object family at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            contains(&final_suggestions, expected),
            "{expected} missing from audit object prefix slot at `{sql}`: {final_suggestions:?}"
        );
        for leaked in leaked {
            assert!(
                !contains(&final_suggestions, leaked),
                "{leaked} leaked into audit object prefix slot at `{sql}`: {final_suggestions:?}"
            );
        }
    }
}

