#[test]
fn mysql_inline_index_options_do_not_suppress_following_column_definition_tail() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let kw = |sql: &str, db: crate::db::DatabaseType| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for db in [MySQL, MariaDB] {
        for sql in [
            "CREATE TABLE t (a INT, INDEX idx_a (a) COMMENT 'doc', b INT |",
            "CREATE TABLE t (a INT, UNIQUE idx_a (a) COMMENT 'doc', b INT |",
            "CREATE TABLE t (a INT, FULLTEXT idx_a (a) WITH PARSER ngram, b INT |",
            "CREATE TABLE t (a POINT, SPATIAL idx_a (a) COMMENT 'doc', b INT |",
        ] {
            let suggestions = kw(sql, db);
            assert!(
                has(&suggestions, "NOT NULL") && has(&suggestions, "DEFAULT"),
                "inline index option tail over-suppressed the following column definition at `{sql}` for {db:?}: {suggestions:?}"
            );
        }
    }
}

#[test]
fn mysql_alter_table_index_options_do_not_suppress_following_add_column_tail() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let kw = |sql: &str, db| -> Vec<String> {
        let cursor = sql.find('|').expect("cursor");
        let plain = sql.replace('|', "");
        let (prefix, _, _) = crate::ui::intellisense::get_word_at_cursor(&plain, cursor);
        SqlEditorWidget::collect_expected_keyword_suggestions(
            &prefix,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |values: &[String], needle: &str| values.iter().any(|value| value == needle);

    for db in [MySQL, MariaDB] {
        for sql in [
            "ALTER TABLE emp ADD INDEX idx_emp (empno) COMMENT 'doc', ADD COLUMN bonus INT |",
            "ALTER TABLE emp ADD UNIQUE idx_emp (empno) COMMENT 'doc', ADD COLUMN bonus INT |",
            "ALTER TABLE emp ADD FULLTEXT idx_emp (ename) WITH PARSER ngram, ADD COLUMN bonus INT |",
            "ALTER TABLE emp ADD PRIMARY KEY (empno) KEY_BLOCK_SIZE 8, ADD COLUMN bonus INT |",
        ] {
            let suggestions = kw(sql, db);
            assert!(
                has(&suggestions, "NOT NULL") && has(&suggestions, "DEFAULT"),
                "ALTER TABLE index option tail over-suppressed the following ADD COLUMN definition at `{sql}` for {db:?}: {suggestions:?}"
            );
        }
    }

    for sql in [
        "ALTER TABLE emp ADD INDEX idx_emp (empno) COMMENT 'doc', |",
        "ALTER TABLE emp ADD UNIQUE idx_emp (empno) COMMENT 'doc', |",
        "ALTER TABLE emp ADD FULLTEXT idx_emp (ename) WITH PARSER ngram, |",
    ] {
        for db in [MySQL, MariaDB] {
            let suggestions = kw(sql, db);
            assert!(
                has(&suggestions, "ADD") && has(&suggestions, "DROP"),
                "ALTER TABLE index option tail over-suppressed the following subcommand start at `{sql}` for {db:?}: {suggestions:?}"
            );
        }
    }
}

/// Relation-naming slots that also carry nearby keywords must still offer the
/// table catalog (not be over-suppressed): the MySQL-family `LOCK TABLES`/`FLUSH TABLES`
/// table-list slots and the `SHOW COLUMNS FROM` table slot. The keyword/alias/
/// lock-type slots in the same statements stay suppressed, and the post-table
/// filters appear only once the table is named.
#[test]
fn mysql_family_relation_naming_admin_slots_offer_the_catalog() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let supp = |sql: &str, db| {
        let excl = sql
            .strip_suffix('|')
            .and_then(|s| s.chars().last())
            .is_some_and(|c| c.is_alphanumeric());
        SqlEditorWidget::cursor_is_at_identifier_suppressing_keyword_slot_for_context(
            &analyze_inline_cursor_sql(sql),
            excl,
            Some(db),
        )
    };
    let kind = |sql: &str, db| {
        SqlEditorWidget::expected_object_suggestion_kind_for_db(
            "",
            None,
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let kw = |sql: &str, db| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |v: &Vec<String>, s: &str| v.iter().any(|x| x == s);
    use ExpectedObjectSuggestionKind as K;

    for db in [MySQL, MariaDB] {
        // LOCK/FLUSH TABLES table-list slots: catalog offered (not suppressed).
        for sql in [
            "LOCK TABLES |",
            "LOCK TABLES emp READ, |",
            "FLUSH TABLES |",
            "FLUSH LOCAL TABLES |",
        ] {
            assert!(
                !supp(sql, db),
                "relation-naming slot must offer the catalog at `{sql}` {db:?}"
            );
        }
        assert_eq!(kind("LOCK TABLES |", db), Some(K::Table));
        assert_eq!(kind("FLUSH TABLES |", db), Some(K::Table));
        // `FLUSH TABLES |` still offers its own keywords alongside the catalog.
        assert!(has(&kw("FLUSH TABLES |", db), "FOR") && has(&kw("FLUSH TABLES |", db), "WITH"));
        assert!(has(&kw("FLUSH TABLES WITH |", db), "READ"));
        assert!(has(&kw("FLUSH TABLES WITH READ |", db), "LOCK"));
        assert!(supp("FLUSH TABLES WITH READ LOCK |", db));

        // The alias / lock-type / post-table slots in the same statements stay
        // suppressed (no relation grammatical there).
        assert!(supp("LOCK TABLES emp |", db)); // lock-type slot -> AS/READ/WRITE
        assert!(has(&kw("LOCK TABLES emp |", db), "READ"));
        assert!(supp("LOCK TABLES emp AS |", db)); // alias = a new name

        // `SHOW COLUMNS FROM |` offers the table via the object kind and no longer
        // leaks the post-table filter keywords prematurely.
        assert_eq!(kind("SHOW COLUMNS FROM |", db), Some(K::ColumnOwner));
        assert!(
            kw("SHOW COLUMNS FROM |", db).is_empty(),
            "premature filter keywords at the SHOW COLUMNS table slot {db:?}: {:?}",
            kw("SHOW COLUMNS FROM |", db)
        );
        // After the table is named the filters appear.
        let after = kw("SHOW COLUMNS FROM emp |", db);
        assert!(
            has(&after, "LIKE") && has(&after, "WHERE"),
            "{after:?} {db:?}"
        );
    }
}

/// Oracle's flashback `AS OF` / `VERSIONS BETWEEN` is dialect-specific: after a
/// table's `AS`, Oracle may continue with `OF` (a flashback query) — but in MySQL
/// `AS` only introduces a table/lock alias (a new name), so `OF` must not be
/// offered there. Guards against the flashback keywords leaking into MySQL.
#[test]
fn flashback_as_of_is_oracle_only() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};
    let kw = |sql: &str, db: crate::db::DatabaseType| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let has = |v: &Vec<String>, s: &str| v.iter().any(|x| x == s);

    // Oracle: `FROM emp AS |` continues a flashback query with `OF`.
    assert!(has(&kw("SELECT * FROM emp AS |", Oracle), "OF"));
    assert!(has(&kw("SELECT * FROM emp AS OF |", Oracle), "SCN"));
    assert!(has(&kw("SELECT * FROM emp VERSIONS |", Oracle), "BETWEEN"));
    assert!(has(
        &kw("SELECT * FROM emp VERSIONS BETWEEN SCN 1 |", Oracle),
        "AND"
    ));
    for (sql, expected) in [
        ("SELECT * FROM emp AS |", "OF"),
        ("SELECT * FROM emp AS OF |", "SCN"),
        ("SELECT * FROM emp VERSIONS |", "BETWEEN"),
        ("SELECT * FROM emp VERSIONS BETWEEN |", "SCN"),
        ("SELECT * FROM emp VERSIONS BETWEEN SCN 1 |", "AND"),
        ("SELECT * FROM emp AS O|", "OF"),
        ("SELECT * FROM emp AS OF S|", "SCN"),
        ("SELECT * FROM emp AS OF T|", "TIMESTAMP"),
        ("SELECT * FROM emp VERSIONS B|", "BETWEEN"),
        ("SELECT * FROM emp VERSIONS BETWEEN S|", "SCN"),
        ("SELECT * FROM emp VERSIONS BETWEEN T|", "TIMESTAMP"),
        ("SELECT * FROM emp VERSIONS BETWEEN SCN 1 A|", "AND"),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, Oracle);
        assert_eq!(
            kind, None,
            "flashback keyword slot should not resolve object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.iter().any(|value| value == expected),
            "{expected} missing from flashback keyword slot at `{sql}`: {final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "EMPNO",
            "ENAME",
            "RUN_JOB",
            "CALC_TOTAL",
        ] {
            assert!(
                !final_suggestions.iter().any(|value| value == leaked),
                "{leaked} leaked into flashback keyword slot at `{sql}`: {final_suggestions:?}"
            );
        }
    }

    // MySQL-family: `AS` is an alias - no flashback `OF`.
    for db in [MySQL, MariaDB] {
        assert!(
            !has(&kw("SELECT * FROM emp AS |", db), "OF"),
            "flashback OF leaked into a MySQL-family table alias {db:?}"
        );
        assert!(
            !has(&kw("LOCK TABLES emp AS |", db), "OF"),
            "flashback OF leaked into a MySQL-family LOCK TABLES alias {db:?}"
        );
        for sql in ["SELECT * FROM emp AS O|", "LOCK TABLES emp AS O|"] {
            let (_kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
            assert!(
                !keywords.iter().any(|value| value == "OF")
                    && !final_suggestions.iter().any(|value| value == "OF"),
                "flashback OF leaked into a MySQL-family alias slot at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
        }
    }
}

/// SQL-standard `TRIM`/`SUBSTRING`/`POSITION` calls have an internal keyword
/// grammar: after a complete operand the only continuation is the function's
/// separator keyword (never another column), so columns are suppressed and the
/// keyword is offered. The first-argument value slots still take a column, the
/// comma form of `SUBSTRING` takes no keyword, and `SUBSTR` (comma-only) and
/// unrelated functions are unaffected.
#[test]
fn standard_function_internal_keyword_grammar_is_offered() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};
    let kw = |sql: &str, db: crate::db::DatabaseType| {
        SqlEditorWidget::collect_expected_keyword_suggestions(
            "",
            &analyze_inline_cursor_sql(sql),
            Some(db),
        )
    };
    let supp = |sql: &str, db: crate::db::DatabaseType| {
        SqlEditorWidget::cursor_is_at_column_suppressing_keyword_slot_for_db(
            &analyze_inline_cursor_sql(sql),
            false,
            Some(db),
        )
    };
    let eq = |sql: &str, db: crate::db::DatabaseType, want: &[&str]| {
        assert_eq!(
            kw(sql, db),
            want.iter().map(|s| s.to_string()).collect::<Vec<_>>(),
            "{sql}"
        );
        assert!(supp(sql, db), "columns must be suppressed at `{sql}`");
    };

    // After-operand keyword slots (columns suppressed, separator keyword offered).
    eq("SELECT POSITION('a' |", Oracle, &["IN"]);
    eq("SELECT POSITION(col |", Oracle, &["IN"]);
    eq("SELECT TRIM(name |", Oracle, &["FROM"]);
    assert_eq!(kw("SELECT TRIM(LEADING |", MariaDB), vec!["FROM"]);
    assert!(
        !supp("SELECT TRIM(LEADING |", MariaDB),
        "TRIM removal-character slot must continue to offer columns"
    );
    eq("SELECT TRIM(LEADING 'x' |", Oracle, &["FROM"]);
    eq("SELECT SUBSTRING(name |", MySQL, &["FROM"]);
    eq("SELECT SUBSTRING(name FROM 1 |", MySQL, &["FOR"]);
    eq("SELECT SUBSTRING(name |", MariaDB, &["FROM"]);
    eq("SELECT SUBSTRING(name FROM 1 |", MariaDB, &["FOR"]);
    eq("SELECT OVERLAY(name |", Oracle, &["PLACING"]);
    eq("SELECT OVERLAY(name PLACING repl |", Oracle, &["FROM"]);
    eq(
        "SELECT OVERLAY(name PLACING repl FROM 1 |",
        Oracle,
        &["FOR"],
    );
    // Nested complete operand resolves to the outer call's keyword.
    eq("SELECT POSITION(INSTR(a, b) |", Oracle, &["IN"]);
    for (sql, db, expected) in [
        ("SELECT POSITION('a' |", Oracle, "IN"),
        ("SELECT POSITION('a' I|", Oracle, "IN"),
        ("SELECT TRIM(name |", Oracle, "FROM"),
        ("SELECT TRIM(name F|", Oracle, "FROM"),
        ("SELECT TRIM(LEADING F| 'x')", MariaDB, "FROM"),
        ("SELECT TRIM(LEADING 'x' |", Oracle, "FROM"),
        ("SELECT TRIM(LEADING 'x' F|", Oracle, "FROM"),
        ("SELECT SUBSTRING(name |", MySQL, "FROM"),
        ("SELECT SUBSTRING(name F|", MySQL, "FROM"),
        ("SELECT SUBSTRING(name FROM 1 |", MySQL, "FOR"),
        ("SELECT SUBSTRING(name FROM 1 F|", MySQL, "FOR"),
        ("SELECT SUBSTRING(name |", MariaDB, "FROM"),
        ("SELECT SUBSTRING(name F|", MariaDB, "FROM"),
        ("SELECT SUBSTRING(name FROM 1 |", MariaDB, "FOR"),
        ("SELECT SUBSTRING(name FROM 1 F|", MariaDB, "FOR"),
        ("SELECT OVERLAY(name |", Oracle, "PLACING"),
        ("SELECT OVERLAY(name P|", Oracle, "PLACING"),
        ("SELECT OVERLAY(name PLACING repl |", Oracle, "FROM"),
        ("SELECT OVERLAY(name PLACING repl F|", Oracle, "FROM"),
        ("SELECT OVERLAY(name PLACING repl FROM 1 |", Oracle, "FOR"),
        ("SELECT OVERLAY(name PLACING repl FROM 1 F|", Oracle, "FOR"),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert_eq!(
            kind, None,
            "standard function keyword slot should not resolve object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.iter().any(|value| value == expected),
            "{expected} missing from standard function keyword slot at `{sql}`: {final_suggestions:?}"
        );
        for leaked in [
            "EMP",
            "DEPT",
            "EMP_V",
            "EMPNO",
            "ENAME",
            "RUN_JOB",
            "CALC_TOTAL",
            "WHERE",
            "JOIN",
            "ORDER BY",
            "FETCH",
            "FOR UPDATE",
        ] {
            assert!(
                !final_suggestions.iter().any(|value| value == leaked),
                "{leaked} leaked into standard function keyword slot at `{sql}`: {final_suggestions:?}"
            );
        }
    }

    // Not keyword slots: the str operand (inside/after the separator), the comma
    // form, `SUBSTR`, the first-arg value slot, and unrelated calls.
    let none = |sql: &str, db: crate::db::DatabaseType| {
        assert!(
            kw(sql, db).is_empty(),
            "unexpected keyword at `{sql}`: {:?}",
            kw(sql, db)
        );
        assert!(!supp(sql, db), "columns must NOT be suppressed at `{sql}`");
    };
    none("SELECT POSITION('a' IN name |", Oracle); // inside the search string
    none("SELECT TRIM(BOTH ' ' FROM name |", Oracle);
    none("SELECT SUBSTRING(name, 1 |", MySQL); // comma form
    none("SELECT SUBSTRING(name, 1 |", MariaDB); // comma form
    none("SELECT OVERLAY(name PLACING |", Oracle); // replacement value slot
    none("SELECT OVERLAY(name PLACING repl FROM |", Oracle); // start value slot
    none("SELECT OVERLAY(name PLACING repl FROM 1 FOR len |", Oracle);
    none("SELECT SUBSTR(name |", Oracle); // comma-only spelling
    none("SELECT UPPER(name |", Oracle); // unrelated function

    for (sql, db) in [
        ("SELECT POSITION('a' IN name n|", Oracle),
        ("SELECT TRIM(BOTH ' ' FROM name n|", Oracle),
        ("SELECT SUBSTRING(name FROM 1 FOR len n|", MySQL),
        ("SELECT SUBSTRING(name FROM 1 FOR len n|", MariaDB),
        ("SELECT OVERLAY(name PLACING repl FROM 1 FOR len n|", Oracle),
    ] {
        let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
        assert_eq!(
            kind, None,
            "completed standard-function tail with prefix should not resolve object kind at `{sql}`; keywords={keywords:?} final={final_suggestions:?}"
        );
        assert!(
            final_suggestions.is_empty(),
            "completed standard-function tail with prefix should not offer catalog or stale keywords at `{sql}`: keywords={keywords:?} final={final_suggestions:?}"
        );
    }
}

/// Regression: a qualified column slot (`t.|` / alias `a.|`) must keep the
/// base-catalog fall-through enabled so the qualified column list is produced.
/// A refactor once gated `base_catalog_suggestions` on `qualifier.is_none()`,
/// which silently dropped every `<alias>.` column completion. This locks the
/// allowance contract (the qualifier/keyword-only cases are routed by later
/// dedicated branches, not by this flag) and verifies the columns actually
/// surface through the production `base_suggestions_for_context` path.
#[test]
fn qualified_alias_column_slot_yields_relation_columns() {
    for sql in ["select * from help a where a.|", "select a.| from help a"] {
        let ctx = analyze_inline_cursor_sql(sql);

        let mut data = IntellisenseData::new();
        data.tables = vec!["help".to_string()];
        data.rebuild_indices();
        data.set_columns_for_table(
            "help",
            vec!["id".to_string(), "topic".to_string(), "text".to_string()],
        );

        // The qualifier resolves to its relation and the mode is RelationColumns.
        assert_eq!(
            SqlEditorWidget::resolve_qualified_completion_mode(
                "a",
                SqlContext::ColumnName,
                &ctx,
                &data,
            ),
            Some(super::QualifiedCompletionMode::RelationColumns),
            "mode for `{sql}`"
        );

        // The allowance must NOT suppress the base catalog merely because a
        // qualifier is present — that branch carries the qualified column list.
        let expr_keyword_ctx = super::ExpressionKeywordContext::ambiguous();
        let policy =
            CompletionSourcePolicy::new(false, false, false, false, false, expr_keyword_ctx);
        let allowance = policy.allowance(SqlContext::ColumnName, Some("a"), expr_keyword_ctx);
        assert!(
            allowance.base_catalog_suggestions,
            "base catalog must stay enabled at a qualified slot for `{sql}`"
        );

        // End-to-end: the production column path yields the relation's columns.
        let column_tables = SqlEditorWidget::resolve_column_tables_for_context(Some("a"), &ctx);
        let cols = SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            "",
            Some("a"),
            Some(&column_tables),
            true,
            SqlContext::ColumnName,
            false,
            Some(crate::db::DatabaseType::Oracle),
            expr_keyword_ctx,
        );
        for expected in ["id", "topic", "text"] {
            assert!(
                cols.iter().any(|c| c.eq_ignore_ascii_case(expected)),
                "`{sql}` should suggest column `{expected}`, got {cols:?}"
            );
        }
    }
}

#[test]
fn qualified_alias_production_completion_does_not_leak_other_relation_columns() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], needle: &str| {
        values
            .iter()
            .any(|value| value.eq_ignore_ascii_case(needle))
    };
    let sql_slots = [
        "SELECT d.| FROM emp e JOIN dept d ON e.deptno = d.deptno",
        "SELECT * FROM emp e JOIN dept d ON d.|",
        "SELECT * FROM emp e JOIN dept d ON e.deptno = d.deptno WHERE d.|",
    ];

    for db_type in [Oracle, MariaDB, MySQL] {
        for sql in sql_slots {
            let suggestions = query_completion_suggestions_impl(sql, db_type, true);
            for expected in ["DEPTNO", "DNAME"] {
                assert!(
                    contains(&suggestions, expected),
                    "target alias column `{expected}` missing at `{sql}` {db_type:?}: {suggestions:?}"
                );
            }
            for leaked in ["EMPNO", "ENAME", "SAL"] {
                assert!(
                    !contains(&suggestions, leaked),
                    "unrelated first-relation column `{leaked}` leaked at `{sql}` {db_type:?}: {suggestions:?}"
                );
            }
        }

        let unresolved_sql =
            "SELECT missing.| FROM emp e JOIN dept d ON e.deptno = d.deptno";
        let unresolved =
            query_completion_suggestions_impl(unresolved_sql, db_type, true);
        for leaked in ["EMPNO", "ENAME", "DEPTNO", "DNAME", "SAL"] {
            assert!(
                !contains(&unresolved, leaked),
                "unresolved qualifier leaked `{leaked}` at `{unresolved_sql}` {db_type:?}: {unresolved:?}"
            );
        }
    }
}

#[test]
fn oracle_qualified_relation_pseudocolumns_are_contextual_and_follow_catalog_columns() {
    use crate::db::DatabaseType::Oracle;

    const ROW_PSEUDOCOLUMNS: &[&str] = &["ROWID", "ORA_ROWSCN"];
    const VERSION_PSEUDOCOLUMNS: &[&str] = &[
        "VERSIONS_STARTSCN",
        "VERSIONS_STARTTIME",
        "VERSIONS_ENDSCN",
        "VERSIONS_ENDTIME",
        "VERSIONS_XID",
        "VERSIONS_OPERATION",
    ];
    let position = |suggestions: &[String], needle: &str| {
        suggestions
            .iter()
            .position(|value| value.eq_ignore_ascii_case(needle))
    };
    let assert_absent = |sql: &str, suggestions: &[String], forbidden: &[&str]| {
        for candidate in forbidden {
            assert!(
                position(suggestions, candidate).is_none(),
                "`{candidate}` must be absent at `{sql}`: {suggestions:?}"
            );
        }
    };
    let assert_catalog_before = |sql: &str,
                                 suggestions: &[String],
                                 catalog_columns: &[&str],
                                 pseudocolumns: &[&str]| {
        for pseudo in pseudocolumns {
            let pseudo_position = position(suggestions, pseudo)
                .unwrap_or_else(|| panic!("`{pseudo}` missing at `{sql}`: {suggestions:?}"));
            for column in catalog_columns {
                let column_position = position(suggestions, column).unwrap_or_else(|| {
                    panic!("catalog column `{column}` missing at `{sql}`: {suggestions:?}")
                });
                assert!(
                    column_position < pseudo_position,
                    "catalog column `{column}` must precede `{pseudo}` at `{sql}`: {suggestions:?}"
                );
            }
        }
    };

    let ordinary_sql = "SELECT a.| FROM help a";
    let ordinary = query_completion_suggestions_impl(ordinary_sql, Oracle, true);
    assert_catalog_before(
        ordinary_sql,
        &ordinary,
        &["ID", "TOPIC"],
        ROW_PSEUDOCOLUMNS,
    );
    assert_absent(ordinary_sql, &ordinary, VERSION_PSEUDOCOLUMNS);

    let as_of_sql = "SELECT a.| FROM help AS OF SCN 1 a";
    let as_of = query_completion_suggestions_impl(as_of_sql, Oracle, true);
    assert_absent(as_of_sql, &as_of, VERSION_PSEUDOCOLUMNS);

    let versions_sql =
        "SELECT v.| FROM emp VERSIONS BETWEEN SCN MINVALUE AND MAXVALUE v";
    let versions = query_completion_suggestions_impl(versions_sql, Oracle, true);
    assert_catalog_before(
        versions_sql,
        &versions,
        &["EMPNO", "ENAME", "DEPTNO", "SAL"],
        ROW_PSEUDOCOLUMNS,
    );
    assert_catalog_before(
        versions_sql,
        &versions,
        &["EMPNO", "ENAME", "DEPTNO", "SAL"],
        VERSION_PSEUDOCOLUMNS,
    );

    let ordinary_join_sql =
        "SELECT d.| FROM emp VERSIONS BETWEEN SCN MINVALUE AND MAXVALUE e \
         JOIN dept d ON e.deptno = d.deptno";
    let ordinary_join_alias =
        query_completion_suggestions_impl(ordinary_join_sql, Oracle, true);
    assert_absent(
        ordinary_join_sql,
        &ordinary_join_alias,
        VERSION_PSEUDOCOLUMNS,
    );
}

#[test]
fn mariadb_oracle_mode_qualified_alias_does_not_use_unqualified_query_fallback() {
    use crate::db::DatabaseType::MariaDB;

    let sql = "DECLARE v_name VARCHAR2(100); BEGIN \
               SELECT d.| INTO v_name FROM emp e JOIN dept d ON e.deptno = d.deptno; \
               END;";
    let suggestions = query_completion_suggestions_impl(sql, MariaDB, true);
    let contains = |needle: &str| {
        suggestions
            .iter()
            .any(|value| value.eq_ignore_ascii_case(needle))
    };

    for expected in ["DEPTNO", "DNAME"] {
        assert!(
            contains(expected),
            "target alias column `{expected}` missing at `{sql}`: {suggestions:?}"
        );
    }
    for leaked in ["EMPNO", "ENAME", "SAL"] {
        assert!(
            !contains(leaked),
            "unqualified query fallback leaked `{leaked}` at `{sql}`: {suggestions:?}"
        );
    }
}

