fn derived_relation_alias_offers_only_projected_columns() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], needle: &str| {
        values
            .iter()
            .any(|value| value.eq_ignore_ascii_case(needle))
    };

    for db in [Oracle, MySQL, MariaDB] {
        for (sql, expected, leaked) in [
            (
                "SELECT d.| FROM (SELECT deptno FROM dept) d",
                &["DEPTNO"][..],
                &["DNAME", "EMPNO", "ENAME"][..],
            ),
            (
                "SELECT d.| FROM (SELECT deptno AS dept_id FROM dept) d",
                &["DEPT_ID"][..],
                &["DEPTNO", "DNAME"][..],
            ),
            (
                "WITH d AS (SELECT deptno FROM dept) SELECT d.| FROM d",
                &["DEPTNO"][..],
                &["DNAME", "EMPNO", "ENAME"][..],
            ),
            (
                "WITH d(dept_id) AS (SELECT deptno FROM dept) SELECT d.| FROM d",
                &["DEPT_ID"][..],
                &["DEPTNO", "DNAME"][..],
            ),
        ] {
            let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
            assert_eq!(
                kind, None,
                "derived relation alias should resolve projected columns at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
            for column in expected {
                assert!(
                    contains(&final_suggestions, column),
                    "derived relation alias lost `{column}` at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
                );
            }
            for column in leaked {
                assert!(
                    !contains(&final_suggestions, column),
                    "`{column}` leaked outside derived projection at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
                );
            }
        }
    }
}

#[test]
fn alias_column_list_final_suggestions_stay_on_projection_columns() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], needle: &str| {
        values
            .iter()
            .any(|value| value.eq_ignore_ascii_case(needle))
    };

    for db in [Oracle, MySQL, MariaDB] {
        for (sql, expected, leaked) in [
            (
                "WITH d(|) AS (SELECT deptno, dname FROM dept) SELECT * FROM d",
                &["DEPTNO", "DNAME"][..],
                &["EMP", "DEPT", "EMP_V", "EMPNO", "ENAME"][..],
            ),
            (
                "WITH d(dept_id, |) AS (SELECT deptno, dname FROM dept) SELECT * FROM d",
                &["DEPTNO", "DNAME"][..],
                &["EMP", "DEPT", "EMP_V", "DEPT_ID", "EMPNO", "ENAME"],
            ),
            (
                "SELECT * FROM (SELECT empno, ename FROM emp) d(|)",
                &["EMPNO", "ENAME"][..],
                &["EMP", "DEPT", "EMP_V", "DEPTNO", "DNAME"],
            ),
            (
                "SELECT * FROM (SELECT empno, ename FROM emp) d(id_alias, |)",
                &["EMPNO", "ENAME"][..],
                &["EMP", "DEPT", "EMP_V", "ID_ALIAS", "DEPTNO", "DNAME"],
            ),
            (
                "SELECT * FROM emp e(|)",
                &["EMPNO", "ENAME", "SAL"][..],
                &["EMP", "DEPT", "EMP_V", "DEPTNO", "DNAME"],
            ),
            (
                "SELECT * FROM emp e(emp_id_alias, |)",
                &["EMPNO", "ENAME", "SAL"][..],
                &["EMP", "DEPT", "EMP_V", "EMP_ID_ALIAS", "DEPTNO", "DNAME"],
            ),
        ] {
            let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
            assert_eq!(
                kind, None,
                "alias column-list slot should not resolve object kind at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
            for expected_column in expected {
                assert!(
                    contains(&final_suggestions, expected_column),
                    "{expected_column} missing from alias column-list slot at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
                );
            }
            for leaked_item in leaked {
                assert!(
                    !contains(&final_suggestions, leaked_item),
                    "{leaked_item} leaked into alias column-list slot at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
                );
            }
            for leaked_object in ["APP_USER", "SCOTT", "RUN_JOB", "CALC_TOTAL", "ADDRESS_T"] {
                assert!(
                    !contains(&final_suggestions, leaked_object),
                    "{leaked_object} leaked into alias column-list slot at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
                );
            }
        }
    }
}

#[test]
fn out_of_scope_qualified_relation_does_not_offer_catalog_columns() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], needle: &str| {
        values
            .iter()
            .any(|value| value.eq_ignore_ascii_case(needle))
    };

    for db in [Oracle, MySQL, MariaDB] {
        for sql in [
            "SELECT dept.| FROM emp",
            "SELECT dept.d| FROM emp",
            r#"SELECT "DEPT".| FROM emp"#,
            r#"SELECT "DEPT".d| FROM emp"#,
            "SELECT scott.dept.| FROM emp",
            "SELECT scott.dept.s| FROM emp",
            r#"SELECT "SCOTT"."DEPT".| FROM emp"#,
            r#"SELECT "SCOTT"."DEPT".s| FROM emp"#,
            "SELECT * FROM emp WHERE dept.|",
            "SELECT * FROM emp WHERE dept.d|",
            "SELECT * FROM emp e JOIN t ON dept.|",
            "SELECT * FROM emp GROUP BY dept.|",
            "SELECT * FROM emp ORDER BY dept.|",
            "SELECT * FROM emp HAVING dept.|",
            "SELECT * FROM emp e WHERE EXISTS (SELECT dept.| FROM dual)",
        ] {
            let (kind, keywords, final_suggestions) = audit_final_suggestions_for(sql, db);
            assert_eq!(
                kind, None,
                "out-of-scope qualified relation should not resolve an object kind at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
            );
            for leaked in ["DNAME", "S_DNAME", "S_DEPTNO", "*"] {
                assert!(
                    !contains(&final_suggestions, leaked),
                    "`{leaked}` leaked from out-of-scope catalog relation at `{sql}` {db:?}: keywords={keywords:?} final={final_suggestions:?}"
                );
            }
        }
    }
}

#[test]
fn schema_qualified_column_slot_yields_only_relation_columns() {
    for (sql, qualifier) in [
        ("SELECT scott.emp.e| FROM scott.emp", "scott.emp"),
        (
            "SELECT * FROM scott.emp WHERE scott.emp.e| = 1",
            "scott.emp",
        ),
        ("COMMENT ON COLUMN scott.emp.e|", "scott.emp"),
    ] {
        let cursor = sql.find('|').expect("cursor marker should exist");
        let source = sql.replace('|', "");
        let (prefix, start, _) = crate::ui::intellisense::get_word_at_cursor(&source, cursor);
        let parsed_qualifier = SqlEditorWidget::qualifier_before_word_in_text(&source, start);
        assert_eq!(
            parsed_qualifier.as_deref(),
            Some(qualifier),
            "qualified column parser should keep the full qualifier chain for `{sql}`"
        );

        let ctx = analyze_inline_cursor_sql(sql);
        let context =
            SqlEditorWidget::classify_intellisense_context(&ctx, ctx.statement_tokens.as_ref());

        let mut data = IntellisenseData::new();
        data.tables = vec!["EMP".to_string()];
        data.views = vec!["EMP_VIEW".to_string()];
        data.procedures = vec!["EMP_PROC".to_string()];
        data.users = vec!["SCOTT".to_string()];
        data.rebuild_indices();
        data.set_columns_for_table(
            "SCOTT.EMP",
            vec!["EMPNO".to_string(), "ENAME".to_string(), "SAL".to_string()],
        );
        data.set_columns_for_table("DEPT", vec!["DNAME".to_string()]);
        data.set_members_for_qualifier_with_kinds(
            "SCOTT",
            vec![
                ("EMP".to_string(), Some(QualifiedMemberKind::Table)),
                ("EMP_VIEW".to_string(), Some(QualifiedMemberKind::View)),
                ("EMP_PROC".to_string(), Some(QualifiedMemberKind::Procedure)),
            ],
        );

        let column_tables =
            SqlEditorWidget::resolve_column_tables_for_context(Some(qualifier), &ctx);
        assert_eq!(
            column_tables,
            vec![qualifier.to_string()],
            "`{sql}` should scope columns to the fully-qualified relation key"
        );
        let suggestions = SqlEditorWidget::base_suggestions_for_context(
            &mut data,
            &prefix,
            Some(qualifier),
            Some(&column_tables),
            true,
            context,
            false,
            Some(crate::db::DatabaseType::Oracle),
            super::ExpressionKeywordContext::ambiguous(),
        );

        assert_eq!(
            suggestions,
            vec!["EMPNO".to_string(), "ENAME".to_string()],
            "`{sql}` should suggest only matching columns from the qualified relation"
        );
    }
}

#[test]
