#[test]
fn plsql_returning_predicate_and_window_value_positions_offer_locals() {
    use crate::db::DatabaseType::Oracle;

    let has = |s: &[String], k: &str| s.iter().any(|x| x.eq_ignore_ascii_case(k));
    let d = "DECLARE v_num NUMBER; v_str VARCHAR2(100); b_flag BOOLEAN; \
        TYPE num_tab IS TABLE OF NUMBER; arr num_tab := num_tab();";
    let mut failures = Vec::new();

    let cases: &[(String, &[&str])] = &[
        (
            format!("{d} BEGIN UPDATE emp SET sal = __CODEX_CURSOR__ RETURNING sal INTO v_num; END;"),
            &["v_num", "NULL", "CASE"],
        ),
        (
            format!("{d} BEGIN UPDATE emp SET sal = 1 RETURNING sal INTO v_num, __CODEX_CURSOR__; END;"),
            &["v_num", "arr"],
        ),
        (
            format!("{d} BEGIN DELETE FROM emp WHERE empno = __CODEX_CURSOR__ RETURNING empno INTO v_num; END;"),
            &["v_num", "NULL", "CASE"],
        ),
        (
            format!("{d} BEGIN INSERT INTO emp (empno, sal) VALUES (v_num, __CODEX_CURSOR__) RETURNING empno INTO v_num; END;"),
            &["v_num", "NULL", "CASE"],
        ),
        (
            format!("{d} BEGIN MERGE INTO emp e USING dept d ON (e.deptno = d.deptno) WHEN MATCHED THEN UPDATE SET sal = __CODEX_CURSOR__; END;"),
            &["v_num", "NULL", "CASE"],
        ),
        (
            format!("{d} BEGIN MERGE INTO emp e USING dept d ON (e.deptno = d.deptno) WHEN NOT MATCHED THEN INSERT (empno, sal) VALUES (__CODEX_CURSOR__, v_num); END;"),
            &["v_num", "NULL", "CASE"],
        ),
        (
            format!("{d} BEGIN SELECT empno INTO v_num FROM emp WHERE ename LIKE __CODEX_CURSOR__; END;"),
            &["v_str", "NULL", "CASE"],
        ),
        (
            format!("{d} BEGIN SELECT empno INTO v_num FROM emp WHERE b_flag OR ename LIKE __CODEX_CURSOR__; END;"),
            &["v_str", "NULL", "CASE"],
        ),
        (
            format!("{d} BEGIN SELECT SUM(sal) OVER (PARTITION BY NVL(__CODEX_CURSOR__, deptno)) INTO v_num FROM emp; END;"),
            &["v_num", "NULL", "CASE"],
        ),
        (
            format!("{d} BEGIN SELECT SUM(sal) OVER (ORDER BY NVL(__CODEX_CURSOR__, sal)) INTO v_num FROM emp; END;"),
            &["v_num", "NULL", "CASE"],
        ),
        (
            format!("{d} BEGIN SELECT empno INTO v_num FROM emp WHERE EXISTS (SELECT 1 FROM dept WHERE dname LIKE __CODEX_CURSOR__); END;"),
            &["v_str"],
        ),
        (
            format!("{d} BEGIN FORALL i IN 1 .. arr.COUNT UPDATE emp SET sal = __CODEX_CURSOR__ WHERE empno = arr(i); END;"),
            &["v_num", "NULL", "CASE"],
        ),
    ];

    for (sql, expected) in cases {
        let suggestions = query_completion_suggestions_with_locals(sql, Oracle);
        if suggestions.is_empty() {
            failures.push(format!("EMPTY at `{}`", sql.replace('\n', " ")));
            continue;
        }
        for item in *expected {
            if !has(&suggestions, item) {
                failures.push(format!("`{item}` missing at `{sql}`: {suggestions:?}"));
            }
        }
    }

    assert!(
        failures.is_empty(),
        "PL/SQL RETURNING/predicate/window value-position gaps:\n{}",
        failures.join("\n")
    );
}

#[test]
fn mysql_family_common_sql_basics_offer_final_suggestions() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    let has = |suggestions: &[String], expected: &str| {
        suggestions
            .iter()
            .any(|value| value.eq_ignore_ascii_case(expected))
    };
    let mut failures = Vec::new();
    let cases: &[(&str, &[&str])] = &[
        (
            "|",
            &[
                "SELECT", "INSERT", "UPDATE", "DELETE", "CREATE", "ALTER", "DROP",
            ],
        ),
        ("SEL|", &["SELECT"]),
        ("SELECT | FROM emp", &["EMPNO", "ENAME"]),
        ("SELECT COUNT(|) FROM emp", &["EMPNO", "ENAME"]),
        ("SELECT * FROM |", &["EMP", "DEPT"]),
        (
            "SELECT * FROM emp WHERE |",
            &["EMPNO", "ENAME", "CASE", "NULL"],
        ),
        ("SELECT * FROM emp e JOIN dept d ON |", &["EMPNO", "DEPTNO"]),
        ("SELECT * FROM emp GROUP BY |", &["EMPNO", "ENAME"]),
        ("SELECT * FROM emp ORDER BY |", &["EMPNO", "ENAME"]),
        ("INSERT INTO |", &["EMP", "DEPT"]),
        ("INSERT INTO emp (|)", &["EMPNO", "ENAME"]),
        ("UPDATE |", &["EMP", "DEPT"]),
        ("UPDATE emp SET |", &["EMPNO", "ENAME", "SAL"]),
        ("DELETE FROM |", &["EMP", "DEPT"]),
    ];

    for db in [MySQL, MariaDB] {
        for (sql, expected) in cases {
            let (kind, keywords, suggestions) = audit_final_suggestions_for(sql, db);
            if suggestions.is_empty() {
                failures.push(format!(
                    "EMPTY at {db:?} `{sql}` (kind={kind:?}, keywords={keywords:?})"
                ));
                continue;
            }
            for item in *expected {
                if !has(&suggestions, item) {
                    failures.push(format!(
                        "`{item}` missing at {db:?} `{sql}`: kind={kind:?} keywords={keywords:?} final={suggestions:?}"
                    ));
                }
            }
        }
    }

    assert!(
        failures.is_empty(),
        "MySQL-family common SQL completion gaps:\n{}",
        failures.join("\n")
    );
}

#[test]
fn mysql_family_column_load_keys_use_catalog_case_for_schema_qualified_relations() {
    use crate::db::DatabaseType::{MariaDB, MySQL};
    use crate::ui::intellisense::QualifiedMemberKind;

    let mut data = IntellisenseData::new();
    data.users = vec!["SalesDb".to_string()];
    data.set_default_qualifier(Some("SalesDb".to_string()));
    data.set_members_for_qualifier_with_kinds(
        "SalesDb",
        vec![
            ("OrderLine".to_string(), Some(QualifiedMemberKind::Table)),
            ("OrderLineView".to_string(), Some(QualifiedMemberKind::View)),
        ],
    );
    data.set_relation_members_for_qualifier(
        "SalesDb",
        vec!["OrderLine".to_string(), "OrderLineView".to_string()],
    );
    data.rebuild_indices();

    for db in [MySQL, MariaDB] {
        assert_eq!(
            SqlEditorWidget::resolve_table_column_load_key_for_db(
                &data,
                "salesdb.orderline",
                Some(db),
            ),
            Some("SalesDb.OrderLine".to_string()),
            "{db:?} should query INFORMATION_SCHEMA with catalog-cased schema/table names"
        );
        assert_eq!(
            SqlEditorWidget::resolve_table_column_load_key_for_db(&data, "orderline", Some(db)),
            Some("SalesDb.OrderLine".to_string()),
            "{db:?} should use the selected schema's catalog-cased member for unqualified tables"
        );
        assert_eq!(
            SqlEditorWidget::resolve_table_column_load_key_for_db(
                &data,
                "salesdb.orderlineview",
                Some(db),
            ),
            Some("SalesDb.OrderLineView".to_string()),
            "{db:?} should canonicalize view column-load keys too"
        );
    }
}

#[test]
fn mysql_family_column_load_keys_preserve_exact_case_schema_variant() {
    use crate::db::DatabaseType::{MariaDB, MySQL};
    use crate::ui::intellisense::QualifiedMemberKind;

    let mut data = IntellisenseData::new();
    data.users = vec!["SalesDb".to_string(), "salesdb".to_string()];
    data.set_default_qualifier(Some("SalesDb".to_string()));
    data.set_members_for_qualifier_with_kinds(
        "salesdb",
        vec![("OrderLine".to_string(), Some(QualifiedMemberKind::Table))],
    );
    data.set_relation_members_for_qualifier("salesdb", vec!["OrderLine".to_string()]);
    data.rebuild_indices();

    for db in [MySQL, MariaDB] {
        assert_eq!(
            SqlEditorWidget::resolve_table_column_load_key_for_db(
                &data,
                "salesdb.orderline",
                Some(db),
            ),
            Some("salesdb.OrderLine".to_string()),
            "{db:?} should not rewrite an exact case-only schema variant to the default schema"
        );
    }
}

#[test]
fn mysql_family_mixed_case_schema_qualified_alias_uses_loaded_columns() {
    use crate::db::DatabaseType::{MariaDB, MySQL};
    use crate::ui::intellisense::QualifiedMemberKind;

    let mut data = IntellisenseData::new();
    data.users = vec!["SalesDb".to_string()];
    data.set_default_qualifier(Some("SalesDb".to_string()));
    data.set_members_for_qualifier_with_kinds(
        "SalesDb",
        vec![("OrderLine".to_string(), Some(QualifiedMemberKind::Table))],
    );
    data.set_relation_members_for_qualifier("SalesDb", vec!["OrderLine".to_string()]);
    data.set_columns_for_table(
        "SalesDb.OrderLine",
        vec!["OrderID".to_string(), "LineTotal".to_string()],
    );
    data.rebuild_indices();

    for db in [MySQL, MariaDB] {
        let mut data = data.clone();
        let suggestions = query_completion_suggestions_with_data(
            "SELECT ol.| FROM salesdb.orderline ol",
            db,
            true,
            &mut data,
        );
        assert!(
            suggestions
                .iter()
                .any(|suggestion| suggestion.eq_ignore_ascii_case("OrderID")),
            "{db:?} alias completion should use columns loaded under the canonical schema-qualified key: {suggestions:?}"
        );
    }
}

