#[test]
fn plsql_open_cursor_for_dynamic_sql_offers_using() {
    use crate::db::DatabaseType::Oracle;
    let has = |s: &[String], k: &str| s.iter().any(|x| x.eq_ignore_ascii_case(k));

    let s = query_keyword_completion_suggestions(
        "DECLARE v_sql VARCHAR2(100); p_rc SYS_REFCURSOR; \
         BEGIN OPEN p_rc FOR v_sql |; END;",
        Oracle,
    );
    assert!(
        has(&s, "USING"),
        "USING missing at `OPEN cur FOR dynamic_sql |`: {s:?}"
    );

    let s = query_keyword_completion_suggestions(
        "DECLARE v_sql VARCHAR2(100); p_rc SYS_REFCURSOR; p_rc2 SYS_REFCURSOR; \
         BEGIN OPEN p_rc FOR SELECT * FROM emp; OPEN p_rc2 FOR v_sql |; END;",
        Oracle,
    );
    assert!(
        has(&s, "USING"),
        "an earlier OPEN masked USING at the current dynamic OPEN: {s:?}"
    );

    // A static embedded query must not offer USING there.
    let s = query_keyword_completion_suggestions(
        "DECLARE p_rc SYS_REFCURSOR; BEGIN OPEN p_rc FOR SELECT * FROM emp |; END;",
        Oracle,
    );
    assert!(
        !has(&s, "USING"),
        "USING wrongly offered after a static query: {s:?}"
    );
}

