/// `OPEN <cursor> FOR |` admits both a query (`SELECT`/`WITH`) and a local
/// variable holding dynamic SQL — the locals must not be suppressed by the
/// slot's keyword classification; the `USING` tail and its bind operands keep
/// working after the source expression.
#[test]
fn plsql_open_for_source_offers_locals_and_query_keywords() {
    use crate::db::DatabaseType::Oracle;
    let has = |s: &[String], k: &str| s.iter().any(|x| x.eq_ignore_ascii_case(k));
    let mut failures = Vec::new();

    for wrapper in [
        "DECLARE v_sql VARCHAR2(100); rc SYS_REFCURSOR; BEGIN {} END;",
        "CREATE PROCEDURE p IS v_sql VARCHAR2(100); rc SYS_REFCURSOR; BEGIN {} END;",
        "CREATE OR REPLACE PACKAGE BODY pkg IS PROCEDURE p IS v_sql VARCHAR2(100); rc SYS_REFCURSOR; BEGIN {} END; END;",
    ] {
        let source_slot = wrapper.replace("{}", "OPEN rc FOR | ;");
        let s = query_completion_suggestions_with_locals(&source_slot, Oracle);
        for expected in ["v_sql", "SELECT", "WITH"] {
            if !has(&s, expected) {
                failures.push(format!("{expected} missing at `{source_slot}`: {s:?}"));
            }
        }

        let using_slot = wrapper.replace("{}", "OPEN rc FOR v_sql | ;");
        let s = query_completion_suggestions_with_locals(&using_slot, Oracle);
        if !has(&s, "USING") {
            failures.push(format!("USING missing at `{using_slot}`: {s:?}"));
        }

        let bind_slot = wrapper.replace("{}", "OPEN rc FOR v_sql USING | ;");
        let s = query_completion_suggestions_with_locals(&bind_slot, Oracle);
        if !has(&s, "v_sql") {
            failures.push(format!("bind local missing at `{bind_slot}`: {s:?}"));
        }
    }

    // Prefix filtering at the source slot.
    let s = query_completion_suggestions_with_locals(
        "DECLARE v_sql VARCHAR2(100); rc SYS_REFCURSOR; BEGIN OPEN rc FOR v_s| ; END;",
        Oracle,
    );
    assert!(
        has(&s, "v_sql"),
        "prefix-filtered local missing at `OPEN rc FOR v_s|`: {s:?}"
    );

    assert!(
        failures.is_empty(),
        "OPEN-FOR source gaps:\n{}",
        failures.join("\n")
    );
}

/// The named `END |` completion must survive the *full* production pipeline
/// (locals position gate included — the test harness now mirrors the
/// production `at_name_only_local_symbol_slot` exactly), across realistic
/// package-body layouts.
#[test]
fn plsql_named_end_completion_works_through_full_pipeline() {
    use crate::db::DatabaseType::Oracle;
    let has = |s: &[String], k: &str| s.iter().any(|x| x.eq_ignore_ascii_case(k));
    let mut failures = Vec::new();

    for (sql, expected) in [
        ("CREATE PACKAGE BODY pkg IS PROCEDURE p IS BEGIN NULL; END |", "p"),
        ("CREATE PACKAGE BODY pkg IS PROCEDURE p IS BEGIN NULL; END p; END |", "pkg"),
        ("CREATE PACKAGE BODY pkg IS PROCEDURE p IS BEGIN NULL; END |; END;", "p"),
        ("CREATE PROCEDURE prc IS BEGIN NULL; END |", "prc"),
        (r#"CREATE OR REPLACE NONEDITIONABLE PROCEDURE "SYSTEM"."QT_SPLIT_PROC"
(
    p_status IN VARCHAR2,
    p_rc     OUT SYS_REFCURSOR
)
IS
BEGIN
    OPEN p_rc FOR
        SELECT
            CASE
                WHEN v.NOTE_PREVIEW LIKE '%;%' THEN 'HAS_SEMI'
                WHEN v.note_preview LIKE '%/%' THEN 'HAS_SLASH'
                ELSE 'PLAIN'
            END AS note_kind
        FROM QT_SPLIT_V v
        WHERE v.STATUS_CD = p_status
        ORDER BY v.user_id;
END |;
/"#, "QT_SPLIT_PROC"),
        (r#"CREATE OR REPLACE NONEDITIONABLE PROCEDURE "SYSTEM"."QT_SPLIT_PROC" IS BEGIN NULL; END qt|"#, "QT_SPLIT_PROC"),
        ("CREATE PACKAGE pkg2 IS PROCEDURE p; END |", "pkg2"),
        ("CREATE PACKAGE BODY pkg IS PROCEDURE a IS BEGIN NULL; END a; PROCEDURE b IS BEGIN NULL; END |", "b"),
        ("CREATE PACKAGE BODY pkg IS PROCEDURE p IS BEGIN NULL; END p|; END pkg;", "p"),
        ("CREATE PACKAGE BODY pkg IS PROCEDURE p IS BEGIN <<lp>> LOOP NULL; END LOOP lp; END p|; END pkg;", "p"),
        ("CREATE PACKAGE BODY pkg IS PROCEDURE p IS BEGIN NULL; END p; END pk|", "pkg"),
        ("SELECT 1 FROM dual;\n/\nCREATE OR REPLACE PACKAGE BODY pkg IS\n  PROCEDURE p IS\n  BEGIN\n    NULL;\n  END |\nEND pkg;\n/", "p"),
        ("CREATE OR REPLACE PACKAGE BODY pkg IS\n  PROCEDURE a IS\n  BEGIN\n    NULL;\n  END |\n  PROCEDURE b IS\n  BEGIN\n    NULL;\n  END b;\nEND pkg;", "a"),
    ] {
        let s = query_completion_suggestions_with_locals(sql, Oracle);
        if !has(&s, expected) {
            failures.push(format!("`{expected}` missing at `{sql}`: {s:?}"));
        }
    }

    assert!(
        failures.is_empty(),
        "named END pipeline gaps:\n{}",
        failures.join("\n")
    );
}

/// The `END `-space auto-trigger fires exactly where the slot has a known
/// completion: the enclosing named object or a construct qualifier — never for
/// an anonymous block's `END`, a SQL `CASE … END`, or an unrelated word.
#[test]
fn plsql_end_space_auto_trigger_is_slot_precise() {
    use crate::db::DatabaseType::Oracle;
    let context_window_bytes = default_intellisense_test_context_window_bytes();
    let (lookbehind_bytes, lookahead_bytes) =
        SqlEditorWidget::intellisense_context_lookaround(context_window_bytes);
    let applies = |script: &str| {
        let cursor = script.find('|').expect("cursor");
        let text = script.replace('|', "");
        let start = cursor.saturating_sub(lookbehind_bytes);
        let end = cursor.saturating_add(lookahead_bytes).min(text.len());
        SqlEditorWidget::plsql_end_auto_trigger_applies_in_text(
            text.get(start..end).unwrap_or(""),
            cursor.saturating_sub(start),
            Some(Oracle),
        )
    };

    // Named objects and construct qualifiers → trigger.
    for script in [
        "CREATE PACKAGE BODY pkg IS PROCEDURE p IS BEGIN NULL; END |",
        "CREATE PROCEDURE prc IS BEGIN NULL; END |",
        r#"CREATE OR REPLACE NONEDITIONABLE PROCEDURE "SYSTEM"."QT_SPLIT_PROC" IS BEGIN NULL; END |"#,
        "CREATE PACKAGE pkg2 IS PROCEDURE p; END |",
        "BEGIN IF a = 1 THEN NULL; END |",
        "BEGIN LOOP NULL; END | END;",
    ] {
        assert!(applies(script), "auto-trigger missing at `{script}`");
    }
    let long_prefix =
        "BEGIN NULL; END;\n".repeat(crate::utils::arithmetic::safe_div(lookbehind_bytes, 8));
    assert!(
        applies(&format!("{long_prefix}BEGIN IF a = 1 THEN NULL; END |")),
        "auto-trigger should use the local bounded END window"
    );

    // Nothing to offer → stay quiet.
    for script in [
        "BEGIN NULL; END |",
        "SELECT CASE WHEN a = 1 THEN 1 END | FROM emp",
        "CREATE PROCEDURE prc IS BEGIN NULL; ENDX |",
        "CREATE PROCEDURE prc IS BEGIN NULL; |",
        "SELECT week_end | FROM emp",
    ] {
        assert!(!applies(script), "auto-trigger misfired at `{script}`");
    }

    // MySQL stored programs use a different grammar — no trigger.
    assert!(!SqlEditorWidget::plsql_end_auto_trigger_applies_in_text(
        "CREATE PROCEDURE prc() BEGIN SELECT 1; END ",
        44,
        Some(crate::db::DatabaseType::MySQL),
    ));
}

#[test]
fn select_space_auto_trigger_is_query_slot_precise_for_every_database() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let context_window_bytes = default_intellisense_test_context_window_bytes();
    let (lookbehind_bytes, lookahead_bytes) =
        SqlEditorWidget::intellisense_context_lookaround(context_window_bytes);
    let applies = |script: &str, db| {
        let cursor = script.find('|').expect("cursor");
        let text = script.replace('|', "");
        let start = cursor.saturating_sub(lookbehind_bytes);
        let end = cursor.saturating_add(lookahead_bytes).min(text.len());
        SqlEditorWidget::select_modifier_space_auto_trigger_applies_in_text(
            text.get(start..end).unwrap_or(""),
            cursor.saturating_sub(start),
            Some(db),
        )
    };

    for db in [Oracle, MySQL, MariaDB] {
        for script in [
            "SELECT |",
            "select |",
            "SELECT * FROM emp UNION SELECT |",
            "INSERT INTO emp SELECT |",
            "WITH e AS (SELECT 1 FROM emp) SELECT | FROM e",
        ] {
            assert!(
                applies(script, db),
                "SELECT-space auto-trigger missing at `{script}` for {db:?}"
            );
        }

        for script in [
            "GRANT SELECT | ON emp TO scott",
            "SELECTED |",
            "SELECT empno | FROM emp",
            "SELECT 'SELECT |' FROM emp",
        ] {
            assert!(
                !applies(script, db),
                "SELECT-space auto-trigger leaked at `{script}` for {db:?}"
            );
        }
    }
}

#[test]
fn plsql_execute_immediate_tail_space_auto_trigger_is_slot_precise() {
    use crate::db::DatabaseType::{MySQL, Oracle};
    let context_window_bytes = default_intellisense_test_context_window_bytes();
    let (lookbehind_bytes, _) =
        SqlEditorWidget::intellisense_context_lookaround(context_window_bytes);
    let applies = |script: &str| {
        let cursor = script.find('|').expect("cursor");
        let text = script.replace('|', "");
        let start = cursor.saturating_sub(lookbehind_bytes);
        SqlEditorWidget::plsql_execute_immediate_tail_auto_trigger_applies_in_text(
            text.get(start..cursor).unwrap_or(""),
            cursor.saturating_sub(start),
            Some(Oracle),
        )
    };

    assert!(applies(
        "CREATE PACKAGE BODY pkg IS PROCEDURE p IS v NUMBER; BEGIN EXECUTE IMMEDIATE 'select 1' INTO v |END p; END pkg;"
    ));
    assert!(applies("BEGIN EXECUTE IMMEDIATE 'select 1' |END;"));
    let long_prefix =
        "BEGIN NULL; END;\n".repeat(crate::utils::arithmetic::safe_div(lookbehind_bytes, 8));
    let long_text = format!("{long_prefix}BEGIN EXECUTE IMMEDIATE 'select 1' INTO v ");
    assert!(
        applies(&format!("{long_text}|")),
        "auto-trigger should use the local EXECUTE IMMEDIATE window"
    );

    assert!(!applies("BEGIN EXECUTE IMMEDIATE |END;"));
    assert!(!applies("BEGIN NULL; |END;"));
    assert!(!applies("EXECUTE IMMEDIATE 'select 1' |"));
    assert!(
        !SqlEditorWidget::plsql_execute_immediate_tail_auto_trigger_applies_in_text(
            "BEGIN EXECUTE IMMEDIATE 'select 1' INTO v ",
            "BEGIN EXECUTE IMMEDIATE 'select 1' INTO v ".len(),
            Some(MySQL),
        )
    );
}

#[test]
fn sweep_missing_structural_keywords_reproduce_through_production_completion() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let cases = [
        (Oracle, "SELECT SUM(sal) A| sum_sal FROM emp", "AS"),
        (
            Oracle,
            "WITH base A| (SELECT empno FROM emp) SELECT * FROM base",
            "AS",
        ),
        (
            Oracle,
            "SELECT * FROM emp MATCH_RECOGNIZE (MEASURES SUM(sal) A| total_sal PATTERN (x) DEFINE x AS x.sal > 0)",
            "AS",
        ),
        (
            Oracle,
            "SELECT * FROM emp MATCH_RECOGNIZE (PATTERN (x) DEFINE x A| x.sal > 0)",
            "AS",
        ),
        (
            Oracle,
            "CREATE TABLE t (doc CLOB) LOB (doc) STORE A| BASICFILE",
            "AS",
        ),
        (Oracle, "SHOW ERRORS PACKAGE BOD| oqt_pkg", "BODY"),
        (
            Oracle,
            "CREATE PACKAGE p AS g_tag CONS| VARCHAR2; END p;",
            "CONSTANT",
        ),
        (
            Oracle,
            "ALTER SESSION SET NLS_| = 'YYYY-MM-DD'",
            "NLS_DATE_FORMAT",
        ),
        (
            MySQL,
            "CREATE PROCEDURE p() BEGIN SELECT 1; EN|",
            "END",
        ),
        (
            MariaDB,
            "CREATE PROCEDURE p() BEGIN SELECT 1; EN|",
            "END",
        ),
        (
            MySQL,
            "SELECT ROW_NUMBER() OVER w_owner FROM emp WINDOW w_owner A| (ORDER BY empno)",
            "AS",
        ),
    ];

    let mut failures = Vec::new();
    for (db, sql, expected) in cases {
        let suggestions = query_completion_suggestions_with_locals(sql, db);
        if !suggestions
            .iter()
            .any(|suggestion| suggestion.eq_ignore_ascii_case(expected))
        {
            failures.push(format!(
                "`{expected}` missing at {db:?} `{sql}`: {suggestions:?}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "sweep structural keyword gaps:\n{}",
        failures.join("\n")
    );
}

