#[test]
fn mysql_family_wave23_catalog_tracks_renames_and_explicit_view_shapes() {
    let mysql =
        mysql_family_catalog_from_script(load_mysql_intellisense_test_file("final_hardcore.sql"));
    assert!(
        mysql
            .tables
            .iter()
            .any(|table| table.eq_ignore_ascii_case("sq_hard_w23_stage")),
        "RENAME TABLE intermediate target was not collected"
    );
    for (relation, expected_columns) in [
        (
            "SQ_HARD_MYSQL.SQ_HARD_W23_LEFT",
            &["RIGHT_ID", "SCORE_VALUE"][..],
        ),
        (
            "SQ_HARD_MYSQL_AUX.SQ_HARD_W23_RIGHT",
            &["LEFT_ID", "RIGHT_ID", "SCORE_VALUE"][..],
        ),
        (
            "SQ_HARD_W23_LEFT",
            &["LEFT_ID", "RIGHT_ID", "SCORE_VALUE"][..],
        ),
        (
            "SQ_HARD_W23_ITEM_V",
            &["ITEM_ID", "ITEM_LABEL", "PAYLOAD", "SCORE_VALUE"][..],
        ),
    ] {
        let columns = mysql.columns.get(relation).unwrap_or_else(|| {
            panic!("missing Wave 23 relation metadata for {relation}")
        });
        for expected in expected_columns {
            assert!(
                columns
                    .iter()
                    .any(|column| column.eq_ignore_ascii_case(expected)),
                "{expected} missing from {relation}: {columns:?}"
            );
        }
    }

    let mariadb =
        mysql_family_catalog_from_script(load_mariadb_intellisense_test_file("final_hardcore.sql"));
    let columns = mariadb
        .columns
        .get("SQ_HARD_W23_VALUE_V")
        .expect("missing MariaDB Wave 23 view metadata");
    for expected in ["ITEM_ID", "ITEM_LABEL", "PAYLOAD"] {
        assert!(
            columns
                .iter()
                .any(|column| column.eq_ignore_ascii_case(expected)),
            "{expected} missing from MariaDB Wave 23 view: {columns:?}"
        );
    }
}

