#[test]
fn sweep_mysql_family_handler_index_references_are_skipped() {
    for (marked, original_word) in [
        (
            "HANDLER mb3_direct READ `PRI__CODEX_CURSOR__` FIRST",
            "PRIMARY",
        ),
        (
            "HANDLER mb3_direct READ`PRI__CODEX_CURSOR__`FIRST",
            "`PRIMARY`",
        ),
    ] {
        assert!(
            intellisense_sweep_word_skip_context(
                marked,
                crate::db::DatabaseType::MariaDB,
                original_word,
            ),
            "HANDLER READ index names are references not represented by completion metadata: {marked}"
        );
    }
}

#[test]
fn sweep_preserves_quotes_around_quoted_identifier_prefixes() {
    let mut data = IntellisenseData::new();
    data.tables.push("mb3_direct".to_string());
    data.rebuild_indices();

    let run = intellisense_sweep_run(
        "HANDLER mb3_direct READ`PRIMARY`FIRST;",
        crate::db::DatabaseType::MariaDB,
        &data,
    );
    assert!(
        run.missing.iter().all(|missing| {
            !missing
                .word
                .trim_matches(|ch| matches!(ch, '`' | '"'))
                .eq_ignore_ascii_case("PRIMARY")
        }),
        "quoted HANDLER index reference should remain lexically separated during the sweep"
    );
}

#[test]
fn final_hardcore_completion_gap_regressions_are_covered() {
    use crate::db::DatabaseType::{MariaDB, MySQL, Oracle};

    let contains = |values: &[String], expected: &str| {
        values
            .iter()
            .any(|value| value.eq_ignore_ascii_case(expected))
    };
    let having_ctx = analyze_inline_cursor_sql(
        "SELECT deptno, SUM(sal) AS bucket_total FROM emp \
         GROUP BY deptno HAVING buck| > 0",
    );
    let having_projection = intellisense_context::extract_select_list_columns(
        SqlEditorWidget::current_query_tokens(&having_ctx),
    );
    assert!(
        contains(&having_projection, "bucket_total"),
        "HAVING query projection was not extracted: phase={:?} range={:?} tokens={:?} projection={having_projection:?}",
        having_ctx.phase,
        having_ctx.active_query_range,
        SqlEditorWidget::current_query_tokens(&having_ctx),
    );
    let type_ctx =
        analyze_inline_cursor_sql("ALTER TABLE emp ADD COLUMN IF NOT EXISTS added_v IN| NOT NULL");
    assert!(
        SqlEditorWidget::data_type_position_for_context_for_db(&type_ctx, true, Some(MariaDB),)
            .is_some(),
        "IF NOT EXISTS column type slot was not classified: phase={:?} new_name={} tokens={:?}",
        type_ctx.phase,
        type_ctx.ddl_new_name_position,
        type_ctx.statement_tokens,
    );
    let type_keywords =
        SqlEditorWidget::collect_expected_keyword_suggestions("IN", &type_ctx, Some(MariaDB));
    assert!(
        contains(&type_keywords, "INT"),
        "IF NOT EXISTS type keywords were preempted: keywords={type_keywords:?}, structural={:?}",
        SqlEditorWidget::mysql_family_structural_keyword_inference("IN", &type_ctx, Some(MariaDB),),
    );

    for (db_type, sql, expected) in [
        (
            MySQL,
            "SELECT deptno, SUM(sal) AS bucket_total FROM emp \
             GROUP BY deptno HAVING buck| > 0",
            "bucket_total",
        ),
        (
            MariaDB,
            "SELECT deptno, SUM(sal) AS bucket_total FROM emp \
             GROUP BY deptno HAVING buck| > 0",
            "bucket_total",
        ),
        (
            MySQL,
            "SELECT h.empno FROM emp h FOR SHARE OF h| NOWAIT",
            "h",
        ),
        (
            Oracle,
            "SELECT p.job_| FROM (SELECT deptno, job, sal FROM emp) \
             PIVOT XML (SUM(sal) AS total FOR job IN (ANY)) p",
            "job_XML",
        ),
        (
            Oracle,
            "DECLARE pivot_rows NUMBER; BEGIN SELECT COUNT(*) INTO pivot_rows \
             FROM (SELECT deptno, job, sal FROM emp) \
             PIVOT XML (SUM(sal) AS total FOR job IN (AN|)); END;",
            "ANY",
        ),
        (
            MariaDB,
            "ALTER TABLE emp ADD COLUMN IF NOT EXISTS added_v IN| NOT NULL",
            "INT",
        ),
        (
            MariaDB,
            "ALTER TABLE emp ADD COLUMN IF NO| EXISTS added_v INT",
            "NOT",
        ),
        (
            Oracle,
            "CREATE TABLE vector_store (embedding VECT|)",
            "VECTOR",
        ),
        (
            Oracle,
            "CREATE PACKAGE p AS TYPE ids_t IS TABLE OF NUMBER; \
             PROCEDURE open_cursor(p_rc OU| SYS_REFCURSOR); END;",
            "OUT",
        ),
    ] {
        let suggestions = query_keyword_completion_suggestions(sql, db_type);
        assert!(
            suggestions
                .iter()
                .any(|suggestion| intellisense_sweep_suggestion_matches_word(suggestion, expected)),
            "{expected} missing at `{sql}` ({db_type:?}): {suggestions:?}"
        );
    }

    let new_column =
        analyze_inline_cursor_sql("ALTER TABLE emp ADD COLUMN IF NOT EXISTS added_v| INT");
    assert!(
        new_column.ddl_new_name_position,
        "IF NOT EXISTS column name must remain a DDL definition slot"
    );
    let mut mysql_catalog = mysql_family_catalog_from_script(
        "CREATE TABLE t (id INT); \
         ALTER TABLE t ADD COLUMN IF NOT EXISTS added_v INT; \
         ALTER TABLE t RENAME COLUMN added_v TO renamed_v;",
    );
    let columns = mysql_catalog.columns.remove("T").unwrap_or_default();
    for expected in ["added_v", "renamed_v"] {
        assert!(
            contains(&columns, expected),
            "{expected} missing from ALTER TABLE script catalog: {columns:?}"
        );
    }

    let mut oracle_catalog = MysqlFamilyScriptCatalog::default();
    oracle_collect_script_catalog_entries(
        "BEGIN DBMS_ERRLOG.CREATE_ERROR_LOG(\
         dml_table_name => 'T', err_log_table_name => 'ERR_T'); END;",
        &mut oracle_catalog,
    );
    assert!(
        contains(&oracle_catalog.tables, "ERR_T"),
        "explicit DBMS_ERRLOG table missing from script catalog: {:?}",
        oracle_catalog.tables
    );

    assert!(
        intellisense_sweep_word_skip_context(
            "ALTER TABLE t DROP CONSTRAINT IF EXISTS ck_t__CODEX_CURSOR__;",
            MariaDB,
            "ck_t",
        ),
        "constraint references intentionally suppressed by production completion must be skipped"
    );
}

#[test]
fn wave11_intellisense_mysql_family_grammar_slots_are_completed() {
    use crate::db::DatabaseType::{MariaDB, MySQL};

    for (db_type, sql, expected) in [
        (
            MariaDB,
            "CREATE OR REPLACE USE| sq_hard_w11_u@localhost",
            "USER",
        ),
        (
            MariaDB,
            "CREATE OR REPLACE USER sq_hard_w11_u@localhost IDENTIFIED VI|",
            "VIA",
        ),
        (
            MariaDB,
            "CREATE OR REPLACE USER sq_hard_w11_u@localhost IDENTIFIED VIA mysq|",
            "mysql_native_password",
        ),
        (
            MariaDB,
            "CREATE OR REPLACE USER sq_hard_w11_u@localhost IDENTIFIED VIA mysql_native_password USI|",
            "USING",
        ),
        (
            MariaDB,
            "CREATE OR REPLACE USER sq_hard_w11_u@localhost IDENTIFIED VIA mysql_native_password USING PASSWORD('secret') OR unix|",
            "unix_socket",
        ),
        (
            MariaDB,
            "CREATE OR REPLACE USER sq_hard_w11_u@localhost IDENTIFIED VIA mysql_native_password USING PASSWORD('secret') O| unix_socket",
            "OR",
        ),
        (
            MariaDB,
            "CREATE OR REPLACE USER sq_hard_w11_u@localhost IDENTIFIED VIA mysql_native_password USING PASSWORD('secret') OR unix_socket WI|",
            "WITH",
        ),
        (
            MariaDB,
            "ALTER USER sq_hard_w11_u@localhost IDENTIFIED VI|",
            "VIA",
        ),
        (
            MariaDB,
            "CREATE TABLE t (n INT UNSIGNED ZERO|)",
            "ZEROFILL",
        ),
        (
            MariaDB,
            "CREATE TABLE t (note TINYTEXT CHAR| SET utf8mb4)",
            "CHARACTER",
        ),
        (
            MySQL,
            "CREATE TABLE t (note TINYTEXT CHAR| SET utf8mb4)",
            "CHARACTER",
        ),
        (
            MySQL,
            "SHOW COLUMNS FROM emp WHERE Fiel| LIKE 'b%'",
            "Field",
        ),
        (
            MySQL,
            "SHOW COLUMNS FROM emp WHERE Field LIK| 'b%'",
            "LIKE",
        ),
        (
            MySQL,
            "GRANT SELECT (EMPN|) ON EMP TO app_user",
            "EMPNO",
        ),
        (
            crate::db::DatabaseType::Oracle,
            "CREATE OR REPLACE PROCEDURE p IS BEGIN NULL; END; EN| p;",
            "END",
        ),
    ] {
        let suggestions = query_keyword_completion_suggestions(sql, db_type);
        assert!(
            suggestions
                .iter()
                .any(|suggestion| intellisense_sweep_suggestion_matches_word(suggestion, expected)),
            "{expected} missing at `{sql}` ({db_type:?}): {suggestions:?}"
        );
    }

    let mut sys_data = IntellisenseData::new();
    sys_data.schemas = vec!["SYS".to_string()];
    sys_data.set_members_for_qualifier_with_kinds(
        "SYS",
        vec![(
            "VERSION_MAJOR".to_string(),
            Some(QualifiedMemberKind::Function),
        )],
    );
    sys_data.rebuild_indices();
    let sys_suggestions = query_completion_suggestions_with_data(
        "SELECT sy|.version_major()",
        MySQL,
        false,
        &mut sys_data,
    );
    assert!(
        sys_suggestions
            .iter()
            .any(|suggestion| suggestion.eq_ignore_ascii_case("SYS")),
        "qualified MySQL function schema missing before dot: {sys_suggestions:?}"
    );
}

#[test]
fn wave13_oracle_completion_covers_model_row_images_and_json_dataguide() {
    use crate::db::DatabaseType::Oracle;

    let cases = [
        (
            "SELECT LAST_VALUE(sal IGNO| NULLS) OVER (ORDER BY empno) FROM emp",
            "IGNORE",
        ),
        (
            "SELECT empno, sal FROM emp MODE| RETURN UPDATED ROWS \
             DIMENSION BY (empno) MEASURES (sal AS projected) \
             IGNORE NAV UNIQUE DIMENSION RULES (projected[1] = 1)",
            "MODEL",
        ),
        (
            "SELECT empno, sal FROM emp MODEL RETU| UPDATED ROWS \
             DIMENSION BY (empno) MEASURES (sal AS projected) \
             IGNORE NAV UNIQUE DIMENSION RULES (projected[1] = 1)",
            "RETURN",
        ),
        (
            "SELECT empno, sal FROM emp MODEL RETURN UPDA| ROWS \
             DIMENSION BY (empno) MEASURES (sal AS projected) \
             IGNORE NAV UNIQUE DIMENSION RULES (projected[1] = 1)",
            "UPDATED",
        ),
        (
            "SELECT empno, sal FROM emp MODEL RETURN UPDATED ROW| \
             DIMENSION BY (empno) MEASURES (sal AS projected) \
             IGNORE NAV UNIQUE DIMENSION RULES (projected[1] = 1)",
            "ROWS",
        ),
        (
            "SELECT empno, sal FROM emp MODEL RETURN UPDATED ROWS \
             DIMENSION BY (empno) MEASURES (sal AS projected) \
             IGNO| NAV UNIQUE DIMENSION RULES (projected[1] = 1)",
            "IGNORE",
        ),
        (
            "SELECT empno, sal FROM emp MODEL RETURN UPDATED ROWS \
             DIMENSION BY (empno) MEASURES (sal AS projected) \
             IGNORE NA| UNIQUE DIMENSION RULES (projected[1] = 1)",
            "NAV",
        ),
        (
            "SELECT empno, sal FROM emp MODEL RETURN UPDATED ROWS \
             DIMENSION BY (empno) MEASURES (sal AS projected) \
             IGNORE NAV UNIQ| DIMENSION RULES (projected[1] = 1)",
            "UNIQUE",
        ),
        (
            "SELECT empno, sal FROM emp MODEL RETURN UPDATED ROWS \
             DIMENSION BY (empno) MEASURES (sal AS projected) \
             IGNORE NAV UNIQUE DIME| RULES (projected[1] = 1)",
            "DIMENSION",
        ),
        (
            "UPDATE emp target SET sal = sal \
             RETURNING SUM(OL| target.sal), SUM(NEW target.sal) INTO :a, :b",
            "OLD",
        ),
        (
            "UPDATE emp target SET sal = sal \
             RETURNING SUM(OLD target.sal), SUM(NE| target.sal) INTO :a, :b",
            "NEW",
        ),
        (
            "SELECT JSON_DATAGUIDE(sal, DBMS_|.FORMAT_HIERARCHICAL) FROM emp",
            "DBMS_JSON",
        ),
        (
            "SELECT JSON_DATAGUIDE(sal, DBMS_JSON.FORM|) FROM emp",
            "FORMAT_HIERARCHICAL",
        ),
        (
            "SELECT JSON_EXISTS(sal FOR| JSON, '$.x') FROM emp",
            "FORMAT",
        ),
    ];

    for (sql, expected) in cases {
        let suggestions = query_completion_suggestions_with_locals(sql, Oracle);
        assert!(
            suggestions
                .iter()
                .any(|suggestion| intellisense_sweep_suggestion_matches_word(suggestion, expected)),
            "{expected} missing at `{sql}`: {suggestions:?}"
        );
    }
}

