#[test]
fn wave14_oracle_completion_covers_domain_merge_and_partitioned_fetch() {
    use crate::db::DatabaseType::Oracle;

    for (sql, expected) in [
        (
            "CREATE DOMAIN money_domain AS (amount AS NUMBER(10, 2), \
             currency_code AS CHAR(3)) CONSTRAINT money_ck CHECK (amou| >= 0)",
            "amount",
        ),
        (
            "CREATE DOMAIN money_domain AS (amount AS NUMBER(10, 2), \
             currency_code AS CHAR(3)) CONSTRAINT money_ck \
             CHECK (amount >= 0 AN| currency_code IN ('USD'))",
            "AND",
        ),
        (
            "CREATE DOMAIN money_domain AS (amount AS NUMBER(10, 2), \
             currency_code AS CHAR(3)) DISPLAY (currency_code) \
             ORDER (currency_code || amount) ANNO__CODEX_CURSOR__ (Title 'Money')",
            "ANNOTATIONS",
        ),
        (
            "MERGE INTO emp target USING (VALUES (1, 10)) source (empno, sal) \
             ON (target.empno = source.empno) WHEN NOT MATCHED THEN \
             INSERT (empno, sal) VALUES (source.empno, source.sal) \
             RETU| target.empno INTO :changed_id",
            "RETURNING",
        ),
        (
            "SELECT * FROM emp ORDER BY deptno, sal DESC FETCH FIRST 3 PART| BY deptno, 2 ROWS ONLY",
            "PARTITIONS",
        ),
        (
            "SELECT * FROM emp ORDER BY deptno, sal DESC FETCH FIRST 3 PARTITIONS B| deptno, 2 ROWS ONLY",
            "BY",
        ),
        (
            "SELECT * FROM emp ORDER BY deptno, sal DESC FETCH FIRST 3 PARTITIONS BY deptno, 2 ROWS ONL|",
            "ONLY",
        ),
    ] {
        let suggestions = query_completion_suggestions_with_locals(sql, Oracle);
        assert!(
            suggestions
                .iter()
                .any(|suggestion| intellisense_sweep_suggestion_matches_word(suggestion, expected)),
            "{expected} missing at `{sql}`: {suggestions:?}"
        );
    }

    for (sql, original) in [
        (
            "CREATE DOMAIN money_domain AS (amou__CODEX_CURSOR__ AS NUMBER, currency_code AS CHAR(3))",
            "amount",
        ),
        (
            "MERGE INTO emp target USING (VALUES (1, 10)) sour__CODEX_CURSOR__ (empno, sal) \
             ON (target.empno = source.empno) WHEN MATCHED THEN UPDATE SET target.sal = source.sal",
            "source",
        ),
    ] {
        assert!(
            intellisense_sweep_word_skip_context(sql, Oracle, original),
            "new domain fields and derived row-source aliases are definition slots: {sql}"
        );
    }
}

