#[test]
fn wave16_oracle_completion_covers_graph_row_shapes_and_iterator_scope() {
    use crate::db::DatabaseType::Oracle;

    let script = load_intellisense_test_file("final_hardcore.sql");
    let local_marked = script.replacen(
        "JSON_VALUE(json_text, '$.size()' RETURNING NUMBER)",
        "JSON_VALUE(json__CODEX_CURSOR__, '$.size()' RETURNING NUMBER)",
        1,
    );
    let local_cursor = local_marked.find("__CODEX_CURSOR__").expect("cursor");
    let local_sql = local_marked.replacen("__CODEX_CURSOR__", "", 1);
    let (routine_cache, expanded) =
        SqlEditorWidget::build_routine_symbol_cache_bundle_for_test(&local_sql, local_cursor);
    let local_analysis = SqlEditorWidget::build_intellisense_analysis_from_routine_cache(
        &routine_cache,
        expanded.cursor_in_statement,
    );
    let json_locals = local_analysis
        .local_symbols
        .iter()
        .filter(|symbol| symbol.upper.starts_with("JSON_"))
        .map(|symbol| symbol.name.clone())
        .collect::<Vec<_>>();
    assert!(
        json_locals
            .iter()
            .any(|name| name.eq_ignore_ascii_case("json_text")),
        "the W16 PL/SQL declaration scanner lost json_text: {json_locals:?}"
    );

    let failures = oracle_fixture_completion_case_failures(
        "final_hardcore.sql",
        &[
            (
                "WITH graph_steps AS (",
                "WIT| graph_steps AS (",
                "WITH",
            ),
            (
                "MATCH route = (a IS metric) -[e IS links]->{1,2}",
                "MATC| route = (a IS metric) -[e IS links]->{1,2}",
                "MATCH",
            ),
            (
                "COUNT(EDGE_ID(e)) = COUNT(DISTINCT EDGE_ID(e))",
                "COUNT(EDGE_|(e)) = COUNT(DISTINCT EDGE_ID(e))",
                "EDGE_ID",
            ),
            (
                "COUNT(EDGE_ID(e)) = COUNT(DISTINCT EDGE_ID(e))",
                "COUNT(EDGE_ID(e)) = COUNT(DIST| EDGE_ID(e))",
                "DISTINCT",
            ),
            (
                "ONE ROW PER STEP (step_src, step_edge, step_dst) IN (route)",
                "ON| ROW PER STEP (step_src, step_edge, step_dst) IN (route)",
                "ONE",
            ),
            (
                "ONE ROW PER STEP (step_src, step_edge, step_dst) IN (route)",
                "ONE RO| PER STEP (step_src, step_edge, step_dst) IN (route)",
                "ROW",
            ),
            (
                "ONE ROW PER STEP (step_src, step_edge, step_dst) IN (route)",
                "ONE ROW PE| STEP (step_src, step_edge, step_dst) IN (route)",
                "PER",
            ),
            (
                "ONE ROW PER STEP (step_src, step_edge, step_dst) IN (route)",
                "ONE ROW PER STE| (step_src, step_edge, step_dst) IN (route)",
                "STEP",
            ),
            (
                "step_src.metric_id AS src_id",
                "step_|.metric_id AS src_id",
                "step_src",
            ),
            (
                "step_src.metric_id AS src_id",
                "step_src.metr| AS src_id",
                "metric_id",
            ),
            (
                "step_edge.hop_cost AS step_cost",
                "step_|.hop_cost AS step_cost",
                "step_edge",
            ),
            (
                "step_edge.hop_cost AS step_cost",
                "step_edge.hop_| AS step_cost",
                "hop_cost",
            ),
            (
                "PARTITION BY match_no, path_name",
                "PARTITION BY match_no, path_|",
                "path_name",
            ),
            (
                "ONE ROW PER VERTEX (step_vertex) IN (route)",
                "ONE ROW PER VERT| (step_vertex) IN (route)",
                "VERTEX",
            ),
            (
                "step_vertex.*,",
                "step_|.*,",
                "step_vertex",
            ),
            (
                "WITH graph_paths AS (",
                "WIT| graph_paths AS (",
                "WITH",
            ),
            (
                "JSON_VALUE(json_text, '$.size()' RETURNING NUMBER)",
                "JSON_VALUE(json_|, '$.size()' RETURNING NUMBER)",
                "json_text",
            ),
        ],
    );
    assert!(
        failures.is_empty(),
        "wave-16 Oracle completion gaps:\n{}",
        failures.join("\n")
    );

    let marked = script.replacen(
        "MATCH route = (a IS metric)",
        "MATCH rout__CODEX_CURSOR__ = (a IS metric)",
        1,
    );
    assert!(
        intellisense_sweep_word_skip_context(&marked, Oracle, "route"),
        "a SQL/PGQ path variable is a definition at `MATCH route =`"
    );
}

