#[test]
fn wave17_oracle_completion_covers_named_window_references_and_inheritance() {
    use crate::db::DatabaseType::Oracle;

    let cases = [
        (
            "WITH ranked AS (\
               SELECT SUM(sal) OVER w_ru| FROM emp \
               WINDOW w_depth AS (PARTITION BY deptno), \
                      w_ordered AS (w_depth ORDER BY empno), \
                      w_running AS (w_ordered ROWS UNBOUNDED PRECEDING)\
             ) SELECT * FROM ranked",
            "w_running",
        ),
        (
            "WITH ranked AS (\
               SELECT SUM(sal) OVER (w_or| ROWS UNBOUNDED PRECEDING) FROM emp \
               WINDOW w_depth AS (PARTITION BY deptno), \
                      w_ordered AS (w_depth ORDER BY empno)\
             ) SELECT * FROM ranked",
            "w_ordered",
        ),
        (
            "WITH ranked AS (\
               SELECT SUM(sal) OVER w_running FROM emp WIND| \
               w_depth AS (PARTITION BY deptno), \
               w_ordered AS (w_depth ORDER BY empno), \
               w_running AS (w_ordered ROWS UNBOUNDED PRECEDING)\
             ) SELECT * FROM ranked",
            "WINDOW",
        ),
        (
            "WITH ranked AS (\
               SELECT SUM(sal) OVER w_running FROM emp \
               WINDOW w_depth AS (PARTITION BY deptno), \
                      w_ordered AS (w_de| ORDER BY empno), \
                      w_running AS (w_ordered ROWS UNBOUNDED PRECEDING)\
             ) SELECT * FROM ranked",
            "w_depth",
        ),
        (
            "WITH ranked AS (\
               SELECT SUM(sal) OVER w_running FROM emp \
               WINDOW w_depth AS (PARTITION BY deptno), \
                      w_ordered AS (w_depth ORDER BY empno), \
                      w_running AS (w_or| ROWS UNBOUNDED PRECEDING) \
               QUALIFY ROW_NUMBER() OVER w_ordered <= 2\
             ) SELECT * FROM ranked",
            "w_ordered",
        ),
        (
            "WITH ranked AS (\
               SELECT SUM(sal) OVER w_running FROM emp \
               WINDOW w_depth AS (PARTITION BY deptno), \
                      w_ordered AS (w_depth ORDER BY empno), \
                      w_running AS (w_ordered ROWS UNBOUNDED PRECEDING) \
               QUALIFY ROW_NUMBER() OVER w_or| <= 2\
             ) SELECT * FROM ranked",
            "w_ordered",
        ),
    ];

    for (sql, expected) in cases {
        let suggestions = query_completion_suggestions_with_locals(sql, Oracle);
        assert!(
            suggestions
                .iter()
                .any(|suggestion| intellisense_sweep_suggestion_matches_word(suggestion, expected)),
            "{expected} missing at `{sql}`: {suggestions:?}"
        );
    }
}

