#[test]
fn wave21_oracle_completion_covers_direct_join_delete_row_images_and_intervals() {
    let interval_locals =
        SqlEditorWidget::collect_local_symbol_suggestions_with_prefix_for_db_type_for_test(
            "DECLARE deleted_elapsed INTERVAL DAY TO SECOND; BEGIN \
             DBMS_OUTPUT.PUT_LINE(EXTRACT(DAY FROM __CODEX_CURSOR__)); END;",
            "dele",
            &[],
            Some(crate::db::DatabaseType::Oracle),
        );
    assert!(
        interval_locals
            .iter()
            .any(|name| name.eq_ignore_ascii_case("deleted_elapsed")),
        "Oracle INTERVAL local declaration was not collected: {interval_locals:?}"
    );
    let interval_popup = query_completion_suggestions_with_locals(
        "DECLARE deleted_elapsed INTERVAL DAY TO SECOND; BEGIN \
         DBMS_OUTPUT.PUT_LINE(EXTRACT(DAY FROM dele|) * 1440); END;",
        crate::db::DatabaseType::Oracle,
    );
    assert!(
        interval_popup
            .iter()
            .any(|name| name.eq_ignore_ascii_case("deleted_elapsed")),
        "Oracle INTERVAL local was not merged into EXTRACT source completion: {interval_popup:?}"
    );
    let failures = oracle_fixture_completion_case_failures(
        "final_hardcore.sql",
        &[
            (
                "DELETE FROM sq_hard_w21_task target_owner\n  FROM sq_hard_w21_prune prune_owner",
                "DELETE FROM sq_hard_w21_task target_owner\n  FRO| sq_hard_w21_prune prune_owner",
                "FROM",
            ),
            (
                "RETURNING SUM(OLD target_owner.task_id),",
                "RETURNING SUM(OL| target_owner.task_id),",
                "OLD",
            ),
            (
                "SUM(OLD target_owner.elapsed)\n  INTO deleted_id_sum",
                "SUM(OL| target_owner.elapsed)\n  INTO deleted_id_sum",
                "OLD",
            ),
            (
                "EXTRACT(DAY FROM deleted_elapsed) * 1440",
                "EXTRACT(DAY FROM dele|) * 1440",
                "deleted_elapsed",
            ),
        ],
    );
    assert!(
        failures.is_empty(),
        "wave-21 Oracle direct-join DELETE/row-image/interval gaps:\n{}",
        failures.join("\n")
    );
}

