#[test]
fn wave24_mariadb_completion_covers_oracle_mode_anonymous_record_and_collection_types() {
    use crate::db::DatabaseType::MariaDB;

    let failures = mysql_family_fixture_completion_case_failures(
        "final_hardcore.sql",
        MariaDB,
        &[
            (
                "DELIMITER /\nDECLARE\n  TYPE explicit_row_t",
                "DELIMITER /\nDECL|\n  TYPE explicit_row_t",
                "DECLARE",
            ),
            (
                "TYPE explicit_row_t IS RECORD (",
                "TYPE explicit_row_t IS RECO| (",
                "RECORD",
            ),
            (
                "  TYPE explicit_map_t IS TABLE OF",
                "  TYP| explicit_map_t IS TABLE OF",
                "TYPE",
            ),
            (
                "  TYPE anchored_map_t IS TABLE OF",
                "  TYP| anchored_map_t IS TABLE OF",
                "TYPE",
            ),
            (
                "explicit_row_t INDEX BY VARCHAR2(20)",
                "explicit_row_t INDEX BY VARC|(20)",
                "VARCHAR2",
            ),
            (
                "sq_hard_w24_source%ROWTYPE",
                "sq_hard_w24_source%ROWT|",
                "ROWTYPE",
            ),
            (
                "anchored_map_t IS TABLE OF sq_hard_w24_source%ROWTYPE",
                "anchored_map_t IS TABLE OF sq_h|%ROWTYPE",
                "sq_hard_w24_source",
            ),
            (
                "current_key sq_hard_w24_source.lookup_key%TYPE;",
                "current_key sq_hard_w24_source.look|%TYPE;",
                "lookup_key",
            ),
            (
                "prior_key   sq_hard_w24_source.lookup_key%TYPE;",
                "prior_key   sq_hard_w24_source.look|%TYPE;",
                "lookup_key",
            ),
            (
                "explicit_map(source_row.lookup_key) := explicit_row_t(",
                "explicit_map(source_row.lookup_key) := expl|(",
                "explicit_row_t",
            ),
            (
                "explicit_map('discard') := explicit_row_t(99",
                "explicit_map('discard') := expl|(99",
                "explicit_row_t",
            ),
            (
                "prior_key := explicit_map.PRIOR",
                "prio| := explicit_map.PRIOR",
                "prior_key",
            ),
        ],
    );
    assert!(
        failures.is_empty(),
        "Wave 24 MariaDB Oracle-mode anonymous block completion gaps:\n{}",
        failures.join("\n")
    );

    let script = load_mariadb_intellisense_test_file("final_hardcore.sql");
    for (needle, replacement, original_word) in [
        (
            "TYPE explicit_row_t IS RECORD",
            "TYPE expl__CODEX_CURSOR__icit_row_t IS RECORD",
            "explicit_row_t",
        ),
        (
            "TYPE explicit_map_t IS TABLE",
            "TYPE expl__CODEX_CURSOR__icit_map_t IS TABLE",
            "explicit_map_t",
        ),
        (
            "TYPE anchored_map_t IS TABLE",
            "TYPE anch__CODEX_CURSOR__ored_map_t IS TABLE",
            "anchored_map_t",
        ),
    ] {
        let marked = script.replacen(needle, replacement, 1);
        assert_ne!(marked, script, "fixture definition probe `{needle}` not found");
        assert!(
            intellisense_sweep_word_skip_context(&marked, MariaDB, original_word),
            "MariaDB Oracle-mode TYPE name must remain a definition slot: {needle}"
        );
    }
}

#[test]
fn wave24_mysql_completion_covers_nested_query_expression_and_analytic_tails() {
    use crate::db::DatabaseType::MySQL;

    let script = load_mysql_intellisense_test_file("final_hardcore.sql");
    for (target, replacement) in [
        (
            ")\n    ORDER BY atom_id DESC\n    LIMIT 5",
            ")\n    ORDER BY atom__CODEX_CURSOR___id DESC\n    LIMIT 5",
        ),
        (
            ")\n  ORDER BY atom_id ASC\n  LIMIT 3",
            ")\n  ORDER BY atom__CODEX_CURSOR___id ASC\n  LIMIT 3",
        ),
        (
            ")\nORDER BY atom_id DESC\nLIMIT 1 OFFSET 1",
            ")\nORDER BY atom__CODEX_CURSOR___id DESC\nLIMIT 1 OFFSET 1",
        ),
    ] {
        let (_, _, context) =
            analyze_full_script_target_replacement(script, target, replacement);
        assert_eq!(
            SqlEditorWidget::mysql_table_statement_column_scope_for_context(&context, true),
            Some(vec!["sq_hard_w24_atom".to_string()]),
            "TABLE-expression row shape must survive each enclosing set-query ORDER BY; \
             active_range={:?}, current_query={:?}",
            context.active_query_range,
            SqlEditorWidget::current_query_tokens(&context),
        );
    }

    let failures = mysql_family_fixture_completion_case_failures(
        "final_hardcore.sql",
        MySQL,
        &[
            (
                "ROW(6, 'six;--/*value*/#')\n      ORDER BY column_0 DESC",
                "ROW(6, 'six;--/*value*/#')\n      ORDER BY colu| DESC",
                "column_0",
            ),
            (
                ")\n    ORDER BY atom_id DESC\n    LIMIT 5",
                ")\n    ORDER BY atom| DESC\n    LIMIT 5",
                "atom_id",
            ),
            (
                ")\n  ORDER BY atom_id ASC\n  LIMIT 3",
                ")\n  ORDER BY atom| ASC\n  LIMIT 3",
                "atom_id",
            ),
            (
                "VALUES ROW(99, 'sentinel')\n  ORDER BY column_0 DESC",
                "VALUES ROW(99, 'sentinel')\n  ORDER BY colu| DESC",
                "column_0",
            ),
            (
                ")\nORDER BY atom_id DESC\nLIMIT 1 OFFSET 1",
                ")\nORDER BY atom| DESC\nLIMIT 1 OFFSET 1",
                "atom_id",
            ),
            (
                "LIMIT 1 OFFSET 1\nINTO\n  @sq_hard_w24_picked_id",
                "LIMIT 1 OFFSET 1\nINT|\n  @sq_hard_w24_picked_id",
                "INTO",
            ),
            (
                "FIRST_VALUE(attribute_value)\n      RESPECT NULLS OVER w_full",
                "FIRST_VALUE(attribute_value)\n      RESP| NULLS OVER w_full",
                "RESPECT",
            ),
            (
                "FIRST_VALUE(attribute_value)\n      RESPECT NULLS OVER w_full",
                "FIRST_VALUE(attribute_value)\n      RESPECT NULL| OVER w_full",
                "NULLS",
            ),
            (
                "FIRST_VALUE(attribute_value)\n      RESPECT NULLS OVER w_full",
                "FIRST_VALUE(attribute_value)\n      RESPECT NULLS OVE| w_full",
                "OVER",
            ),
            (
                "NTH_VALUE(attribute_value, 2)\n      FROM FIRST RESPECT NULLS OVER w_full",
                "NTH_VALUE(attribute_value, 2)\n      FROM FIRS| RESPECT NULLS OVER w_full",
                "FIRST",
            ),
            (
                "NTH_VALUE(attribute_value, 2)\n      FROM FIRST RESPECT NULLS OVER w_full",
                "NTH_VALUE(attribute_value, 2)\n      FROM FIRST RESPECT NULL| OVER w_full",
                "NULLS",
            ),
            (
                "NTH_VALUE(attribute_value, 2)\n      FROM FIRST RESPECT NULLS OVER w_full",
                "NTH_VALUE(attribute_value, 2)\n      FROM FIRST RESPECT NULLS OVE| w_full",
                "OVER",
            ),
            (
                "LAST_VALUE(attribute_value)\n      RESPECT NULLS OVER w_full",
                "LAST_VALUE(attribute_value)\n      RESP| NULLS OVER w_full",
                "RESPECT",
            ),
            (
                "LAST_VALUE(attribute_value)\n      RESPECT NULLS OVER w_full",
                "LAST_VALUE(attribute_value)\n      RESPECT NULL| OVER w_full",
                "NULLS",
            ),
            (
                "LAST_VALUE(attribute_value)\n      RESPECT NULLS OVER w_full",
                "LAST_VALUE(attribute_value)\n      RESPECT NULLS OVE| w_full",
                "OVER",
            ),
            (
                "ROW_NUMBER() OVER w_reverse AS reverse_no\n  FROM sq_hard_w24_stream_event",
                "ROW_NUMBER() OVER w_reverse AS reverse_no\n  FRO| sq_hard_w24_stream_event",
                "FROM",
            ),
            (
                "FROM analytic\nWHERE reverse_no = 1",
                "FROM analytic\nWHERE reve| = 1",
                "reverse_no",
            ),
        ],
    );
    assert!(
        failures.is_empty(),
        "Wave 24 MySQL query-expression/analytic completion gaps:\n{}",
        failures.join("\n")
    );

    let analytic_call = query_keyword_completion_suggestions(
        "SELECT FIRST_VALUE(empno) | OVER () FROM emp",
        MySQL,
    );
    assert!(
        analytic_call.iter().any(|word| word == "RESPECT")
            && !analytic_call.iter().any(|word| word == "IGNORE"),
        "MySQL must offer only its executable null treatment: {analytic_call:?}"
    );
    let nth_direction = query_keyword_completion_suggestions(
        "SELECT NTH_VALUE(empno, 1) FROM | OVER () FROM emp",
        MySQL,
    );
    assert_eq!(
        nth_direction,
        vec!["FIRST".to_string()],
        "MySQL must not offer unsupported FROM LAST"
    );
}

