#[test]
fn wave25_mariadb_completion_covers_insert_cte_and_session_authorization() {
    let failures = mysql_family_fixture_completion_case_failures(
        "final_hardcore.sql",
        crate::db::DatabaseType::MariaDB,
        &[
            (
                "INSERT INTO sq_hard_w25_note (note_key, note_text, note_value)\nWITH running_geometry AS (",
                "INSERT INTO sq_hard_w25_note (note_key, note_text, note_value)\nWIT| running_geometry AS (",
                "WITH",
            ),
            ("GRANT SET USER", "GRANT SE| USER", "SET"),
            ("GRANT SET USER", "GRANT SET USE|", "USER"),
            (
                "SET SESSION AUTHORIZATION 'sq_hard_w25_actor'@'localhost';",
                "SET SESSION AUTH| 'sq_hard_w25_actor'@'localhost';",
                "AUTHORIZATION",
            ),
            (
                "SET SESSION AUTHORIZATION 'root'@'localhost';",
                "SET SESSION AUTH| 'root'@'localhost';",
                "AUTHORIZATION",
            ),
        ],
    );
    assert!(
        failures.is_empty(),
        "Wave 25 MariaDB insert/authorization completion gaps:\n{}",
        failures.join("\n")
    );

    for sql in ["INSERT INTO t |", "INSERT INTO t (a) |"] {
        let suggestions =
            query_keyword_completion_suggestions(sql, crate::db::DatabaseType::MariaDB);
        for expected in ["SELECT", "VALUES", "WITH"] {
            assert!(
                suggestions.iter().any(|value| value == expected),
                "MariaDB insert source head `{expected}` missing at `{sql}`: {suggestions:?}"
            );
        }
    }
}

#[test]
fn wave25_mysql_completion_covers_lateral_derived_columns_and_join_transition() {
    let failures = mysql_family_fixture_completion_case_failures(
        "final_hardcore.sql",
        crate::db::DatabaseType::MySQL,
        &[
            (
                "ST_AsText(sample_owner.point_value) AS sampled_point",
                "ST_AsText(sample_owner.poin|) AS sampled_point",
                "point_value",
            ),
            (
                "  ON TRUE\nJOIN LATERAL (\n  SELECT ST_LineInterpolatePoint",
                "  ON TRUE\nJOI| LATERAL (\n  SELECT ST_LineInterpolatePoint",
                "JOIN",
            ),
        ],
    );
    assert!(
        failures.is_empty(),
        "Wave 25 MySQL LATERAL completion gaps:\n{}",
        failures.join("\n")
    );
}
